  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx0778367b57$doc_0_4_nomy0tn_pdf$CODEx0778367b57$,$CODEx9165d720e0$संशोिन गने ऐन$CODEx9165d720e0$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,0,0,206,$CODExb5be9cc8a9$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np\nमलु कु ी फौजदारी कार्वयिधि संविता, २०७४\nप्रमाणीकरण धमधत\n२०७४।०६।३०\nसंशोिन गने ऐन", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "१", "title": "मलु कु ी संविता सम्बन्िी के िी नेपाल ऐनलाई संशोिन", "content": "गने ऐन, २०७५ २०७६।०१।०२", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२", "title": "फौजदारी कसूर तथा फौजदारी कार्वयिधि सम्बन्िी के िी", "content": "ऐन संशोिन गने ऐन, २०७९ २०७9।०3।31", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३", "title": "र्ौन विंसा विरुद्धका के िी ऐनलाई संशोिन गने ऐन, २०७९ २०७९।०३।३१", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४", "title": "मलु कु ी संविता सम्बन्िी के िी नेपाल ऐनलाई संशोिन गने ऐन, २०८० २०८०।०४।१२", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५", "title": "सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) धनिारण तथा व्र्ािसावर्क", "content": "िातािरण प्रिद्धयन सम्बन्िी के िी ऐनलाई संशोिन गने ऐन, २०८० २०८०।१२।३०", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६", "title": "सशु ासन प्रििनय तथा सािजय धनक सेिा प्रिाि सम्बन्िी के िी नेपाल", "content": "ऐनलाई संशोिन गने ऐन, २०८१ २०८१।१२।१८\nसंित ् २०७४ सालको ऐन नं. ३७\nप्रस्तािनााः फौजदारी मद्दु ाको अनसु न्िान, अधिर्ोजन, दार्री, कारबािी, सनु िु ाई र वकनारा तथा\nसोसँग सम्बत्तन्ित अन्र् कार्वयिधि र त्र्स्ता मद्दु ामा िएको फै सला कार्ायन्िर्न सम्बन्िी प्रचधलत\nकानूनलाई संशोिन र एकीकरण गरी कार्वयिधि कानूनलाई सरलीकृ त र समर्ानकु ू ल बनाउन\nिाञ्छनीर् िएकोले,\nनेपालको संवििानको िारा २९६ को उपिारा (१) बमोत्तजमको व्र्िस्थावपका-संसदले र्ो\nऐन बनाएको छ।\nपररच्छेद-१\nप्रारत्तम्िक", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१", "title": "संत्तिप्त नाम र प्रारम्िाः (१) र्स ऐनको नाम", "content": "“मलु\nकु ी फौजदारी कार्वयिधि संविता,\n२०७४” रिेको छ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n1\nwww.lawcommission.gov.np\n(२) र्ो संविताको दफा १९२ नपे ाल सरकारले नपे ाल राजपत्रमा सूचना प्रकाशन\nगरी तोके को धमधतदेत्ति र अन्र् दफािरु संित ् २०७५ साल िदौ १ गतेदेत्ति प्रारम्ि\nिनु ेछन।्", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२", "title": "पररिाषााः विषर् िा प्रसङ्गले अको अथ य नलागेमा र्स ऐनमा,-", "content": "(क) “अदालत” िन् नाले सिोच् च अदालत, उच्च अदालत िा त्तजल्ला अदालत\nसम्झन ु पछय र सो शब्दले कुनै िास वकधसमका फौजदारी मद्दु ाको\nकारबािी, सनु िु ाई र वकनारा गन य कानून बमोत्तजम अधिकार प्राप् त अन्र्\nअदालत, न्र्ावर्क धनकार् िा अधिकारी समेतलाई जनाउँछ।\n(ि) “अनसु न्िान अधिकारी” िन् नाले र्स ऐन बमोत्तजम कुनै कसूरको\nसम्बन्िमा अनसु न्िान गन य तोवकएको िा कानून बमोत्तजम अधिकार प्राप् त\nअधिकारी सम्झन ु पछय र सो शब्दले कुनै िास कसूरको सम्बन्िमा\nअनसु न्िान गन य गठित अनसु न्िान टोली समेतलाई जनाउँछ।\n(ग) “अपराि संविता” िन् नाले मलु कु ी अपराि (संविता), ऐन २०७४ सम्झन ु\nपछय।\n(घ) “उजरु ी” िन् नाले अदालतमा दार्र िनु े वफरादपत्र सम्झन ु पछय र सो\nशब्दले अनसु ूची-१ िा अनसु ूची-२ अन् तगतय का कसूरका सम्बन्िमा\nअधिर्ोगपत्र र अन्र् मद्दु ाका सम्बन्िमा सो सम्बन्िी प्रधतिेदन समेतलाई य\nजनाउँछ।\n(ङ) “कसूर” िन् नाले अपराि संविता िा अन्र् ऐन बमोत्तजम सजार् िनु े काम\nसम्झन ु पछय।\n(च) “कानून” िन् नाले तत्काल प्रचधलत कानून सम्झन ु पछय।\n(छ) “गम्िीर कसूर” िन् नाले तीन िषिय न्दा बढी दश िषसय म्म कै द सजार् िनु े\nकसूर सम्झन ु पछय।\n(ज) “जघन्र् कसूर” िन् नाले जन्मकै द िनु े िा दश िषिय न्दा बढी कै द सजार्\nिनु े कसूर सम्झन ु पछय।\n2\nwww.lawcommission.gov.np\n(झ) “िाउँ” िन् नाले घर, टिरा, गोि, मचान िा पाल सम्झन ु पछय र सो शब्दले\nसिारी सािन, डुङ्गा, िार्र्ु ान तथा त्र्स्तै प्रकृ धतका अन्र् स्थान िा सािन\nसमेतलाई जनाउँछ।\n(ञ) “न्र्ार्ािीश” िन् नाले मद्दु ाको कारबािी, सनु िु ाई र वकनारा गने\nअदालतको अधिकारी सम्झन ु पछय र सो शब्दले फौजदारी मद्दु ाको\nकारबािी, सनु िु ाई र वकनारा गन य अधिकार प्राप् त अधिकारी समेतलाई\nजनाउँछ।\n(ट) “प्रिरी कार्ायलर्” िन् नाले अनसु ूची-१ मा उत्तल्लत्तित कसूरको सम्बन्िमा\nअनसु न्िान गन य अधिकार प्राप् त प्रिरी कार्ायलर् सम्झन ु पछय।\n(ि) “फौजदारी मद्दु ा” िन् नाले अनसु ूची-१, अनसु ूची-२, अनसु ूची-३ िा\nअनसु ूची-४ अन्तगतय का कसूर सम्बन्िी मद्दु ा सम्झन ु पछय र सो शब्दले\nदेिार्को विषर् बािेक अन्र् मद्दु ा समेतलाई जनाउँछाः-\n(१) कानूनी िक, िैधसर्त, पद, पाररिाररक सम्बन्ि िा सम्पत्ति सम्बन्िी\nमद्दु ा,\n(२) नाता कार्म िा सम्बन्ि विच्छेद,\n(३) दस्तरु , पाररश्रधमक, तलब, ििा िा ज्र्ाला,\n(४) अंश, अपतु ाली, दान बकस, इच्छापत्र, संरिक, माथिर, माधत्रक,\nपैधत्रक, अत्तततर्ारी, िमपय त्रु िा िमपय त्रु ी,\n(५) कुनै करार, अद्धय-करार िा अनत्तुचत सम्बवृद्ध अन्तगतय को कुनै िक\nदािी,\n(६) दष्ु कृ धत, अद्धय-दष्ु कृ धत िा त्रवुटपूण य उत्पादन सम्बन्िी िक िा दािी,\n(७) सवुििािार,\n(८) िधतपूधत,य िा\n(९) देिानी प्रकृ धतको अन्र् कुनै िक िा दावर्त्ि।\n(ड) “मद्दु ा” िन् नाले फौजदारी मद्दु ा सम्झन ु पछय।\n3\nwww.lawcommission.gov.np\n(ढ) “मद्दु ा िेने अधिकारी” िन् नाले मद्दु ाको कारबािी, सनु िु ाई र वकनारा गन य\nकानून बमोत्तजम अधिकार प्राप् त अधिकारी सम्झन ु पछय र सो शब्दले\nविरासतमा धलएको व्र्त्तिको िकमा धनजलाई विरासतमा धलएको िाउँको\nनत्तजकको अदालतलाई समेत जनाउँछ।\n(ण) “स्थानीर् ति” िन् नाले गाउँपाधलका िा नगरपाधलका सम्झन ु पछय।\n(त) “सरकारी िवकल” िन् नाले मिान्र्ार्ाधिििा, नार्ि मिान्र्ार्ाधिििा,\nसिन्र्ार्ाधिििा, उपन्र्ार्ाधिििा, त्तजल्ला न्र्ार्ाधिििा िा सिार्क\nत्तजल्ला न्र्ार्ाधिििा सम्झन ु पछय र सो शब्दले मिान्र्ार्ाधिििाबाट\nसरकारी िवकलको िैधसर्तमा काम गन य तोवकएको अधिकृ तलाई समेत\nजनाउँछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३", "title": "छुट्टै कानूनी व्र्िस्था िएकोमा असर नपनेाः (१) कुनै कसूरको अनसु न्िान, अधिर्ोजन, मद्दु ा", "content": "िेने अधिकारिेत्र, सनु िु ाइ फै सला कार्ायन्िर्न िा अन्र् कुनै कारबािीका सम्बन्िमा छुट्टै\nऐनमा व्र्िस्था गररएको रिेछ िने त्र्स्तो विषर्मा र्स संविताको व्र्िस्थाले असर पाने\nछैन।\n(२) उपदफा (१) मा उत्तल्लत्तित छुट्टै ऐनमा व्र्िस्था निएको कात्त्िधयिको\nविषर्मा र्स संविताको व्र्िस्था लागू िनु ेछ।\n(३) उपदफा (१) को सिसय ामान्र्तामा प्रधतकू ल असर नपने गरी देिार्को\nविषर्मा देिार् बमोत्तजम िनु ेछाः-\n(क) कुनै कसूरमा मद्दु ा चलाउने सम्बन्िमा छुट्टै ऐनमा कुनै\nअधिकारी तोवकएको िए त्र्स्तो अधिकारीबाट र त्र्स्तो अधिकारी\nनतोवकएकोमा सम्बत्तन्ित कार्ायलर् प्रमिु ले सबतु प्रमाण साथ\nअधिर्ोगपत्र दार्र गन य म्र्ाद ननाघ्ने गरी आफ्नो रार् सवित मद्दु ा\nचल्ने िा नचल्ने धनणर्य को लाधग सम्बत्तन्ित सरकारी िकील समि\nधमधसल पेश गन यु पने,\n(ि) िण्ड (क) बमोत्तजम धमधसल प्राप् त िएपधछ मद्दु ा चल्ने िा नचल्न े\nधनणर्य गरी मद्दु ा चल्ने धनणर्य िए मद्दु ा चलाउन ु पने व्र्त्ति तथा\nधनज उपरको अधिर्ोग, सजार् र अधिर्ोगपत्रमा धलन ु पने दाबी\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n4\nwww.lawcommission.gov.np\nसमेत उल्लेि गरी मद्दु ा दार्र गन य म्र्ाद ननाघ्ने गरी प्राप् त\nधमधसल वफताय पिाउन ु पने,\n(ग) िण्ड (ि) बमोत्तजम मद्दु ा चलाउने धनणर्य प्राप् त िएपधछ सोिी\nअनरूु पको अधिर्ोगपत्र तर्ार गरी थनु िु ा िए थनु िु ा समेत लगी\nम्र्ादधित्रै सम्बत्तन्ित अदालत समि मद्दु ा दार्र गरी धमधसलको\nएक प्रधत नक् कल सरकारी िकीललाई उपलब्ि गराउन ु पने,\n(घ) िण्ड (क) बमोत्तजमको अधिकारी िा कार्ायलर् प्रमिु ले िण्ड (ग)\nबमोत्तजम अधिर्ोगपत्र दार्र गनकयु ा अधतररि देिार्का कार् य गन य\nसक्नेछाः-\n(१) सरकारी िकीलको रार् धलई दफा ३३ बमोत्तजम\nअधिर्िु लाई सजार् कम गने सम्बन्िी माग दाबी धलई\nअधिर्ोगपत्र दार्र गन य र सोिी दफाको उपदफा (६) को\nअिस्थामा छूट सजार् रद्द गन य माग दाबी धलई सम्बत्तन्ित\nअदालतमा धनिेदन ठदन,\n(२) सरकारी िकीलको रार् धलई दफा ३५ बमोत्तजम थप\nदाबी सवित मद्दु ा दार्र गन,य\n(३) सरकारी िकीलको रार् धलई दफा ३६ बमोत्तजम थप\nदाबी सवित मद्दु ा दार्र गन,य\n(४) सरकारी िकीलको रार् धलई दफा ३७ बमोत्तजम त्रवुट\nसच्र्ाउनको लाधग अदालतमा धनिेदन ठदन,\n(५) सरकारी िकील माफय त ् दफा १०१ बमोत्तजम अदालतमा\nसािी पेश गन,य\n(६) सािी विशेषज्ञलाई दफा ११३ बमोत्तजमको दैधनक तथा\nभ्रमण ििा उपलब्ि गराउन।\nपररच्छेद-२\nकसूरको सूचना तथा अनसु न्िान सम्बन्िी व्र्िस्था\n5\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४", "title": "कसूरको जािेरी दरिास्त िा सूचना ठदन ु पनेाः (१) अनसु ूची-१ मा उत्तल्लत्तित कुनै कसूर", "content": "िएको, िइरिेको िा िनु लागेको छ िन् ने कुरा थािा पाउने व्र्त्तिले त्र्स्तो कसूरका\nसम्बन्िमा आफू सँग िएको िा आफू ले देिे जाने सम्मको सिदु प्रमाण िलु ाई त्र्स्तो\nकुराको धलत्तित जािेरी दरिास्त िा मौत्तिक सूचना िा विद्यतु ीर् माध्र्मको सूचना\nअनसु ूची-५ बमोत्तजमको ढाँचामा नत्तजकको प्रिरी कार्ायलर्मा र्थात्तशघ्र ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको जािेरी दरिास्त िा सूचना ठदने व्र्त्तिले त्र्स्तो\n\nसूचना िा धनजले ठदएको जािेरी दरिास्त अनसु ूची-५ बमोजमको ढाँचा अनरुु प निएमा\nधनजले ठदएको सूचनाका सबै कुरािरु सम्बत्तन्ित प्रिरी कमचय ारीले अनसु ूची-५ बमोत्तजमको\nढाँचामा िलु ाई धनजलाई सो पढी िाची सनु ाई धनजको सिीछाप समेत गराई रात न ु\nपनेछ।\n(३) उपदफा (१) बमोत्तजमको जािेरी दरिास्त िा सूचना कुनै व्र्त्तिले\n\nसम्बत्तन्ित प्रिरी कार्ायलर्मा आफैँ उपत्तस्थत िई ठदएमा िा िलु ाक िा कुनै व्र्त्ति\nमाफय त ् पिाएमा िा विद्यतु ीर् माध्र्मबाट सूचना ठदएमा त्र्स्तो प्रिरी कार्ायलर्ले त्र्स्तो\nजािेरी दरिास्त िा सूचना दताय गरी धनजलाई अनसु ूची-६ बमोत्तजमको ढाँचामा िरपाई\nठदन ु पनेछ। कसैले विद्यतु ीर् माध्र्मबाट सूचना ठदएकोमा सोिी माध्र्मबाट त्र्स्तो\nसूचना पाएको जानकारी गराउन ु पनेछ।\n\n(३क) उपदफा (१) बमोत्तजम िलु ाक िा विद्यतु ीर् माध्र्मबाट प्राप् त िनु\nआएको सूचनाको विश्वसनीर्ता र्वकन गन यु पने िएमा त्र्स्तो सूचना ठदने व्र्त्तिलाई\nत्तझकाई प्रिरी कार्ायलर्ले सनाित गराउन सक्नेछ।\n(४) उपदफा (१), (२) िा (३) मा जनु सकु ै कुरा लेत्तिएको िए तापधन अनसु ूची-\n१ मा उत्तल्लत्तित कुनै कसूर िएको कुराको सूचना िा जानकारी प्रिरीले अन्र् कुन ै\nस्रोतबाट िा आफैँ ले प्राप्त गरेमा सो सम्बन्िमा अनसु ूची-५ मा उत्तल्लत्तित वििरण\nसवितको प्रधतिेदन िडा गन यु पनेछ।\n(५) र्स दफा बमोत्तजमको जािेरी दरिास्त, सूचना िा उपदफा (४) बमोत्तजमको\n\nप्रधतिेदनलाई प्रिरी कार्ायलर् िा अनसु न्िान गन य अधिकारप्राप् त कार्ायलर् िा अधिकारीले\nअनसु ूची-७ बमोत्तजमको ढाँचाको दताय वकताबमा दताय गरी रात न ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n6\nwww.lawcommission.gov.np\n(६) उपदफा (१) बमोत्तजम प्राप् त जािेरी दरिास्त िा सूचनाको सम्बन्िमा\nकानूनद्वारा छुट्टै अनसु न्िान गने अधिकारी तोवकएकोमा त्र्स्तो अधिकारी समि र छुट्टै\nअनसु न्िान गने अधिकारी निएकोमा सम्बत्तन्ित त्तजल्ला प्रिरी कार्ायलर् समि पिाउन ु\nपनेछ।\n(७) अनसु ूची-२ मा उत्तल्लत्तित कुनै कसूर सम्बन्िी सूचना ठदन चािने व्र्त्तिले\nअनसु न्िान गन य अधिकार प्राप् त कार्ालय र् िा अधिकारी समि अनसु ूची-५ बमोत्तजमको\nढाँचामा सूचना ठदन ु पनेछ।\n(८) उपदफा (७) बमोत्तजम प्राप् त सूचना सम्बत्तन्ित कार्ायलर् िा अधिकारीले\nदताय गरी त्र्स्तो सूचना ठदने व्र्त्तिलाई अनसु ूची-६ बमोत्तजमको ढाँचामा िरपाई ठदन ु\nपनेछ।\n(९) उपदफा (७) बमोत्तजमको सूचना सम्बत्तन्ित कार्ायलर् िा अधिकारी समि\nदताय गन य तत्काल सम्िि निएमा त्र्स्तो सूचना नत्तजकको प्रिरी कार्ायलर्मा पधन ठदन\nसवकनेछ।\n(१०) उपदफा (९) बमोत्तजम कुनै सूचना प्राप् त िनु आएमा सम्बत्तन्ित प्रिरी\nकार्ायलर्ले पधन त्र्स्तो सूचना उपदफा (३) बमोत्तजम दताय गरी तीन ठदनधित्र\nकारबािीका लाधग सम्बत्तन्ित कार्ायलर् िा अधिकारी समि पिाउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५", "title": "जािेरी दरिास्त िा सूचना दता य नगरेमा उजरु गन य सक्नाःे (१) दफा ४ को उपदफा (१)", "content": "बमोत्तजम ठदएको जािेरी दरिास्त िा सूचना सम्बत्तन्ित प्रिरी कार्ायलर्ले दता य गन य इन्कार\nगरेमा जािेरी दरिास्त िा सूचना गने व्र्त्तिले त्र्स्तो व्र्िोरा िलु ाई सम्बत्तन्ित त्तजल्ला\nसरकारी िवकल कार्ायलर् िा त्र्स्तो जािेरी दरिास्त िा सूचना दताय गन यु पने प्रिरी\nकार्ायलर्िन्दा माधथल्लो तिको प्रिरी कार्ायलर्मा जािेरी दरिास्त िा सूचना सवित उजरु\nगन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजमको उजरु प्राप् त िएमा सम्बत्तन्ित त्तजल्ला सरकारी\nिवकल कार्ायलर् िा प्रिरी कार्ायलर्ले त्र्सको अधिलेि रािी त्र्स्तो जािेरी दरिास्त िा\nसूचना आिश्र्क कारबािीको लाधग सम्बत्तन्ित प्रिरी कार्ायलर्मा पिाउन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n7\nwww.lawcommission.gov.np\n(३) उपदफा (२) बमोत्तजम प्राप् त िनु आएको जािेरी दरिास्त िा सूचनालाई\nसम्बत्तन्ित प्रिरी कार्ायलर्ले दफा ४ को उपदफा (३) बमोत्तजम दताय गरी कारबािी गन यु\nपनेछ।\n(४) दफा ४ को उपदफा (७) बमोत्तजमको सूचना दताय गन य त्र्स उपदफामा\nउत्तल्लत्तित कार्ालय र् िा अधिकारीले इन्कार गरेमा त्र्स्तो सूचना ठदने व्र्त्तिले सोिी\nव्र्िोरा िलु ाई कसूरको सूचना सवित सम्बत्तन्ित त्तजल्लाका प्रमिु त्तजल्ला अधिकारी\nसमि उजरु ठदन सक्नेछ।\nतर प्रमिु त्तजल्ला अधिकारी नै अनसु न्िान अधिकारी तोवकएको रिेछ र धनजले\nत्र्स्तो सूचना दताय गन य इन्कार गरेमा गिृ मन्त्रालर्मा त्र्स्तो उजरु ठदन सवकनेछ।\n(५) उपदफा (४) बमोत्तजम उजरु प्राप् त िएमा सम्बत्तन्ित प्रमिु त्तजल्ला अधिकारी\nिा गिृ मन्त्रालर्ले तीन ठदनधित्र सूचना दताय गने िा नगने धनणर्य गरी सम्बत्तन्ित\nकार्ायलर्लाई सो बमोत्तजम गन य िा गराउन धनदेशन ठदन ु पनेछ।\n(६) उपदफा (५) बमोत्तजमको धनदेशन प्राप् त िएपधछ सम्बत्तन्ित कार्ायलर् िा\nअधिकारीले सो धनदेशन अनसु ारको कारबािी गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६", "title": "प्रमाण लोप िा नास िनु नठदन र कसूर गने व्र्त्ति उम्कन नपाउन े व्र्िस्था गनेाः (१)", "content": "कुनै प्रिरी कार्ायलर् िा प्रिरी कमचय ारीले अनसु ूची-१ मा उत्तल्लत्तित कुनै कसूर िएको\nिा िई रिेको िा िनु लागेको जानकारी पाएमा कसूरदारलाई कसूर गनबय ाट रोक्ने िा\nकसूरसँग सम्बत्तन्ित कुनै प्रमाण लोप िा नास िनु नठदने र कसूर गने व्र्त्ति िाग्न,\nउम्कन नपाउने आिश्र्क र प्रिािकारी व्र्िस्था र्थात्तशघ्र गन यु पनेछ।\n(२) उपदफा (१) बमोत्तजम तत्कालै कारबािी नगरेमा कसूरसँग सम्बत्तन्ित कुन ै\nप्रमाण लोप िा नास िनु े िा कसूर गने व्र्त्ति िाग्ने, उम्कने सम्िािना िएमा त्र्स्तो\nप्रिरी कार्ालय र् िा कमचय ारीले आिश्र्कता अनसु ार अको प्रिरी कार्ायलर्को िेत्रमा समेत\nगई आिश्र्क कारबािी गन य सक्नेछ।\n(३) उपदफा (२) बमोत्तजम अको प्रिरी कार्ालय र्को िेत्रमा गई कुनै कारबािी\nगन यु पने िएमा त्र्स्तो कार्ायलर् िा कमचय ारीले त्र्सको जानकारी सम्बत्तन्ित प्रिरी\nकार्ायलर् िा धनकार् तथा आफू िन्दा माधथल्लो प्रिरी कार्ायलर्लाई ठदन ु पनेछ।\n8\nwww.lawcommission.gov.np\n(४) अनसु ूची-२ मा उत्तल्लत्तित कुनै कसूर िएको िा िइरिेको िा िनु लागेको\nजानकारी कसैको सूचना िा सम्बत्तन्ित अधिकारीले आपैmले कुनै स्रोतबाट पाएमा त्र्स्तो\nअधिकारीले उपदफा (१) िा (२) बमोत्तजमको कारबािी गन यु पनेछ।\nतर त्र्स्तो कसूरको सूचना कुनै प्रिरी कमचय ारीले थािा पाएको र सम्बत्तन्ित\nअनसु न्िान अधिकारी तत्काल उपलब्ि निएमा त्र्स्तो प्रिरी कमचय ारीले उपदफा (१) मा\nउत्तल्लत्तित कारबािी गरी कुनै व्र्त्ति पक्राउ परेको िए त्र्स्तो व्र्त्ति सवित\nकारबािीको वििरण अनसु न्िान अधिकारी समि पिाउन ु पनेछ।\n(५) प्रिरी कमचय ारी िा अनसु न्िान अधिकारीले कसूरसँग सम्बत्तन्ित कुनै प्रमाण\nलोप िा नास िनु नठदन िा कसूरदारलाई पक्राउ गन य कुनै धनकार्, अधिकारी िा\nव्र्त्तिसँग मद्दत माग्न सक्नेछ र त्र्स्तो मद्दत मागेमा आिश्र्क मद्दत ठदन ु त्र्स्तो\nधनकार्, अधिकारी िा व्र्त्तिको कतव्य र् िनु ेछ।\n(६) प्रिरी कमचय ारीले कुनै कसूर िएको िा िइरिेको िा िनु लागेको छ िन् न े\nजानकारी िा सूचना िा सरु ाक पाई सरु ाक धलन गएका बित िा आफ्नो उपत्तस्थधतमा\nकुनै कसूर िएमा त्र्स्तो कसूर गने व्र्त्तिलाई तरुु न्त पक्राउ गन यु पनेछ।\n(७) प्रिरी कमचय ारीले कसूरसँग सम्बत्तन्ित दसीको मालसामान र अन्र् कुन ै\nप्रमाण िा िस्त ु फे ला पारेमा त्र्स्तो प्रमाण िा िस्त ु समेत घटनास्थलमा उपलब्ि कसूर\nिएको देख्न े व्र्त्तििरु कोिी िए धनजिरुको रोििरमा आफ्नो कब्जामा धलई आिश्र्कता\nअनसु ार मचु ल्ु का िडा गन यु पनेछ।\n(८) उपदफा (७) बमोत्तजम मचु ल्ु का िडा गने कार् य सम्पन्न निएसम्म त्र्स्तो\nिस्त,ु स्थान िा घटनास्थलको अिस्थालाई र्थात्तस्थधतमा सरु त्तित रात न ु पनेछ।\n(९) उपदफा (७) बमोत्तजम प्राप् त िएको दसीको मालसामान र कसूरसँग\nसम्बत्तन्ित प्रमाण िा िस्त ु तत्काल आफ्नो त्तजम्मा िा कब्जामा धलन नसवकने अिस्था\nरिेछ िने त्र्स्तो चीज िा िस्तलु ाई सरु त्तित साथ रात नको धनधमि सम्बत्तन्ित प्रिरी\nकमचय ारीले स्थानीर् ति िा अन्र् कुनै कार्ायलर्लाई अनरु ोि गन य सक्नेछ र त्र्सरी\nअनरु ोि गररएमा सम्बत्तन्ित ति िा कार्ायलर्ले पधन त्र्स्तो मालसामान िा प्रमाण त्तजम्मा\nधलई त्र्सको िरपाई ठदन ु पनेछ।\nतर कसूरसँग सम्बत्तन्ित निएको िस्त ु सम्बत्तन्ित व्र्त्तिलाई तत्काल वफता य गन यु\nपनेछ।\n9\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७", "title": "सम्बत्तन्ित प्रिरी कार्ालय र्लाई सूचना ठदन ु पनेाः (१) अनसु ूची-१ मा उत्तल्लत्तित कुन ै", "content": "कसूरको सम्बन्िमा कुनै प्रिरी कार्ायलर्मा प्राप्त िएको सूचनाको व्र्िोराबाट िा प्रिरी\nकार्ायलर् आफैँ ले त्र्स्तो कसूर अन्र् प्रिरी कार्ायलर्को िेत्रधित्र िएको िा िइरिेको िा\nिनु लागेको थािा पाएमा त्र्स्तो प्रिरी कार्ायलर्ले त्र्स्तो सूचना र्थात्तशघ्र सम्बत्तन्ित\nप्रिरी कार्ायलर्मा पिाइठदन ु पनेछ र आिश्र्कता अनसु ार सूचना ठदने व्र्त्तिलाई पधन\nसम्बत्तन्ित प्रिरी कार्ायलर्मा उपत्तस्थत िनु जानकारी ठदन ु पनेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन िौगोधलक विकटता िा\nअन्र् कुनै कारणले अनसु न्िान अधिकारी तत्काल उपलब्ि िनु नसक्ने िई कसूर गने\nव्र्त्ति उम्कन े तथा कसूरसँग सम्बत्तन्ित दसी, प्रमाण लोप िनु सक्ने िएमा त्र्स्तो\nिेत्रधित्रको िारदातका िकमा पधन त्र्स्तो सूचना प्राप् त गने सम्बत्तन्ित प्रिरी कार्ायलर्का\nअधिकार प्राप् त अनसु न्िान अधिकारीले प्रारत्तम्िक अनसु न्िान गरी सम्बत्तन्ित प्रिरी\nकार्ायलर्मा पिाउन ु पनेछ।\n(३) उपदफा (२) बमोत्तजम प्रारत्तम्िक अनसु न्िान गनअयु त्तघ त्र्स्तो अधिकारीले\nसम्बत्तन्ित प्रिरी कार्ायलर् र एक ति माधथको प्रिरी कार्ायलर्लाई जानकारी ठदन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८", "title": "अनसु न्िान गरी सिदु प्रमाण सङ्कलन गनेाः (१) अनसु ूची-१ मा उत्तल्लत्तित कुनै कसूर", "content": "िएको िा िइरिेको िा िनु लागेको जानकारी प्राप्त िएमा सम्बत्तन्ित प्रिरी कार्ायलर्ले\nर्थात्तशघ्र कम्तीमा प्रिरी नार्ब धनरीिक दजायको प्रिरी कमचय ारीलाई अनसु न्िान अधिकारी\nतोकी त्र्सको जानकारी सम्बत्तन्ित सरकारी िवकल कार्ायलर् र आफू िन्दा माधथल्लो\nप्रिरी कार्ायलर्लाई ठदन ु पनेछ र त्र्सरी तोवकएको अनसु न्िान अधिकारीले त्र्स्तो\nकसूरको अनसु न्िान गन यु पनेछ।\nतर देिार्का कसूरको अनसु न्िान गन य कम्तीमा प्रिरी धनरीिक दजायको\nअधिकृ तलाई तोक्न ु पनेछाः-\n(क) अपराि संविताको िाग-२ को पररच्छेद-१, पररच्छेद-१२,\nपररच्छेद-१७, पररच्छेद-१८ को दफा २१९, पररच्छेद-१९ को\n\nदफा २३०, २३१, २३२, २३३, २३५, २३८, पररच्छेद-२०\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n10\nwww.lawcommission.gov.np\nको दफा २४४, पररच्छेद-२२ को दफा २५६, २५७ र २५८\nका कसूर,\n\n(ि) ...........\n(ग) नेपाल सरकारले कसूरको गम्िीरता िेरी नेपाल राजपत्रमा सूचना\nप्रकाशन गरी तोके को अन्र् कसूर।\n(२) अनसु न्िान अधिकारीले र्स दफा बमोत्तजम अनसु न्िान गदाय कसूर तथा\nकसूर िएको िाउँको र्थाथ य त्तचत्रण िनु े गरी र्थासम्िि धनम्न धलत्तित कुरािरु िलु ाई\nघटनास्थल मचु ल्ु का तर्ार गन यु पनेछाः-\n(क) कसूर िएको धमधत र समर्,\n(ि) कसूर िएको िाउँको िेगाना, वििरण र रेिात्तचत्र,\n(ग) त्र्स्तो िाउँको िस्तत्तुस्थधत तथा कसूर िा कसूरदारसँग त्र्सको\nसम्बन्ि,\n(घ) कसूर िएको िाउँ िा त्र्सको िरपर देत्तिएको िा पाइएको दसी\nप्रमाण र कसूरसँग सम्बत्तन्ित अन्र् कुनै उल्लेिनीर् कुरा।\n\n(३) अनसु न्िान अधिकारीले उपदफा (२) बमोत्तजम घटनास्थल मचु ल्ु का तर्ार\nगदाय त्र्स्तो िाउँलाई अरु माधनस प्रिेश गन य नपाउने गरी घेरा िाली र्थासम्िि त्र्स्ता\nिाउँको र त्र्स्तो िाउँमा देत्तिएको िा पाइएको ित्के ला र औलँ ा िा पाइलाको त्तचह्न,\nधनशाना िा अन्र् दसी िा कसूर ििर गन य मद्दत पर्ु र्ाउने अन्र् कुनै मित्िपूण य कुराको\nफोटो समेत धलन सक्नेछ।\n(४) उपदफा (२) बमोत्तजम घटनास्थल मचु ल्ु का तर्ार गदाय कसूर गने व्र्त्ति िा\nआरोवपत व्र्त्ति उपत्तस्थत िए धनजको औलं ाको छाप लगार्त पविचान िल्ु ने वििरण\nसमेत धलन ु पनेछ।\n(५) अनसु न्िान अधिकारीले कसूरसँग सम्बत्तन्ित कुनै दसी प्रमाण, सामान िा\nिस्त ु फे ला पारेमा त्र्सलाई आफ्नो कब्जामा धलन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n11\nwww.lawcommission.gov.np\n(६) उपदफा (५) बमोत्तजम दसी प्रमाण सामान िा िस्त ु कब्जामा धलन े\nअधिकारीले सोको िरपाई सम्बत्तन्ित व्र्त्तिलाई ठदन ु पनेछ।\n(७) अनसु ूची-२ मा उत्तल्लत्तित कसूरको अनसु न्िान गन य कानूनमा कुनै अधिकारी\nतोवकएकोमा सोिी अधिकारीबाट र त्र्स्तो अधिकारी नतोवकएकोमा सम्बत्तन्ित प्रमिु\nत्तजल्ला अधिकारी िा धनजले तोके को अधिकृ तस्तरको कमचय ारीबाट अनसु न्िान िनु ेछ।\n(८) उपदफा (७) बमोत्तजम तोवकएको अधिकारीले त्र्स्तो कसूरको अनसु न्िान\nगदाय उपदफा (२), (३), (४), (५) र (६) मा उत्तल्लत्तित कार्वयिधि पूरा गन यु पनेछ।\n(९) र्स पररच्छेद बमोत्तजम एकै िारदातको अनसु न्िान गदाय त्र्स्तो िारदातबाट\nचल्न सक्ने सबै मद्दु ाको एकै पटक अनसु न्िान गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९", "title": "कसूरसगँ सम्बत्तन्ित व्र्त्ति पक्राउ गन य सवकनाःे (१) कसूरसँग सम्बत्तन्ित कुनै व्र्त्ति", "content": "फे ला परेमा िा कसूर गदाय गदैको अिस्थामा रिेमा धनजलाई प्रिरी िा अनसु न्िान\nअधिकारीले पक्राउ गन य सक्नेछ।\n(२) कुनै व्र्त्तिलाई कसूरको अनसु न्िानको धसलधसलामा र्स पररच्छेद बमोत्तजम\nतत्कालै पक्राउ गन यु पने िएमा त्र्सको कारण िलु ाई सम्िि िएसम्म पक्राउ गन यु पने\nव्र्त्तिको पविचान िल्ु ने वििरण सवित पक्राउ पूजी जारी गने अनमु धतको लाधग मद्दु ा िेने\nअधिकारी समि धनिेदन ठदन ु पनेछ।\n(३) उपदफा (२) बमोत्तजम धनिेदन परेमा र पक्राउ गन यु पने कारण मनाधसब\nदेत्तिएमा मद्दु ा िेने अधिकारीले सोिी धनिेदनमा पक्राउ पूजी जारी गने अनमु धत ठदन\nसक्नेछ।\n(४) पक्राउ पूजीको ढाँचा अनसु ूची-८ मा उल्लेि िए बमोत्तजम िनु ेछ।\n(५) उपदफा (३) बमोत्तजमको आदेश पक्राउ गन यु पने व्र्त्ति पक्राउ नपरेसम्म\nसािजय धनक गररने छैन।\n(६) उपदफा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन कसूर गने व्र्त्ति\n\nतत्काल पक्राउ निएमा त्र्स्तो व्र्त्ति िाग्ने उम्कने िा धनजले प्रमाण, दसी िा सबूद\nनष्ट गने मनाधसब कारण िएमा त्र्स्तो व्र्त्तिलाई अनसु ूची-९ बमोत्तजमको ढाचँ ामा\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n12\nwww.lawcommission.gov.np\nतत्कालै जरुरी पक्राउ पूजी जारी गरी पक्राउ गरी स्िीकृ धतको लाधग पक्राउ परेको\nव्र्त्ति सवित मद्दु ा िेने अधिकारी समि पेश गन यु पनेछ।\n(७) उपदफा (६) बमोत्तजम जरुरी पक्राउ पूजी जारी गरी कुनै व्र्त्ति पक्राउ\nिएकोमा मद्दु ा िेने अधिकारीबाट स्िीकृ धत प्राप् त नगरी त्र्स्तो कसूरसँग सम्बत्तन्ित अन्र्\nअनसु न्िान सम्बन्िी कारबािी गन य सवकने छैन।\n\nतर कसूरसँग सम्बत्तन्ित सबूद प्रमाण नष्ट िनु े, िराउने िा नाधसने सम्िािना\nिएमा पक्राउ गररएको व्र्त्तिको शरीर, धनजले प्रर्ोग गरेको त्तचजिस्त,ु सिारी सािन, धनज\nरिे बसेको घर िा स्थानको तत्काल िानतलासी धलन सवकनेछ। त्र्सरी िानतलासी\nधलएकोमा त्र्सको वििरण, िानतलासी पूजी तथा बरामदी मचु ल्ु का समेत संलग्न रािी\nमद्दु ा िेने अधिकारी समि पेश गन यु पनेछ।\n(८) कुनै कसूर िएको बित तत्काल प्रिरी उपलब्ि निएमा कसूर गदायका\nबित उपत्तस्थत िएको िा कसूर िएको देख्न े व्र्त्तिले त्र्स्तो कसूर गने व्र्त्तिलाई िाग्न\nिा उम्कन नठदई धनजलाई नत्तजकको प्रिरी कार्ायलर्मा बझु ाउन सक्नेछ।\n(९) उपदफा (१) िा (६) बमोत्तजम कुनै व्र्त्तिलाई पक्राउ गन यु पदाय धनजलाई\nपक्राउ गनअयु त्तघ पक्राउ गन यु पने कारण िलु ाई सम्झाई बझु ाई आत्मसमपणय गने आदेश\nठदन ु पनेछ।\n(१०) उपदफा (९) बमोत्तजम सम्झाउँदा, बझु ाउँदा िा आदेश ठदँदा पधन कुन ै\nव्र्त्तिले आत्मसमपणय नगरी पक्राउबाट बच्ने िा िाग्ने िा उम्कने प्रर्त्न गरेमा िा बल\nप्रर्ोग गरी िा नगरी कुनै वकधसमले जोर जलु मु गरेमा िा गन य प्रर्त्न गरेमा धनजलाई\nपक्राउ गन य प्रिरी कमचय ारीले आिश्र्क बल प्रर्ोग गन य सक्नेछ।\n(११) र्स दफा बमोत्तजम कुनै मविलालाई पक्राउ गन यु परेमा र्थासम्िि मविला\nप्रिरीद्वारा पक्रन लगाउन ु पनेछ।\nतर पक्राउ गन यु पने अिस्थामा तत्काल मविला प्रिरी उपलब्ि निएमा धनजको\nइज्जत िा प्रधतष्ठामा आचँ नआउने गरी मविलाको शारीररक संिेदनत्तशलताको सम्मान गदै\nपरुु ष प्रिरी कमचय ारीले पक्राउ गन य िािा पने छैन।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n13\nwww.lawcommission.gov.np\n(१२) र्स दफा बमोत्तजम पवक्रएको व्र्त्तिको िानतलासी िा शरीर तलासी धलन\nसवकनेछ।\n(१३) र्स दफा बमोत्तजम पक्राउ गन यु पने व्र्त्ति कुनै घर िा िाउँमा बसेको छ\nिन् न े शङ्का गन यु पने मनाधसब कारण िएमा त्र्स्तो घर िा िाउँको िानतलासी धलई\nपक्राउ गन य सवकनेछ।\n(१४) उपदफा (१३) बमोत्तजम िानतलासी धलँदा कुनै व्र्त्ति पक्राउ परेमा सो\nव्र्त्तिको शरीरको तलासी पधन धलन सवकनेछ।\n(१५) उपदफा (१२) िा (१३) बमोत्तजम तलासी धलँदा फे ला परेका प्रमाण\nसम्बन्िी धलित िा दसी प्रमाण िा अन्र् कुनै िस्त ु त्र्स्तो व्र्त्तिलाई पक्राउ गने व्र्त्ति\nिा अनसु न्िान अधिकारीले आफ्नो कब्जामा धलई त्र्सको िरपाई ठदन ु पनेछ।\n\n(१६) उपदफा (१) र (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन अनसु ूची-\n१ िा अनसु ूची-२ अन्तगतय का कुनै कसूर कुनै व्र्त्तिले कुनै प्रिरी कमचय ारी िा\nअधिकारीको उपत्तस्थधतमा िा कुनै सरकारी कार्ायलर्मा गरेमा त्र्स्तो व्र्त्तिलाई\nसम्बत्तन्ित प्रिरी कमचय ारी, अधिकारी िा कार्ायलर् प्रमिु ले िाग्न उम्कन नठदई धनजलाई\nपक्राउ गरी सम्बत्तन्ित प्रिरी कार्ायलर् िा अनसु न्िान अधिकारी समि बझु ाउन ु पनेछ।\n\n(१७) उपदफा (८) र (१६) बमोत्तजम पक्राउ गरी ल्र्ाएको व्र्त्तिलाई\nसम्बत्तन्ित प्रिरी िा अनसु न्िान अधिकारीले जरुरी पक्राउ पूजी ठदई उपदफा (६)\nबमोत्तजम स्िीकृ धतको लाधग मद्दु ा िेने अधिकारी समि पेश गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०", "title": "प्रारत्तम्िक अनसु न्िान प्रधतिदे न पिाउनाःे (१) अनसु ूची-१ िा अनसु ूची-२ मा उत्तल्लत्तित", "content": "कुनै कसूरको जािेरी दरिास्त िा सूचना दफा ४ बमोत्तजम दताय िनु ासाथ त्र्स्तो कसूरको\nअनसु न्िान गन य तोवकएका प्रिरी कमचय ारी िा अनसु न्िान अधिकारीले तरुु न्त प्रारत्तम्िक\nअनसु न्िान गन यु पनेछ।\n(२) उपदफा (१) बमोत्तजम प्रारत्तम्िक अनसु न्िान शरुु गरेपधछ त्र्स्तो प्रिरी\nकमचय ारी िा अनसु न्िान अधिकारीले सोको प्रधतिेदन त्तजल्ला सरकारी िवकल कार्ायलर्मा\nतीन ठदनधित्र पिाउन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n14\nwww.lawcommission.gov.np\nस्पष्टीकरणाः र्स पररच्छेदको प्रर्ोजनको लाधग “प्रारत्तम्िक अनसु न्िान” िन् नाले घटनास्थल\nवििरण, कसूर िएको स्थानको िस्तत्तुस्थधत मचु ल्ु का, िानतलासी िा बरामदी मचु ल्ु का िा\nज्र्ान मरेको कसूर िए लास जाँच मचु ल्ु का तथा अन्र् कसूर िए त्र्स्तो कसूरको प्रकृ धत\nअनसु ार तर्ार गन यु पने प्रधतिेदन, मचु ल्ु का िा अन्र् आिश्र्क वििरणलाई सम्झन ु पछय।\n(३) उपदफा (१) बमोत्तजम प्रारत्तम्िक प्रधतिेदन प्राप्त िएपधछ सरकारी िवकलले\nत्र्सको अध्र्र्न गरी कसूरसँग सम्बत्तन्ित कुनै विषर्मा थप अनसु न्िान गन य अनसु न्िान\nअधिकारीलाई आिश्र्क धनदेशन ठदन ु पने देत्तिएमा त्र्सको कारण िलु ाई आिश्र्क\nधनदेशन ठदन सक्नेछ।\n(४) उपदफा (३) बमोत्तजम ठदएको धनदेशनको पालना गन यु सम्बत्तन्ित अनसु न्िान\nअधिकारीको कतव्य र् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११", "title": "भ्रमपूण,य झठ्ठु ा िा काल्पधनक सूचनालाई तामेलीमा रातन सवकनाःे (१) अनसु ूची-१ िा", "content": "अनसु ूची-२ मा उत्तल्लत्तित कुनै कसूरको सम्बन्िमा प्राप् त जािेरी दरिास्त िा सूचनाका\nसम्बन्िमा सम्बत्तन्ित व्र्त्ति िा जािेरिाला समेतलाई बिु m्दा त्र्स्तो दरिास्त िा सूचना\nभ्रमपूण,य झठ्ठु ा िा काल्पधनक िई अनसु न्िान गन य आिश्र्क निएमा िा धनरथकय देत्तिएमा\n\nसम्बत्तन्ित प्रिरी कार्ायलर् िा सम्बत्तन्ित अनसु न्िान अधिकारीले सोिी कुरा िलु ाई\nसामान्र्तर्ा तीन ठदनधित्र सम्बत्तन्ित सरकारी िवकल कार्ायलर्मा प्रधतिेदन पिाउन ु\nपनेछ।\n(२) उपदफा (१) बमोत्तजम प्रधतिेदन प्राप् त िएपधछ सम्बत्तन्ित सरकारी िवकल\nकार्ायलर्ले त्र्स्तो कसूरको सम्बन्िमा तत्काल अनसु न्िान गन य मनाधसब आिार\nनदेत्तिएमा त्र्सको कारण िलु ाई थप प्रमाण प्राप् त िनु आएका बित अनसु न्िान गन य\nसवकने गरी तत्काल तामेलीमा रात ने िा िारदातको प्रकृ धत अध्र्र्न गदाय तत्काल\nअनसु न्िान गन य उपर्िु िनु े देिेमा कारण िलु ाई थप अनसु न्िान गन य अनसु न्िान\nअधिकारीलाई धनदेशन ठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजम सरकारी िवकल कार्ालय र्ले अनसु न्िान गन य धनदेशन\nठदएमा सम्बत्तन्ित अनसु न्िान अधिकारीले त्र्स्तो कसूरका सम्बन्िमा अनसु न्िान गन यु\nपनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n15\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२", "title": "अनसु न्िान गन य विशषे टोली गिन गन य सवकनाःे (१) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा", "content": "लेत्तिएको िए तापधन र्स ऐनको अनसु ूची-१ िा अनसु ूची-२ मा उत्तल्लत्तित कुनै कसूरको\nसम्बन्िमा कसूरको गम्िीरता िेरी सम्बत्तन्ित अनसु न्िान अधिकारीबाट मात्र अनसु न्िान\nिनु नसक्ने िई छुटैृ अनसु न्िान टोली गिन गन य उपर्िु िनु े कुरा अनसु न्िान\nअधिकारीको तालकु िाला अधिकारी िा प्रिरी मिाधनरीिकलाई लागेमा धनजले आफू\nमातितका कमचय ारीिरु संलग्न रिने गरी अनसु न्िान टोली गिन गन य सक्नेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन आफू मातितका\nकमचय ारी बािेकका अन्र् व्र्त्ति समेत संलग्न रिेको अनसु न्िान टोली गिन गन यु परेमा\nत्र्स्तो अनसु न्िान अधिकारीको तालकु िाला अधिकारी िा प्रिरी मिाधनरीिकले त्र्स\nसम्बन्िमा मिान्र्ार्ाधिििाको परामश य धलई विशेषज्ञ समेत रिेको अनसु न्िान टोली गिन\nगरी अनसु न्िान गराउन सक्नेछ।\n(३) उपदफा (१) िा (२) बमोत्तजम अनसु न्िान टोली गिन िएमा त्र्स्तो\nटोलीले र्स पररच्छेद बमोत्तजम अनसु न्िान अधिकारीलाई िएको अधिकार प्रर्ोग गरी\nअनसु न्िान गनेछ।\n(४) उपदफा (१) िा (२) बमोत्तजम अनसु न्िान टोली गिन िएकोमा सम्बत्तन्ित\nअनसु न्िान अधिकारीले गरेको अनसु न्िान सम्बन्िी वििरण त्र्स्तो टोलीलाई िस्तान्तरण\nगन यु पनेछ।\n(५) उपदफा (१) िा (२) बमोत्तजम गिन िएको अनसु न्िान टोलीले अनसु न्िान\nगरी आफ्नो प्रधतिेदन सम्बत्तन्ित सरकारी िवकल समि पेश गरी त्र्सको जानकारी\n\nसम्बत्तन्ित प्रिरी कार्ालय र् िा अनसु न्िान गन य अधिकारप्राप् त कार्ायलर् िा अधिकारीलाई\nसमेत ठदन ु पनेछ।\n(६) उपदफा (५) बमोत्तजम प्रधतिेदन प्राप् त िएपधछ सरकारी िवकलले कसूरसँग\nसम्बत्तन्ित कुनै विषर्मा थप अनसु न्िान गन य आिश्र्क धनदेशन ठदनपु ने देत्तिएमा सोको\nकारण िलु ाई अनसु न्िान टोलीलाई आिश्र्क धनदेशन ठदन सक्नेछ।\n(७) उपदफा (६) बमोत्तजम सरकारी िवकलले ठदएको धनदेशन पालना गन यु\nसम्बत्तन्ित अनसु न्िान टोलीको कतव्य र् िनु ेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n16\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३", "title": "विरासतमा रातन :े (१) र्स पररच्छेद बमोत्तजम पक्राउ िएको व्र्त्तिलाई विरासतमा रात न ु", "content": "पनेछ।\n(२) उपदफा (१) बमोत्तजम विरासतमा रातदा त्र्स्तो व्र्त्तिलाई पक्राउ गररएको\nिाउँ उल्लेि गरी विरासतमा रात नपु ने कारण सवितको अनसु ूची-१० बमोत्तजमको ढाँचामा\nथनु िु ा पूजी ठदएर मात्र विरासतमा रात न ु पनेछ।\n(३) उपदफा (१) बमोत्तजम कुनै व्र्त्तिलाई विरासतमा रात्तिएकोमा धनजको नाम,\nथर, उमेर, टोल सवितको िेगाना, बाब,ु आमाको नाम, धनजको नागररकताको प्रमाणपत्र िा\nधनजको पविचान िल्ु ने अन्र् पररचर्पत्र िए त्र्स्तो प्रमाणपत्र िा पररचर्पत्र र निए\nसिारी चालक इजाजतपत्र, रािदानी, धनजको टेधलफोन िए टेधलफोन नम्बर लगार्त\nधनजको िास्तविक पररचर् िल्ु ने र्स्तै कागजातको प्रधतधलवप समेत धलई धनजको अधिलेि\nतर्ार गन यु पनेछ।\n(४) उपदफा (३) को प्रर्ोजनको लाधग अनसु न्िान अधिकारीले आिश्र्कता\nअनसु ार धनजको तस्िीर र दिु ै िातको ित्के ला सवितको औिँ ा छाप समेत धलन\nसक्नेछ।\n(५) उपदफा (३) बमोत्तजम अधिलेि तर्ार िएपधछ सम्बत्तन्ित प्रिरी कार्ायलर्\nिा अनसु न्िान अधिकारीले त्र्स्तो अधिलेिको आिारमा विरासतमा रिेको व्र्त्तिले\nजानकारी ठदन अनरु ोि गरेको व्र्त्तिलाई धनज विरासतमा रिेको जानकारी ठदन ु पनेछ।\n(६) र्स दफा बमोत्तजम पक्राउ गररएको व्र्त्तिले कानून व्र्िसार्ीसँग सल्लाि\nधलन चािेमा अनसु न्िान अधिकारीले धनजलाई त्र्स्तो कानून व्र्िसार्ीसँग सल्लाि धलन\nठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४", "title": "अनसु न्िानको लाधग विरासतमा रातन सवकन े अिधि र तत्सम्बन्िी कार्वयिधिाः (१) कुन ै", "content": "व्र्त्तिलाई कसूरको अनसु न्िानको लाधग र्स पररच्छेद बमोत्तजम पक्राउ गरेपधछ चौबीस\nघण्टाधित्र जधतसक्दो चाँडो मद्दु ा िेने अधिकारी समि उपत्तस्थत गराउन ु पनेछ।\n(२) उपदफा (१) विपरीत िनु े गरी कसैलाई विरासतमा रात न सवकने छैन।\n(३) कुनै व्र्त्तिलाई उपदफा (१) मा लेत्तिएको म्र्ादिन्दा बढी विरासतमा\nरात न ु परेमा अनसु न्िान अधिकारीले त्र्सको आिार र कारण िलु ाई सरकारी िवकल\nकार्ायलर् माफय त मद्दु ा िेने अधिकारी समि अनमु धतको लाधग धनिेदन ठदन ु पनेछ।\n17\nwww.lawcommission.gov.np\nस्पष्टीकरणाः र्स दफाको प्रर्ोजनको लाधग चौबीस घण्टाको अिधिधित्र पक्राउ परेको\nव्र्त्तिलाई मद्दु ा िेने अधिकारी समि उपत्तस्थत गराउनको लाधग पक्राउ गररएको िाउँबाट\n \nप्रिरी कार्ायलर् िा अनसु न्िान गन य अधिकार प्राप् त कार्ायलर्मा ल्र्ाउन िा प्रिरी\nकार्ायलर् िा अनसु न्िान गन य अधिकार प्राप् त कार्ालय र्बाट अदालतमा प¥ुर्ाउन बाटोमा\nलाग्ने अिधिलाई गणना गररने छैन।\n(४) अनसु न्िान अधिकारीले मद्दु ा िेने अधिकारी समि उपदफा (३) बमोत्तजम\nधनिेदन ठदँदा विरासतमा रिेको व्र्त्ति उपर लागके ो अधिर्ोग, त्र्सको आिार, धनजलाई\nविरासतमा रािी अनसु न्िान गन यु पने कारण र धनजको बर्ान िइसके को िए बर्ान\nकागज अनसु ारको व्र्िोरा स्पष्ट रुपमा उल्लेि गन यु पनेछ।\n(५) उपदफा (३) बमोत्तजम विरासतमा रात ने अनमु धतको लाधग उपत्तस्थत\nगराइएको व्र्त्तिले चािेमा आफ्नो शारीररक जाँच गरी पाउनका लाधग मद्दु ा िेने अधिकारी\nसमि धनिेदन ठदन सक्नछे ।\n(६) अनसु न्िान अधिकारीले कुनै व्र्त्तिलाई उपदफा (३) बमोत्तजम विरासतमा\nरात ने अनमु धत माग गरेकोमा मद्दु ा िेने अधिकारीले सम्बत्तन्ित कागजातिरु िेरी\nअनसु न्िान सन्तोषजनक रुपमा िएको िा निएको विचार गरी, आिश्र्क देत्तिए\nसम्बत्तन्ित कानून व्र्िसार्ीको बिस समेत सनु ी अनसु न्िानको लाधग विरासतमा रािी\nरात न आिश्र्क िएको देत्तिएमा एकै पटक िा पटकपटक गरी बढीमा पच्चीस ठदनसम्म\nविरासतमा रात ने आदेश ठदन सक्नेछ।\n(७) उपदफा (६) मा जनु सकु ै कुरा लेत्तिएको िए तापधन अनसु ूची-१ अन्तगतय को\nकसूरमध्र्े राष्ट्रपधत उपरको आक्रमण, जासूसी, सैधनक िड्काउने, नेपाल राज्र् विरुद्ध र्द्धु\nगने िा नेपालसँग र्द्धु मा संलग्न राज्र्का सेनालाई सिर्ोग गने िा विस्फोटक पदाथ,य\nअपिरण र शरीर बन्िक सम्बन्िी कसूरको अनसु न्िान उपदफा (६) बमोत्तजम ठदएको\nसमर्ािधिधित्र पूरा िनु नसक्ने िन् न े कारण सवितको प्रधतिेदन अनसु न्िान गने अधिकारी\n\nतथा संर्िु रुपमा मद्दु ा िेने अधिकारी समि पेश गन य सक्ने छन।्\n(८) उपदफा (७) बमोत्तजमको प्रधतिेदन पेश िनु आएमा अनसु न्िानको त्तस्थधत\nिेरी मद्दु ा िेने अधिकारीले एकै पटक िा पटकपटक गरी बढीमा थप पन्र ठदनसम्म\nविरासतमा रात ने आदेश ठदन सक्नेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n18\nwww.lawcommission.gov.np\nतर कुनै पधन अधिर्ोग लागेको व्र्त्तिलाई त्र्स्तो अधिर्ोग ििर िएमा धनजलाई\nिनु सक्ने कै दको अिधििन्दा बढी विरासतमा रात न सवकने छैन।\n(९) उपदफा (६) िा (८) बमोत्तजम मद्दु ा िेने अधिकारीले विरासतमा रात न े\nआदेश ठदँदा कारण सवितको पचाय िडा गन यु पनेछ।\n(१०) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन सात मविनािन्दा\nबढी अिधिको गििय ती मविला, बालबाधलका र पचििर िष य नाघेको व्र्त्तिलाई कसूरको\nप्रकृ धत िेरी अनसु न्िान अधिकारीले थनु ामा नरािी अनसु न्िान गन य मनाधसब देिेमा सोको\nकारण िलु ाई पचाय िडा गरी ताररिमा रािी अनसु न्िान गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५", "title": "विरासतमा रिेको व्र्त्तिलाई अनसु न्िान अधिकारीले छाड्न सक्नाःे (१) र्स ऐन बमोत्तजम", "content": "अनसु न्िानको धसलधसलामा विरासतमा रिेको कुनै व्र्त्तिलाई विरासतमा रात्तिरिन ु\nआिश्र्क िा उपर्िु नदेत्तिएमा अनसु न्िान अधिकारीले सरकारी िवकलको सिमधत धलई\nिा तत्काल त्र्स्तो सिमधत धलन सवकने अिस्था निएमा कारण सवितको पचाय िडा गरी\nत्र्स्तो व्र्त्तिबाट िरौट िा जमानत धलई िा धनजलाई कुनै माथिर व्र्त्तिको त्तजम्मामा\nिात्तजर जमानीमा छाड्न िा ताररिमा रात न सक्नेछ।\n(२) उपदफा (१) बमोत्तजम िरौट िा जमानीमा छाड्दा िा ताररिमा रातदा\nत्र्सरी छोधडएको िा ताररिमा रात्तिएको व्र्त्ति उपर मद्दु ा चलाउने िएमा त्र्स्तो\nअिस्थामा धनज उपत्तस्थत िनु े गरी धनजको कागज गराउन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम िात्तजर जमानी ठदने व्र्त्तिले िात्तजर जमानीमा\nछोधडएको व्र्त्तिलाई अनसु न्िान अधिकारी िा सरकारी िवकल कार्ायलर्ले तोके को\nसमर्मा उपत्तस्थत गराउन ु पनेछ।\n(४) उपदफा (३) बमोत्तजम तोके को समर्मा त्र्स्तो माधनस उपत्तस्थत नगराएमा\n\nिात्तजर जमानी ठदने व्र्त्तिलाई अनसु न्िान गने अधिकारीले पचास िजार रुपैर्ाँसम्म\nजररबाना गन य सक्नेछ।\n(५) उपदफा (१) बमोत्तजम ताररिमा रािी अनसु न्िान गरेकोमा अनसु न्िान\nअधिकारीले त्र्सको जानकारी सरकारी िवकल र माधथल्लो प्रिरी कार्ायलर्लाई ठदन ु\nपनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n19\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६", "title": "बर्ान धलन े र सोिपछू गनेाः (१) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय का कसूरको", "content": "सम्बन्िमा अनसु न्िान अधिकारीले सरकारी िवकल समि अधिर्िु को बर्ान धलनेछ।\n(२) उपदफा (१) बमोत्तजम बर्ान धलँदा कसूरको सम्बन्िमा िलु ाउन ु पने\nआिश्र्क कुरा सोध्ने अधिकार सरकारी िवकललाई िनु ेछ।\n(३) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय का कुनै कसूरको सम्बन्िमा कुन ै\nमित्िपूण य कुरा थािा छ िन् ने विश्वास गन यु पने मनाधसब कारण िएको व्र्त्तिसँग\nअनसु न्िान अधिकारीले आिश्र्क सोिपछु गन य सक्नेछ।\nतर बालबाधलका िा शारीररक रुपमा असमथ य िएको व्र्त्तिसँग सोिपछु गन यु\nपरेमा धनज रिे बसेकै िाउँमा नै गई सोिपछु गन य सवकनेछ।\nस्पष्टीकरणाः र्स दफाको प्रर्ोजनको लाधग “शारीररक रुपमा असमथ”य िन् नाले विँडडलु\nगन य नसक्ने, दृवष्टवििीन, िद्धृ अिस्था जस्ता शारीररक रुपमा असमथ य व्र्त्तिलाई सम्झन ु\nपछय।\n(४) उपदफा (३) बमोत्तजम सोिपछु गरेकोमा अनसु न्िान अधिकारीले त्र्सरी\nसोिपछु गरेको कुरा अनसु ूची-११ बमोत्तजमको ढाँचामा लेिबद्ध गरी सम्बत्तन्ित धमधसलमा\nरात न ु पनेछ।\n(५) र्स दफा बमोत्तजम बालबाधलका िा शारीररक रुपमा असमथ य व्र्त्तिबाट कुन ै\nकागज गराउन ु पने िएमा धनजको संरिक िा उपलब्ि अन्र् व्र्त्तिको रोििरमा गराउन ु\nपनेछ।\n(६) र्स दफा बमोत्तजम बर्ान िा सोिपछु गन यु पने कुनै व्र्त्ति शारीररक\nअस्िस्थताको कारणले अनसु न्िान अधिकारी समि उपत्तस्थत िनु नसक्ने िएमा िा\nत्र्स्तो व्र्त्तिको सरु िाको कारणले धनजलाई त्र्स्तो अधिकारी समि उपत्तस्थत गराउन\nउपर्िु नदेत्तिएमा अनसु न्िान अधिकारीले श्रव्र् दृष्र् सम्िाद (धिधडर्ो कन्फरेन्स) को\nमाध्र्मबाट त्र्स्तो व्र्त्तिसँग बर्ान धलन िा सोिपछु गन य सक्नेछ।\n(७) उपदफा (६) बमोत्तजम बर्ान धलएको िा सोिपछु गरेकोमा अनसु न्िान\nअधिकारीले सोको अधिलेि रात ने व्र्िस्था गन यु पनेछ।\n20\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७", "title": "सोधिएको प्रश्न को जिाफ ठदन ु पनेाः अनसु न्िान अधिकारीले र्स पररच्छेद बमोत्तजम कुनै", "content": "कसूरको सम्बन्िमा अनसु न्िान गदाय सोिेको प्रश्न को जाने सम्मको जिाफ ठदई\nसम्बत्तन्ित व्र्त्तिले अनसु न्िानमा सिर्ोग गन यु पनेछ।\nतर आफू उपर कुनै कसूरको अधिर्ोग लाग्न सक्ने वकधसमको जिाफ ठदन कुन ै\nव्र्त्तिलाई कर लाग्ने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८", "title": "िानतलासी गन य सवकनाःे (१) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय को कुनै कसूरको", "content": "अनसु न्िान गदाय त्र्स्तो कसूरसँग सम्बत्तन्ित कुनै धलित, दसी प्रमाण, अधिर्िु िा अन्र्\nकुनै व्र्त्ति कुनै िाउँमा छ िन् ने कुरा शङ्का गन यु पने मनाधसब कारण िएमा अनसु न्िान\nअधिकारीले त्र्स्तो व्र्त्ति िा िाउँको िानतलासी धलन र त्र्स्तो धलित िा दसी प्रमाण\nबरामद गन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम िानतलासी धलनअु त्तघ िानतलासी गने घरमा तत्काल\nबसोबास गरररिेको व्र्त्तिलाई िानतलासी धलन ु पनायको कारण सवितको धलत्तित सूचना\nअनसु ूची-१२ बमोत्तजमको ढाँचामा ठदन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम िानतलासी धलँदा अनसु ूची-१३ बमोत्तजमको ढाँचामा\nमचु ल्ु का िडा गरी िानतलासी धलन ु पनेछ।\n(४) उपदफा (१) बमोत्तजम िानतलासी गन य त्र्स्तो िाउँमा प्रिेश गनअयु त्तघ\nअनसु न्िान अधिकारीले सम्बत्तन्ित घरिनी िा व्र्त्तिलाई आफ्नो समेत तलासी ठदन ु\nपनेछ।\n(५) उपदफा (१) बमोत्तजम िानतलासी गदाय मविला मात्र रिने िा बस्ने गरेको\nघर कोिाको िानतलासी धलन ु परेमा सम्िि िएसम्म अन्र् मविलालाई समेत साथमा\nधलई घरधित्र प्रिेश गरी िानतलासी धलन ु पनेछ।\nतर कुनै मविलाको शरीरको तलासी धलन ु पदाय मविला प्रिरी िा त्र्स्तो मविला\nप्रिरी तत्काल उपलब्ि निएमा अन्र् कुनै मविलाद्वारा तलासी धलन लगाउन सवकनेछ।\n(६) िानतलासी धलँदा प्राप् त िएको कसूरसँग सम्बत्तन्ित िस्तकु ो वििरण, त्र्स्ता\nिस्त ु पाइएको िाउँ र अिस्था िलु ाई िानतलासी धलने कमचय ारीले दईु प्रधत मचु ल्ु का\nतर्ार गरी एक प्रधत सम्बत्तन्ित व्र्त्तिलाई ठदई एक प्रधत धमधसलमा सामेल रात न ु पनेछ।\n21\nwww.lawcommission.gov.np\n(७) िानतलासी धलन ु पने व्र्त्ति िा िाउँ अन्र् प्रिरी कार्ायलर्को िेत्रधित्र पने\nिएमा अनसु न्िान अधिकारीले त्र्स्तो प्रिरी कार्ालय र् समि त्र्स्तो व्र्त्ति िा िाउँको\nिानतलासी धलन धलत्तित अनरु ोि गन य सक्नेछ।\n(८) उपदफा (७) बमोत्तजम अनरु ोि िएकोमा त्र्स्तो प्रिरी कार्ायलर्को कम्तीमा\n\nप्रिरी नार्ब धनरीिकले त्र्स्तो व्र्त्ति िा िाउँको िानतलासी धलई उपदफा (३)\nबमोत्तजमको मचु ल्ु का तर्ार गरी त्र्सरी अनरु ोि गने अधिकारी समि पिाउन ु पनेछ।\n(९) उपदफा (७) मा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्तो प्रिरी\nकार्ायलर्मा धलत्तित अनरु ोि गदाय कुनै प्रमाण लोप िा नास िनु े सम्िािना छ िन् ने\nलागेमा अनसु न्िान अधिकारी आफैँ िानतलासी धलन ु पने व्र्त्ति िएको िाउँ िा स्थानमा\nगई र्स दफा बमोत्तजम िानतलासी धलन सक्नेछ र त्र्सको सूचना सम्बत्तन्ित कार्ायलर्\nिा प्रिरी कार्ायलर्लाई ठदन ु पनेछ।\n(१०) र्स दफा बमोत्तजम िानतलासी धलने अधिकारीले िानतलासीबाट प्राप् त\nकसूरसँग सम्बत्तन्ित कुनै िस्त ु आफ्नो साथमा लैजान चािेमा सम्बत्तन्ित व्र्त्तिलाई\nत्र्सको िरपाई ठदएर मात्र लैजान ु पनेछ।\n(११) कुनै िाउँको तत्काल िानतलासी नधलएमा कसूरसँग सम्बत्तन्ित दसी\nप्रमाण लोप िा नास िनु सक्ने िा शङ्कास्पद व्र्त्ति िाग्न िा उम्कन सक्ने विश्वास गन यु\nपने मनाधसब कारण िएकोमा बािेक कसैको घरको तलासी धलन ु परेमा सूर्ोदर्देत्ति\nसूर्ायस्त िनु अु त्तघसम्मको समर्धित्र धलन ु पनेछ।\n(१२) र्स दफा बमोत्तजम िानतलासी धलन े अधिकारी िानतलासी धलन कुनै घर\nिा कुनै िाउँमा प्रिेश गदाय सो घर िा िाउँको स्िाधमत्ि िएको िा त्र्स्तो घर िा\nिाउँको िेरविचार गने त्तजम्मा धलएको िा तत्काल बसोबास गरररिेको व्र्त्तिले धनजलाई\nत्र्स्तो घर िा िाउँमा प्रिेश गन य ठदन ु पनेछ र त्र्सरी प्रिेश गन य नठदएमा िानतलासी\nधलने अधिकारीले सो घर िा िाउँको िm्र्ाल, ढोका, छाना, धििा इत्र्ाठदमध्र्े प्रिेश गन य\nआिश्र्क िनु ेसम्म ित्काई िा फुटाई िा ताल्चा लगाएकोमा ताल्चा समेत फोडी\nसके सम्म कम िाधन, नोक्सानी िनु े गरी धित्र प्रिेश गन य सक्नेछ।\n(१३) कुनै घर िा िाउँको र्स दफा बमोत्तजम िानतलासी धलइसके पधछ\nिानतलासी धलन धित्र गएको व्र्त्ति बाविर धनस्कन िोज्दा कुनै कारणिश सािारण\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n22\nwww.lawcommission.gov.np\nरुपमा बाविर धनस्कन नसके मा धनजले त्र्स्तो घर िा िाउँको िm्र्ाल, ढोका, छाना, धििा\nइत्र्ाठदमध्र्े बाविर धनस्कन आिश्र्क पने कुनै िाउँ सके सम्म कम िाधन, नोक्सानी िनु े\nगरी ित्काई िा फुटाई बाविर धनस्कन सक्नेछ।\n(१४) िानतलासी गने अधिकारी र िानतलासीको काममा धनजलाई मद्दत गन य\nिवटएका अन्र् कमचय ारी तथा दफा १६ को उपदफा (५) बमोत्तजम रोििरमा रिेका\nव्र्त्तििरुले आफू ले लगाएको लगु ा र िानतलासीको काममा उपर्ोग गररने िस्त ु बािेक\nअरु कुनै िस्त ु साथमा रात न पाइने छैन र सम्बत्तन्ित व्र्त्तिले चािेमा िानतलासीको\nकाम शरुु िनु िु न्दा पविले नै त्र्स्तो कुनै अधिकारी, कमचय ारी िा रोिबरमा रिने व्र्त्तिको\nशरीरको तलासी धलन सक्नेछ।\n(१५) र्स दफा बमोत्तजम कुनै व्र्त्ति, घर िा िाउँको िानतलासी धलन पाउन े\nअधिकारीले िानतलासी धलनअु त्तघ सम्बत्तन्ित घर िनी, िाउँ िनी िा व्र्त्तिलाई धनज\nिानतलासी धलन पाउने अधिकार प्राप् त अधिकारी िएको पररचर् पत्र देिाउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९", "title": "मचु ल्ु का िडा गदा य रोििरमा रातन ु पनेाः (१) कुनै कसूर िएकोमा अनसु न्िान अधिकारीले", "content": "त्र्स्तो कसूरको िारदातको िास्तविक र र्थाथ य तथ्र् त्तचत्रण िनु े गरी घटनास्थल\nमचु ल्ु का तर्ार गदाय दफा ८ को उपदफा (२), (३) र (४) बमोत्तजम गन यु पनेछ।\n(२) उपदफा (१) बमोत्तजम घटनास्थल मचु ल्ु का तर्ार गदाय िा कुनै व्र्त्ति िा\nिस्त ु िा िाउँको िानतलासी धलँदा िा ज्र्ान मरेको कसूर िएकोमा लाश जाचँ गदाय िा\nअन्र् कुनै कसूर िएकोमा त्र्स्तो कसूरको प्रकृ धत अनसु ार आिश्र्क मचु ल्ु का िडा गदाय\nत्र्स्तो िाउँमा तत्काल उपलब्ि कम्तीमा दईु जना स्थानीर् व्र्त्ति र स्थानीर् तिका\nएक जना सदस्र् िा त्र्स्तो सदस्र् उपलब्ि निए कुनै सरकारी कार्ालय र्को एक जना\nकमचय ारी िए धनजलाई र फे ला परेसम्मका अधिर्िु र कसूरको सूचना ठदने व्र्त्तिलाई\nसमेत रोििरमा रात न ु पनेछ।\nतर अधिर्िु िा कसूरको सूचना ठदने व्र्त्ति रोििरमा नरािेको कारणले मात्र\nत्र्स्तो घटनास्थल मचु ल्ु का िेररतको िएको माधनने छैन।\n(३) कुनै व्र्त्तिको स्िाधमत्ि िा त्तजम्मामा रिेको कुनै िाउँको िानतलासी धलँदा\nउपलब्ि िएसम्म त्र्स्तो व्र्त्तिलाई समेत रोििरमा रात न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२०", "title": "लाश जाचँ गन यु पनेाः (१) कुनै व्र्त्ति कसैको कतव्य र्बाट िा कुनै दघु टय ना िई िा", "content": "आत्मित्र्ा गरी िा अस्ििाविक रुपमा िा अन्र् कुनै शङ्कास्पद त्तस्थधतमा मरेको जानकारी\n23\nwww.lawcommission.gov.np\nप्राप् त िएमा अनसु न्िान अधिकारीले तरुु न्त लाश रिेको िाउँमा गई लाश जाँच गन यु\nपनेछ।\n(२) उपदफा (१) बमोत्तजम लाश जाँच गदाय र्थासम्िि धनम्नधलत्तित कुरािरु\nसमेत िलु ाई अनसु ूची-१४ बमोत्तजमको ढाँचामा मचु ल्ु का तर्ार गन यु पनेछ र लाशको\nिास्तविक र्थाथ य त्तचत्रण िनु े गरी लाश र सम्बत्तन्ित िाउँको तत्तस्बर समेत त्तिच्न ु पनेछाः-\n(क) लाशको पररचर्ात्मक वििरण,\n(ि) लाश रिेको िाउँ र लाशको अिस्था,\n(ग) लाशमा कुनै घाउ, चोट, नील िा डाम देत्तिएमा त्र्स्तो घाउ, चोट,\nनील िा डाम देत्तिएको िाउँ, त्र्सको सङ्खतर्ा, लम्िाइ, चौडाइ,\nगविराइ सवितको प्रत्र्ेक घाउ, चोट, नील िा डामको वििरण,\n(घ) िण्ड (ग) मा उल्लेि िएको बािेक मत्ृ र्सु ँग सम्बत्तन्ित सािन र\nलाशमा देिा परेको तत्सम्बन्िी वििरण,\n(ङ) मत्ृ र्कु ो कारण थािा पाउन सिार्ता िनु े लाशमा देत्तिएको अन्र्\nकुनै लिण,\n(च) अन्र् उल्लेिनीर् कुनै कुरा िए सोको वििरण।\n(३) उपदफा (१) बमोत्तजम लाश जाँच गरी सम्बत्तन्ित अनसु न्िान अधिकारीले\nत्र्स्तो लाशलाई शि परीिणको धनधमि सरकारी त्तचवकत्सक िा नेपाल सरकारले तोके का\nविशेषज्ञ िा इजाजत प्राप् त त्तचवकत्सक समि सरकारी िचमय ा पिाउन ु पनेछ।\n(४) उपदफा (३) बमोत्तजम शि परीिण गदाय लाग्ने आिश्र्क िच य नपे ाल\nसरकारले सम्बत्तन्ित प्रिरी कार्ायलर्लाई उपलब्ि गराउन ु पनेछ।\n(५) उपदफा (३) बमोत्तजम गररएको शि परीिण प्रधतिेदन अनसु ूची-१५\nबमोत्तजमको ढाँचामा तर्ार गन यु पनेछ।\n(६) उपदफा (३) मा जनु सकु ै कुरा लेत्तिएको िए तापधन उपदफा (२) बमोत्तजम\nलाश जाँच मचु ल्ु का िइसके पधछ त्र्स्तो लाश जाँचबाट कुनै कसूरको पररणामस्िरुप िा\nशङ्कास्पद त्तस्थधतमा मत्ृ र् ु िएको देत्तिन नआई त्र्स्तो लाशको शि परीिण गराउन\nआिश्र्क नपने ििर् र्ाएमा अनसु न्िान अधिकारीले त्र्सको कारण िलु ाई स्थानीर् िद्र\nिलादमीको रोििरमा पचाय िडा गरी धमधसल संलग्न रात न ु पनेछ।\n24\nwww.lawcommission.gov.np\n(७) लाश सडी गली परीिण गन य नसवकने अिस्थाको िएमा िा देत्तिएमा\nसम्बत्तन्ित अनसु न्िान अधिकारीले त्र्स्तो कुरा िलु ाई स्थानीर् िद्र िलाद्मीको रोििरमा\nमचु ल्ु का िडा गरी रात न ु पनेछ।\nतर लाश सडे गले िा शि परीिण िनु नसक्ने िए तापधन लाश िा त्र्सको कुन ै\nअंशको अन्र् परीिणबाट मत्ृ र्कु ो कारण पिा लगाउन सवकने अिस्था िएमा अन्र्\nिैज्ञाधनक परीिण गराउन सवकनेछ।\n(८) लाशको शि परीिण िइसके पधछ िा उपदफा (६) बमोत्तजम पचाय िडा\nिएपधछ सम्बत्तन्ित प्रिरी कमचय ारीले सम्बत्तन्ित मतृ कको िकिालालाई िरपाई गराई\nलाश बझु ाउन ु पनेछ।\n(९) उपदफा (८) बमोत्तजम िकिालाले लाश बझु ी नधलएमा िा कुनै िकिाला\nउपत्तस्थत निएमा िा िकिाला नै र्वकन निएमा सम्बत्तन्ित प्रिरी कमचय ारीले सरकारी\nिचमय ा लाशको सदगत गराउन ु पनेछ।\n(१०) शि परीिण िा लाश जाँच गदाय िा अन्र् कुनै सिदु प्रमाण सङ्कलन गदाय\nअनसु न्िान अधिकारीले कसूरको गम्िीरता िेरी सम्बत्तन्ित विशेषज्ञ साथमा लैजान उपर्िु\nििर् र्ाएमा त्र्स्तो विशेषज्ञलाई साथमा धलई जान सक्नेछ।\n(११) र्स दफा बमोत्तजम शि परीिण गने विशेषज्ञ िा त्तचवकत्सकलाई कुन ै\nव्र्त्तिको मत्ृ र्कु ो िास्तविक कारण पिा लगाउन िा कसूरको अन्र् कुनै कुरा\nअनसु न्िान गन य एकिन्दा बढी विशेषज्ञिरुको टोलीबाट शि परीिण गराउन पने िन् न े\nलागेमा िा अनसु न्िान अधिकारीलाई कुनै व्र्त्तिको मत्ृ र्कु ो कारणका सम्बन्िमा\nविशेषज्ञिरुको टोलीबाट शि परीिण गराउन उपर्िु िन्ु छ िन् ने लागेमा त्र्स्तो\nटोलीबाट शि परीिण गराउन सवकनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२१", "title": "िौधतक प्रमाण परीिण गन यु पनेाः (१) कुनै कसूरको प्रकृ धतबाट सम्बत्तन्ित व्र्त्तिको रगत,", "content": "िीर्,य रौँ िा शरीरको अन्र् कुनै अङ्ग, िात िधतर्ार िा चीज िस्त ु िा धड.एन.ए. िा अन्र्\nकुनै कुरा परीिण गदाय कसूरदार पिा लगाउन कसूर सम्बन्िी प्रमाण उपलब्ि िनु\nसक्दछ िन् ने लागेमा अनसु न्िान अधिकारीले सरकारी त्तचवकत्सक िा मान्र्ता प्राप्त\nप्रर्ोगशालामा त्र्स्तो रगत, िीर्,य रौँ िा शरररको कुनै अङ्ग, िातिधतर्ार िा चीज िस्त ु िा\n25\nwww.lawcommission.gov.np\n\nधड.एन.ए. िा विद्यतु ीर् स्िरुपमा रिेको सामग्री िा अन्र् कुनै िौधतक प्रमाण परीिण\nगराउन सक्नेछ।\nतर कुनै मविलाको शारीररक अङ्ग जाँच गन यु परेमा पाएसम्म मविला\nत्तचवकत्सकद्वारा र त्र्स्तो त्तचवकत्सक उपलब्ि निएमा मविलाको रोििरमा परुु ष\nत्तचवकत्सकबाट गराउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम परीिण गन य आिश्र्क पने रगत, िीर्,य रौं िा अङ्ग,\nिातिधतर्ार िा िस्तकु ो नमूना (स्र्ाम्पल) उपलब्ि गराउन अनसु न्िान अधिकारीलाई\nसम्बत्तन्ित व्र्त्तिले सिर्ोग गन यु पनेछ।\n(३) उपदफा (१) बमोत्तजम िएको परीिणको प्रधतिेदन सम्बत्तन्ित त्तचवकत्सक िा\nप्रर्ोगशालाले तर्ार गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२२", "title": "घाउ जाचँ गराउन ु पनेाः (१) कुटवपटको कारणबाट कुनै िारदात िई घाउ, चोट, नील िा", "content": "डाम, इत्र्ाठद िएकोमा सो जाँची पाउँ िनी सम्बत्तन्ित व्र्त्तिले धनिेदन ठदएमा िा\nअनसु न्िान अधिकारीबाट लेिी आएमा सरकारी त्तचवकत्सक िा स्िास्थ्र्कमीले धनजको\nघाउ, चोटपटक, नील िा डाम जाँची अनसु ूची-१६ बमोत्तजमको ढाँचामा घाउ जाँच के श\nगरी ठदन ु पनेछ।\n(२) उपदफा (१) मा लेत्तिए बािेक अनसु न्िानको धसलधसलामा विरासतमा\nरात्तिएको व्र्त्तिलाई कुटवपट गररएको, र्ातना ठदएको िा धनजको विरुद्ध अरु कुनै कसूर\nिएको प्रमाण धनजको शारीररक जाँचबाट उपलब्ि िनु सक्ने मनाधसब आिार देिाई धनज\nिा धनजको तफय बाट अरु कसैले धनिेदन ठदएमा अदालतले सरकारी त्तचवकत्सक िा नेपाल\nसरकारले तोके को त्तचवकत्सक िा स्िास्थ्र्कमीबाट त्र्स्तो व्र्त्तिको शारीररक जाँच\nगराउन आदेश ठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजम शारीररक जाँच गदाय समेत उपदफा (१) मा\nउल्लेत्तित घाउ जाँच गरी ठदन ु पनेछ।\n(४) दफा २०, २१ र र्स दफा बमोत्तजम िएको परीिण प्रधतिेदन त्र्स्तो\nपरीिण िएको धमधतले बाटोको म्र्ाद बािेक बढीमा तीन ठदनधित्र सम्बत्तन्ित त्तचवकत्सक,\nविशेषज्ञ िा प्रर्ोगशालाले सम्बत्तन्ित कार्ायलर् िा अनसु न्िान अधिकारीलाई उपलब्ि\nगराउन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n26\nwww.lawcommission.gov.np\n(५) उपदफा (२) बमोत्तजम विरासतमा धलएको व्र्त्तिलाई कुटवपट गरेको िा\nधनजलाई र्ातना ठदएको देत्तिएमा त्र्सरी कुटवपट गररएको िा र्ातना पाएको व्र्त्तिको\nउपचार गराई धनजलाई अन्तररम राित उपलब्ि गराउन र त्र्सरी कुटवपट गने िा\nर्ातना ठदने व्र्त्तिलाई कानून बमोत्तजम वििागीर् कारबािी गन य अदालतले सम्बत्तन्ित\n\nप्रिरी कार्ायलर् िा अनसु न्िान गने अधिकारप्राप् त कार्ायलर् िा अधिकारीलाई आदेश\nठदन ु पनेछ।\n\n(६) उपदफा (१) बमोत्तजम अनसु न्िान अधिकारीले घाउ जाँच गन य सरकारी\nत्तचवकत्सक िा स्िास्थकमीलाई लेिी नपिाएमा त्र्सको व्र्िोरा उल्लेि गरी\nसरोकारिाला व्र्त्तिले अदालतमा धनिेदन ठदन सक्नछे र त्र्सरी धनिेदन परेमा अदालतले\nघाउ जाँचको लाधग सरकारी त्तचवकत्सक िा स्िास्थ्र्कमीलाई आदेश ठदन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२३", "title": "विशषे ज्ञको रार् धलन सवकनाःे (१) अनसु न्िान अधिकारीले अनसु न्िानको सन्दिमय ा", "content": "आिश्र्क िानेमा कुनै विशेषज्ञलाई साथमा लैजान िा अपरािसँग सम्बत्तन्ित कुनै कुराको\nसम्बन्िमा विशेषज्ञको रार् धलन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम रार् माग िएमा त्र्स्तो रार् उपलब्ि गराउन ु\nसम्बत्तन्ित विशेषज्ञको कतव्य र् िनु ेछ।\n(३) उपदफा (२) बमोत्तजम उपलब्ि िएको विशषे ज्ञको रार् धमधसल साथ रात न ु\nपनेछ।\n(४) र्स दफा बमोत्तजमको विशेषज्ञ व्र्त्ति गैरसरकारी व्र्त्ति िए धनजको सेिा\nधलँदा लाग्ने रकम नपे ाल सरकारले उपलब्ि गराउन ु पनेछ।\n(५) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन अनसु न्िान\nअधिकारीले कुनै मद्दु ाको सम्िेदनत्तशलता िा जवटलताको कारणबाट त्र्स्तो मद्दु ामा\nमेधडकल बोड य िा अन्र् कुनै विशेषज्ञिरुको बोडबय ाट रार् धलन उपर्िु िानी धसफाररस\nगरेमा नेपाल सरकारले त्र्स्तो बोड य गिन गन य सक्नेछ।\n(६) उपदफा (५) बमोत्तजम बोड य गिन िएकोमा त्र्स्तो बोडलय े सो सम्बन्िमा\nरार् ठदन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n27\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२४", "title": "सनाित गराउन ु पनेाः (१) कुनै मद्दु ामा कुनै व्र्त्तिको सनाित गराउन ु पने िएमा", "content": "कम्तीमा प्रिरी नार्ब धनरीिक दजायको प्रिरी कमचय ारीले सनाित गराउन ु पनेछ।\nतर सनाित नगराएकै कारणबाट मात्र मद्दु ाको काम कारबािीमा कुनै तात्तत्िक\nअसर पने छैन।\n(२) उपदफा (१) बमोत्तजम सनाित गराउँदा सनाित गन यु पने व्र्त्तिलाई देख्न\nर िेन य नपाउने िाउँमा रात न ु पनेछ र त्र्स्तो व्र्त्तिसँग धमल्दाजल्ु दो उमेर, िण य िा\nशारीररक स्िरुप िएको कम्तीमा चार जना व्र्त्तिलाई सम्िि िएसम्म एकै वकधसमको\nपविरन गराई धनजिरुसँग सनाित गन यु पने व्र्त्तिलाई रािी सनाित गने प्रत्र्ेक\nव्र्त्तिलाई छुट्टाछुट्टै सनाित गराउन ु पनेछ।\n(३) सनाितको ढाँचा अनसु ूची-१७ मा उल्लेि िए बमोत्तजम िनु ेछ।\n(४) उपदफा (२) बमोत्तजम सनाित गराउँदा सनाित गने व्र्त्तिले पविचान गन य\nसके िा नसके को व्र्िोरा लेिी धमधसल सामेल रात न ु पनेछ।\n(५) मद्दु ासँग सम्बत्तन्ित दसी िा चीज िस्तलु ाई प्रिरी नार्ब धनरीिक दजायको\nप्रिरी कमचय ारीले सनाित मचु ल्ु का िडा गरी सनाित गराउन सक्नेछ।\n ", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२५", "title": "अनसु न्िान डार्री रातन ु पनेाः (१) र्स पररच्छेद अन्तगतय अनसु न्िान गने प्रिरी", "content": "अधिकृ त िा अनसु न्िान अधिकारीले अनसु न्िानको सम्बन्िमा आफू ले गरेको प्रत्र्ेक काम\n\nकारबािी तत्कालै अधिलेि गनकय ो लाधग अनसु ूची-१८ बमोत्तजमको ढाँचामा अनसु न्िान\nडार्री िडा गन यु पनेछ।\n\n(२) उपदफा (१) बमोत्तजम िडा गरेको डार्रीमा त्र्स्तो प्रिरी अधिकृ त िा\nअनसु न्िान अधिकारीले देिार्का कुराको अधिलेि रात न ु पनेछाः-\n(क) कसूरको सूचना पाएको धमधत, समर् र सोको संत्तिप् त वििरण,\n(ि) अनसु न्िानको धसलधसलामा धनजले गरेको काम, कारबािी,\n(ग) अनसु न्िानको धसलधसलामा धनजले भ्रमण गरेको िाउँ,\n(घ) अनसु न्िानको धसलधसलामा प्राप् त दसी, प्रमाण र अन्र् आिश्र्क\nकुरा,\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n28\nwww.lawcommission.gov.np\n(ङ) अनसु न्िानको धसलधसलामा कसैलाई पक्राउ गररएको िए त्र्सको\nवििरण,\n(च) अनसु न्िानको धसलधसलामा आफू ले सोिपछु गरेका माधनसको नाम,\nिेगाना र धनजले कसूरको सम्बन्िमा बताएको कुरा,\n(छ) पक्राउ परेका िा बत्तुझएका माधनसको स्ििाि,\n(ज) अनसु न्िानको धसलधसलामा प्राप् त अन्र् सम्बद्ध तथ्र् िा\nजानकारी।\n\n(३) उपदफा (१) बमोत्तजम ......... िडा गरेको डार्री आिश्र्कता अनसु ार\nसरकारी िवकल िा अदालतले त्तझकाई िेन य सक्नेछ।\n(४) उपदफा (१) बमोत्तजम िडा गरेको डार्रीमा उत्तल्लत्तित विषर्िस्तकु ा\nसम्बन्िमा सम्बत्तन्ित अनसु न्िान अधिकारीिन्दा माधथल्लो तिको अधिकारीले चािेमा\nधनरीिण गरी अनसु न्िानका सन्दिमय ा आिश्र्क धनदेशन समेत ठदन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२६", "title": "अनसु न्िान सम्बन्िमा रार्, सल्लाि माग गन य सक्नाःे (१) र्स पररच्छेद बमोत्तजम", "content": "अनसु न्िान गदा य सम्बत्तन्ित अनसु न्िान अधिकारीले कुनै विषर्मा सरकारी िवकलको रार्,\nसल्लाि माग गन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम रार्, सल्लाि माग िएकोमा सम्बत्तन्ित सरकारी\nिवकलले आफ्नो रार् िा सल्लाि ठदन ु पनेछ।\n(३) उपदफा (२) बमोत्तजम रार्, सल्लाि ठदँदा अनसु न्िानको समर्मा कुन ै\nविषर्मा थप अनसु न्िान गन य िा थप प्रमाण सङ्कलन गन य िा कुनै दसी प्रमाण बरामद गन य\nिा कसैसँग के िी कुरा बझ्ु न ु आिश्र्क छ िन्न े लागेमा सरकारी िवकलले त्र्स्तो\nबमोत्तजम गन य िा गर।उन सम्बत्तन्ित अनसु न्िान अधिकारीलाई धनदेशन ठदन सक्नेछ।\n(४) उपदफा (३) बमोत्तजम ठदएको धनदेशन पालना गन यु सम्बत्तन्ित अनसु न्िान\nअधिकारीको कतब्य र् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२७", "title": "अनसु न्िानको सन्दिमय ा मिान्र्ार्ाधिििाले आिश्र्क धनदेशन ठदन सक्नाःे (१) नपे ाल", "content": "सरकारबाट दार्र िनु े कुनै फौजदारी मद्दु ामा िई रिेको अनसु न्िानको बारे\nमिान्र्ार्ाधिििाले आिश्र्क जानकारी धलन सक्नछे ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n29\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजम जानकारी धलँदा नेपाल सरकारिादी िनु े कुन ै\nकसूरको अनसु न्िान अपर्ाप्तय िएको िा त्र्स्तो कसूरमा कुनै िास उपार्, तररका िा विधि\nअपनाउन ु पनेमा त्र्स्तो उपार्, तररका िा विधि नअपनाइएको िा थप अनसु न्िान गन यु पने\nिन् न े लागेमा मिान्र्ार्ाधिििाले अनसु न्िान सम्बन्िमा अनसु न्िान अधिकारी िा धनजको\nवििागीर् प्रमिु लाई जनु सकु ै समर्मा धनदेशन ठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजम ठदएको धनदेशनको पालना गन यु सम्बत्तन्ित अनसु न्िान\nअधिकारीको कतव्य र् िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२८", "title": "जािेरी दरिास्तको अधिलेि रातन ु पनेाः (१) पक्राउ परेको व्र्त्तिलाई दफा १४ को", "content": "उपदफा (३) बमोत्तजम विरासतमा रात ने अनमु धतको लाधग अदालत समि धनिेदन ठदँदा\nप्रिरी कार्ायलर् िा अनसु न्िान अधिकारी समि परेको जािेरी दरिास्त िा ठदएको\nसूचनाको एक प्रधत अनसु न्िान अधिकारीले सरकारी िवकल माफय त मद्दु ा िेने अधिकारी\nसमि पेश गन यु पनेछ।\n(२) मद्दु ा िेने अधिकारीले उपदफा (१) बमोत्तजमको दरिास्त िा सूचनाको छट्टै\nअधिलेि रात न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२९", "title": "सम्बत्तन्ित धनकार्मा पिाउन सवकनाःे र्स ऐनमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए", "content": "तापधन अनसु ूची-१ िा अनसु ूची-२ अन्तगतय को कसूर अनसु न्िान गदै जाँदा अन्र् कानून\nअन्तगतय अनसु न्िान गन यु पने देत्तिएमा अनसु न्िानको प्रगधत वििरण सवित त्र्स्तो\nकसूरको अनसु न्िान गने सम्बत्तन्ित धनकार् िा अधिकारी समि पिाउन सवकनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३०", "title": "नपे ाल बाविर िए गरेको कसूरको अनसु न्िानाः (१) नेपाल बाविर िए गरेको कसूरको", "content": "सम्बन्िमा नेपालको अदालतमा मद्दु ा चल्ने कानूनी व्र्िस्था िएमा र्स ऐनमा अन्र्त्र\nजनु सकु ै कुरा लेत्तिएको िए तापधन देिार् बमोत्तजमको रीत पर्ु र्ाई िएको त्र्स्तो कसूरको\nअनसु न्िान र्सै ऐन बमोत्तजम रीतपूिकय िए गरेको माधननेछाः-\n(क) नेपालका अदालतमा मद्दु ा चल्न सक्न े फौजदारी कसूरको\nअनसु न्िान एक अकाय मलु कु का अधिकार प्राप् त अनसु न्िान\nअधिकारीबाट िनु सक्ने गरी कुनै मलु कु सँग कुनै सत्तन्ि िएको\nरिेछ िने त्र्स्तो सत्तन्िको व्र्िस्था बमोत्तजम िएको अनसु न्िान,\n(ि) िण्ड (क) बमोत्तजमको सत्तन्ि िएको रिेनछ िने कू टनैधतक\nमाध्र्म माफय त कसूर िएको मलु कु को अनमु धत प्राप्त गरी त्र्स्तो\n30\nwww.lawcommission.gov.np\nमलु कु को अधिकार प्राप् त अधिकारीको सिर्ोगमा नेपाल सरकारले\nतोके को अनसु न्िान अधिकारीले गरेको अनसु न्िान,\n(ग) िण्ड (क) िा (ि) बमोत्तजम अनसु न्िान िनु सक्ने अिस्था\nरिेनछ िने जनु मलु कु मा कसूर िएको िो सोिी मलु कु को\nअधिकार प्राप् त अनसु न्िान अधिकारीले गरेको अनसु न्िान,\n(घ) िण्ड (ग) बमोत्तजम पधन सम्िि निएको अिस्थामा जनु\nइलाकामा अधिर्िु फे ला परेको छ सोिी इलाकामा िा अधिर्िु\nफे ला नपरेकोमा धनजको स्थार्ी बसोबास िएको इलाकाको\nअधिकार प्राप् त अनसु न्िान अधिकारीले गरेको अनसु न्िान।\n(२) उपदफा (१) बमोत्तजम िएको अनसु न्िानको प्रधतिेदन िा त्र्ससँग\nसम्बत्तन्ित धलितिरु नपे ाली िाषा बािेकको अन्र् िाषामा िएका रिेछन ् िने त्र्स्ता\nधलितको नपे ाली िाषामा प्रामात्तणक अनिु ाद गरी अदालतमा पेश गन यु पनेछ।\n(३) उपदफा (१) बमोत्तजम िएको अनसु न्िानबाट कुनै व्र्त्ति उपर मद्दु ा दार्र\nगन यु पने देत्तिएमा सम्बत्तन्ित सरकारी िवकलले र्स पररच्छेद बमोत्तजम अधिर्ोगपत्र तर्ार\nगरी अदालतमा मद्दु ा दार्र गनेछ।\n\n३०क. सम्पत्ति शद्धु ीकरण सम्बन्िी कसरु मा कारबािी िनु :े अनसु न्िान अधिकारीले अनत्तुचत\nलेनदेन सम्बन्िी कसरु मा अनसु न्िान गदाय सािलु े अस्िािाविक रूपमा िूलो रकम\nघरसारमा ऋण ठदएको देत्तिएमा प्रचधलत कानून बमोत्तजम सम्पत्ति शद्धु ीकरण सम्बन्िी\nकसरु मा अनसु न्िान गरी कारबािी चलाइनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३१", "title": "अनसु न्िान प्रधतिदे न पिाउन ु पनेाः (१) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय को कुन ै", "content": "कसूरको सम्बन्िमा अनसु न्िान पूरा िएपधछ अनसु न्िान अधिकारीले कसूर गरेको शङ्का\nगररएका सबै िा कुनै व्र्त्ति उपर मद्दु ा चलाउन पर्ायप्त प्रमाण पग्ु ने देत्तिएमा धनजलाई\nकुन कानून अन्तगतय सजार् िनु ु पने िो सो कुरा िलु ाई तथा कसूर निएको देत्तिएको िा\nकसूर िएको िए पधन त्र्स्तो कसूर गने व्र्त्ति र्िी िो िन् ने र्वकन िनु नसके को िा\nकुनै व्र्त्ति उपर मद्दु ा चलाउन पर्ायप्त प्रमाण नपग्ु ने देत्तिएकोमा सोिी व्र्िोरा िलु ाई\nधमधसल कागजको सक् कल तथा नक् कल प्रधत र दसी प्रमाण सवितको अनसु न्िान\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८० द्वारा थप।\n31\nwww.lawcommission.gov.np\nप्रधतिेदन अनसु ूची-१९ बमोत्तजमको ढाँचामा तर्ार गरी सम्बत्तन्ित सरकारी िवकल\nकार्ायलर्मा पिाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम प्रधतिेदन पिाउँदा थनु िु ा निएको मद्दु ा िए\nसम्बत्तन्ित कानूनको िदम्र्ाद पग्ु ने कम्तीमा पन्र ठदन अगािै र थनु िु ा िएको मद्दु ा िए\nमद्दु ा चलाउने िा नचलाउने धनणर्य गने र अधिर्ोगपत्र तर्ार गरी अदालतमा दार्र गन य\nलाग्ने समर्लाई समेत ध्र्ानमा रािी मद्दु ा दार्र गने ठदनिन्दा सामान्र्तर्ा कम्तीमा तीन\nठदन अगाधड नै पिाउन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम अनसु न्िान प्रधतिेदन सवितको धमधसल प्राप्त िएपधछ\nसम्बत्तन्ित सरकारी िवकलले धमधसल अध्र्र्न गरी अनसु न्िानको धसलधसलामा सङ्कधलत\nसिदु प्रमाणको मूल्र्ाङ्कन गरी मद्दु ा चलाउने िा नचलाउने सम्बन्िमा धनणर्य को लाधग\nमिान्र्ार्ाधिििा समि धमधसल पिाउन ु पनेछ।\n\nतर मद्दु ा चलाउने िा नचलाउने धनणर्य गने अधिकार मिान्र्ार्ाधिििाबाट\nमातितको सरकारी िकीललाई सत्तुम्पएकोमा त्र्स्तो धमधसल सम्बत्तन्ित सरकारी िकील\nसमि पिाउन ु पनेछ।\nस्पष्टीकरणाः र्स दफाको प्रर्ोजनका लाधग “मातितको अधिकृ त” िन् नाले\nमिान्र्ार्ाधिििा अन्तगतय का सरकारी िवकल सम्झन ु पछय र सो शब्दले संवििानमा\nअन्र्था व्र्िस्था िएकोमा बािेक नेपाल सरकार िादी िनु े अन्र् कुनै मद्दु ा चलाउन\nमिान्र्ार्ाधिििाले अत्तततर्ारी ठदएको नेपाल सरकारको कुनै अधिकृ त िा कमचय ारीलाई\nसमेत जनाउँछ।\n(४) उपदफा (३) बमोत्तजम मद्दु ा चलाउने िा नचलाउने धनणर्य गने धसलधसलामा\nधमधसल अध्र्र्न गदाय सरकारी िवकलले थप सिदु प्रमाण सङ्कलन गन य िा थप अनसु न्िान\nगन य िा कुनै व्र्त्तिसँग थप सोिपछु गन य आिश्र्क देिेमा त्र्स्तो सिदु प्रमाण सङ्कलन\nगरी िा थप अनसु न्िान गरी पिाउन िा त्र्स्तो व्र्त्तिसँग सोिपूछ गरी पिाउन\nअनसु न्िान अधिकारीलाई धनदेशन ठदन सक्नेछ।\n(५) सरकारी िवकलले कसूरको थप अनसु न्िान गन य उपदफा (४) बमोत्तजम\nधनदेशन ठदएमा अनसु न्िान अधिकारीले त्र्स्तो धनदेशन प्राप्त िएको धमधतले पन्र ठदनधित्र\nथप अनसु न्िान पूरा गररसक्न ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n32\nwww.lawcommission.gov.np\n(६) उपदफा (५) बमोत्तजमको थप अनसु न्िान सोिी उपदफामा उत्तल्लत्तित\nअिधिधित्र पूरा िनु नसक्ने िन् ने अनसु न्िान अधिकारीलाई लागेमा र कुनै व्र्त्ति\nविरासतमा रिेको िएमा अनसु न्िान अधिकारीले त्र्स्तो व्र्त्तिलाई माथिर व्र्त्तिको\nजमानी धलई िा नधलई ताररिमा रात न सक्नेछ।\n(७) अनसु न्िान अधिकारीले र्स दफा बमोत्तजम कुनै व्र्त्ति उपर मद्दु ा चलाउन\nनसवकने कारण सवितको प्रधतिेदन सरकारी िवकल समि पेश गरेकोमा अनसु न्िानको\nधसलधसलामा कुनै व्र्त्ति विरासतमा रिेको िए अनसु न्िान अधिकारीले त्र्स्तो व्र्त्तिलाई\nसरकारी िवकलले मद्दु ा चल्ने िा नचल्ने धनणर्य नगरेसम्म विरासतमा रािी रात न ु पनेछ।\n\n(८) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन अनसु ूची-१ िा\nअनसु ूची-२ मा उत्तल्लत्तित कुनै कसूरमा प्रमाणको अिािमा मद्दु ा नचलाउने गरी धनणर्य\nिए पधन पधछ कुनै मित्िपूण य प्रमाण प्राप् त िएमा त्र्स्तो कसूरका सम्बन्िमा पनु ाः\nअनसु न्िान गरी अधिर्ोगपत्र दार्र गन य सवकनेछ।\nपररच्छेद-३\nअधिर्ोजन तथा मद्दु ाको दार्री", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३२", "title": "अधिर्ोग पत्र दार्र गनेाः (१) दफा ३१ को उपदफा (३) बमोत्तजम मद्दु ा चल्ने िा नचल्न े", "content": "धनणर्य गन य धमधसल अध्र्र्न गदाय सङ्कधलत सिदु प्रमाणबाट मद्दु ा चल्ने पर्ायप्त प्रमाण\nदेत्तिएमा अनसु ूची-१ िा अनसु ूची-२ अन्तगतय को मद्दु ा िए सम्बत्तन्ित सरकारी िवकलले\nदेिार्का वििरणिरु उल्लेि गरी अनसु ूची-२० बमोत्तजमको ढाँचामा अधिर्ोगपत्र तर्ार\nगरी म्र्ाद धित्रै सम्बत्तन्ित अदालतमा पेश गन यु पनेछाः-\n(क) अधिर्िु को पूरा नाम, थर, िेगाना, िधुलर्ा, उमेर, पेशा िा व्र्िसार्,\n(ि) अधिर्िु को बाब,ु आमा िा पधत, पत्न ीको नाम,\n(ग) अधिर्िु बसोबास गरेको गाउँपाधलका िा नगरपाधलका, िडा नं.,\nगाउँ, टोल, िएसम्म ब्लक नं.,\n(घ) अधिर्िु को िास्तविक पविचान िनु े वििरण, धनजको फोटो,\nनागररकता िा रािदानी, सिारी चालक इजाजतपत्र िा धनजको\nिास्तविक पररचर् िल्ु ने अन्र् कागजातको प्रधतधलवप,\n(ङ) अधिर्िु को िएसम्मको दिु ै िातको चोरी औलँ ािरुको छाप,\n33\nwww.lawcommission.gov.np\n(च) अरुको घरमा डेरा गरी बसेको िए घरिनीको नाम, थर र िेगाना\nसवितको वििरण,\n(छ) कसूरसँग सम्बत्तन्ित सूचनाको व्र्िोरा,\n(ज) कसूर सम्बन्िी वििरण,\n(ज१) अधिर्ोजन गन य लाधगएको कसूर सम्पत्ति शद्धु ीकरण (मनी\nलाउण्डररङ्ग) धनिारण सम्बन्िी कानून अन्तगतय को सम्बद्ध कसूर\n(प्रधेडके ट अफे न्स) मा पने देत्तिएमा सम्पत्ति शद्धु ीकरण सम्बन्िी\nकसूर िए िा निएको र िएको िए त्र्स्तो कसूरमा समेत िनु े\nसजार् मागदाबी,\n(झ) अधिर्िु ले कसूर गरेको कुरा प्रमात्तणत गने दसी, प्रमाणको वििरण,\n(ञ) अधिर्िु उपर लगाइएको अधिर्ोग र त्र्सको आिार र\nकारणिरु,\n\n(ञ१) कुनै अधिर्िु फरार रिेको िए धनजको सम्पत्ति तथा अन्र् वििरण\nर धनज कुनै सािजय धनक पद िारण गरेको व्र्त्ति िए सोको\nवििरण,\n\n(ञ२) अधिर्ोग लगाईएको कसूरबाट अधिर्िु को नैधतक पतन िनु े िएमा\nसोको लाधग माग दाबी,\n(ट) प्रर्ोग िनु ु पने सम्बत्तन्ित कानून र त्र्सको कारण,\n(ि) अधिर्िु लाई िनु ु पने सजार्को माग दािी र त्र्सको कारण,\n(ड) कसूरबाट िधत पगु ेको व्र्त्तिलाई िधतपूधत य िराई ठदन ु पने िए\nत्र्स्तो िधतपूधतकय ो रकम,\n(ढ) कसूरको प्रकृ धतसँग सम्बत्तन्ित अन्र् आिश्र्क कुनै कुरा िए\nत्र्सको वििरण।\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) धनिारण तथा व्र्ािसावर्किातािरण प्रिद्धयन सम्बन्िी केिी ऐनलाई\nसंशोिन गने ऐन, २०८० द्धारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n34\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजम अधिर्ोगपत्र पेश गदाय कसूरका सम्बन्िमा सङ्कधलत\nसिदु प्रमाण,  दसी तथा िस्त,ु जिजस्य ती करणी सम्बन्िी कसूर िएमा सम्िि िएसम्म\nपीधडत व्र्त्ति र अधिर्िु विरासतमा रिेको िए धनज सवित पेश गन यु पनेछ।\n\n(२क) अधिर्ोगपत्र पेश गदाय उपदफा (२) बमोत्तजम पीधडतलाई उपत्तस्थत\nगराइएको रिेछ िने धनजको तत्काल बकपत्र गराई दफा १०१ को उपदफा (७)\nबमोत्तजम प्रधतिादीलाई त्तजरि गने अिसर ठदन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम पेश गररने अधिर्ोगपत्रमा अधिर्िु उपर अधिर्ोग\nलगाउन प्रस्ताि गररएको कसूरको कुनै िास नामाकरण कानूनमा गररएको रिेछ िन े\nत्र्स्तो कसूरको सम्बन्िमा सोिी नामको उल्लेि गन यु पनेछ।\n(४) उपदफा (३) बमोत्तजम प्रचधलत कानूनमा कसूरको कुनै नामाकरण\nनगररएको िए त्र्स्तो कसूरको प्रकृ धत अनसु ार अधिर्िु उपर लगाइएको अधिर्ोग धनजले\nस्पष्ट रुपमा बझु न सक्न े गरी कसूरका तत्ििरु समेत विचार गरी नामाकरण गन यु\nपनेछ।\n(५) अधिर्िु ले पविले कुनै कसूरमा सजार् पाइसके को जानकारी िनु आएमा िा\nधनज उपर अन्र् कुनै मद्दु ा चलाइएको रिेछ िने र त्र्सको कारणले बढी सजार् िनु ु पने\nअिस्था रिेछ िने धनजले पविले सजार् पाएको धमधत र सजार् गने अदालतको नाम तथा\nमद्दु ा समेत उपदफा (१) बमोत्तजम दार्र गररएको अधिर्ोगपत्रमा िा पधछ िल्ु न आएमा\nिल्ु न आएको बित उल्लेि गन यु पनेछ।\n(६) कुनै कसूरका सम्बन्िमा कुनै व्र्त्तिका धबरुद्ध मद्दु ा चलाउन तत्काल\nसङ्कधलत सिदु प्रमाण पर्ायप्त निई सरकारी िवकलले दफा ३१ को उपदफा (३)\nबमोत्तजम मद्दु ा नचल्ने धनणर्य गरेकोमा त्र्स्तो कसूरमा कुनै व्र्त्तिको धनजी सम्पत्ति िा\nधबगो िाधन, नोक्सानी सम्बन्िी देिानी दावर्त्िका विषर् समेत समािेश िएको रिेछ िन े\nसरकारी िवकलले सोको सूचना जािेरिाला िा त्र्स्तो कसूरबाट पीधडत व्र्त्तिलाई\nसम्बत्तन्ित अनसु न्िान अधिकारी माफय त ठदन ु पनेछ।\n(७) उपदफा (६) बमोत्तजमको सूचना प्राप् त िएकोमा प्रचधलत कानूनमा जनु सकु ै\nकुरा लेत्तिएको िए तापधन त्र्स्तो सूचना प्राप् त िएको धमधतले सािी ठदनधित्र सम्बत्तन्ित\n र्ौन विंसा विरुद्धका केिी ऐनलाई संशोिन गने ऐन, २०७९ द्वारा संशोधित।\n र्ौन विंसा विरुद्धका केिी ऐनलाई संशोिन गने ऐन, २०७९ द्वारा थप।\n35\nwww.lawcommission.gov.np\nव्र्त्तिले मद्दु ा दार्र गन य चािेमा अनसु ूची-४ अन्तगतय को कसूर सरि मद्दु ा दार्र गन य\nसक्नेछ।\n(८) र्स ऐन बमोत्तजम अनसु न्िान गदाय एकिन्दा बढी व्र्त्ति उपर अनसु न्िान\nिएको तर त्र्स्ता व्र्त्तिमध्र्े कुनै व्र्त्तिको िकमा मात्र मद्दु ा चलाइएको अिस्थामा िा\nनेपाल सरकार िादी िनु े िई अनसु न्िान िएको तर अनसु न्िानबाट त्र्स्तो मद्दु ा र्स ऐन\nबमोत्तजम नेपाल सरकार िादी िई चल्न सक्ने अिस्था निई अन्र् कानून अन्तगतय मद्दु ा\nचल्न सक्ने धनणर्य िएमा िा व्र्त्तििादी िई चल्न सक्ने िएमा सम्बत्तन्ित सरकारी\nिवकलले त्र्सको जानकारी सम्बत्तन्ित उच्च सरकारी िवकल कार्ायलर् र\nमिान्र्ार्ाधिििाको कार्ायलर्मा तरुु न्त पिाउन ु पनेछ।\n\n(९) उपदफा (८) बमोत्तजम जानकारी प्राप् त िएपधछ उच्च सरकारी िवकल\nकार्ायलर्को प्रमिु ले त्र्स्तो विषर् अध्र्र्न गरी मद्दु ा चलाउन ु पने िा नचलाउन ु पने\nधनणर्य गन यु पनेछ र मद्दु ा चलाउन ु पने मनाधसब कारण देत्तिएमा त्र्सको कारण िलु ाई\nसम्बत्तन्ित सरकारी िवकललाई मद्दु ा चलाउने धनदेशन ठदनेछ र त्र्स्तो धनदेशन प्राप्त\nिएमा त्र्स्तो सरकारी िवकलले अधिर्ोगपत्र िा पूरक अधिर्ोग पत्र दार्र गरी मद्दु ा\nनचलाइएका व्र्त्ति उपर मद्दु ा चलाउन ु पनेछ।\n\n(१०) उपदफा (९) बमोत्तजम उच्च सरकारी िवकल कार्ालय र्को प्रमिु ले मद्दु ा\nनचलाउने धनणर्य गरेकोमा त्र्सको जानकारी मिान्र्ार्ाधिििाको कार्ालय र्लाई ठदन ु\nपनेछ।\n(११) उपदफा (१०) बमोत्तजमको जानकारी प्राप् त िएपधछ मिान्र्ार्ाधिििाको\nकार्ायलर्ले सम्बत्तन्ित सरकारी िवकललाई मद्दु ा चलाउने िा नचलाउन े सम्बन्िमा\nआिश्र्क धनदेशन ठदन सक्नेछ।\n(१२) उपदफा (८) बमोत्तजम अन्र् कानून अन्तगतय मद्दु ा चल्ने जानकारी प्राप्त\nिएकोमा त्र्स्तो व्र्िोरा मनाधसब देत्तिएमा उच्च सरकारी िवकल कार्ालय र्ले सो कुराको\nजानकारी सम्बत्तन्ित व्र्त्तिलाई ठदन ु पनेछ।\n(१३) र्स पररच्छेदमा अन्र्था व्र्िस्था िएकोमा बािेक अनसु न्िानको\n\nधसलधसलामा कुनै व्र्त्तिबाट िरौट िा जमानत धलएको िए धनज उपर चलाइएकोमा\nअदालतबाट अन्र्था आदेश िएकोमा बािेक थनु छेक आदेश िएपधछ र मद्दु ा नचल्न े\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n36\nwww.lawcommission.gov.np\nधनणर्य िएमा त्र्सरी रािेको िरौटी िा जमानत त्र्स्तो व्र्त्तिलाई वफताय गररठदन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३३", "title": "सजार् कम गने माग दािी धलई अधिर्ोग पत्र दार्र गन य सवकनाःे (१) र्स पररच्छेदमा", "content": "अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै कसूरको अधिर्िु ले अनसु न्िान\nअधिकारीलाई त्र्स्तो कसूरको अनसु न्िान गन य सिर्ोग प¥ुर्ाएमा त्र्स बापत त्र्स्तो\nअधिर्िु लाई कानून बमोत्तजम िनु े सजार्मा छुट िनु अनसु न्िान अधिकारीले सरकारी\nिवकल समि धसफाररस गन य सक्नेछ।\n\n(२) उपदफा (१) बमोत्तजम धसफाररस िई आएमा िा अनसु न्िान प्रधतिेदन िा\nधमधसल संलग्न कागजातबाट अधिर्िु ले अनसु न्िानमा सिर्ोग पर्ु र्ाएको देत्तिएमा\nसरकारी िवकलले त्र्स्तो धसफाररस िा सिर्ोगलाई समेत विचार गरी त्र्स्तो\nअधिर्िु लाई िनु े सजार्मा छुट ठदन प्रस्ताि गरी शत य सवितको माग दािी धलई\nअधिर्ोगपत्र दार्र गन य सक्नेछ।\n(३) उपदफा (२) बमोत्तजम अधिर्ोगपत्र दार्र गदाय सरकारी िवकलले देिार्\nबमोत्तजमको सजार् छुटको प्रस्ताि गरी अधिर्ोगपत्र दार्र गन य सक्नेछाः-\n(क) अधिर्िु ले आफू ले गरेको कसूर अनसु न्िान अधिकारी िा सरकारी\nिवकल समि पूण य रुपमा स्िीकार गरी साधबती िएमा धनजलाई\nिनु े सजार्मा पच्चीस प्रधतशतसम्म छुट,\n(ि) अधिर्िु ले आफू समेत संलग्न िएको कसूरमा साधबत िई सो\nकसूरमा संलग्न अन्र् कसूरदार िा धगरोि िा कसूर गराउन\nधनदेशन ठदने मतु र् व्र्त्ति िा कसूरको सम्बन्िमा विस्ततृ तथ्र्\nबताउन िा कसूरमा संलग्न व्र्त्तिलाई पक्राउ गन य िा कुन ै\nसङ्गठित िा समूिगत रुपमा िएको कसूर िए सो कसूरमा संलग्न\nअन्र् व्र्त्तििरु िा त्र्स्तो कसूरको आपराधिक षडर्न्त्र िनु े\nस्थान देिाउन, कसूर गन य प्रर्ोग िनु े सिारी सािन, र्न्त्र, उपकरण\nिा अन्र् िस्त ु िा िातिधतर्ार बरामद गन य िा जफत गन य सघाउ\nप¥ुर्ाएको िए धनजलाई िनु े सजार्मा पचास प्रधतशतसम्म छुट।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n37\nwww.lawcommission.gov.np\n(४) उपदफा (२) बमोत्तजम सजार् छुटको माग दािी गनकय ो लाधग सम्बत्तन्ित\nमद्दु ाको धमधसल संलग्न कागजातबाट त्र्स्तो अधिर्िु ले त्र्स्तो सिर्ोग गरेको कुरा स्पष्ट\nरुपमा देत्तिन ु पनेछ।\n(५) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन देिार्का कसूरका\nसम्बन्िमा िा अिस्थामा सजार्मा छुट िनु े माग दािी गन य सवकने छैनाः-\n(क) एकपटक र्स दफा अन्तगतय को सवुििा पाइसके को,\n(ि) कै द सजार् पाएकोमा त्र्स्तो कै द ििु ान गरेको अिधि तीन िष य\nपूरा नगरेको,\n(ग) जनु कसूरमा अधिर्ोग लगाइने िो त्र्स्तै कसूरमा एक पटक\nसजार् पाइसके को।\n(६) उपदफा (२) बमोत्तजम सजार्मा छुट पाउने गरी अधिर्ोगपत्र दार्र\nिइसके पधछ त्र्स्तो अधिर्िु ले अदालतमा अनसु न्िान अधिकारी िा सरकारी िवकल\nसमि ठदएको िन्दा फरक बर्ान ठदएमा िा प्रधतकू ल प्रमाण ठदएमा िा आफ्नो कसूर\nइन्कार गरेमा िा न्र्ावर्क कारबािीमा सिर्ोग नप¥ुर्ाएमा धनजले र्स दफा बमोत्तजमको\nसवुििा पाउन सक्ने छैन।\n(७) उपदफा (६) बमोत्तजमको अिस्थामा सरकारी िवकलले उपदफा (१) िा\n(२) बमोत्तजम प्रस्ताि गररएको छुट सजार् रद्द गरी थप सजार्को माग गरी अदालतमा\nधनिेदन ठदन ु पनेछ र त्र्स्तो धनिेदन सोिी अधिर्ोग पत्रको अधिन् न अङ्ग िनु छे ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३४", "title": "िास वकधसमका सानाधतना कसूरमा मद्दु ा दार्र गन य आिश्र्क निनु ाःे (१) अनसु ूची-१ िा", "content": "अनसु ूची-२ बमोत्तजमको कुनै िास वकधसमको सानाधतना कसूरमा मद्दु ा दार्र गन यु\nव्र्ििाररक निएको िा सािजय धनक वितलाई िास असर नपने देत्तिएमा सरकारी िवकलले\nमिान्र्ार्ाधिििाको स्िीकृ धत धलई त्र्स्तो व्र्त्ति विरुद्ध मद्दु ा दार्र नगने धनणर्य गन य\nसक्नेछ।\n(२) उपदफा (१) बमोत्तजम धनणर्य गनअयु त्तघ सरकारी िवकलले त्र्स्तो\nअधिर्िु लाई िविष्र्मा त्र्स्तो कसूर नगने कबधुलर्त गराउन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n38\nwww.lawcommission.gov.np\n(३) र्स दफाको प्रर्ोजनको लाधग “िास वकधसमका सानाधतना कसूर” िन् नाले\nदेिार्का कसूर सम्झन ु पछयाः-\n(क) पविलो पटक गरेको एक िजार रुपैर्ाँसम्म विगो िएको\nबगलीमारा सम्बन्िी कसूर,\n(ि) पविलो पटक गरेको धििा माग्ने कसूर,\n(ग) तीन िजार रुपैर्ाँसम्म जररबाना िा एक मविनासम्म कै द िा दिु ै\nसजार् िनु े पविलो पटक गरेको अन्र् कुनै कसूर।\n(४) र्स दफा बमोत्तजम मद्दु ा नचलाउने धनणर्य गनअयु त्तघ सरकारी िवकलले\nकसूरको धबगो जफत गन यु पनेछ।\n\n(५) उपदफा (४) बमोत्तजम जफत गररएको धबगो कसूरबाट पीधडत व्र्त्ति\nरिेछ िने धनजलाई र निएमा कानून बमोत्तजम स्थावपत पीधडत राित कोषमा दात्तिला गन यु\nपनेछ।\n(६) उपदफा (१) बमोत्तजम मद्दु ा दार्र नगररएकोमा त्र्स्तो व्र्त्तिले त्र्स्तो\nधमधतबाट तीन िषधयित्र र्स ऐन अन्तगतय को कुनै कसूर गरेमा धनजलाई पविले गरेको\nकसूरको सजार् समेत थप िनु ेछ।\n(७) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन सरकारी िवकलले\nमद्दु ा नचलाउने धनणर्य गरेकोमा त्र्स्तो धनणर्य उपर त्तचि नबझु ने पीधडत पिले आफ्नो\nतपmयबाट मद्दु ा दार्र गन य सक्नेछ।\n(८) उपदफा (७) बमोत्तजम मद्दु ा नचलाउने धनणर्य िएकोमा पीधडतलाई तत्काल\nत्र्सको सूचना ठदन ु पनेछ र त्र्स प्रर्ोजनको लाधग त्र्स्तो धनणर्य िएको सूचना प्राप्त\nिएको धमधतबाट कानून बमोत्तजमको िदम्र्ाद प्रारम्ि िएको माधननेछ।\n(९) उपदफा (७) बमोत्तजम मद्दु ा दार्र गने व्र्त्तिलाई सम्बत्तन्ित सरकारी\nिवकलले र्स पररच्छेद बमोत्तजम िएको अनसु न्िानको कागजातका प्रधतधलवप उपलब्ि\nगराउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३५", "title": "थप दािी धलन सवकनाःे कुनै मद्दु ा अदालतमा दार्र िैसके पधछ त्र्स्तो मद्दु ामा अन्र् सम्बद्ध", "content": "थप प्रमाणिरुबाट मद्दु ा दार्र िैसके का अधिर्िु बािेक अन्र् अधिर्िु िरु उपर समेत\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n39\nwww.lawcommission.gov.np\nदािी धलन पने िएमा िा मद्दु ा दार्र िई अधिर्िु कार्म िई सके का व्र्त्ति उपर थप\nअधिर्ोग लगाउन ु पने देत्तिएमा त्र्सको कारण िलु ाई थप अनसु न्िान गन य लगाई अन्र्\nथप अधिर्िु को िकमा समेत थप दािी धलई सरकारी िवकलले मद्दु ा दार्र गन य\nसक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३६", "title": "अधिर्ोगपत्र संशोिन गन य सक्नाःे (१) अदालतमा एकपटक दार्र िैसके को मद्दु ामा थप", "content": "प्रमाण फे ला परी पविले धलएको माग दािी संशोिन गन यु पने देत्तिएमा\nमिान्र्ार्ाधिििाको स्िीकृ धत धलई सम्बत्तन्ित सरकारी िवकलले अधिर्ोगपत्रमा संशोिन\nगन य शरुु तिको सम्बत्तन्ित अदालतमा कारण िलु ाई धनिेदन ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम धनिेदन पन य आएमा र त्र्सको व्र्िोरा मनाधसब\nदेत्तिए धनिेदन बमोत्तजम अधिर्ोगपत्रमा माग दािी संशोिन गने आदेश सम्बत्तन्ित\nअदालतले ठदन सक्नेछ।\nतर त्र्स्तो संशोिन गने आदेश शरुु तिको सम्बत्तन्ित अदालतले फै सला गनअयु त्तघ\nनै ठदइसके को िनु ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३७", "title": "सानाधतना त्रटु ी सच्र्ाउन आदेश ठदन सक्नाःे (१) अदालतमा दार्र िएको मद्दु ाको", "content": "अधिर्ोगपत्रमा सानाधतना त्रटु ी िई सच्र्ाउन परेमा सम्बत्तन्ित सरकारी िवकलले\n\nसम्बत्तन्ित अदालत समि त्र्सको कारण िलु ाई धनिेदन ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम पन य आएको धनिेदन जाँचबझु गदाय त्रटु ी सच्र्ाउन\nमनाधसब देत्तिएमा अदालतले त्र्स्तो त्रटु ी सच्र्ाउन आदेश ठदन सक्नेछ।\nस्पष्टीकरणाः र्स दफाको प्रर्ोजनको लाधग “सानाधतना त्रटु ी” िन् नाले अधिर्िु को नाम,\nथर, उमेर िा िेगानाको विज्जे िा टाइवपङ्ग िा छपाइ सम्बन्िी त्रटु ीलाई सम्झन ु पछय।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३८", "title": "दसी, प्रमाण र अधिर्िु राख्नाःे (१) अनसु न्िान अधिकारीले अधिर्ोजनका लाधग अनसु न्िान", "content": "प्रधतिेदन साथ धमधसल सरकारी िवकल समि पेश गदाय कसूरसँग सम्बत्तन्ित दसी, प्रमाण\nर अधिर्िु लाई आफ्नो धनर्न्त्रणमा रात न ु पनेछ र सम्बत्तन्ित सरकारी िवकलले आदेश\nठदएमा सोिी बित सम्बत्तन्ित अदालतमा पेश गन यु पनेछ।\n(२) उपदफा (१) मा लेत्तिएदेत्ति बािेक र्स पररच्छेद बमोत्तजम अदालतमा दार्र\nिएको मद्दु ाका सम्बन्िमा मद्दु ा दार्र िएपधछ थप कुनै सिदु , प्रमाण िा कुनै िस्त,ु धलित\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n40\nwww.lawcommission.gov.np\nिा दसी फे ला परेमा सम्बत्तन्ित प्रिरी कार्ायलर्ले सम्बत्तन्ित सरकारी िवकल कार्ायलर्मा\nदात्तिल गन यु पनेछ र त्र्स्तो सरकारी िवकल कार्ालय र्ले आिश्र्क जाँचबझु गरी त्र्स्ता\nधलित, दसी, प्रमाण अदालतमा पेश गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "३९", "title": "सरु त्तित रातन ु पनेाः (१) सरकारी िवकलले दफा ३१ को उपदफा (३) बमोत्तजम मद्दु ा", "content": "नचल्ने धनणर्य गरेकोमा धमधसल लगार्तका दसी, प्रमाणका िस्त ु सम्बत्तन्ित प्रिरी\nकार्ायलर्मा अविलम्ब वफताय पिाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम प्राप् त धमधसल, दसी प्रमाण, िस्त ु सम्बत्तन्ित प्रिरी\nकार्ायलर्ले त्र्स्तो कसूरको मद्दु ा चलाउन सवकने िदम्र्ादको अिधिसम्म सरु त्तित रात न ु\nपनेछ।\n(३) उपदफा (१) बमोत्तजमको दसी, प्रमाण िा िस्त ु कसैको सम्पत्ति रिेछ िन े\nत्र्स्तो सम्पत्ति िनीलाई आिश्र्क परेको बित अनसु न्िान अधिकारी िा अदालतमा\nदात्तिला गने शत य सवितको कागज गराईय प्रिरी कार्ायलर्ले त्र्स्तो सम्पत्ति वफताय ठदन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४०", "title": "प्रधतधलवप िा जानकारी ठदन ु पनेाः (१) सरकारी िवकलले दफा ३१ को उपदफा (३)", "content": "बमोत्तजम मद्दु ा नचल्ने गरी धनणर्य गरेकोमा त्र्स्तो धनणर्य को प्रधतधलवप र मद्दु ा चल्ने धनणर्य\nिएकोमा अधिर्ोगपत्रको प्रधतधलवप सम्बत्तन्ित अनसु न्िान अधिकारी र अधिर्िु लाई ठदन ु\nपनेछ।\n(२) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय का कुनै मद्दु ामा मद्दु ा चलाउन पर्ायप्त\nप्रमाण निएको िनी सम्बत्तन्ित सरकारी िवकलले धनणर्य गरेमा धनजले त्र्स्तो धनणर्य को\nजानकारी सम्बत्तन्ित अनसु न्िान अधिकारी र त्र्स्तो अनसु न्िान अधिकारीिन्दा माधथल्लो\nतिको अधिकारी िा कार्ायलर्लाई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४१", "title": "जािेरिाला िा पीधडतलाई सूचना ठदन ु पनेाः कुनै कसूरको सम्बन्िमा दफा ३१ को", "content": "उपदफा (३) बमोत्तजम मद्दु ा नचलाउने धनणर्य िएमा अनसु न्िान अधिकारीले त्र्सको\nकारण सवितको सूचना जािेरिाला िा पीधडतलाई र्थात्तशघ्र ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४२", "title": "सरोकारिाला व्र्त्तिलाई पि कार्म गनेाः (१) र्स ऐन बमोत्तजम नेपाल सरकार िादी", "content": "िई दार्र िएको कुनै मद्दु ा कारबािी िँदु ा अनसु ूची-१ िा अनसु ूची-२ धित्र नपने देत्तिएको\nतर कानून बमोत्तजम अन्र् कुनै मद्दु ा चल्न सक्ने देत्तिएमा अदालतले सोिी आदेश गरी\nसरोकारिाला व्र्त्तिलाई त्र्सको सूचना ठदन ु पनेछ।\n41\nwww.lawcommission.gov.np\n(२) सरोकारिालाले उपदफा (१) बमोत्तजम सूचना पाएको धमधतले दईु मविनाधित्र\nत्र्स मद्दु ा सकार गरेमा धनजलाई िादी पि कार्म गरी सोिी मद्दु ाको धमधसलबाट कानून\nबमोत्तजम कारबािी र वकनारा गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४३", "title": "मद्दु ाको दार्रीाः (१) र्स ऐन बमोत्तजम दार्र गन यु पने देिार्को मद्दु ा देिार्को अधिकारी", "content": "िा व्र्त्तिले सम्बत्तन्ित अदालतमा दार्र गन य सक्नेछाः-\n(क) अनसु ूची-१ र अनसु ूची-२ अन्तगतय का कसूर सम्बन्िी मद्दु ा\nअधिर्ोगपत्रका रुपमा सम्बत्तन्ित सरकारी िवकलले,\n(ि) अनसु ूची-३ अन्तगतय का कसूर सम्बन्िी मद्दु ा उजरु ी िा प्रधतिेदनको\nरुपमा नेपाल सरकार, संिैिाधनक धनकार्, अदालत िा कुन ै\nसािजय धनक अधिकारीले,\n(ग) अनसु ूची-४ अन्तगतय का कसूर सम्बन्िी मद्दु ा वफरादपत्रका रुपमा\nत्र्स्तो मद्दु ा दार्र गन य सक्न े िकदैर्ा िएको िा सरोकारिाला\nव्र्त्तिले,\n(२) उपदफा (१) बमोत्तजम मद्दु ा दार्र गरेमा त्र्स्तो मद्दु ा र्स ऐन बमोत्तजम\nदार्र िएको माधननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४४", "title": "पोल उजरु गरे बापत सजार् निनु ाःे (१) अनसु ूची-१, अनसु ूची-२ र अनसु ूची-३ अन्तगतय का", "content": "कसूर सम्बन्िी मद्दु ामा पोल िा उजरु गरे बापत कुनै सजार् िनु े छैन।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन आफू सािी िई नेपाल\nसरकार, प्रिरी कमचय ारी िा अन्र् अधिकारीलाई विश्वास पने वकधसमको कुनै कुरा िा सिूद\nप्रमाण देिाई पोल िा उजरु गरेकोमा सोिी आिारबाट अनसु न्िान िई अदालतमा मद्दु ा\nचधलसके पधछ त्र्स्तो कुरा िा सिूद िा प्रमाण झठ्ठु ा िा बनािटी िएको कुरा उल्लेि गरी\nकसैको प्रधतिेदन, उजरु ी परेमा िा बर्ान िएमा िा कुनै सािी िा जािेरिालाको बकपत्र\nिा अन्र् कुनै वकधसमबाट देत्तिएमा अदालतले सोिी धमधसलबाट प्रमाण बझु ी देिार्\nबमोत्तजम गन य सक्नेछाः-\n(क) झठ्ठु ा कुरा लेत्तिठदने िा बनािटी व्र्िोराको बकपत्र गने सािीलाई\nतीन मविनासम्म कै द िा पाँच िजार रुपैर्ाँसम्म जररबाना िा दिु ै\nसजार् गन,य\n42\nwww.lawcommission.gov.np\nतर त्र्सरी सजार् गदाय कसूरदारलाई िनु े सजार्को\nआिािन्दा बढी कै द िा जररबाना गन य सवकने छैन।\n(ि) झठ्ठु ो कुरा लेत्तिठदने िा बनािटी प्रमाण पेश गने काम िा पोल\nिा उजरु गन यु पने मनाधसब मावफकको कारण निई सािीले\nव्र्त्तिगत ररसइविले िा कुनै प्रलोिनमा परी गरेको िन् न े\nअदालतलाई लागेमा सफाई पाउने प्रधतिादीलाई मद्दु ाको प्रकृ धत र\nअिस्था विचार गरी त्र्स्तो सािीबाट मनाधसब िधतपूधत य त्र्सै\nमद्दु ाबाट िराई ठदन।\nतर धनजले ठदएको जािेरी िा सािी प्रधतकू ल िनु ाको\nमनाधसब कारण ठदएमा िधतपूधत य िराइने छैन।\nपररच्छेद-४\nअदालतको अधिकार ित्रे", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४५", "title": "कसूर िएको ित्रे को अदालतले मद्दु ा िेनेाः कुनै कसूर सम्बन्िी मद्दु ाको कारबािी र", "content": "वकनारा गने अधिकार त्र्स्तो कसूर िएको िेत्रको अदालतलाई िनु ेछ।\nतर नेपाल सरकारले कानून बमोत्तजम कुनै त्तजल्लामा छुट्टै फौजदारी अदालत िा\nफौजदारी इजलास गिन गरी त्र्स्ता कसूरको कारबािी र वकनारा गन य िा गराउन\nसक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४६", "title": "विधिन्न ित्रे सगँ सम्बत्तन्ित कसूर िएमा त्र्स्ता ित्रे मध्र् े कुन ै ित्रे को अदालतले मद्दु ा िेन य", "content": "सक्नाःे देिार्को अिस्थामा कुनै िेत्रको अदालतले मद्दु ाको कारबािी र वकनारा गन य\nसक्नेछाः-\n(क) कसूर ििररने कुनै काम आंत्तशक रुपमा एउटा िेत्र र आंत्तशक रुपमा\nअको इलाकामा िएकोमा त्र्स्तो िेत्रिरुमध्र्े कुनै िेत्रको अदालतले,\n(ि) कुनै काम एउटा िेत्रमा िएको र त्र्सको पररणाम कसूरको रुपमा अको\nिेत्रमा प्रकट िएकोमा त्र्समध्र्े कुनै िेत्रको अदालतले,\n(ग) एकै घटनाको धसलधसलामा विधिन् न कसूरिरु विधिन् न िेत्रमा िएकोमा\nत्र्स्तो कसूरिरुमध्र्े कुनै कसूर िएको िेत्रको अदालतले,\n43\nwww.lawcommission.gov.np\n(घ) कुनै कसूर विधिन् न िेत्रिरुमा िई कुन िेत्रमा कसूर िनु े काम पूरा\nिएको िो िन् ने र्कीन िनु नसके मा त्र्स्ता िेत्रिरुमध्र्े कुनै िेत्रको\nअदालतले,\n(ङ) माधनसको अपिरण िा शरीर बन्िक सम्बन्िी कसूर िएकोमा त्र्स्तो\nकसूर जनु िेत्रमा िएको छ िा जनु िेत्रमा अपिरण िा बन्िक\nबनाइएको व्र्त्ति रात्तिएको िा लकु ाइएको िा थधुनएको छ त्र्समध्र् े\nकुनै िेत्रको अदालतले,\n(च) र्ात्रा गरररिेको कुनै व्र्त्तिले गरेको िा र्ात्रा गरररिेको कुनै व्र्त्तिको\nविरुद्ध िा एक िेत्रबाट अको िेत्रमा लैजान लागेको मालसामानको\nसम्बन्िमा गररएको कसूर िए कसूर प्रारम्ि िएको िा त्र्स्तो व्र्त्ति\nर्ात्राकालमा जनु जनु िेत्रमा गएको छ िा त्र्स्तो मालसामान बरामद\nिएको िा जनु जनु िेत्र िएर लधगएको छ सोमध्र्े कुनै िेत्रको अदालतले,\n(छ) कुनै कसूरको तर्ारी िा आपराधिक षडर्न्त्र एक िेत्रमा िई कसूर िनु े\nकाम अको िेत्रमा पूरा िएकोमा तर्ारी िा षड्यन्त्र िएको िेत्र िा कसूर\nिनु े काम पूरा िएको िेत्रको अदालतमध्र्े कुनै अदालतले,\n(ज) कुनै कसूर त्तचठ्ठी िा अन्र् कुनै सञ् चार िा सूचना प्रविधिको माध्र्मबाट\nिएकोमा त्र्स्तो त्तचठ्ठी, सञ् चार िा सूचना जनु ित्रे बाट सम्पेर् षण िएको\nिा जनु िेत्रमा प्राप् त गररएको छ त्र्समध्र्े कुनै ित्रे को अदालतले,\n(झ) कुनै कसूर दईु मलु कु को धसमानामा िएकोमा त्र्स्तो धसमाना जोधडएको\nअदालतले,\nस्पष्टीकरणाः र्स िण्डको प्रर्ोजनको लाधग धसमाना िन् नाले दईु मलु कु को\nधसमानामा रिेको दशगजा िेत्रलाई समेत जनाउँछ।\n(ञ) सम्पत्ति सम्बन्िी कसूरको िकमा त्र्स्तो कसूर िएको िेत्र िा कसूरबाट\nप्राप् त सम्पत्ति लकु ाएको, वकनेको, बेचेको िा अन्र् कुनै प्रकारले धलए\nठदएको िेत्रको अदालतले,\n(ट) नेपाल िा नेपाल सरकार पि िएको कुनै सत्तन्ि िा कानून बमोत्तजम\nविश्वव्र्ापी अधिकार िेत्र (र्धुनिसलय जरुरत्तस्डक्शन) कार्म िनु े कसूर\nसम्बन्िी मद्दु ाको िकमा नेपाल सरकारले तोके को अदालतले।\n44\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४७", "title": "नपे ाल बाविर िएको कसूर सम्बन्िी मद्दु ा िेने अधिकार ित्रे ाः नपे ालमा दताय िएको िार्र्ु ान", "content": "िा पानीजिाजमा िएको िा नेपाल बाविर िएको कुनै कसूरको सम्बन्िमा प्रचधलत\nकानूनले सजार् िनु े व्र्िस्था िएकोमा त्र्स्तो कसूरको अधिर्िु नेपाल धित्रको जनु\nत्तजल्लामा फे ला परेको छ सोिी त्तजल्लाको अदालतमा र फे ला नपरेकोमा धनजको स्थार्ी\nबासस्थान िएको िेत्रको त्तजल्ला अदालतमा त्र्स्तो कसूर सम्बन्िी मद्दु ाको कारबािी र\nवकनारा गररनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४८", "title": "दईु अदालत िा धनकार्मा परेका मद्दु ाको कारबािी र वकनारााः (१) कुनै कसूर सम्बन्िी", "content": "मद्दु ा एकिन्दा बढी अदालतको अधिकार िेत्रधित्र पने िई एकिन्दा बढी अदालतमा मद्दु ा\nदार्र िएको रिेछ िने जनु अदालतमा पविले मद्दु ा दार्र िएको िो सोिी अदालतले र\nएकै ठदन दार्र िएकोमा एकै पनु रािेदन सन्ु ने अदालतको अधिकार िेत्रधित्र पने\nअदालतमा िए त्र्स्तो अदालतको पनु रािेदन सन्ु ने अदालतले तोके को अदालतले र\nधिन् नधिन् न पनु रािेदन सन्ु ने अदालतको अधिकार िेत्रधित्र पने िए सिोच् च अदालतले\nतोके को अदालतले त्र्स्तो कसूर सम्बन्िी मद्दु ाको कारबािी र वकनारा गन यु पनेछ।\n(२) उपदफा (१) मा जनु सु कु ै कुरा लेत्तिएको िए तापधन कुनै एक कसूर\nसम्बन्िी मद्दु ा अदालत र अि य न्र्ावर्क धनकार्को अधिकार िेत्रधित्र पने िई अदालत र\nअिन्य र्ावर्क धनकार्मा मद्दु ा दार्र िएको रिेछ िने त्र्स्तो मद्दु ाको कारबािी र वकनारा\nअदालतबाट गन यु पनेछ।\n(३) दफा ५४ को उपदफा (१) र उपदफा (२) को िण्ड (क) िा (ग)\nअन्तगतय संर्िु रुपमा कारबािी िनु सक्ने अिस्था िए तापधन धिन् नधिन् न प्रकारका\nअदालत िा न्र्ार्ीक धनकार्को अधिकार िेत्र अन्तगतय पने मद्दु ा रिेछ िने कानून\nबमोत्तजम अधिकार प्राप् त तित ् अदालत िा धनकार्बाट कारबािी र वकनारा गन यु पनेछ", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "४९", "title": "तल्लो र माधथल्लो अदालतको अधिकार ित्रे धित्र पने मद्दु ा माधथल्लो अदालतले िेन यु पने:", "content": "प्रचधलत कानून बमोत्तजम कुनै कसूर सम्बन्िी मद्दु ा तल्लो र माधथल्लो तिको अदालत\nदिु ैको अधिकार िेत्रधित्र पने िा दफा ५४ अन्तगतय संर्िु रुपमा कारबािी िनु सक्न े\nव्र्त्ति िा कसूर सम्बन्िी मद्दु ा तल्लो ति र माधथल्लो तिको दिु ै अदालतको अधिकार\nिेत्रधित्र परी दार्र िनु सक्ने िएमा िा दार्र िएकोमा त्र्स्तो मद्दु ा िेने अधिकार\nमाधथल्लो तिको अदालतलाई िनु ेछ।\n45\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५०", "title": "अधिकार ित्रे निएको िा िेररतको िएमा दरपीि गन यु पनेाः (१) कुनै अधिर्ोगपत्र िा", "content": "उजरु ीको व्र्िोराबाट त्र्स्तो उजरु ी सम्बन्िी मद्दु ाको कारबािी र वकनारा गने आफ्नो\nअधिकार िेत्र निएको िा रीत नप¥ुर्ाई दताय गन य ल्र्ाएको देत्तिएमा अदालतले सोिीे े\nकुरा उल्लेि गरी त्र्स्तो अधिर्ोगपत्र िा उजरु ी दरपीि गरी ठदन ु पनेछ।\n(२) अधिकार िेत्र निएको कारणले उपदफा (१) बमोत्तजम दरपीि िएको\nउजरु ीको विषर्मा मद्दु ा गन यु पने अत्तन्तम िदम्र्ाद दरपीि िएको ठदनसम्म रिेछ िन े\nप्रचधलत कानूनमा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्तो उजरु ी गने व्र्त्तिले सो\nठदनबाट बाटोको म्र्ाद बािेक पन्र ठदनधित्र दता य गन य ल्र्ाएमा अधिकार िेत्र िएको\nअदालतले कानून बमोत्तजम दताय गररठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५१", "title": "अधिकार ित्रे र िदम्र्ाद सम्बन्िमा धनणर्य गन यु पनेाः (१) र्स ऐनमा अन्र्त्र जनु सकु ै", "content": "कुरा लेत्तिएको िए तापधन कुनै मद्दु ाका सम्बन्िमा अधिर्िु ले बर्ान गदाय िा प्रधतिादीले\n\nप्रधतउिर पत्र पेश गदाय अदालतको अधिकार िेत्र निएको, िादीलाई मद्दु ा दार्र गने\nिकदैर्ा निएको िा िदम्र्ाद निएको िन् ने प्रश्न उिाएमा अदालतले पविले त्र्स्तो\nप्रश्न का सम्बन्िमा धनणर्य गरेर मात्र त्र्स्तो मद्दु ाको अन्र् कारबािी अगाधड बढाउन ु पनेछ\nर आफ्नो अधिकारिेत्रधित्र नपने देत्तिएमा अधिकार िेत्र िएको अदालतमा पिाउन\nआदेश ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम िएको धनणर्य उपर त्र्स्तो धनणर्य िएको धमधतले\n\nतीस ठदनधित्र पनु रािेदन सन्ु ने अदालतमा उजरु गन य सवकनेछ।\n(३) उपदफा (१) िा (२) बमोत्तजम धनरुपण िएको प्रश्न पनु रािेदन सन्ु न े\nअदालतमा पनु ाः उिाउन सवकने छैन।\nतर मद्दु ाको रोिमा िनु े अन्तरकालीन आदेशका िकमा र्ो व्र्िस्था लागू िनु े\nछैन।\nपररच्छेद-५\nमद्दु ाको प्रारत्तम्िक कारबािी सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५२", "title": "मद्दु ा दार्र िएपधछ अदालतले कारबािी प्रारम्ि गनपयु नेाः (१) र्स ऐनमा अन्र्था व्र्िस्था", "content": "िएकोमा बािेक कुनै कसूरका सम्बन्िमा र्स पररच्छेद बमोत्तजम अदालतमा मद्दु ा दार्र\nिएपधछ अदालतले त्र्स्तो मद्दु ाको कारबािी प्रारम्ि गन यु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n46\nwww.lawcommission.gov.np\nतर,\n(क) अदालतको आदेशको अिज्ञा गरेको िा अरु कुनै वकधसमले\nअदालतको अििेलना गरेको कसूरमा अदालतले अधिर्िु को िाडो\nबर्ान धलएर िा धलत्तित स्पष्टीकरण मागेर िा अन्र् कुनै धनिेदन\nिा प्रधतिेदनबाट पधन मद्दु ाको कारबािी प्रारम्ि गन य सक्नेछ।\n(ि) कुनै मद्दु ामा अदालतले प्रमाण बिु m्दा कुनै पिले कुनै प्रमाणलाई\nजालसाँजी िा कीते िनी बर्ान गरेकोमा सोिी बर्ानको आिारमा\nधलित कीते िा जालसाजीको कसूरमा िा सो कसूर गन य\nदरुु त्सािन ठदएको, आपराधिक षडर्न्त्र गरेको िा मधतर्ार िएको\nकसूरमा सोिी धमधसलबाट मद्दु ाको कारबािी प्रारम्ि गन य\nसवकनेछ।\n(२) अपराि संविताको िाग-२ को पररच्छेद-३ को दफा ८१, ८२ पररच्छेद-४\nको दफा ८९, ९०, ९१, ९२, ९३, ९७, ९८, १०० मा उत्तल्लत्तित कुनै कसूर गरेको,\nत्र्स्तो कुनै कसूर गन य दरुु त्सािन ठदएको, अपराधिक षडर्न्त्र गरेको िा मधतर्ार िएको\nअधिर्ोगमा उपदफा (१) को प्रधतबन्िात्मक िाक्र्ांशको िण्ड (ि) बमोत्तजम मद्दु ाको\nकारबािी प्रारम्ि िएकोमा बािेक अदालतले सम्बत्तन्ित व्र्त्तिको धनिेदन, प्रधतिेदन, बर्ान\nिा कुनै छुट्टै उजरु ीको आिारमा मद्दु ा चलाउन न्र्ार्ोत्तचत ििराई कारण सवितको आदेश\nपचाय िडा गरी मद्दु ाको कारबािी प्रारम्ि गन य सक्नेछ।\n(३) उपदफा (२) मा उत्तल्लत्तित मद्दु ाको कारबािी र वकनारा मूल कसूर\nसम्बन्िी मद्दु ा साथै रािी गन यु पनेछ।\n(४) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन नपे ाल सरकार\nिा सम्बत्तन्ित वििागीर् प्रमिु को धलत्तित स्िीकृ धत िएकोमा बािेक नेपाल सरकारको कुन ै\nकमचय ारी उपर धनजले आफ्नो ओिदाको कतव्य र् पालनाको धसलधसलामा गरेको कुनै\nकामको सम्बन्िमा धनज उपर कुनै कसूरको अधिर्ोग लगाई मद्दु ा चल्ने छैन।\nतर कुनै कमचय ारीले आफ्नो ओिदाको कतव्य र्िन्दा बाविरको कुनै काम गरी कुन ै\nकसूर गरेमा धनज उपर त्र्स्तो कसूरको अधिर्ोग लगाई मद्दु ा चलाउन नेपाल सरकारको\nिा सम्बत्तन्ित वििागीर् प्रमिु को स्िीकृ धत धलन ु पने छैन।\n47\nwww.lawcommission.gov.np\n(५) अनसु ूची-१ र अनसु चु ी-२ अन्तगतय का कसूरको सम्बन्िमा सरकारी\nिवकलबाट अधिर्ोगपत्र पेश नगरी कुनै व्र्त्ति उपर मद्दु ा चल्ने छैन।\n\nतर दफा ३४ को उपदफा (७) मा उत्तल्लत्तित विषर्मा सोिी बमोत्तजम\nिनु ेछ।\n(६) उपदफा (५) मा जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै कसूरबाट िनु\n\nगएको िधत पूधतकय ा लाधग देिार्को व्र्त्तिले अधिर्ोग पत्र पेश गरेको सािी ठदनधित्र\nछुट्टै उजरु ी ठदन सक्नेछाः-\n(क) कसूरबाट िधत पगु ेको व्र्त्ति,\n(ि) आफ्नो नोकरीको धसलधसलामा अन्र्त्र िवटएको िा विदेशमा\nरिेको राष्ट्रसेिकले उजरु गन य पने कुराको सम्बन्िमा धनजको\nनत्तजकको कुनै िकिाला,\n(ग) कुनै व्र्त्तिले कुनै पद, ओिदा िा अन्र् कुनै िैधसर्तले गन यु पने\nकुनै काम िा संरिण गन यु पने कुनै कुराको सम्बन्िमा त्र्स्तो\nपद, ओिदा िा िैधसर्तमा रिेको व्र्त्ति,\n(घ) अपाङ्गता िएको व्र्त्ति, बालबाधलका िा पचििर िष य उमेर\nनाघेको व्र्त्ति िा शारीररक िा मानधसक रोगले असमथ य िएको\nव्र्त्तिले उजरु गन य पाउने कुराको सम्बन्िमा धनजको एकाघरको\nिकिाला र त्र्स्तो िकिाला निए अन्र् कुनै िकिाला िा\nसंरिक,\n\n(ङ) कसूरबाट कुनै सङ्गठित संस्थालाई िधत पगु ेकोमा त्र्स्तो\nसंस्थाको मतु र् िई काम गने अधिकार प्राप् त सञ्चालक िा सदस्र्,\nप्रशासक िा प्रमिु कार्कय ारी अधिकृ त।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५३", "title": "उजरु ी गन य सक्नाःे (१) र्स ऐनमा अन्र्था व्र्िस्था िएकोमा बािेक अनसु ूची-४", "content": "बमोत्तजमको कुनै कसूरको सम्बन्िमा अदालतमा देिार्को व्र्त्तिले उजरु ी ठदन सक्नेछाः-\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n48\nwww.lawcommission.gov.np\n(क) कसूरबाट िधत पगु ेको व्र्त्ति,\n(ि) आफ्नो नोकरीको धसलधसलामा अन्र्त्र िवटएको िा विदेशमा\nरिेको राष्ट्रसेिकले उजरु गन य पने कुराको सम्बन्िमा धनजको\nनत्तजकको कुनै िकिाला,\n(ग) कुनै व्र्त्तिले कुनै पद, ओिदा िा अन्र् कुनै िैधसर्तले गन यु पने\nकुनै काम िा संरिण गन यु पने कुनै कुराको सम्बन्िमा त्र्स्तो\nपद, ओिदा िा िैधसर्तमा रिेको व्र्त्ति,\n(घ) बविरा, दृवष्टवििीन बालबाधलका िा पचििर िष य उमेर नाघेको\nव्र्त्ति िा शारीररक िा मानधसक रोगले असमथ य िएको व्र्त्तिले\nउजरु गन य पाउने कुराको सम्बन्िमा धनजको एकाघरको िकिाला\nर त्र्स्तो िकिाला निए अन्र् कुनै िकिाला िा संरिक,\n\n(ङ) कसूरबाट कुनै सङ्गठित संस्थालाई िधत पगु ेकोमा त्र्स्तो\nसंस्थाको मतु र् िई काम गने अधिकार प्राप् त सञ्चालक िा सदस्र्,\nप्रशासक िा प्रमिु कार्कय ारी अधिकृ त।\n(२) उपदफा (१) बमोत्तजमको उजरु ी ठदँदा देिार्को वििरण िलु ाई अनसु ूची-२१\nबमोत्तजमको ढाँचामा ठदन ु पनेछाः-\n\n(क) अधिर्िु िा प्रधतिादीको नाम, थर, ितन (टोल समेत) िधुलर्ा,\nउमेर, पेशा िा व्र्िसार्, बाब ु आमा िा पधत िा पत्न ीको नाम,\n\n(ि) अधिर्िु िा प्रधतिादीको नागररकता, रािदानी सिारी चालक\nइजाजतपत्र िा सत्तजलैसँग फे ला पान य सवकने अन्र् पररचर्ात्मक\nवििरण,\n\n(ग) अधिर्िु िा प्रधतिादी रिे बसेको गाउँपाधलका िा नगरपाधलका,\nिडा नं., गाउँ, टोल, िएसम्म ब्लक नं. र अधिर्िु को थािा\nिएसम्मको अन्र् वििरण,\n(घ) अरुको घरमा डेरा गरी बसेको िए थािा िएसम्म घरिनीको नाम,\nथर र िेगाना,\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n49\nwww.lawcommission.gov.np\n\n(ङ) अधिर्िु िा प्रधतिादीको स्थार्ी बासस्थान निए धनज बसेको\nघर िनीको नाम थर र ितन,\n(च) कसूर सम्बन्िी वििरण,\n\n(छ) एकै पटकमा एकिन्दा बढी कसूर िएको िए अधिर्िु िा\n\nप्रधतिादी उपर लगाइएको प्रत्र्ेक अधिर्ोग िा आरोप र\nतत्सम्बन्िी प्रमाण,\n(ज) प्रर्ोग िनु ु पने सम्बत्तन्ित कानून र त्र्सको आिार,\n\n(झ) अधिर्िु िा प्रधतिादीलाई िनु ु पने सजार्को माग दािी र सोको\nआिार,\n\n(ञ) कसूरबाट पगु ेको िधत र अधिर्िु िा प्रधतिादीबाट िधतपूधत य\nिराउन ु पने िए िधतपूधतकय ो रकम र त्र्सको आिार,\n(ट) अन्र् आिश्र्क कुरा।\n\n(३) उपदफा (१) बमोत्तजम उजरु ी ठदँदा त्र्स्तो उजरु ीको साथ अधिर्िु िा\nप्रधतिादीको सङ्खतर्ा बरािरको उजरु ीको नक् कल र उजरु िालाले पेश गन य चािेको धलित\nप्रमाणिरुको एक प्रधत नक्क ल पधन पेश गन यु पछय।\n\n.........................", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५४", "title": "संर्िु रुपमा मद्दु ा चलाउन सवकनाःे (१) देिार्का व्र्त्तििरु उपर एउटै अधिर्ोगपत्र,", "content": "प्रधतिेदन, उजरु ी, वफरादपत्र िा आदेश पचायबाट मद्दु ा चलाउन सवकनेछाः-\n(क) एउटै कामको धसलधसलामा एउटै िा विधिन् न कसूर गने व्र्त्तििरु,\n(ि) एउटै कामको धसलधसलामा निए पधन संर्िु रुपमा िा\nधमलोमतोबाट एक िा एकिन्दा बढी कसूर गने व्र्त्तििरु, िा\n(ग) एक अकोसँग सम्बत्तन्ित विधिन् न कसूर गने व्र्त्तििरु।\n(२) देिार्का कसूरिरुमा संलग्न व्र्त्तििरुको िकमा एउटै अधिर्ोगपत्र,\nप्रधतिेदन, उजरु ी, वफरादपत्र िा आदेश पचायबाट मद्दु ा चलाउन सवकनेछाः-\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n50\nwww.lawcommission.gov.np\n(क) कसूरको उद्योग, दरुु त्सािन िा अपराधिक षडर्न्त्र,\n(ि) मधतर्ार िएको कसूर,\n(ग) कसूरबाट प्राप् त कुनै चीजिस्त ु रािेको, वकनके ो, बेचेको, ठदएको िा\nधलएको कसूर,\n(घ) कसूर गने मनसार्ले कुनै चीजिस्त ु रािेको, बेचेको ठदएको िा\nधलएको कसूर, िा\n(ङ) कसूरसँग सम्बत्तन्ित कुनै व्र्त्तिलाई लकु ाएको िा िगाएको\nकसूर।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५५", "title": "प्रत्र्के कसूर िा अधिर्िु को सम्बन्िमा छुट्टा छुट्टै उजरु ी ठदन ु पनेाः दफा ५३ र ५४ मा", "content": "अन्र्था लेत्तिएकोमा बािेक प्रत्र्ेक कसूर िा अधिर्िु को सम्बन्िमा छुट्टाछुट्टै अधिर्ोगपत्र\nिा उजरु ी ठदन ु िा आदेश पचाय िडा गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५६", "title": "नपे ाल सरकारलाई िादी कार्म गनेाः दफा ५२ को उपदफा (२) बमोत्तजमको उजरु ीबाट", "content": "चलेको मद्दु ा बािेक अनसु ूची-१ र अनसु ूची-२ अन्तगतय का कसूर सम्बन्िी मद्दु ामा नेपाल\nसरकारलाई िादी कार्म गरी मद्दु ाको कारबािी चलाइनेछ।\nपररच्छेद-६\nपक्राउ पजू ी र समाह्वान", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५७", "title": "पक्राउ गने िा समाह्वान जारी गनेाः (१) र्स ऐन बमोत्तजम उजरु ी परेपधछ अनसु ूची-१ र", "content": "अनसु ूची-२ मा उत्तल्लत्तित कसूर सम्बन्िी मद्दु ामा उजरु ीसाथ उपत्तस्थत निएका\nअधिर्िु लाई उपत्तस्थत गराउन अदालतले र्स पररच्छेदको अिीनमा रिी आिश्र्कता\nअनसु ार पक्राउ पूजी िा समाह्वान जारी गनेछ।\n(२) देिार्को कसूरको अधिर्िु लाई उपत्तस्थत गराउन अदालतले उपदफा (१)\nबमोत्तजम पक्राउ पूजी जारी गनेछाः-\n(क) जघन्र् कसूर िा गम्िीर कसूर,\n(ि) िण्ड (क) मा उत्तल्लत्तित कुनै कसूरको उद्योग, दरुु त्सािन िा\nआपराधिक षडर्न्त्र गरेको िा सो कसूरमा मधतर्ार िएको कसूर\nिा त्र्स्ता कसूरको अधिर्िु लाई लकु ाएको िा िगाएको कसूर।\n51\nwww.lawcommission.gov.np\n(३) उपदफा (२) मा उत्तल्लत्तित कसूर बािेक अन्र् कसूरको अधिर्िु लाई\nअदालतमा उपत्तस्थत गराउन अदालतले आिश्र्कता अनसु ार समाह्वान जारी गनेछ।\nतर अधिर्िु िागी पक्राउ िनु नसक्ने सम्िािना छ िन् ने विश्वास गन यु पने\nमनाधसब कारण िएमा िा समाव्िानमा तोवकएको म्र्ादमा अधिर्िु अदालतमा उपत्तस्थत\nनिएमा त्र्स्तो अधिर्िु का िकमा अदालतले उपदफा (२) बमोत्तजम पक्राउ पूजी जारी\nगन य सक्नेछ।\n(४) अदालतमा दात्तिल गन यु पने कुनै धलित िा दसी प्रमाण लकु ाउने िा नास\nगने सम्िािना छ िन् ने विश्वास गन यु पने मनाधसब कारण िएमा िा उपदफा (३) बमोत्तजम\nजारी िएको समाह्वानमा तोवकएको म्र्ादधित्र कुनै धलित िा दसी प्रमाण अदालतमा\nदात्तिल नगरेमा अदालतले त्र्स्तो धलित िा दसी प्रमाण दात्तिल गन यु पने कतव्य र् िएको\nव्र्त्तिलाई पक्राउ गरी उपत्तस्थत गराउन पक्राउ पूजी जारी गन य सक्नेछ।\n(५) उपदफा (४) बमोत्तजम पक्राउ पूजी जारी िएकोमा अदालतले त्र्स दफामा\nउत्तल्लत्तित धलित िा दसी प्रमाण रिेको िाउँको तलासी धलई अदालतमा दात्तिल गन य\nकुनै कमचय ारी िा कुनै प्रिरी अधिकृ तलाई आदेश ठदन सक्नेछ।\n(६) उपदफा (५) बमोत्तजमको कमचय ारी िा प्रिरी अधिकृ तले कुनै िाउँको\nिानतलासी गदाय दफा १८ बमोत्तजम गन यु पनेछ।\n(७) अदालतले र्स दफा बमोत्तजम कुनै अधिर्िु लाई उपत्तस्थत गराउन पक्राउ\nपूजी िा समाह्वान जारी गदाय उजरु ीको व्र्िोरा समेत िल्ु ने गरी अनसु ूची-२२ बमोत्तजमको\nढाँचामा सूचना पिाउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५८", "title": "पक्राउ पजू ी जारी गन े कार्वयिधिाः (१) अदालतले र्स पररच्छेद बमोत्तजम पक्राउ पूजी", "content": "जारी गदाय पक्राउ गन यु पने व्र्त्तिको पूरा नाम र िेगाना तथा पक्राउ गन यु पने कारण\nस्पष्ट रुपमा उल्लेि गरी अधिर्िु को सम्बन्िमा िए अनसु ूची-२३ बमोत्तजमको ढाँचामा\nर सािी तथा अन्र् व्र्त्तिको सम्बन्िमा िए अनसु ूची-२४ बमोत्तजमको ढाँचामा पक्राउ\nपूजी जारी गन यु पनेछ।\n(२) उपदफा (१) बमोत्तजम जारी िएको पक्राउ पूजीमा सम्बत्तन्ित अधिकारीले\nसिीछाप गरी अदालतको छाप लगाउन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम पक्राउ पूजी जारी गदाय पक्राउ गन यु पने व्र्त्ति रिे\nबसेको िा रिन बस्न सक्ने इलाकाको प्रिरी कार्ालय र्को नाउँमा जारी गन यु पनेछ।\n52\nwww.lawcommission.gov.np\nतर अदालतले आिश्र्क सम्झेमा अदालतकै कमचय ारीको नाउँमा पधन पक्राउ पूजी\nजारी गन य सक्नेछ।\n(४) र्स दफा बमोत्तजम जारी िएको पक्राउ पूजी तामेल निएसम्म िा\nअदालतबाट बदर निएसम्म कार्म रिनेछ।\n(५) पक्राउ पूजी जारी िएको व्र्त्तिलाई त्र्स्ता पूजी बमोत्तजम पक्राउ गन य\nसवकनेछ र त्र्स बमोत्तजम कुनै व्र्त्तिलाई पक्राउ गदाय धनजलाई पक्राउ पूजी देिाई\nदफा ५७ को उपदफा (७) बमोत्तजम पिाएको सूचना समेत धनजलाई ठदन ु पनेछ।\n(६) पक्राउ पूजी बमोत्तजम पक्राउ गररएको व्र्त्तिलाई बाटोको म्र्ाद बािेक\nचौबीस घण्टामा नबढाई र्थासम्िि चाँडो सम्बत्तन्ित अदालतमा उपत्तस्थत गराउन ु\nपनेछ।\n(७) प्रिरीले पक्राउ पूजी प्राप् त गरेको धमधतले सात ठदनधित्र पक्राउ गन यु पने\nव्र्त्ति फे ला परेन िने सम्बत्तन्ित प्रिरी कार्ायलर्ले धनजको िोजी गदै रिी त्र्सपधछ\nत्र्स्तो व्र्त्ति रिे बसेको घर िेगानामा गई धनजको नाउँमा जारी िएको अनसु ूची-२५\nबमोत्तजमको ढाँचामा पैँतीस ठदने पक्राउ पूजी धनजको एकाघरका उमेर पगु ेका व्र्त्तिलाई\nबझु ाई सोको िरपाईय धमसील सामेल रात न ु पनेछ।\n(८) उपदफा (७) बमोत्तजमका व्र्त्तिले त्र्स्तो पूजी बझु ी नधलए िा फे ला नपरे\nस्थानीर् तिको सम्बत्तन्ित िडा सधमधतका सदस्र् उपलब्ि िए धनज र धनज पधन उपलब्ि\n\nनिए कम्तीमा दईु जना स्थानीर् व्र्त्तिलाई सािी रािी धनजको घर दैलोमा टाँसी एक\nप्रधत पूजी अदालतमा ल्र्ाई बझु ाउन ु पनेछ।\n(९) उपदफा (८) बमोत्तजम सम्बत्तन्ित व्र्त्ति रिे बसेको घरमा सूचना टाँस\nगरेको पूजीको एक प्रधत स्थानीर् तिको सम्बत्तन्ित िडा कार्ायलर्मा समेत बझु ाई\nत्र्सको िरपाईय धमधसल सामेल रात न ु पनेछ।\n(१०) उपदफा (९) बमोत्तजम पूजी बझु ाएकोमा स्थानीर् तिको सम्बत्तन्ित िडा\nकार्ायलर्ले त्र्स्तो पूजी प्राप् त िएपधछ सम्बत्तन्ित व्र्त्तिलाई त्र्सको जानकारी गराई\nआफ्नो सूचना पाटीमा समेत टाँस गन यु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n53\nwww.lawcommission.gov.np\n(११) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन पक्राउ पजु ी जारी\nगररएको व्र्त्ति पक्राउ पनियु न्दा अगािै आफैँ अदालतमा उपत्तस्थत िएमा धनजलाई\nपक्राउ गरी थनु ामा रात न ु पने िा नपने सम्बन्िमा कानून बमोत्तजम सनु िु ाई गन यु पनेछ र\nधनजको नाममा पविले जारी िएको पक्राउ पजु ी बदर गरी सम्बत्तन्ित अधिकारीलाई\nत्र्सको जानकारी ठदन ु पनेछ।\n(१२) पक्राउ पूजी जारी िएको व्र्त्ति धनजको िेगाना बािेक अन्र् कुनै\nत्तजल्लामा गई बसेको छ िन् ने पिको धनिेदन िा अन्र् कुनै माध्र्मबाट अदालतलाई\nजानकारी िएमा अदालतले धनज रिे बसेको त्तजल्लामा पधन पक्राउ पूजी पिाउन\nसक्नेछ।\n(१३) र्स पररच्छेद बमोत्तजम जारी िएको पक्राउ पूजीको म्र्ादधित्र अधिर्िु\nिात्तजर निई फरार रिेमा िा अधिर्िु को र्वकन बतन िल्ु न नसके मा िा अधिर्िु रिे\nबसेको िाउँ पिा नलागेमा अदालतले त्र्स्तो अधिर्िु को िधुलर्ा ठदई नेपाल सरकारको\nस्िाधमत्िमा रिेको रावष्ट्रस्तरको दैधनक समाचारपत्रमा सूचना प्रकात्तशत गरी सम्बत्तन्ित\nअदालतको सूचना पाटीमा टाँस्न सक्नेछ।\n(१४) उपदफा (१३) बमोत्तजम सूचना प्रकात्तशत िएपधछ अधिर्िु ले रीतपूिकय\nसूचना पाएको माधननेछ र धनजलाई जनु सकु ै प्रिरी कार्ायलर् िा कमचय ारीले जनु सकु ै बित\nपक्राउ गरी दािेल गन य सक्नेछ।\n\n(१५) उपदफा (१३) बमोत्तजम सूचना प्रकाशन िएपधछ जनु सकु ै बित\nअदालतले पक्राउ पूजी बमोत्तजम पक्राउ गन यु पने व्र्त्तिको िकको सम्पत्ति रोक् का गन य\nआदेश ठदन सक्नेछ।\n(१६) उपदफा (१५) बमोत्तजम सम्पत्ति रोक् का गने आदेश िएकोमा त्र्सको\nजानकारी सम्बत्तन्ित मालपोत कार्ायलर् िा अन्र् धनकार् िा संस्थालाई ठदई त्र्सको\nसूचना अदालतको सूचना पाटीमा टाँस्न ु पनेछ।\n(१७) उपदफा (१६) बमोत्तजम सम्पत्ति रोक् का रात न अदालतबाट लेिी\nआएकोमा सम्बत्तन्ित मालपोत कार्ायलर् िा धनकार् िा संस्थाले त्र्स्तो सम्पत्ति तरुु न्त\nरोक् का रािी त्र्सको जानकारी रोक् का रात ने अदालतलाई ठदन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n54\nwww.lawcommission.gov.np\n(१८) अदालतबाट उपदफा (१५) बमोत्तजम सम्पत्ति रोक् का रात ने आदेश\nिएकोमा प्रचधलत कानूनमा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्तो सम्पत्ति त्र्स्तो\nआदेश िएको धमधतबाट न ै रोक् का िएको माधननेछ।\n(१९) र्स पररच्छेद बमोत्तजम पक्राउ गन यु पने व्र्त्ति अदालतमा उपत्तस्थत\nिएपधछ मद्दु ाको कारबािी जनु सकु ै अिस्थामा पगु ेको िए तापधन अदालतले सम्बत्तन्ित\nमालपोत कार्ालय र् िा अन्र् धनकार् िा संस्थालाई र्स दफा बमोत्तजम रोक् का रािेको\nत्र्स्तो व्र्त्तिको सम्पत्ति तरुु न्त फुकुिा गने आदेश ठदन ु पनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "५९", "title": "समाह्वान जारी गने कार्वयिधिाः (१) अदालतले र्स ऐन बमोत्तजम अधिर्िु िा", "content": "प्रधतिादीको नाउँमा अदालतमा उपत्तस्थत िनु समाह्वान जारी गदाय बाटाको म्र्ाद बािेक\nएक्काईस ठदनको अिधि तोकी म्र्ाद जारी गन यु पनेछ।\n\n(२) उपदफा (१) बमोत्तजम अधिर्िु िा प्रधतिादीको नाउँमा समाह्वान जारी\nगदाय अनसु ूची-४ मा उत्तल्लत्तित कसूर बािेकको मद्दु ामा अनसु ूची-२६ बमोत्तजमको ढाँचामा\nर अनसु ूची-४ मा उत्तल्लत्तित कसूर सम्बन्िी मद्दु ामा अनसु ूची-२७ बमोत्तजमको ढाँचामा\nम्र्ाद जारी गन यु पनेछ।\n\n(३) उपदफा (१) बमोत्तजमको म्र्ादधित्र उपत्तस्थत िनु नसके को कारण देिाई\nसमाह्वानको म्र्ाद थामी पाउन धनिेदन ठदएमा र त्र्स्तो व्र्िोरा मनाधसब देत्तिएमा\nअदालतले एकपटकको लाधग बढीमा पन्र ठदनसम्मको समाह्वानको म्र्ाद थामी ठदन े\nआदेश ठदन सक्नेछ।\n\n(४) .............\n(५) र्स दफा बमोत्तजम तामेल िएको समाव्िानमा तोवकएको म्र्ादधित्र उपत्तस्थत\n\nनिनु े अधिर्िु िा प्रधतिादीको िकमा धनजलाई पक्राउ गरी उपत्तस्थत गराउन ु पने िन् न े\nअदालतलाई लागेमा दफा ५७ को उपदफा (३) को प्रधतिन्िात्मक िाक्र्ांश बमोत्तजम\nपक्राउ पूजी जारी गन य सक्नेछ।\nतर काबू बाविरको पररत्तस्थधत परी तोवकएको म्र्ादधित्र उपत्तस्थत िनु नसके को\nकारण देिाई अधिर्िु ले धनिेदन ठदएमा र अदालतले धनिेदनको व्र्िोरा मनाधसब\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n55\nwww.lawcommission.gov.np\nििराएमा काबू बाविरको पररत्तस्थधत कार्म रिेको अिधि व्र्तीत िएको धमधतले बाटोको\nम्र्ाद बािेक बढीमा पन्र ठदनसम्मको म्र्ाद थामी ठदने आदेश ठदन सक्नेछ।\nस्पष्टीकरणाः र्स ऐनको प्रर्ोजनका लाधग “काबू बाविरको पररत्तस्थधत कार्म रिेको अिधि”\nिन् नाले देिार्को अिधिलाई जनाउँछाः-\n(क) अदालतमा उपत्तस्थत िनु ु पने व्र्त्तिको कोिी मत्ृ र् ु िई परम्परा अनसु ार\n\nधनज आफैँ वकररर्ा िा वकररर्ा सरिको शोकिरण गरी बस्न ु परेको िए\nत्र्स्तो व्र्त्तिको मत्ृ र् ु िएको पन्र ठदन पगु ेको धमधतले बाटोको म्र्ाद\nबािेक सात ठदन,\n(ि) अदालतमा उपत्तस्थत िनु ु पने व्र्त्ति मविला िई सत्ु के री िएको िए\nसत्ु के री िएको धमधतले बाटोको म्र्ाद बािेक सािी ठदन,\n(ग) अदालतमा उपत्तस्थत िनु ु पने म्र्ादधित्र िोलो पविरो िा विउँले बाटो बन्द\nिई िा कफ्र्र्ूको घोषणा िएको िा अन्र् कुनै कारणले सािजय धनक\nर्ातार्ातको सािन नचलेको िए बाटो िलु ेको िा सािजय धनक र्ातार्ातको\nसािन चलेको धमधतले बाटोको म्र्ाद बािेक पन्र ठदन,\n(घ) अदालतमा उपत्तस्थत िनु ु पने म्र्ादधित्र िकू म्प िा ज्िालामिु ी जस्ता\nविपद् परेको िए त्र्स्तो िएको धमधतले बाटोको म्र्ाद बािेक दश ठदन,\n(ङ) अदालतमा उपत्तस्थत िनु ु पने व्र्त्तिलाई कसैले अपिरण गरी लगेको िा\nशरीर बन्िक बनाएको िए त्र्स्तो अपिरण िा बन्िकबाट मिु िएको\nधमधतले बाटोको म्र्ाद बािेक पन्र ठदन,\n(च) अदालतमा उपत्तस्थत िनु ु पने व्र्त्ति कुनै दघु टय नाको कारण अचेत िा\nविँडडुल गन य नसक्ने िई िा अशि विरामी िएको कारण विँडडुल गन य\nनसक्ने िई नेपाल सरकारबाट स्िीकृ त अस्पतालमा िनाय िई उपचार\nगराएकोमा अनसु ूची-४ बमोत्तजमको मद्दु ाको पिको िकमा पन्र ठदन र\nअन्र् मद्दु ाको पिको िकमा तीन मविनािन्दा बढी निनु े गरी\nअस्पतालबाट धडस्चाज य निएसम्मको अिधि।\n(६) उपदफा (५) को िण्ड (क) र (ङ) को अिस्थामा सम्िि िएसम्म\nसम्बत्तन्ित व्र्त्तिले अदालतलाई सोको सूचना तरुु न्त ठदन ु पनेछ।\n56\nwww.lawcommission.gov.np\n\n(७) उपदफा (५) बमोत्तजम ठदइने धनिेदन साथ काबूबाविरको पररत्तस्थधत उत्पन्न\nिएको व्र्िोरा पष्टु ी गन य आिश्र्क पने प्रमाण संलग्न गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६०", "title": "सािीको नाममा समाह्वान जारी गन य सक्नाःे र्स ऐन बमोत्तजम अदालतले सािीका नाममा", "content": "समाह्वान जारी गदाय आिश्र्क वििरण उल्लेि गरी अनसु ूची-२८ बमोत्तजमको ढाँचामा\nजारी गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६१", "title": "समाह्वानको तामेलीाः (१) समाह्वान तामेल गन य पिाउदा तीन प्रधत समाह्वान पूजी ठदई कुन ै", "content": "प्रिरी कमचय ारी, अदालतको कुनै कमचय ारी िा अदालतले तोके को अन्र् कुनै सरकारी\nकार्ायलर्द्वारा तामेल गराउन पिाउन ु पनेछ।\n\n(२) र्स ऐन बमोत्तजम जारी िएको समाह्वान जनु व्र्त्तिको नाममा जारी िएको\nिो र्थासम्िि सोिी व्र्त्तिलाई बझु ाउन ु पनेछ।\n(३) उपदफा (२) बमोत्तजम समाह्वान बझु ाउन जाँदा सम्बत्तन्ित व्र्त्ति फे ला\nनपरेमा िा फे ला परे पधन धनजले बझु ी नधलएमा धनजको एकाघरको कम्तीमा अिार िष य\nउमेर पधुगसके को कुनै व्र्त्तिलाई बझु ाउन सवकनेछ।\n(४) उपदफा (३) बमोत्तजम सम्बत्तन्ित व्र्त्ति िा एकाघरका व्र्त्ति फे ला\nनपरेमा िा फे ला परेमा पधन धनजले िा धनजको एकाघरका व्र्त्तिले समेत बझु ी नधलएमा\nस्थानीर् तिको सम्बत्तन्ित िडाको सदस्र् एक जना र कम्तीमा दईु जना स्थानीर् व्र्त्ति\nसमेत रािी आफ्नो तथा धनजिरुको समेत सिीछाप गराई एक प्रधत धनजको घर दैलामा\nटाँसी एक प्रधत म्र्ाद सम्बत्तन्ित स्थानीर् तिको सम्बत्तन्ित िडा कार्ायलर्मा बझु ाई एक\nप्रधत तामेली समाह्वान अदालतमा दात्तिला गन यु पनेछ।\n(५) उपदफा (४) बमोत्तजम प्राप् त िएको समाह्वान बमोत्तजमको सूचना स्थानीर्\nतिको सम्बत्तन्ित िडा कार्ायलर्ले आफ्नो सूचना पाटीमा टासँ गन यु पनेछ।\n(६) उपदफा (५) बमोत्तजम समाह्वान जारी गररएको व्र्त्तिको समाव्िानमा\nउत्तल्लत्तित िेगानामा बसोबास निएको िन् ने कुरा स्थानीर् तिको सम्बत्तन्ित िडा\nसधमधतको कम्तीमा एक जना सदस्र् र कम्तीमा दईु जना स्थानीर् व्र्त्तििरुले प्रमात्तणत\nगरेमा धनजको बसोबास िएको िेगाना िल्ु न सक्न े िए िलु ाई र िल्ु न नसक्ने िए सोिी\nव्र्िोरा जनाई समाह्वान अदालतमा वफताय बझु ाई ठदन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n57\nwww.lawcommission.gov.np\n(७) उपदफा (६) बमोत्तजम समाह्वान वफताय िएकोमा अदालतले धनज बसोबास\nगरेको िाउँमा िा िाउँ निलु ेमा िादी पिलाई समेत बझु ी आिश्र्कता अनसु ार िेगाना\nिलु ाई अको समाह्वान जारी गनेछ।\n(८) नेपाल सरकार िा कुनै सङ्गठित संस्थाको पदाधिकारी िा कमचय ारीका नाममा\nसमाह्वान तामेल गन यु परेमा त्र्स्तो पदाधिकारी िा कमचय ारी ििाल रिेको कार्ायलर्मा\nसमाह्वान तामेल गन य सवकनेछ।\n(९) उपदफा (८) बमोत्तजम कुनै समाह्वान तामेल गन य पिाएकोमा त्र्स्तो\nकार्ायलर् िा संस्थाको तत्काल उपलब्ि िएको प्रमिु ले एक प्रधत समाह्वान सम्बत्तन्ित\nपदाधिकारी िा कमचय ारीलाई बझु ाई अको प्रधतमा तामेलीको व्र्िोरा र धमधत जनाई सम्िि\nिएमा सम्बत्तन्ित पदाधिकारी िा कमचय ारीको सिीछाप गराई अदालतमा वफताय पिाउन ु\nपनेछ।\n(१०) उपदफा (९) बमोत्तजम समाह्वान तामेल िनु नसके मा सम्बत्तन्ित कार्ायलर्\nिा संस्थाको सूचना पाटीमा त्र्स्तो समाह्वान टाँसी ठदन ु पनेछ। र्सरी सूचना पाटीमा\nटाँधसएको प्रधतिेदन सम्बत्तन्ित अदालतमा ठदन ु पनेछ।\n(११) उपदफा (८) बमोत्तजम समाह्वान तामेल गदाय त्र्स्तो पदाधिकारी िा\nकमचय ारी धबदामा रिेकोमा सम्बत्तन्ित कार्ायलर् िा संस्थाले र्थाशीघ्र त्र्स्तो कमचय ारीलाई\nत्र्सरी समाह्वान तामेल िएको व्र्िोराको सूचना ठदन ु पनेछ।\n(१२) कुनै सङ्गठित संस्थाको नाममा समाह्वान तामेल गन यु परेमा त्र्स्तो\nसमाह्वानको एक प्रधत त्र्स्तो संस्थाको प्रिान िा स्थानीर् कार्ायलर्मा बझु ाई सोकोेे\nिरपाईय अदालतमा बझु ाउन ु पनेछ।\n(१३) उपदफा (१२) बमोत्तजम स्थानीर् कार्ायलर्मा समाह्वान तामेल िएकोमा\nसो समाह्वान त्र्स्तो संस्थाको प्रिान कार्ायलर्मा तामेल िएको माधननेछ।\n(१४) र्स दफा बमोत्तजम समाह्वान तामेल गदाय तामेल िएको धमधत र व्र्िोरा\nउल्लेि गरी तामेल गने कमचय ारीले अदालतमा प्रधतिेदन ठदन ु पनेछ।\n(१५) कुनै अदालतले आफ्नो िेत्रिन्दा बाविरको अन्र् कुनै िेत्रमा बसोबास\nगरररिेको कुनै व्र्त्तिलाई समाह्वान तामेल गन यु पने िएमा त्र्स्तो िेत्रको अदालतमा\nसमाह्वान पिाई सो अदालत माफय त तामेल गराउन ु पनेछ र त्र्स्तो अदालतले पधन र्स\n58\nwww.lawcommission.gov.np\nपररच्छेद बमोत्तजम समाह्वान तामेल गराई त्र्सको एक प्रधत समाह्वान जारी गने अदालतमा\nवफताय पिाइठदन ु पनेछ।\n(१६) र्स दफा बमोत्तजम समाह्वान तामेली गदाय अधिर्िु लाई दफा ५७ को\nउपदफा (७) बमोत्तजम पिाइएको सूचना पधन समाह्वान साथै बझु ाउन िा अिस्थाअनसु ार\nघर दैलोमा टाँस्न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६२", "title": "छापा िा विद्यतु ीर् सञ्च ार माध्र्मबाट समाह्वान तामेल गन य सवकनाःे (१) कुनै समाह्वान", "content": "दफा ६१ बमोत्तजम तामेल गन य नसवकएकोमा अदालतले त्र्स्तो समाह्वानको व्र्िोरा\nनेपाल सरकारको स्िाधमत्िमा रिेको रावष्ट्रर् स्तरको कुनै दैधनक समाचारपत्रमा प्रकाशन\nगरी िा विद्यतु ीर् सञ् चार माध्र्मबाट प्रसारण गरी तामेली गन य सक्नेछ।\n(२) उपदफा (१) बमाोत्तजम समाह्वान प्रकाशन िा प्रसारण िएकोमा त्र्स्तो\nसमाह्वान रीतपूिकय तामेल िएको माधननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६३", "title": "पक्राउ पजू ीको तामेलीाः (१) पक्राउ पूजी तामेल गन य पिाउँदा तीन प्रधत पक्राउ पूजी", "content": "\nपिाई जनु व्र्त्तिका नाममा जारी िएको िो िरसक धनजलाई नै बझु ाई पक्राउ गरी\nल्र्ाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम जारी गररएको पक्राउ पूजी जसको नाममा जारी\nगररएको िो त्र्स्तो व्र्त्तिले बत्तुझधलन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम पक्राउ पूजी बझु ाउन जाँदा सम्बत्तन्ित व्र्त्ति फे ला\nनपरेमा धनजको एकाघरको कम्तीमा अिार िष य उमेर पधुगसके को कुनै व्र्त्तिलाई बझु ाउन\nसवकनेछ।\n(४) उपदफा (३) बमोत्तजम सम्बत्तन्ित व्र्त्ति िा एकाघरका व्र्त्ति फे ला\nनपरेमा िा फे ला परेमा पधन धनजले िा धनजको एकाघरको व्र्त्तिले समेत बझु ी नधलएमा\n\nस्थानीर् तिको सम्बत्तन्ित िडा सधमधतका सदस्र् उपलब्ि िए धनज र धनज पधन\nउपलब्ि निए कम्तीमा दईु जना स्थानीर् व्र्त्ति सािी रािी आफ्नो तथा धनजिरुको\nसमेत सिीछाप गराई एक प्रधत धनजको घर दैलामा टाँसी एक प्रधत स्थानीर् तिको\nसम्बत्तन्ित िडा कार्ायलर्मा बझु ाई एक प्रधत तामेली पक्राउ पूजी अदालतमा दात्तिला गन यु\nपनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n59\nwww.lawcommission.gov.np\n(५) उपदफा (४) बमोत्तजम प्राप् त िएको पक्राउ पूजी बमोत्तजमको सूचना स्थानीर्\n\nतिको सम्बत्तन्ित िडा कार्ायलर्ले आफनो सूचना पाटीमा टाँस गन यु पनेछ।\n(६) र्स पररच्छेद बमोत्तजम जारी िएको पक्राउ पूजी बमोत्तजम पक्राउ गन यु पने\nव्र्त्तिको उत्तल्लत्तित िेगानामा बसोबास निएको कुरा त्र्स्तो िाउँमा बसोबास गने\nकम्तीमा दईु जना व्र्त्तििरु र स्थानीर् तिको सम्बत्तन्ित िडा सधमधतको कम्तीमा एक\nजना सदस्र्ले प्रमात्तणत गरेमा धनजको बसोबास िएको िाउँ िल्ु न सक्ने िए िलु ाई र\nिल्ु न नसक्ने िए सोिी व्र्िोरा जनाई पक्राउ पूजी अदालतमा वफताय बझु ाइठदन ु पनेछ।\n(७) उपदफा (६) बमोत्तजम पक्राउ पूजी वफताय िएकोमा अदालतले धनज बसोबास\nगरेको िेगानामा िा त्र्स्तो िेगाना निलु े िादी पिलाई िलु ाउन मौका ठदई आिश्र्कता\nअनसु ार अको पक्राउ पूजी जारी गन यु पनेछ।\n(८) र्स दफा बमोत्तजम पक्राउ पूजी तामेल गदाय तामेल िएको धमधत र व्र्िोरा\nउल्लेि गरी तामेल गने कमचय ारीले अदालतमा प्रधतिेदन ठदन ु पनेछ।\n(९) कुनै अदालतले आफ्नो अधिकार िेत्रिन्दा बाविरको अन्र् कुनै िेत्रमा\nबसोबास गरी रिेको कुनै व्र्त्तिलाई पक्राउ पूजी तामेल गन यु पने िएमा त्र्स्तो िेत्रको\nअदालतमा पक्राउ पूजी पिाई त्र्स्तो अदालत माफय त तामेल गराउन ु पनेछ र त्र्स्तो\nअदालतले पधन र्स पररच्छेद बमोत्तजम पक्राउ पूजी तामेल गराई त्र्सको एक प्रधत\nपक्राउ पूजी जारी गने अदालतमा वफताय पिाइठदन ु पनेछ।\n(१०) उपदफा (८) बमोत्तजमको प्रधतिेदन ठदने कमचय ारीले र्स दफा बमोत्तजमको\nकार्वयिधि अपनाउँदा पक्राउ पूजी तामेल िनु नसके को कारण िलु ाई प्रधतिेदन ठदएमा\nर्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन सम्बत्तन्ित व्र्त्तिको नाममा जारी\nिएको पक्राउ पूजी नेपाल सरकारको स्िाधमत्िमा रिेको रावष्ट्रर् स्तरको दैधनक\nसमाचारपत्रमा प्रकाशन गरी तामेल गन य सवकनेछ र त्र्सरी तामेल िएको पक्राउ पूजी\nरीतपूिकय तामेल िएको माधननेछ।\n(११) पक्राउ पूजी तामेली गदाय अधिर्िु लाई दफा ५७ को उपदफा (७)\nबमोत्तजम पिाइएको सूचना पधन पक्राउ पूजी साथै बझु ाउन िा अिस्था अनसु ार धनजको\nघर दैलोमा टाँस्न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६४", "title": "विदेशमा रिे बसेका अधिर्िु का नाममा पक्राउ पजू ी जारी गन य िा समाह्वान तामेल गन य", "content": "सवकनाःे (१) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै अदालतमा\n60\nwww.lawcommission.gov.np\nविचारािीन रिेको कुनै कसूरको अधिर्िु विदेशमा रिे बसेको िए त्र्स्ता व्र्त्तिको\nनाममा पक्राउ पूजी जारी गनपयु दाय िा समाह्वान तामेल गन यु पदाय पारस्पररक कानून\nसिार्ता सम्बन्िी प्रचधलत कानून बमोत्तजम त्र्स्तो व्र्त्तिको नाममा पक्राउ पूजी जारी\nगन य िा समाह्वान तामेल गन य सवकनेछ।\n(२) उपदफा (१) बमोत्तजम जारी िएको पक्राउ पूजी िा समाह्वान तामेल िएको\nसूचना नेपाल सरकारलाई प्राप् त िएमा सोको जानकारी सम्बत्तन्ित अदालतलाई ठदन ु\nपनेछ।\n(३) उपदफा (१) बमोत्तजम जारी िएको पक्राउ पूजी िा समाह्वान तामेल िनु\nनसके मा त्र्स्तो पक्राउ पूजी िा समाह्वान नेपाल सरकारको स्िाधमत्िमा रिेको रावष्ट्रर्\nस्तरको दैधनक समाचारपत्रमा प्रकाशन गरी िा विद्यतु ीर् सञ् चार माध्र्ममा प्रसारण गरी\nतामेल गन य सवकनेछ।\n(४) उपदफा (१) बमोत्तजम पक्राउ पूजी जारी िएकोमा िा समाह्वान तामेल\nिएकोमा र्सै ऐन बमोत्तजम जारी िएको िा तामेल िएको माधननेछ।\n(५) उपदफा (१) बमोत्तजम पक्राउ पूजी जारी िई सम्बत्तन्ित मलु कु को प्रिरीले\nअधिर्िु लाई पक्राउ गरी कुनै प्रिरी कार्ायलर्लाई िस्तान्तरण गरेमा धनजलाई बाटोको\nम्र्ाद बािेक बढीमा चौबीस घण्टाधित्र र्थात्तशघ्र सम्बत्तन्ित अदालतमा उपत्तस्थत गराउन ु\nपनेछ।\n(६) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन र्स दफा बमोत्तजम\nविदेशमा रिे बसेको व्र्त्तिको नाममा पक्राउ पूजी जारी िनु िा समाह्वान तामेल िनु\nनसके कोमा सोिी कारणले मात्र मद्दु ाको कारबािी र वकनारा गन य बािा पगु ेको माधनन े\nछैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६५", "title": "फरार रिेको व्र्त्तिको सम्बन्िमा विशषे व्र्िस्थााः (१) र्स पररच्छेद बमोत्तजम पक्राउ", "content": "पूजी जारी िई फे ला पन य नसकी पक्राउ िनु नसके को िा फरार रिी अदालतमा उपत्तस्थत\n\nनिनु े व्र्त्तिका िकमा पक्राउ पूजी जारी िएको पैंतीस ठदनको िोधलपल्टदेत्ति धनज\nअदालतमा उपत्तस्थत निएसम्म देिार्का कुरामा देिार् बमोत्तजम िनु ेछाः-\n(क) त्र्स्तो व्र्त्ति नेपाल सरकार, प्रदेश सरकार, स्थानीर् ति,\nसंिैिाधनक धनकार् िा कुनै सरकारी कार्ायलर्, नेपाल सरकार,\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n61\nwww.lawcommission.gov.np\nप्रदेश सरकार िा स्थानीर् तिको पूण य िा आंत्तशक स्िाधमत्ि िा\nधनर्न्त्रणमा रिेको सङ्गठित संस्था, शैत्तिक िा प्रात्तज्ञक संस्था िा\nअन्र् कुनै सािजय धनक संस्थाको बिालिाला पदाधिकारी िा\nकमचय ारी िए धनज आफ्नो पदबाट स्िताः धनलम्बन िएको\nमाधननेछ,\n(ि) त्र्स्तो व्र्त्तिको सम्पत्ति दफा ५८ को उपदफा (१५) बमोत्तजम\nरोक् का िएको रिेनछ िने धनजको नाममा रिेको अचल सम्पत्ति\nसोिी उपदफा बमोत्तजम रोक् का रात्तिनेछ,\n(ग) त्र्स्तो व्र्त्तिको नाममा िा एकल स्िाधमत्िमा रिेको उद्योग,\nव्र्ापार िा व्र्िसार् िा आर्कर दताय सम्बन्िी फम,य उद्योग,\nइजाजत पत्र इत्र्ाठद निीकरण गन यु पने िएमा निीकरण गने\nकार् य स्िताः मलु तिी रिनछे ,\n(घ) त्र्स्तो व्र्त्तिको नाममा रिेको धितोपत्रको कारोबार स्िताः रोक् का\nिनु ेछ,\n(ङ) त्र्स्तो व्र्त्तिले कानून बमोत्तजम प्राप् त गन य सक्ने तलब, ििा,\nउपदान, धनित्तृििरण जस्ता सवुििािरु स्िताः रोक् का रिेको\nमाधननेछ,\n(च) त्र्स्तो व्र्त्तिले प्रचधलत कानून बमोत्तजम पेटेण्ट, धडजाइन, टे«डमाकय ,\nप्रधतधलपी अधिकार जस्ता बौवद्धक सम्पत्तिबाट प्राप् त गने रोर्ल्टी\nलाि िा सवुििा स्िताः रोक् का रिेको माधननेछ,\n(छ) त्र्स्तो व्र्त्तिको नाममा बैङ्क िाता रिेको जानकारी िए त्र्स्तो\nिाताको सञ् चालन रोक् का रात न लेिी आएमा बैङ्क िाता रोक् का\nरात न ु पनेछ,\n(ज) त्र्स्तो व्र्त्तिलाई प्रचधलत कानून बमोत्तजम नागररकताको\nप्रमाणपत्र, रािदानी िा जग्गािनी प्रमाणपूजाय उपलब्ि नगराउन\nलेिी आएमा सम्बत्तन्ित धनकार्ले नागररकताको प्रमाणपत्र,\nरािदानी िा जग्गा िनी प्रमाण पूजाय उपलब्ि गराउन िँदु ैन,\n62\nwww.lawcommission.gov.np\n(झ) त्र्स्तो व्र्त्ति नेपाल बाविर रिे बसेको जानकारी प्राप् त िनु\nआएमा िा नेपाल सरकार पि रिेको सत्तन्ि िा प्रचधलत कानून\nबमोत्तजम सपदु यगी गन य सवकने अिस्था रिेछ िने त्र्स सम्बन्िी\nकारबािी र त्र्स्तो अिस्था निएमा कसूरको गम्िीरता िेरी\nधनजलाई पक्राउ गन य कू टनैधतक माध्र्म माफय त सम्बत्तन्ित मलु कु\nिा सम्बद्ध अन्तररावष्ट्रर् संस्थालाई अनरु ोि गन य सवकनेछ।\n(२) उपदफा (१) बमोत्तजमको व्र्िस्थालाई प्रिािकारी बनाउन अदालतले\nसम्बत्तन्ित अधिकारी िा धनकार्लाई त्र्सको सूचना ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६६", "title": "अदालतमा न ै म्र्ाद तामेल गन य सवकनाःे (१) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा", "content": "\nलेत्तिएको िए तापधन कुनै अदालतबाट देिार्का व्र्त्तिका नाममा जारी िएको म्र्ाद,\nपक्राउ पूजी, समाह्वान िा सूचना त्र्स्तो व्र्त्तिलाई देिार्को अिस्थामा अदालतमा न ै\nबझु ाई तामेल गन य सवकनेछाः-\n(क) सम्बत्तन्ित अदालतका कमचय ारी िा पदाधिकारी िए धनज\nअदालतमा िात्तजर िँदु ा,\n(ि) सम्बत्तन्ित अदालतमा अको कुनै मद्दु ामा ताररिमा रिेको पि िए\nत्र्स्तो ताररिमा उपत्तस्थत िँदु ा,\n(ग) सम्बत्तन्ित अदालतमा रिेको कुनै मद्दु ामा कुनै पिलाई प्रधतधनधित्ि\nगने िाररस िए त्र्सरी प्रधतधनधित्ि गरी उपत्तस्थत िँदु ा,\n(घ) सम्बत्तन्ित अदालतमा कानून व्र्िसार्को धसलधसलामा उपत्तस्थत\nिनु े कानून व्र्िसार्ी िए त्र्स्तो व्र्िसार्को धसलधसलामा\nउपत्तस्थत िँदु ा, िा\n(ङ) सम्बत्तन्ित अदालतमा सािीको रुपमा उपत्तस्थत िएको व्र्त्ति िए\nसो िैधसर्तमा उपत्तस्थत िँदु ा।\n(२) उपदफा (१) बमोत्तजमका व्र्त्तिका नाममा अदालतबाट जारी िएको\n\nम्र्ाद, पक्राउ पूजी, समाह्वान िा सूचना धनज सम्बत्तन्ित अदालतमा उपत्तस्थत िँदु ाका\nबित बझु ाउन ल्र्ाएमा धनजले बत्तुझधलन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n63\nwww.lawcommission.gov.np\n\n(३) उपदफा (२) बमोत्तजम बझु ाउन ल्र्ाउँदा त्र्स्तो म्र्ाद, पक्राउ पूजी,\nसमाह्वान िा सूचना धनजले बत्तुझधलन इन्कार गरेमा तामेलदारले त्र्स्तो कुराको प्रधतिेदन\nसम्बत्तन्ित अदालतमा तरुु न्त गन यु पनेछ।\n(४) उपदफा (३) बमोत्तजम परेको प्रधतिेदनको व्र्िोरा मनाधसब देत्तिएमा त्र्स्ता\n\nव्र्त्तिले धनजको नाममा जारी िएको त्र्स्तो म्र्ाद, पक्राउ पूजी, समाह्वान िा सूचना\nनबझु ेसम्म सम्बत्तन्ित अदालतले धनजलाई िाररसको िैधसर्तमा प्रधतधनधित्ि गन,य ताररि\nधलन, कानून व्र्िसार् गन य िा सािीको िैधसर्तमा बकपत्र गन य रोक लगाउने आदेश\nगनेछ।\nपररच्छेद-७\nथनु छेक, िरौट तथा जमानत सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६७", "title": "अधिर्िु लाई थनु ामा रातन :े (१) देिार्को कुनै कसूरको अधिर्ोग लागके ो अधिर्िु", "content": "तत्काल प्राप्त प्रमाणबाट कसूरदार देत्तिने िएमा िा कसूरदार िो िन् ने विश्वास गने कुनै\nमनाधसब आिार िएमा अदालतले त्र्स्तो अधिर्िु लाई कारण िलु ाई पपु िय को लाधग\nथनु ामा रात नेछाः\n(क) जन्म कै दको सजार् िनु सक्ने कसूर,\n(ि) तीन िषिय न्दा बढी कै दको सजार् िनु सक्ने अनसु ूची-१ िा\nअनसु ूची-२ अन्तगतय का कसूर, िा\n(ग) िण्ड (क) िा (ि) मा उत्तल्लत्तित कसूरको उद्योग, दरुु त्सािन िा\nअपराधिक षडर्न्त्र गरेको िा त्र्स्तो कसूरमा मधतर्ार िएको\nकसूर।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन कानून बमोत्तजम\nकै दको सजार् िनु सक्ने अधिर्िु लाई देिार्को अिस्थामा अदालतले पपु िय को लाधग\nथनु ामा रात न सक्नेछाः-\n\n(क) अधिर्िु ले अदालतमा कसूर स्िीकार गरेको र मद्दु ाको तथ्र् र\nप्रमाणको मूल्र्ाङ्कन गदाय थनु ामा रात न मनाधसब देत्तिएको,\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n64\nwww.lawcommission.gov.np\n(ि) एक िष य िा सोिन्दा बढी सजार् िनु सक्ने कसूरको अधिर्ोग\nलागेको अधिर्िु को नेपालमा स्थार्ी बसोबास निएको र धनजलाई\nथनु ामा नरािेको िण्डमा धनज िाग्ने र पधछ पक्राउ पने सम्िािना\nनरिेकोमा,\n(ग) दफा ५८ को उपदफा (१) बमोत्तजम जारी िएको पक्राउ पूजी\nबमोत्तजम म्र्ादधित्र िात्तजर निई अधिर्िु पक्राउ िई आएको र\nधनजले उजरु ी साथ अदालतमा उपत्तस्थत िनु नआएको कुन ै\nसन्तोषजनक कारण देिाउन नसके कोमा,\n(घ) अधिर्ोग लाग्निु न्दा तीन िषअय त्तघको अिधिधित्र अन्र् कुन ै\nकसूरको अधिर्ोगमा धनजले कै द सजार् पाउने ििर िएकोमा।\n(३) उपदफा (१) िा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन दश िषिय न्दा\nबढी कै द सजार् िनु सक्ने कसूरमा बािेक अधिर्िु बालबाधलका िा शारीररक िा\nमानधसक रोग लागी अशि िएको िा सात मविनािन्दा बढीकी गििय ती मविला िा\nपचििर िष य माधथको िद्धृ िएमा त्र्स्तो अधिर्िु लाई अदालतले िरौटी िा जमानत\nधलई ताररिमा छोड्न सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६८", "title": "अधिर्िु सगँ िरौट िा जमानत िा बैङ्क जमानत धलनाःे (१) दफा ६७ को अिस्थामा", "content": "िनु ेमा बािेक कुनै अधिर्िु उपरको अधिर्ोग प्रमात्तणत िनु े मनाधसब आिार िएमा\n\nअदालतले धनजसँग िरौट, जमानत िा बैङ्क जमानत धलई ताररिमा रात न सक्नेछ।\nतर बैङ्क जमानत विना शतकय ो र अदालतले तोके बमोत्तजमको अिधिसम्म\nअद्यािधिक िनु सक्ने िनु ु पनेछ।\n(२) उपदफा (१) बमोत्तजम िरौट, जमानत िा बैङ्क जमानत नठदन े अधिर्िु लाई\nअदालतले थनु ामा रात नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६९", "title": "ताररिमा रातन ु पनेाः दफा ६७ र दफा ६८ को अिस्थामा बािेक अन्र् अिस्थामा", "content": "अधिर्िु अदालतमा िात्तजर िएपधछ धनजलाई ताररिमा रािी मद्दु ाको पपु िय गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७०", "title": "थप िरौट, जमानत िा बैङ्क जमानत माग्न सवकनाःे (१) कुनै अधिर्िु बाट धलएको िरौट,", "content": "जमानत िा बैंक जमानतको रकम पधछ अपर्ायप्त िएको देत्तिन आएमा अदालतले धनजसँग\nथप िरौट, जमानत िा बैङ्क जमानत माग्न सक्नेछ।\n65\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजमको थप िरौट, जमानत िा बैङ्क जमानत ठदन नसके मा\nत्र्स्तो अधिर्िु लाई अदालतले थनु ामा रात न सक्नछे ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७१", "title": "कारबािीको जनु सकु ै अिस्थामा पधन थनु ामा िा जमानतमा रातन सवकनाःे (१) मद्दु ाको", "content": "कारबािी जनु सकु ै अिस्थामा पगु ेको िए तापधन अदालतले प्रमाण बिु m्दै जाँदा\nअधिर्िु लाई अिस्था अनसु ार दफा ६७ बमोत्तजम थनु ामा रात न िा दफा ६८ बमोत्तजम\nधनजसँग िरौट, जमानत िा बैङ्क जमानत माग्न सक्नेछ र शरुु मा पपु क्र्षको लाधग\nअधिर्िु लाई थनु ामा नरािेको िा धनजसँग िरौट, जमानत िा बैङ्क जमानत नधलएको\nकारणले मात्र पधछ धनजलाई थनु ामा रात न िा धनजसँग िरौट, जमानत िा बैङ्क जमानत\nमाग्न अदालतलाई िािा परेको माधनने छैन।\n(२) दफा ६७ िा दफा ६८ बमोत्तजम थनु ामा परेको कुनै अधिर्िु कसूरदार\nिोइन िन् ने प्रमात्तणत िनु सक्ने कुनै मनाधसब आिार प्राप् त िनु आएमा मद्दु ाको कारबािी\nजनु सकु ै अिस्थामा पगु ेको िए पधन त्र्स्तो विषर्मा सनु िु ाई गरी अदालतले धनजलाई\nथनु ाबाट छोड्ने आदेश ठदन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७२", "title": "िरौट, जमानत िा बैङ्क जमानतको रकम तोक्न े आिाराः (१) र्स पररच्छेद बमोत्तजम धलन ु", "content": "पने िरौट, जमानत िा बैङ्क जमानतको रकम तोक्दा देिार्को कुरा विचार गरी मनाधसब\nवकधसमले तोक्न ु पछयाः-\n(क) कसूरको प्रकृ धत र गम्िीरता,\n(ि) अधिर्िु िा कसूरदारको आधथकय अिस्था तथा पाररिाररक त्तस्थधत,\n(ग) अधिर्िु िा कसूरदारको उमेर र शारीररक त्तस्थधत,\n(घ) धनजले पविले कुनै कसूरमा कसूरदार ििरी सजार् पाएको िा\nनपाएको,\n(ङ) धनजले एकै िारदातमा विधिन् न कसूर गरे िा नगरेको,\n(च) धनजलाई िएको िा िनु सक्ने सजार् र धनजले व्र्िोन यु पने\nिधतपूधत,य\n(छ) कसूरबाट सत्तृजत पररणाम,\n(ज) कसूरमा साधबती िए िा निएको,\n66\nwww.lawcommission.gov.np\n(झ) असिार् िा अशि व्र्त्ति िा गििय ती िा दिु े बालबाधलका िएकी\nमविला अधिर्िु रिेको।\n(२) र्स ऐन अन्तगतय कुनै व्र्त्तिसँग माधगएको िरौट, जमानत िा बैङ्क\nजमानतको रकम घटी िा बढी िई मनाधसब निएको कारण देिाई मद्दु ाको कुनै पिले\nधनिेदन ठदएमा पनु रािेदन सन्ु ने अदालतले त्र्स्तो विषर्मा सनु िु ाई गरी त्र्स्तो िरौट,\nजमानत िा बैङ्क जमानत रकम थप घट गने िा पररितनय गने आदेश ठदन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७३", "title": "पनु रािदे न सन्ु न े अदालतमा धनिदे न गन य सवकनाःे र्स पररच्छेद बमोत्तजम िएको थनु छेक िा", "content": "\nतोवकएको िरौट, जमानत िा बैङ्क जमानतमा त्तचि नबझु ने पिले एक तिसम्म\nपनु रािेदन सन्ु ने अदालतमा धनिेदन ठदन सक्नेछ।\n\nतर जन्मकै द िा दश िष य िा सोिन्दा बढी कै द सजार् िनु सक्ने कसूरमा\nिएको थनु छेकको आदेश िेरीत िएको प्रश्न मा एक तििन्दा माधथको पनु रािेदन सन्ु ने\nअदालतमा पधन धनिेदन ठदन सवकनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७४", "title": "िरौट, जमानत िा बैङ्क जमानत धलदँ ा कागज गराउन ु पनेाः (१) र्स पररच्छेद बमोत्तजम", "content": "कुनै व्र्त्तिबाट िरौट धलँदा अदालतबाट तोवकएको समर् र स्थानमा त्र्स्तो व्र्त्ति\nउपत्तस्थत निएमा िरौट जफत िनु े शत य उल्लेि गरी अनसु ूची-२९ बमोत्तजमको ढाँचामा\nकागज गराउन ु पनेछ।\n(२) र्स ऐन बमोत्तजम जमानत िा बैङ्क जमानत धलँदा जमानतको रकमको अङ्क\nतोकी त्र्स्तो बमोत्तजमको सम्पत्ति जमानत धलन ु पनेछ।\n(३) जमानत ठदन ु पने व्र्त्तिले आफ्नो सम्पत्ति जमानत ठदएको िए अदालतबाट\nतोवकएको समर् र स्थानमा आफू उपत्तस्थत निएमा जमानतको रकम जमानत रिेको\nत्र्स्तो सम्पत्ति िा धनजको अरु कुनै सम्पत्तिबाट असूल गने शत य उल्लेि गरी धनजबाट\nअनसु ूची-३० बमोत्तजमको ढाँचामा कागज गराउन ु पनेछ।\nस्पष्टीकरणाः र्स पररच्छेदको प्रर्ोजनको लाधग “जमानत” िन् नाले बैङ्क जमानतलाई समेत\nसम्झन ु पछय।\n(४) र्स पररच्छेद बमोत्तजम जमानत ठदन ु पने व्र्त्तिको लाधग अरु कसैले आफ्नो\nसम्पत्ति जमानत ठदएको िए अदालतबाट तोवकएको समर् र स्थानमा धनजलाई उपत्तस्थत\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n67\nwww.lawcommission.gov.np\nनगराएमा जमानतको रकम त्र्स्तो जमानत रिेको सम्पत्ति िा आफ्नो अरु कुन ै\nसम्पत्तिबाट असूल गन य धनजको मञ् जरु ी रिेको व्र्िोरा सवितको शत य गराई त्र्स्तो\nव्र्त्तिसँग अनसु ूची-३१ बमोत्तजमको ढाँचामा कागज गराउन ु पनेछ।\n(५) र्स दफा बमोत्तजम जमानत ठदइएको सम्पत्तिको मूल्र् पधछ कुनै कारणिश\nघट्न गएमा त्र्स्तो जमानत ठदने व्र्त्तिले त्र्स्तो घटेको मूल्र् बराबरको सम्पत्ति\nअदालत समि पेश गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७५", "title": "िरौटी जफत िनु ाःे (१) र्स पररच्छेद बमोत्तजम िरौट रात ने व्र्त्ति अदालत समि", "content": "तोवकएको तारेिमा उपत्तस्थत निएमा धनजले रािेको िरौटी जफत िनु ेछ।\n(२) र्स पररच्छेद बमोत्तजम रात्तिएको िरौटी अचल सम्पत्ति रिेछ िने त्र्स्तो\nव्र्त्तिले बझु ाउन ु पने रकम बराबरको सम्पत्ति धबक्री िा असूल गरी अरु सम्पत्ति\nधनजलाई वफताय गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७६", "title": "िरौट वफता य र जमानत फुकुिा िनु सक्नाःे (१) अदालतमा दार्र िएको मद्दु ामा र्स", "content": "पररच्छेद बमोत्तजम अधिर्िु लाई थनु ामा रात ने आदेश िएमा थनु ामा रात नअु त्तघ धनजले\nरािेको िरौट िा जमानत फुकिा गररठदन ु पनेछ।\n(२) अदालतले कुनै मद्दु ाको धसलधसलामा कुनै अधिर्िु बाट धलएको िरौटी िा\nजमानत त्र्स्तो मद्दु ाको अत्तन्तम धनणर्य िँदु ा अधिर्िु ले सफाई पाएमा र्स पररच्छेदमा\nअन्र्था व्र्िस्था िएकोमा बािेक धनजलाई तरुु न्त वफताय िा फुकुिा गरी ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७७", "title": "िास अिधिधित्र मद्दु ा फै सला निएमा थनु ाबाट छोड्न सवकनाःे (१) र्स पररच्छेद बमोत्तजम", "content": "पपु िय को लाधग थनु ामा रात्तिएको कुनै अधिर्िु को सम्बन्िमा प्रमाण बझ्ु न पविलो पटक\nताररि तोवकएको धमधतले एक िषधयित्र मद्दु ाको वकनारा िनु नसके मा त्र्स्तो अधिर्िु लाई\nथनु ामा रात्तिएको िए िरौटी िा जमानत धलई मद्दु ाको कारबािी र वकनारा गन य सवकनेछाः\nतर-\n(क) जन्मकै द िा दश िष य िा सोिन्दा बढी कै दको सजार् िनु े कुन ै\nकसूरको अधिर्ोग लागेको कुनै अधिर्िु दफा ६७ बमोत्तजम\nथनु ामा परेको रिेछ िने धनजको सम्बन्िमा र्ो दफा लागू िनु े\nछैन।\n68\nwww.lawcommission.gov.np\n(ि) पटके कसूरदारलाई अदालतले मनाधसब सम्झेमा थनु ामै रािी\nकारबािी गन य सक्नेछ।\n(२) कुनै अदालतले उपदफा (१) बमोत्तजम कुनै अधिर्िु लाई छाड्न आदेश\nठदएकोमा त्र्सरी छाड्ने आदेश ठदएको तीन ठदनधित्र पनु रािेदन सन्ु न े अदालतलाई\nत्र्सको जानकारी गराउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७८", "title": "थनु ामा रातन सवकन े अधिकतम अिधिाः र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको", "content": "िए तापधन अधिर्िु लाई धनज उपर लगाइएको अधिर्ोग प्रमात्तणत िएमा िनु सक्न े\nअधिकतम कै दको सजार्को अिधििन्दा बढी अिधिसम्म थनु ामा रात्तिने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७९", "title": "आदेश पचा य िडा गन यु पनेाः र्स पररच्छेद बमोत्तजम कुनै अधिर्िु लाई थनु ामा रातदा,", "content": "थनु ामा रात्तिएको अधिर्िु लाई छोड्दा िा कुनै अधिर्िु सँग िरौट िा जमानत धलँदा िा\nथपघट िा पररितनय गदा य िा दफा ७७ बमोत्तजम थनु ाबाट छाड्दा अदालतले कारण\nसवितको आदेश पचाय िडा गन यु पनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८०", "title": "थनु िु ा पजू ी ठदन ु पनेाः र्स पररच्छेद बमोत्तजम कुनै व्र्त्तिलाई थनु ामा रातदा त्र्सको", "content": "कानूनी आिार र कारण िलु ाई अधिकार प्राप् त अधिकारीले अनसु ूची-३२ बमोत्तजमको\nढाँचामा थनु िु ा पूजी ठदई थनु ामा रात न ु पनेछ।\nपररच्छेद-८\nताररि सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८१", "title": "कारण िलु ाई ताररि तोक्नाःे (१) अदालतले ताररि तोक्दा मद्दु ाका पििरुको", "content": "उपत्तस्थधतमा गन यु पने प्रत्र्ेक काम िलु ाई तोक्न ु पनेछ र प्रत्र्ेक ताररिका ठदन सम्पादन\nिनु े काम ताररि पचायमा िलु ाउन ु पनेछ।\n(२) ताररि तोवकएको ठदन उपदफा (१) बमोत्तजम तोवकएको काम सम्पादन िनु ु\nपनेछ।\nतर तोवकएको ताररिमा कुनै कारणबस तोवकएको काम िनु नसके मा त्र्सकोे े\nकारण िलु ाई आदेश पचा य िडा गरी अको ताररि तोक्न सवकनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n69\nwww.lawcommission.gov.np\n(३) नपे ाल सरकार िादी िा प्रधतिादी िएको मद्दु ामा अदालतले उपदफा (१)\nबमोत्तजम मद्दु ाको सनु िु ाई िा कारबािीको लाधग ताररि तोवकएको सूचना सम्बत्तन्ित\nसरकारी िवकलको कार्ायलर्लाई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८२", "title": "ताररि वकताब र ताररि िरपाईाः (१) अदालतले अनसु ूची-३३ बमोत्तजमको ढाँचामा एउटा", "content": "िा आिश्र्कता अनसु ार मद्दु ाको प्रत्र्ेक फाँटको लाधग छुट्टा छुट्टै ताररि वकताब िडा\nगरी रात न ु पनेछ।\n(२) उपदफा (१) बमोत्तजम िडा गररएको ताररि वकताबमा कुन प्रर्ोजनको\nलाधग कविलेको ताररि तोवकएको िो त्र्स्तो व्र्िोरा जनाई सम्बत्तन्ित कमचय ारीले\nसिीछाप गन यु पनेछ र मद्दु ामा उपत्तस्थत पििरुको सिीछाप गराई अनसु ूची-३४\nबमोत्तजमको ताररि िरपाई िडा गरी धमधसल सामेल रात न ु पनेछ।\n(३) उपदफा (२) बमोत्तजम तोवकएको ताररिका ठदन कुनै पि अदालतमा\n\nउपत्तस्थत निएमा सम्बत्तन्ित कमचय ारीले त्र्स्तो कुरा ताररि िरपाईमा जनाई सिीछाप\nगन यु पनेछ।\n(४) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन नेपाल सरकार िादी\nिएको मद्दु ामा नेपाल सरकार ताररिमा बस्न ु पने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८३", "title": "ताररि पचााःय (१) अदालतले प्रत्र्ेक मद्दु ाको पििरुलाई अनसु ूची-३५ बमोत्तजमको", "content": "ढाँचामा ताररि पचाय ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको ताररि पचायमा कुन प्रर्ोजनको लाधग कविलेको\nताररि तोवकएको िो त्र्स्तो कुरा जनाई सम्बत्तन्ित कमचय ारीले सिीछाप गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८४", "title": "ताररि तोक्दा पििरुलाई सवुििा िनु े वकधसमले तोक्न ु पनेाः (१) मद्दु ामा कुनै प्रर्ोजनको", "content": "लाधग ताररि तोक्दा र्थासम्िि मद्दु ाका पििरुको सवुििा र तोवकएको काम िनु सक्न े\nिा नसक्ने कुरालाई विचार गरी तोक्न ु पनेछ।\n(२) उपदफा (१) बमोत्तजम ताररि तोक्दा मद्दु ाको कारबािीको सम्बन्िमा\nतोवकएको कार्तय ाधलका अनसु ार तोक्न ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n70\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८५", "title": "तोवकएको ताररिका ठदन उपत्तस्थत िनु पु नेाः (१) अदालतबाट कुनै कामका लाधग उपत्तस्थत", "content": "िनु ताररि तोवकएकोमा तोवकएको ताररिका ठदन अधिर्िु िा प्रधतिादी अदालतमा\nउपत्तस्थत िनु ु पनेछ।\n\nतर तोवकएको ताररिका ठदन काबूबाविरको पररत्तस्थधत उत्पन्न िई अदालतमा\nउपत्तस्थत िनु नसके को कारण देिाई मद्दु ाका कुनै पिले धनिेदन ठदएमा र त्र्स्तो व्र्िोरा\nमनाधसब देत्तिएमा अदालतले बढीमा दईु पटकसम्म एक्काईस ठदनसम्मको गज्रु के ो ताररि\nथाधमठदने आदेश ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम तोवकएको ताररिको ठदन उपत्तस्थत िनु ु पने व्र्त्ति\nकुनै व्र्िोराले थधुनएको िा कै द परेको रिेछ िन े आफू थनु ा िा कै दमा परेको कारागार\nमाफय त त्र्स्तो कुराको सूचना सम्बत्तन्ित अदालतमा पिाउन ु पनेछ।\n(३) उपदफा (२) बमोत्तजम सूचना ठदएकोमा त्र्सरी थनु ा िा कै दमा रिेको\nअिधििर त्र्स्तो व्र्त्तिले ताररि गजु ारेको माधनने छैन।\n(४) उपदफा (२) बमोत्तजम थधुनएको िा कै द परेको व्र्त्तिले त्र्सको सूचना\nअदालतलाई ठदएमा अदालतले पपु िय का बित धनजलाई उपत्तस्थत गराउन सम्बत्तन्ित\nकारागारलाई आदेश ठदन सक्नेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८६", "title": "ताररिको ठदन मद्दु ाका पि अनपु त्तस्थत िएमा त्र्सको पररणामाः (१) मद्दु ाको कुनै पि", "content": "तोवकएको ताररिको ठदन िादी िात्तजर निएमा अदालतले धनजले दफा ८५ को उपदफा\n(१) को प्रधतबन्िात्मक िाक्र्ांश बमोत्तजम थमाउने म्र्ादको विसाि गरी अको ताररि\nतोक्न ु पनेछ।\n(२) उपदफा (१) बमोत्तजम तोवकएको अको ताररिको ठदन िा सोिन्दा अगािै\nमद्दु ाको पि उपत्तस्थत िई काबू बाविरको कुनै पररत्तस्थधत परेकोले अत्तघल्लो ताररिमा\n\nउपत्तस्थत िनु नसके को कुनै मनाधसब कारण देिाई ............ धनिेदन ठदएमा\nअदालतले धनजको ताररि थामी कानून बमोत्तजम मद्दु ाको वकनारा गन यु पनेछ।\n(३) उपदफा (१) बमोत्तजम तोवकएको अको ताररिको ठदन मद्दु ाको पि\nअदालतमा उपत्तस्थत निएमा समेत अदालतले धमधसल सामेल रिेका प्रमाणबाट प्रधतिादीले\nिादीको दाबी पूरै िा आंत्तशक रुपमा स्िीकार गरेको देत्तिन आएमा िा ििरेमा त्र्स्तो\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n71\nwww.lawcommission.gov.np\nिदसम्म इन्साफ गने गरी र स्िीकार नगरेको िा स्िीकार गरेको नििरेकोमा त्र्स्तो\nिदसम्म िारेज गने गरी मद्दु ाको वकनारा गन यु पनेछ।\nतर िादी िात्तजर रिेको र प्रधतिादी िात्तजर नरिेको अिस्थामा िादी प्रधतिादीको\nजो बझ्ु न ु पने प्रमाण बझु ी ििरे बमोत्तजम मद्दु ाको फै सला गन यु पनेछ।\n(४) र्स ऐन बमोत्तजम अदालतमा बर्ान िा प्रधतउिरपत्र ठदइसके पधछ तोवकएको\nताररिमा अधिर्िु िा प्रधतिादी अदालतमा उपत्तस्थत निए पधन अदालतले कानून\nबमोत्तजम मद्दु ाको कारबािी र वकनारा गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८७", "title": "पक्राउ पजू ी जारी गन य र सम्पत्ति रोक्क ा रातन सवकनाःे (१) दफा ८६ मा जनु सकु ै कुरा", "content": "लेत्तिएको िए तापधन कुनै अधिर्िु पविले तोवकएको ताररिमा अनपु त्तस्थत रिेछ र\nधनजलाई पक्राउ गरी अदालतमा उपत्तस्थत गराउन पने अदालतलाई लागेमा दफा ५८\nबमोत्तजम पक्राउ पूजी जारी गरी त्र्स्तो अधिर्िु लाई पक्राउ गन य र त्र्स्तो अधिर्िु को\nसम्पत्ति रोक् का गन य समेत अदालतले आदेश ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम आदेश ठदएकोमा त्र्स्तो आदेश बमाोत्तजम सम्बत्तन्ित\nप्रिरी कमचय ारीले अधिर्िु लाई पक्राउ गन य र सम्बत्तन्ित मालपोत कार्ालय र् िा अन्र्\nधनकार् िा संस्थाले अधिर्िु को सम्पत्ति रोक् का रात न ु पनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८८", "title": "प्रमाण बत्तुझसके पधछ ताररिमा नबसे पधन िनु ाःे (१) र्स पररच्छेदमा अन्र्त्र जनु सकु ै", "content": "कुरा लेत्तिएको िए तापधन प्रमाण बत्तुझसके पधछ कुनै पि ताररिमा बस्न नचािेमा धनजले\nत्र्सको अनमु धतको लाधग अदालतमा धनिेदन ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम धनिेदन परेमा अदालतले धनजलाई ताररिमा रात न\nआिश्र्क नदेत्तिए धनजको ताररि टुटाइठदन सक्नेछ।\nपररच्छेद-९\nिाररस सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "८९", "title": "िाररस धनर्िु िनु सक्नाःे (१) मद्दु ाको कुनै पि उजरु ी, पनु रािेदनपत्र िा प्रधतउिरपत्र", "content": "ठदन, प्रमाण पेश गन,य फै सला बमोत्तजम धबगो, िधतपूधत य िा अन्र् कुनै कुरा िराई धलन िा\nमद्दु ा सम्बन्िी अन्र् कुनै आिश्र्क काम कारबािी गन य आफू उपत्तस्थत िनु नसक्ने िएमा\nत्र्सको कारण िलु ाई त्र्स्तो पिले आफ्नो तफय बाट िाररस धनर्िु गन य सक्नेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n72\nwww.lawcommission.gov.np\n(२) उपदफा (१) मा जनसकु ै कुरा लेत्तिएको िए तापधन देिार्को अिस्थामा\nिाररस धनर्िु गन य सवकन े छैनाः -\n(क) अनसु ूची-१ र अनसु ूची-२ अन्तगतय को कसूर सम्बन्िी मद्दु ा िएमा,\n(ि) र्स ऐन बमोत्तजम बर्ान ठदन ु पने अिस्थाको अधिर्िु अदालतमा\nआफैँ उपत्तस्थत िै बर्ान ठदन ु पने िएमा,\n(ग) र्स ऐन बमोत्तजम पपु िय का लाधग थनु ामा िस्न ु पने िा िरौटी िा\nजमानत माग िएको अिस्थामा त्र्स्तो िरौटी िा जमानत ठदन\nनसकी थनु ामा िसेको व्र्त्ति िएमा,\n(घ) िाररस रिेको िा रात न पाउने अिस्था िएपधन कुनै मनाधसब\nकारण िई अदालतले मद्दु ाको पिलाई आफैँ अदालतमा उपत्तस्थत\nिनु आदेश ठदएमा,\n(ङ) थनु ामा रिेको िा पविले नै िरौट िा जमानत ठदइसके कोमा बािेक\nविदेशी नागररक िा नागररकताको िेगाना निएको व्र्त्तिले\nमद्दु ाको फै सला िँदु ा कानून बमोत्तजम आफू लाई िनु सक्ने सजार्\nबराबरको रकम िरौटी नरािेमा िा त्र्स बापत जमानत नठदएमा,\n(च) अदालतको आदेश बमोत्तजम लागेको दण्ड, जररबाना, दशौंद, धबसौँद\nनधतरी बाँकी रिेको िएमा, िा\n(छ) अदालतले कुनै मनाधसब कारण देिाई िाररस रात न नपाउने िनी\nआदेश ठदएकोमा।\n(३) कसैले उपदफा (२) प्रधतकू ल िनु े गरी िाररस ठदएकोमा अदालतले त्र्स्तो\nिाररस बदर गनेछ।\n(४) देिार्को र्ोग्र्ता पगु के ो व्र्त्ति िाररस िनु सक्नेछाः-\n(क) प्रचधलत कानून बमोत्तजम करार गन य र्ोग्र्,\n(ि) वकते, जालसाजी, भ्रष्टाचार िा नैधतक पतन देत्तिन े अन्र् फौजदारी\nकसूरमा सजार् नपाएको,\n73\nwww.lawcommission.gov.np\nतर मद्दु ाको कुनै पिले आफ्नो एकाघरसँगको कुन ै\nनातेदारलाई िाररस धनर्िु गन य र्स िण्डमा उल्लेि िएको कुन ै\nकुराले बािा प¥ुर्ाएको माधनने छैन।\n(ग) फै सला बमोत्तजम सरकारी धबगो, फै सला कार्ायन्िर्न गरे बापत\nअदालतलाई धतन यु पने कुनै दस्तूर, अदालती शल्ु क िा कुनै दण्ड\nिा जररबाना धतन य बाँकी नरिेको।\n(५) उपदफा (१) बमोत्तजम िाररस धनर्िु गदाय देिार्को कुरािरु उल्लेि गरी\nअनसु ूची-३६ बमोत्तजमको ढाँचामा िारेसनामा लेिी धनर्िु गन यु पनेछाः-\n(क) मद्दु ाको विषर्,\n(ि) िाररस िनु े व्र्त्तिको पूरा नाम, थर, टोल सवितको िेगाना र उमेर,\nनागररकता नम्बर र नागररकता धलएको त्तजल्ला,\n(ग) िाररस िनु े व्र्त्तिमा उपदफा (४) बमोत्तजमको कुनै अर्ोग्र्ता\nछैन िन् ने कुरा,\n(घ) अदालतको आदेश बमोत्तजम कुनै दण्ड, जररबाना, दशौद र धबसौँद\nबाँकी नरिेको कुरा,\n(ङ) धनजले अत्तततर्ार पाएको काम।\n(६) िारेसनामाको धलित तर्ार गदाय कम्तीमा दईु जना सािी रात न ु पनेछ।\n(७) िारेसनामाको धलितमा िाररस धनर्त्तुि गने पि र सािीिरुले सिीछाप गन यु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९०", "title": "एकै साथ एकिन्दा बढी व्र्त्तिको िाररस िनु सक्नाःे एउटै व्र्त्ति एकै साथ एकिन्दा बढी", "content": "व्र्त्तििरुको िाररस िनु सक्नेछ।\nतर कुनै मद्दु ामा एउटा पिको िाररस िएको व्र्त्ति सोिी मद्दु ा िा सोिी मद्दु ासँग\nसम्बत्तन्ित मद्दु ामा धनजको विपिीको िाररस िनु सक्ने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९१", "title": "पि िाररस िनु सक्नाःे कुनै मद्दु ामा एकिन्दा बढी िादी िा प्रधतिादी िएकोमा त्र्स्ता", "content": "व्र्त्तििरुमध्र्े कुनै व्र्त्तिलाई िाररस धनर्िु गन य सवकनेछ।\nतर एक पिको िाररस सोिी मद्दु ामा विपिीको िाररस िनु सक्ने छैन।\n74\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९२", "title": "िाररसको अधिकार र कतव्य र्ाः (१) िाररसले आफू लाई धनर्िु गने पिको तफय बाट", "content": "िारेसनामामा लेत्तिए बमोत्तजमको सबै काम गन य सक्नेछ।\n(२) िाररस धनर्िु गने व्र्त्तिलाई नै उपत्तस्थत गराउन अदालतबाट आदेश\nिएमा िाररसले त्र्स्तो व्र्त्तिलाई अदालतमा उपत्तस्थत गराउन ु पनेछ।\n(३) उपदफा (२) बमोत्तजम सम्बत्तन्ित व्र्त्ति उपत्तस्थत निएमा त्र्स्तो व्र्त्तिको\nिाररस अदालतले बदर गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९३", "title": "िाररस बदर गन य सवकनाःे (१) िाररस धनर्िु गने पिले चािेमा जनु सकु ै बित आफू ले", "content": "ठदएको िारेसनामा बदर गरी आपैmले मद्दु ा सकार गन य िा अको व्र्त्तिलाई िाररस धनर्िु\nगन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम िारेसनामा बदर गरी आफ्नो मद्दु ा आफैँ ले सकार\nगरेमा सम्बत्तन्ित पिले त्र्सको जानकारी अदालतलाई धनिेदन माफय त ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९४", "title": "िाररसलाई पक्राउ नगररनाःे मद्दु ाको फै सला िँदु ा पिलाई िएको सजार् िा पिले व्र्िोन यु", "content": "पने दावर्त्िको सम्बन्िमा िाररसलाई पक्राउ गररने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९५", "title": "िाररस धनर्िु गन य अनमु धत ठदन सवकन े विशषे व्र्िस्थााः (१) दफा ८९ को उपदफा (२)", "content": "को िण्ड (क) मा जनु सकु ै कुरा लेत्तिएको िए तापधन देिार्का अिस्थाको व्र्त्तिले सोिी\nव्र्िोरा िलु ाई िाररस धनर्िु गन य अनमु धतको लाधग अदालतमा धनिेदन ठदन सक्नेछाः-\n(क) तीन िष य िा तीन िषिय न्दा घटीको कै द सजार् िनु सक्ने कसूरको\nअधिर्ोग लागेको अधिर्िु थनु ामा बसेको रिेनछ र काबू\nबाविरको पररत्तस्थधतले तोवकएको ताररिमा उपत्तस्थत िनु नसक्न े\nअिस्था सजृ ना िएमा,\n(ि) पाँच िषसय म्म कै दको सजार् िनु सक्ने कसूरको अधिर्ोग लागेको\nमविला सत्ु के री िएको िा अन्र् कुनै कारणले गदाय तोवकएको\nताररिमा अदालतमा उपत्तस्थत िनु नसक्ने िएमा।\n(२) उपदफा (१) बमोत्तजम धनिेदन परेमा र त्र्स्तो धनिेदनको व्र्िोरा मनाधसब\nदेत्तिएमा र्स पररच्छेदका अन्र् व्र्िस्थािरुको अिीनमा रिी अदालतले कारण िलु ाई\nधनजलाई अिधि तोकी िा नतोकी िाररस रात न अनमु धत ठदन सक्नेछ।\nपररच्छेद-१०\n75\nwww.lawcommission.gov.np\nमद्दु ाको स्थानान्तरण र मलु तिी सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९६", "title": "मद्दु ा सान य सक्नाःे (१) सिोच् च अदालतले नपे ालको संवििानको िारा १३४ को उपिारा", "content": "(१) बमोत्तजमको अिस्थामा कुनै उच्च अदालतमा विचारािीन मद्दु ा सिोच् च अदालतमा\nत्तझकाई कारबािी, सनु िु ाई र वकनारा गन य सक्नेछ।\n(२) सिोच् च अदालतले नेपालको संवििानको िारा १३४ को उपिारा (२)\nबमोत्तजमको अिस्थामा एक उच्च अदालतमा विचारािीन मद्दु ा अको उच्च अदालतमा सारी\nत्र्स्तो मद्दु ाको कारबािी, सनु िु ाई र वकनारा गन य आदेश ठदन सक्नेछ।\n(३) उच्च अदालतले नेपालको संवििानको िारा १४५ को उपिारा (२)\nबमोत्तजमको अिस्थामा आफ्नो मातितको एक त्तजल्ला अदालतमा विचारािीन रिेको मद्दु ा\nमातितको अको त्तजल्ला अदालतमा सारी सनु िु ाई गने आदेश ठदन सक्नेछ।\n(४) उपदफा (२) िा (३) बमोत्तजमको मद्दु ा साने अिस्था विद्यमान िए िा\nनिएको विषर्को धनणर्य मद्दु ाका सम्बत्तन्ित पिको धनिेदन िा अदालतको धनरीिण िा\nप्रधतिेदनबाट प्राप् त िएको जानकारीबाट गररनेछ।\n(५) कुनै अदालतमा दार्र रिेको कुनै मद्दु ा र्स ऐन बमोत्तजम त्र्स्तो अदालतको\nन्र्ार्ािीशले िेन य निनु े कुनै कारण िएमा सम्बत्तन्ित अदालतले त्र्स्तो कुरा उल्लेि गरी\nपनु रािेदन सन्ु ने अदालतमा प्रधतिेदन पिाउन ु पनेछ र त्र्स बमोत्तजम प्रधतिेदन प्राप् त\nिएमा पनु रािेदन सन्ु ने अदालतले पििरुको सवुििालाई समेत विचार गरी त्र्स्तो मद्दु ा\nआफ्नो प्रादेत्तशक अधिकार िेत्रको समान तिको अको अदालतमा सान य सक्नेछ।\n(६) उपदफा (२) बमोत्तजम आदेश िएकोमा त्र्स्तो अदालतले सिोच् च\nअदालतको आदेश बमोत्तजम त्र्स्तो मद्दु ाको कारबािी, सनु िु ाई िा वकनारा गनेछ।\n(७) उपदफा (२), (३) िा (५) बमोत्तजम अको अदालतबाट मद्दु ाको वकनारा िए\nपधन त्र्स्तो अदालतले गरेको फै सला उपर शरुु मा वफरादपत्र दताय िएको अदालतको\nपनु रािेदन सन्ु ने अदालतमा नै पनु रािेदन लाग्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९७", "title": "मद्दु ा मलु तिी रातन सवकनाःे (१) धिन् न धिन् न अदालतमा दार्र रिेका धिन् न धिन् न", "content": "मद्दु ािरुमध्र्े एउटाको वकनारा निई अकोको वकनारा िनु नसक्ने िा गन य निनु े िा एउटा\nमद्दु ाको धनणर्य बाट अको मद्दु ाको धनणर्य मा तात्तत्िक असर पने कुनै मनाधसब कारण देिाई\nत्र्स्ता मद्दु ाको कुनै पिले सम्बत्तन्ित अदालतमा धनिेदन ठदएमा िा मद्दु ाको कारबािीको\n76\nwww.lawcommission.gov.np\nधसलधसलामा अदालतले स्िर्ं त्र्स्तो कुरा मिससु गरेमा अदालतले कारण िलु ाई त्र्स्तो\nमद्दु ा मलु तिी रात ने आदेश ठदन सक्नेछ।\n(२) कुनै अदालतले त्र्स्तो अदालतमा दार्र रिेको कुनै मद्दु ा उपदफा (१)\nबमोत्तजम मलु तिी रात ने आदेश ठदएकोमा त्र्स्तो कुरा पििरुलाई धलत्तित रुपमा सूत्तचत\nगरी मद्दु ाको सबै कारबािी स्थधगत गन यु पनेछ र अको मद्दु ा दार्र रिेको सम्बत्तन्ित\nअदालतलाई समेत त्र्स्तो कुराको सूचना ठदन ु पनेछ।\n(३) उपदफा (२) बमोत्तजमको सूचना प्राप् त िएपधछ सम्बत्तन्ित अदालतले त्र्स्तो\nअदालतमा दार्र रिेको सम्बत्तन्ित मद्दु ाको वकनारा गरेपधछ तीस ठदनधित्र फै सलाको एक\nप्रधत नक् कल संलग्न गरी मद्दु ा मलु तिी रिेको अदालतलाई त्र्स्तो कुरा सूत्तचत गन यु पनेछ\nर सूचना पाएपधछ मद्दु ा मलु तिी रिेको अदालतले ताररि तोकी मद्दु ाको पििरुलाई\nधलत्तित सूचना ठदई मलु तिी जगाई कारबािी र वकनारा गन यु पनेछ।\n\n(३क) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन अको अदालतमा\nविचारािीन रिेको मद्दु ाको धनणर्य िएको जानकारी प्राप् त िएमा िा मद्दु ा मलु तबी रािी\nरात न ु पने कुनै कारण नदेत्तिएमा अदालतले मलु तबी रिेको मद्दु ा तरुु न्त जगाई कारबािी\nगन यु पनेछ।\n(४) उपदफा (३) मा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्ता पििरु\nउपदफा (३) बमोत्तजमको मद्दु ाको पधन पि िए धनजिरुलाई मलु तिी रिेको मद्दु ा िएको\nअदालतमा पन्र ठदनधित्र िात्तजर िनु जान ु िनी मद्दु ामा धनणर्य गने अदालतले आदेश ठदन ु\nपनेछ।\n(५) दईु धिन् नधिन् न अदालतमा दार्र रिेका मद्दु ािरुमध्र्े कुन मद्दु ा मलु तिी रात न े\nिन् न े कुरामा दईु अदालतको रार् फरक िएमा दिु ै अदालतले पनु रािेदन सन्ु ने अदालतमा\nआफ्नो प्रधतिेदन पिाउन ु पनेछ।\n(६) उपदफा (५) बमोत्तजमको अिस्थामा मद्दु ाका पिले पधन सम्बत्तन्ित\nपनु रािेदन सन्ु ने अदालतमा धनिेदन ठदन सक्नेछ।\n(७) उपदफा (५) बमोत्तजम प्रधतिेदन पिाएकोमा िा उपदफा (६) बमोत्तजम\n\nपिको धनिेदन परेकोमा त्र्स्तो मद्दु ाका सम्बन्िमा पनु रािेदन सन्ु ने अदालतले एक\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n77\nwww.lawcommission.gov.np\nमविनाधित्र उपर्िु आदेश गनेछ र त्र्स्तो आदेश बमोत्तजम सम्बत्तन्ित अदालतले\nमद्दु ाको कारबािी गनेछ।\n\n(८) उपदफा (५) बमोत्तजम धिन् न रार् िएका दईु अदालतको पनु रािेदन सन्ु न े\nअदालत एउटै निई धिन् न धिन् न िएमा त्र्स्तो विषर्को प्रधतिेदन सिोच् च अदालतमा पेश\nगन यु पनेछ। र्सरी पेश िएको विषर्मा सिोच् च अदालतले तीन मविनाधित्र उपर्िु\nआदेश गनेछ र सम्बत्तन्ित अदालतले त्र्स्तो आदेश बमोत्तजम मद्दु ाको कारबािी गन यु\nपनेछ।\n(९) र्स दफा बमोत्तजम मद्दु ा मलु तिी रात ने िा रात न लगाउने आदेश ठदनिु न्दा\nअत्तघ अदालतले मनाधसब सम्झेमा सम्बत्तन्ित पिलाई सूचना ठदई सनु िु ाई गराउन\nसक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९८", "title": "अधिर्िु उपत्तस्थत निएकोमा मद्दु ा मलु तिी राख्नाःे (१) दफा ५७ बमोत्तजम पक्राउ पूजी", "content": "जारी िएको अधिर्िु पक्राउ पूजी जारी िएको धमधतले पैँतीस ठदनधित्र पधन अदालतमा\nउपत्तस्थत निएमा िा धनजलाई उपत्तस्थत गराउन नसवकएमा अदालतले धनजको िकमा\nमद्दु ा मलु तिी रािी त्र्स्तो मद्दु ामा संलग्न अन्र् अधिर्िु िरुको िकमा प्रमाण बझु ी\nमद्दु ाको वकनारा गन यु पनेछ।\nतर,\n(क) अदालतमा बर्ान िा प्रधतउिर ठदइसके पधछ अनपु त्तस्थत रिेको\nअधिर्िु िा प्रधतिादीको िकमा मद्दु ा मलु तिी रात्तिने छैन र िादी\nप्रधतिादीले पेश गरेको सिदु प्रमाण र अदालतले मनाधसब सम्झेको\nअन्र् प्रमाण बझु ी मद्दु ाको वकनारा गन यु पनेछ,\n(ि) तीन िष य िा तीन िषिय न्दा घटी कै दको सजार् िनु े मद्दु ामा\nअदालतमा िात्तजर निएको अधिर्िु िा प्रधतिादीिरुको िकमा\nसमेत ििरे बमोत्तजम फै सला गन यु पनेछ।\n\n(२) उपदफा (१) बमोत्तजम कुनै मद्दु ा मलु तिी रिने िएमा अदालतले मद्दु ा\nमलु तबी रिेका प्रधतिादीिरुको िकमा मद्दु ाको कारबािी स्थगन गन यु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n78\nwww.lawcommission.gov.np\n(३) उपदफा (१) बमोत्तजम मद्दु ा मलु तिी रिेकोमा मद्दु ाको वकनारा गनियु न्दा\nअगाधड अधिर्िु अदालतमा उपत्तस्थत िएमा िा गराइएमा अदालतले मलु तिी जगाई\nउजरु िालालाई त्र्स्तो कुराको सूचना ठदई मद्दु ाको कारबािी र वकनारा गन यु पनेछ।\n(४) उपदफा (१) बमोत्तजम मद्दु ा मलु तिी रिेको धमधतले तीन िषकय ो अिधिधित्र\nअधिर्िु अदालतमा उपत्तस्थत िएन िा गराइएन िने अदालतले त्र्स्तो अधिर्िु को\nसम्बन्िमा मलु तिी रिेको मद्दु ा जगाई कारबािी र वकनारा गन यु पनेछ।\n\n(५) उपदफा (४) बमोत्तजम मद्दु ा मलु तबी रिन सक्ने अिधिसम्म पधन अधिर्िु\nअदालतमा उपत्तस्थत निएमा दफा ५८ को उपदफा (१५) बमोत्तजम रोक् का िएको\nधनजको िकको सम्पत्ति मद्दु ा फै सला िँदु ा धनज कसूरदार ििरेमा कानून बमोत्तजम धललाम\nधबक्री गरी प्राप् त िएको रकममध्र्े धनजलाई फै सला बमोत्तजम लागेको दण्ड, जररबाना,\nधबगो िा िधतपूधत य बापतको रकम असूल उपर गररनेछ र बाँकी रकम धनजले वफताय माग\nगन य आएको बित वफताय ठदन ु पनेछ।\n(६) मद्दु ाको वकनारा िनु िु न्दा पविले नै अधिर्िु अदालतमा उपत्तस्थत िएको िा\nगराइएको र धनजले आफ्नो विरुद्ध मद्दु ा चलेको कुरा थािै नपाएकोले उपत्तस्थत िनु\nनसके को िनी अदालतलाई विश्वास िनु े कुनै प्रमाण पेश गरेमा अदालतले देिार्\nबमोत्तजमको िचिय रु कटाई िा असलु गरी रोक् का रिेको सम्पत्ति धनजलाई फुकुिा गने\nआदेश ठदन ु पनेछाः-\n(क) सम्पत्ति धबक्री िई नसके कोमा त्र्स्तो सम्पत्ति रोक् का रातदा\nलागेको िच,य\n(ि) अदालतमा उपत्तस्थत िनु धनजका नाममा िा मद्दु ाको कारबािी\nसम्बन्िी कुनै विषर्मा धनजको िकमा सािजय धनक सूचना प्रकाशन\nगदाय लागेको िच।य\n(७) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन एउटा अदालतमा\nदार्र िएको मद्दु ा मलु तिी रिेकोमा सोिी अदालत िा अन्र् कुनै अदालतमा दार्र िएको\nअको कुनै मद्दु ामा अधिर्िु िादी िा प्रधतिादीको िैधसर्तमा उपत्तस्थत िएको िन् न े\nप्रधतिेदन िा जानकारी प्राप्त िएमा त्र्स्तो मद्दु ा मलु तिी रिेको माधनने छैन र अदालतले\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n79\nwww.lawcommission.gov.np\nत्र्स्तो मद्दु ाको कारबािी अगाधड बढाउनको लाधग त्र्स्तो अधिर्िु लाई अदालतमा\nउपत्तस्थत िनु े आदेश ठदन सक्नेछ।\n(८) उपदफा (७) बमोत्तजमको आदेश बमोत्तजम अधिर्िु उपत्तस्थत निए तापधन\nत्र्स्तो मद्दु ा जगाई कारबािी र वकनारा गन य सवकनछे ।\nपररच्छेद-११\nप्रमाण परीिण सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "९९", "title": "प्रमाण पेश गन यु पनेाः (१) िादीले उजरु ीमा, अधिर्िु ले बर्ानमा र प्रधतिादीले", "content": "प्रधतउिरपत्रमा आपm्ना सबै सािी, धलित र दसी प्रमाण िलु ाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम िलु ाएको धलित िा दसी प्रमाणको प्रकृ धतबाट\nआफू सँग रिन ु पने िा आफू ले प्राप् त गन य सक्न े धलित िा दसी प्रमाण िादीले उजरु ीका\nसाथ, प्रधतिादीले प्रधतउिरपत्रका साथ र अधिर्िु ले बर्ान गदायका बित पेश गन यु\nपनेछ।\n(३) उपदफा (१) िा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन देिार्का\nकुरामा देिार् बमोत्तजम िनु ेछाः-\n(क) अधिर्िु ले बर्ान गदाय िा प्रधतिादीले प्रधतउिरपत्र ठदँदा तत्काल\nपेश गन य नसवकन े कुनै धलित िा दसी प्रमाण पशे गने अको\nताररि तोकी पाउँ िनी अनरु ोि गरेमा अदालतले बढीमा एक\nमविनासम्मको अको ताररि तोक्न सक्नेछ,\n(ि) दफा १०४ को उपदफा (३) बमोत्तजम कीते िा जालसाजी\nसम्बन्िी प्रमाण बझ्ु ने कुराको िकमा सोिी दफा बमोत्तजम िनु ेछ,\n(ग) मद्दु ाको पपु िय िँदु ाका बित कुनै नर्ाँ तथ्र्को समथनय िा िण्डन\nगन य कुनै थप प्रमाण पेश गन यु पने अिस्था िएमा अदालतको\nअनमु धत धलई सम्बत्तन्ित पिले थप प्रमाण पेश गन य सक्नेछ।\n(४) मद्दु ाको कुनै पिले उपदफा (२) बमोत्तजम कुनै धलित प्रमाण पेश गदाय\nत्र्स्तो धलितको नक् कल विपिीको सङ्खतर्ािन्दा एक प्रधत बढी पेश गन यु पनेछ।\nतर अनसु ूची-१ र अनसु ूची-२ अन्तगतय का कसूर सम्बन्िी मद्दु ामा िने त्र्स्तो\nधलितको नक् कल पेश गन यु पने छैन।\n80\nwww.lawcommission.gov.np\nस्पष्टीकरणाः र्स दफाको प्रर्ोजनको लाधग “नक् कल” िन् नाले धलितको फोटोकपी िा\nअन्र् कुनै छार्ाँप्रधत सम्झन ु पछय।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१००", "title": "सक्क ल धलित वफता य ठदन ु पनेाः (१) दफा ९९ को उपदफा (२) बमोत्तजम कुनै धलित", "content": "अदालतमा पेश िएकोमा अदालतले आफ्नो कमचय ारीलाई सोिी दफाको उपदफा (४)\nबमोत्तजम पेश िएको नक् कल प्रधत सक् कल धलित बमोत्तजमको िए िा निएको रुज ु गन य\nलगाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम रुज ु गने कमचय ारीले रुज ु गरी सके पधछ त्र्स्तो\nनक् कलको प्रत्र्ेक पानामा सक् कल बमोत्तजम नक् कल दरुु स्त छ िनी लेिी धमधत िलु ेको\nदस्तित गरी त्र्स्तो धलित पेश गने पिको समेत सिीछाप गराई अदालतको छाप\nलगाई प्रमात्तणत गन यु पनेछ।\n(३) उपदफा (२) बमोत्तजम प्रमात्तणत िएपधछ त्र्स्तो कमचय ारीले त्र्स्तो सक् कल\nधलितको पीिमा अदालतको छाप लगाई धमधत िलु ेको दस्तित गरी त्र्स्तो धलित पेश\nगने पिलाई वफताय ठदन ु पनेछ।\n(४) उपदफा (३) बमोत्तजम वफताय ठदएको सक् कल धलित अदालतले चािेमा\nआिश्र्कता अनसु ार पनु ाः पेश गन य सम्बत्तन्ित पिलाई आदेश ठदन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०१", "title": "पिले सािी उपत्तस्थत गराउन ु गनेाः (१) अदालतमा दार्र िएका मद्दु ाका सािी अदालतले", "content": "तोके को ठदन सम्बत्तन्ित पिले उपत्तस्थत गराउन ु पनेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै िास मद्दु ामा\nत्र्स्तो मद्दु ा दार्र गदाय कै बित प्रधतिादीिरु उपत्तस्थत िएमा िादी, प्रधतिादी िा दिु ै\nपिले मद्दु ा दार्र गदाय कै बित आ-आफनो सािी प्रमाणिरु अदालतमा पेश गन य सक्न े\nछन।्\n(३) उपदफा (१) िा (२) बमोत्तजम सािी पेश गदाय अनसु ूची-१ र अनसु ूची-२\nअन्तगतय का कसूर सम्बन्िी मद्दु ाका सरकारी पिको सािीलाई सम्बत्तन्ित अनसु न्िान\nअधिकारी िा धनजको कार्ायलर्ले सरकारी िवकल कार्ायलर् माफय त उपत्तस्थत गराउन ु\nपनेछ।\n(४) उपदफा (१) बमोत्तजम सािी बझ्ु न तोके को ताररिका ठदन उपत्तस्थत निनु े\nसािीलाई िातेल गररठदन ु पछय।\n81\nwww.lawcommission.gov.np\nतर काबू बाविरको पररत्तस्थधत परी उपत्तस्थत िनु नसके कोमा पिले सोिी व्र्िोरा\nिलु ाई धनिेदन ठदएमा अदालतले त्र्स्तो सािी बझ्ु न े अको ताररि तोक्न सक्नेछ।\n(५) र्स ऐनको अनसु ूची-१ िा अनसु ूची-२ मा उत्तल्लत्तित कुनै कसूर सम्बन्िी\nमद्दु ामा सबै प्रधतिादीिरु उपत्तस्थत निएको कारण सािी परीिणको प्रकृ र्ा शरुु\nनिएकोमा कुनै पिले आफू ले ठदएको सािी तत्काल उपत्तस्थत नगराएमा पधछ उपत्तस्थत\nगराउन नसवकने कारण देिाई त्र्स्ता सािीिरु तत्कालै उपत्तस्थत गराई िकपत्र गराउन\nअनरु ोि गन य सक्नेछ।\n(६) उपदफा (५) बमोत्तजम अनरु ोि िएकोमा र त्र्स्तो कारण मनाधसब िएमा\nअदालतले सोको कारण िलु ाई त्र्स्तो सािीको तत्कालै िकपत्र गराउन सक्नेछ।\n(७) उपदफा (६) बमोत्तजम सािीले गरेको िकपत्रमा उपत्तस्थत िएसम्मका\nमद्दु ाका पि विपिलाई त्तजरि गन य ठदन ु पनेछ र त्र्स्तो अिस्था रिेनछ िने त्र्स्तो\nिकपत्रको व्र्िोराको िकमासम्म पधछ उपत्तस्थत पिले िण्डन गन य सक्नेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०२", "title": "विशषे ज्ञ ......लाई बझ्ु न सवकनाःे नेपाल सरकार िादी िएको जघन्र् िा गम्िीर कसूर", "content": "सम्बन्िी कुनै मद्दु ामा विशेषज्ञ रार् व्र्ि गने विशेषज्ञको मत्ृ र् ु िएमा िा धनज लामो\nअिधि विदेशमा बसी नेपाल आउन नसक्ने िएमा िा अन्र् कारणले धनजलाई बझ्ु न\nअसम्िि िएमा त्र्स्तो विशेषज्ञ ...... सरिको िा सोिन्दा माधथको समान विषर्को\nविशेषज्ञबाट विशेषज्ञ रार् धलन सवकनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०३", "title": "सिअधिर्िु को त्तजरि गन य सवकनाःे र्स पररच्छेद बमोत्तजम प्रमाण परीिण गदाय कुन ै", "content": "अधिर्िु ले कुनै सिअधिर्िु लाई पोल गरेमा त्र्सरी पोलेको कुराको िदसम्म त्र्स्तो\nसिअधिर्िु ले त्तजरि गन य सक्नेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०४", "title": "सद्द े वकतेमा बर्ान गराउन ु पनेाः (१) प्रमाण बझ्ु न तोवकएको ताररिमा िादीले पेश गरेको", "content": "प्रमाणको कागज प्रधतिादीलाई र प्रधतिादीले पेश गरेको प्रमाणको कागज िादीलाई सक्कलै\nदेिाई सनु ाई धनजले त्र्स्तो कागजलाई सद्दे, वकते िा जालसाजी नामाकरण गरेमा\nअदालतले सोिी व्र्िोराको बर्ान गराई अधिलेि गन यु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n82\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजम देिाउँदा िा सनु ाउँदा तत्काल सद्दे, कीते िा\nजालसाजी छुट्याउन नसक्ने िई कुनै पिले म्र्ाद माग गरेमा अदालतले तीन\nठदनसम्मको म्र्ाद ठदन ु पनेछ।\n(३) मद्दु ाको पि बािेक अरुको सिीछाप परेको कागज पेश िएमा तत्काल सद्दे,\nवकते िा जालसाजी छुट्याई नामाकरण गन य नसक्ने िई मद्दु ाका कुनै पिले म्र्ाद मागेमा\nप्रमाण सवित सद्दे, वकते िा जालसाजीमा बर्ान गन य पन्र ठदनसम्मको म्र्ाद ठदन\nसवकनेछ।\n(४) उपदफा (३) बमोत्तजम ठदइएको म्र्ादधित्र बर्ान गने व्र्त्तिले सद्दे, वकते िा\nजालसाजी ज े नामाकरण गदयछ अदालतले सोिी अनरुु प बर्ान गराई अधिलेि गन यु\nपनेछ।\n(५) उपदफा (४) बमोत्तजम बर्ान गराउँदा कुनै पिले त्र्स्तो धलित वकते िा\nजालसाजी िो िन् ने बर्ान गरेमा अदालतले सो ठदन मद्दु ाका सबै पििरू िात्तजर रिेको\nिए धनजिरूको सोिी ठदन र कुनै पि िात्तजर नरिेको िए त्र्स्तो पिको िकमा\nत्र्सपधछ िात्तजर िएकै ठदन बर्ान गराउन ु पनेछ।\n(६) िाररस िा कानून व्र्िसार्ी ताररिमा रिेको मद्दु ामा सम्बत्तन्ित पिलाई न ै\nत्तझकाउन ु आिश्र्क देत्तिएमा अदालतले त्र्स्तो पिलाई त्तझकाई धनजको बर्ान गराउन ु\nपनेछ।\n(७) र्स दफा बमोत्तजम प्रमाणको कागज देिाउँदा िा सनु ाउँदा सम्बत्तन्ित पिले\nसद्दे, कीते िा जालसाजी छुट्याउन नसक्ने िएमा अदालतले त्र्स्तो प्रमाणको कागज जाँच\nगन य सम्बत्तन्ित विशेषज्ञ समि पिाउन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०५", "title": "कीते िा जालसाजी िधनएको धलित धमधसल साथ रातन ु पनेाः दफा १०४ को उपदफा", "content": "(१) बमोत्तजम एउटा पिले पेश गरेको धलित अको पिलाई देिाउँदा त्र्सलाई धनजले\nकीते िा जालसाजी धलित नामाकरण गरेमा त्र्स्तो धलितको पीिमा दिु ै पिको\nसिीछाप गन य लगाई सम्बत्तन्ित कमचय ारीको िस्तािर र अदालतको छाप समेत लगाई\nधसलिन्दी गरी धमधसल साथ सरु त्तित रात न ु पनेछ र सिीछाप गने िाउँ निएमा छुट्टै\nकागज जोडी जोनीमा समेत सिीछाप गरी मचु ल्ु का गरी रात न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०६", "title": "तोवकएको ठदन सािी बझ्ु न ु पनेाः (१) अदालतले सािी बझ्ु न तोवकएको ताररिको ठदन", "content": "उपत्तस्थत िएसम्मको सबै सािीिरुको िकपत्र गराउन ु पनेछ र त्र्स ठदन उपत्तस्थत सबै\n83\nwww.lawcommission.gov.np\nसािीिरुको िकपत्र गराउन समर् अिािको कारणले नभ्र्ाएमा मात्र त्र्सपधछ अदालत\nिल्ु ने अको ठदन िकपत्र गराउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम िकपत्र गन य उपत्तस्थत िएको सािीले बकपत्र\nगनअयु त्तघ धनजले सत्र् कुरा मात्र व्र्ि गने उद्घोषण गरी अनसु ूची-३७ बमोत्तजमको\nढाँचामा अरुले सन्ु न े गरी शपथ धलन ु पनेछ र त्र्स्तो शपथ सम्बत्तन्ित धमधसलमा संलग्न\nगन यु पनेछ।\n(३) सािीले गरेको िकपत्र अनसु ूची-३८ बमोत्तजमको ढाँचामा अधिलेि गन यु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०७", "title": "बन्दसिालद्वारा सािी बझ्ु न सवकनाःे (१) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको", "content": "िए तापधन मद्दु ा दार्र रिेको अदालतको अधिकार िेत्र िएको इलाकािन्दा बाविर रिे\nबसेको िा कुनै कारणले अदालतमा उपत्तस्थत िनु नसक्ने तर नबझु ी निनु े सािीलाई\nमद्दु ाको गम्िीरता िेरी बन्दसिालद्वारा बझ्ु न ु पने िएमा अदालतले त्र्सको सूचना मद्दु ाका\nपििरुलाई ठदन ु पनेछ।\n(२) मद्दु ाको कुनै पिले चािेमा उपदफा (१) बमोत्तजमको बन्दसिालमा आफू ले\nसािीसँग सोध्न चािेको प्रश्न िरु समािेश गररर्ोस िनी कारण िलु ाई अदालतमा धनिेदन\nठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजमको कुनै धनिेदन परेमा र अदालतले त्र्स्तो प्रश्न\nत्र्स्तो बन्दसिालमा समािेश िनु ु मनाधसब िानेमा त्र्स्तो प्रश्न समेत त्र्स्तो\nबन्दसिालमा समािेश गन य आदेश ठदनेछ र सोिी बमोत्तजम बन्द सिालको प्रश्न िरु तर्ार\nगररनेछ।\n(४) बन्द सिालको ढाँचा अनसु ूची-३९ मा उल्लेि िए बमोत्तजम िनु ेछ।\n(५) उपदफा (१) बमोत्तजम बन्दसिालद्वारा सािी बिु m्दा मद्दु ाको कुनै पिले\nचािेमा बन्दसिाल पिाइएको अदालतमा उपत्तस्थत िै प्रमाण सम्बन्िी प्रचधलत कानून\nबमोत्तजम सािी परीिण, त्तजरि िा पनु ाः सोिपछु गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०८", "title": "िकपत्र इजलासमा गराउन ु पनेाः (१) र्स ऐन बमोत्तजम सािीको िकपत्र गराउँदा", "content": "न्र्ार्ािीशको इजलासमा गन यु पनेछ।\n84\nwww.lawcommission.gov.np\nतर शारीररक असमथतय ाले गदाय अदालतमा उपत्तस्थत िनु नसक्ने सािीको िकपत्र\nगराउन ु पदाय त्र्स्तो सािी रिे िसेको िाउँमा न्र्ार्ािीश आफैँ गई िा आफ्नो मातितको\nअधिकृ त कमचय ारी िटाई िकपत्र गराउन लगाउन सवकनेछ।\n(२) उपदफा (१) बमोत्तजम िकपत्र गराउँदा मद्दु ाका सम्बत्तन्ित पििरुलाई\nत्र्स्तो कुराको सूचना ठदई दफा १०७ को उपदफा (५) बमोत्तजम परीिण गने मौका\nसमेत ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१०९", "title": "श्रव्र्-दृश्र् संिाद (धिधडर्ो कन्फरेन्स) माफय त सािी बझ्ु न सवकनाःे (१) र्स पररच्छेद", "content": "बमोत्तजम बझु न ु पने सािी शारीररक रुपमा अशि िा बालबाधलका िएको िा सरु िाको\nकारणले गदा य धनजलाई अदालतमा उपत्तस्थत गराउन नसवकने िएमा सम्बत्तन्ित पिले\nसोिी व्र्िोरा िोली श्रव्र्-दृश्र् संिाद (धिधडर्ो कन्फरेन्स) माफय त त्र्स्तो सािी बझु नको\nलाधग अदालतमा धनिेदन ठदन सक्नेछ।\n(२) कुनै िास प्रकृ धतको सािीको परीिण श्रव्र् दृश्र् सम्िाद (धिधडर्ो\nकन्फरेन्स) माफय त गराउन अदालतले आदेश गरेमा सोिी बमोत्तजम सािी परीिण गन यु\nपनेछ।\n(३) उपदफा (१) बमोत्तजमको धनिेदन परेमा र धनिेदनमा उत्तल्लत्तित कारण\nमनाधसब देत्तिएमा िा उपदफा (२) बमोत्तजम अदालतले आदेश ठदएमा र्स ऐनमा अन्र्त्र\nजनु सकु ै कुरा लेत्तिएको िए तापधन अदालतले त्र्स्तो सािी श्रव्र्-दृश्र् संिाद (धिधडर्ो\nकन्फरेन्स) माफय त बझ्ु न सक्नेछ।\n(४) उपदफा (३) बमोत्तजम श्रव्र्-दृश्र् संिाद (धिधडर्ो कन्फरेन्स) गदाय\nअदालतको अनमु धत धलई मद्दु ाको सम्बत्तन्ित पि त्र्स्तो सम्िाद स्थलमा उपत्तस्थत िई\nसोिपछु , त्तजरि िा पनु ाः सोिपछु गन य सक्नेछ।\n(५) उपदफा (३) बमोत्तजम सािी बझ्ु दा त्र्स्तो सािीले व्र्ि गरेको कुरा\nअधिलेि िनु े व्र्िस्था गन यु पनेछ र अदालतले श्रव्र्-दृश्र् संिाद (धिधडर्ो कन्फरेन्स) को\nअधिलेि रात न ु पनेछ।\n(६) श्रव्र्-दृश्र् संिाद (धिधडर्ो कन्फरेन्स) माफय त सािी बझु ेको अधिलेि\nअनसु ूची-४० बमोत्तजमको ढाँचामा रात न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११०", "title": "सािीको व्र्ििार, मिु ाकृ धत इत्र्ाठद वटपोट गन य सवकनाःे (१) न्र्ार्ािीशले कुनै सािीलाई", "content": "िकपत्र गराउँदा धनजको व्र्ििार र मिु ाकृ धत कस्तो धथर्ो, धनजसँग सोधिएको प्रश्न िरुको\n85\nwww.lawcommission.gov.np\nजिाफ ठदँदा धनज उिेत्तजत िएको, िडिडाएको िा डराएको धथर्ो िा धथएन, धनजको\nमिु ाकृ धतबाट धनजले ठदएको जिाफ साँचो िा झठ्ठु ो के कस्तो झल्कन्थ्र्ो जस्ता कुरा र\nअन्र् आिश्र्क कुराको सम्बन्िमा आफू लाई लागेको कुरािरुको वटपोट बनाउन\nसक्नेछ।\n(२) उपदफा (१) बमोत्तजम बनाइएको वटपोटमा न्र्ार्ािीशले सिीछाप गरी\nधमधसल संलग्न रातन ु पनेछ।\n(३) सािीको िकपत्रलाई प्रमाणको रुपमा मूल्र्ाङ्कन गदाय उपदफा (१)\nबमोत्तजमको वटपोटलाई आिार धलन सवकनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१११", "title": "एक पटक बत्तुझसके को सािी फे रर बझ्ु न निनु ाःे एक पटक िकपत्र गररसके को सािीबाट", "content": "पनु ाः कुनै कुरा बझ्ु न सवकने छैन।\nतर त्र्स्तो सािीबाट नबझु ी निनु े कुनै कुरा छुट्न गई न्र्ार्ािीशले कारण\nिलु ाई आदेश गरेमा पनु ाः समाह्वान जारी गरी धनजलाई बझ्ु न सवकनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११२", "title": "निझु ी निनु े सािीलाई समाह्वान िा पक्राउ पजू ी जारी गन य सवकनाःे (१) र्स पररच्छेद", "content": "बमोत्तजम प्रमाण परीिणको लाधग अदालतले तोके को ठदन उपत्तस्थत निएको तर मद्दु ाको\nगम्िीरता िेरी नबझु ी निनु े नेपाल सरकार िादी िनु े फौजदारी मद्दु ासँग सम्बत्तन्ित\nसािीलाई उपत्तस्थत गराउन िा कुनै धलित िा दसी प्रमाण दात्तिला गराउन समाह्वान\nजारी िोस ् िनी कारण िलु ाई मद्दु ाको पिले धनिेदन ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजमको धनिेदन परेमा र त्र्स्तो धनिेदनको व्र्िोरा\nमनाधसब िई त्र्स्तो सािी बझ्ु न ु पने देिेमा अदालतले त्र्स्तो सािीलाई बढीमा पन्र\nठदनको म्र्ाद ठदई समाह्वान जारी गरी बझु न सक्नेछ।\n(३) उपदफा (२) बमोत्तजम समाह्वान जारी िएकोमा मनाधसब कारण िएकोमा\nबािेक त्र्स्तो सािी तोवकएको म्र्ादधित्र उपत्तस्थत िनु ु पनेछ।\n(४) उपदफा (३) बमोत्तजम तोवकएको म्र्ादधित्र उपत्तस्थत निनु े सािीलाई\nअदालतले दईु िजार रुपैर्ाँसम्म जररबाना गरी पक्राउ पूजी जारी गरी पक्राउ गरी\nिकपत्र गराउन सक्नेछ।\n(५) उपदफा (४) बमोत्तजम जनु सािीका धबरुद्ध पक्राउ पूजी जारी िएको िो\nत्र्स्तो सािी फे ला परेन िा पक्राउ िनु सके न िन े त्र्स्तो सािी पक्राउ परेका िा फे ला\n86\nwww.lawcommission.gov.np\n\nपरेका बित सजार् कार्ायन्िर्न गने गरी पैँतालीस ठदनसम्म कै द सजार् गरी बत्तुझएको\nप्रमाणबाट मद्दु ा फै सला गन यु पनेछ।\n(६) र्स दफा बमोत्तजम जारी िएको समाह्वान िा पक्राउ पूजी पररच्छेद-६\nबमोत्तजम तामेली गररनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११३", "title": "सािीलाई दैधनक तथा भ्रमण ििा तथा सरु िा ठदन ु पनेाः (१) अनसु ूची-१ िा अनसु ूची-२", "content": "अन्तगतय का कसूर सम्बन्िी मद्दु ामा नेपाल सरकारका तफय बाट अदालतमा उपत्तस्थत िएका\nसािीलाई राजपत्र अनवङ्कत प्रथम श्रेणीका सरकारी कमचय ारीले र विशेषज्ञको रुपमा\nउपत्तस्थत िएको सािी िए राजपत्रावङ्कत ततृ ीर् श्रेणीको सरकारी कमचय ारीले कानून\nबमोत्तजम पाए सरिको दैधनक तथा भ्रमण ििा सम्बत्तन्ित प्रिरी कार्ायलर्ले उपलब्ि\nगराउन ु पनेछ।\n(२) कुनै सरकारी कमचय ारी सािी िा विशेषज्ञको िैधसर्तले अदालतमा उपत्तस्थत\nिएमा धनजलाई प्रचधलत कानून बमोत्तजम धनजले पाउने दैधनक तथा भ्रमण ििा धनज\nबिाल रिेको कार्ायलर्ले उपलब्ि गराउन ु पनेछ।\n(३) उपदफा (१) बमोत्तजमको सािीको आिश्र्क सरु िाको व्र्िस्था नेपाल\nसरकारले गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११४", "title": "सािी िा पीधडतको संरिण गनेाः (१) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय को कसूर", "content": "सम्बन्िी कुनै मद्दु ामा सािी रिेको कुनै व्र्त्तिलाई अदालत समि उपत्तस्थत िनु िा\nअदालतमा िकपत्र गररसके पधछ आफ्नो सरु िामा ितरा रिेको छ िन् न े लागेमा धनजले\nत्र्सको कारण िलु ाई सरु िाको प्रबन्ि गररठदन अदालत समि धनिेदन ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजमको अनरु ोि िएमा अदालतले त्र्स्तो सािीको\nसरु िाको प्रिन्ि गन य सम्बत्तन्ित धनकार्लाई आदेश ठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजम अदालतले आदेश ठदएमा त्र्स्तो सरु िाको प्रबन्ि\nगने कतव्य र् त्र्स्तो धनकार्को िनु ेछ।\n(४) र्स दफा बमोत्तजम सािी संरिण गन य अदालतले गरेको आदेश बमोत्तजम\nअपनाइएको कुनै विषर्का सम्बन्िमा कुनै अदालतमा प्रश्न उिाउन पाइने छैन।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n87\nwww.lawcommission.gov.np\n(५) कुनै िास कसूरबाट पीधडत व्र्त्ति िा कुनै मद्दु ाको सािीको रुपमा रिेका\nव्र्त्तिले सािीका रुपमा रिेको कारणले आफू लाई पिबाट अनत्तुचत डर त्रास िा िर् िनु\n\nसक्ने िा आफ्नो त्तजउ ज्र्ानको सरु िामा प्रधतकू ल असर पन य सक्ने सूचना प्रिरीलाई\nठदएमा प्रिरीले त्र्स्ता सािी िा पीधडतको संरिण गररठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११५", "title": "नपे ाल राज्र् बाविर पधन सािी प्रमाण बझ्ु न सवकनाःे (१) कुनै अदालतमा विचारािीन", "content": "रिेको कुनै मद्दु ाका सम्बन्िमा नेपाल राज्र् बाविर रिे बसेको कुनै सािी िा प्रमाण बझ्ु न ु\nपरेमा िा बन्दसिाल गन यु परेमा त्र्स्तो विषर्मा पारस्पररक कानूनी सिार्ता सम्बन्िी\nप्रचधलत कानून बमोत्तजम सािी िा प्रमाण बझ्ु न सवकनेछ।\n(२) उपदफा (१) बमोत्तजम प्रर्ोग िनु े बन्द सिालको ढाँचा अनसु ूची-४१ मा\nउल्लेि िए बमोत्तजम िनु ेछ।\n(३) उपदफा (१) बमोत्तजम बत्तुझएको सािी िा प्रमाणलाई र्सै ऐन बमोत्तजम\nबत्तुझएको माधननेछ।\nतर त्र्सरी बत्तुझएको सािी िा प्रमाण वििरण सम्बत्तन्ित मलु कु को कानून\nबमोत्तजम प्रमात्तणत िएको िनु ु पनेछ।\n(४) र्स दफा बमोत्तजम बझ्ु न ु पने िा बत्तुझएको सािी िा प्रमाण नेपाली िाषा\nबािेक अन्र् िाषामा बझ्ु न ु पने िा बत्तुझएको रिेछ िने सोको नेपाली िाषामा आधिकाररक\nअनिु ाद गरी अदालतमा पेश गन यु पनेछ।\n(५) कुनै कसूरको अनसु न्िान िा पपु िय को धसलधसलामा नेपाल राज्र् बाविर\nरिेको सािीलाई बझ्ु न ु परेमा िा धनजको बकपत्र गराउन परेमा त्र्स्तो सािीलाई सो\nप्रर्ोजनका लाधग तोवकए बमोत्तजम श्रव्र् दृष्र् संिाद (धिधडर्ो कन्फरेन्स) िा अन्र् र्स्तै\nप्रविधि माफय त बझु न िा धनजको बकपत्र गराउन सवकनेछ।\n(६) उपदफा (५) बमोत्तजम बिु m्दा िा बकपत्र गराउँदा त्र्स्तो सािीले िनेको\nकुरा िा गरेको बकपत्रको अधिलेि िनु े व्र्िस्था गन यु पनेछ।\n(७) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन र्स दफा\nबमोत्तजम प्रमाण बझु न नसवकएको कारणले मात्र मद्दु ाको कारबािी र वकनारा गन य बािा\nपगु ेको माधनने छैन।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n88\nwww.lawcommission.gov.np\nपररच्छेद-१२\nमद्दु ा वफता य धलन,े धमलापत्र र मेलधमलाप सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११६", "title": "मद्दु ा वफता य धलन निनु ाःे (१) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय का कसूरमा अदालतमा", "content": "एक पटक दार्र िइसके को मद्दु ा वफताय धलन सवकने छैन।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन देिार्को मद्दु ा बािेक\nअन्र् मद्दु ा वफताय धलन सवकनेछाः-\n(क) झट्टु ा रािदानी िा नागररकता, अध्र्ागमन, िष्ट्राचार, मानि बेचधबिन\nतथा ओसार पसार, लागू औषि ओसार पसार िा कारोबार,\nिन्र्जन्तकु ो अिैि त्तशकार तथा व्र्ापार, सािजय धनक उपिोगका\nिस्तमु ा विष धमसाएको, विष प्रर्ोग गरी िा क्रु र, अमानिीर् तिरले\nिा धनर्न्त्रणमा धलई ज्र्ान मारेको, सम्पत्ति शद्धु ीकरण, प्राचीन\nस्मारक संरिण सम्बन्िी मद्दु ा,\n\n(ि) अपराि संविताको िाग-२ को पररच्छेद-२ को दफा ५२ र\n५६, पररच्छेद-६ को दफा १२९, १३० १३१ र १३४,\nपररच्छेद-७ को दफा १३८, १३९ र १४१, पररच्छेद-८,\n\nपररच्छेद-१० को दफा १६७, पररच्छेद-१४ को दफा १९२क.\nपररच्छेद-१६ को दफा २०६, पररच्छेद-१७, पररच्छेद-१८ को\nदफा २१९ को उपदफा (१), (२) र (३), पररच्छेद-१९ को\nदफा २३० र २३१ तथा पररच्छेद-२२ को दफा २५६\nअन्तगतय को कसूर सम्बन्िी मद्दु ा,\n(ग) मद्दु ा वफताय धलदा कुनै व्र्त्तिको सम्पत्ति सम्बन्िी अधिकारमा\nप्रधतकू ल असर पने िएमा त्र्स िदसम्मको कुरामा त्र्स्तो\nव्र्त्तिको स्िीकृ धत निएको मद्दु ा।\n(३) नपे ाल सरकारले उपदफा (२) बमोत्तजम वफताय धलने मद्दु ाका सम्बन्िमा\nआिश्र्क मापदण्ड सवितको धनदेत्तशका बनाउन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n फौजदारी कसूर तथा फौजदारी कार्वयिधि सम्बन्िी केिी ऐन संशोिन गने ऐन, २०७९ द्वारा थप।\n89\nwww.lawcommission.gov.np\n(४) उपदफा (२) बमोत्तजम मद्दु ा वफताय गन यु पने िएमा नेपाल सरकारले\nमिान्र्ार्ाधिििासँग परामश य गरी उपदफा (३) बमोत्तजम बनाएको धनदेत्तशका बमोत्तजम\nवफताय धलने धनणर्य गन य सक्नेछ।\n(५) उपदफा (४) बमोत्तजम नेपाल सरकारले कुनै मद्दु ा वफताय धलने धनणर्य गरेमा\nमिान्र्ार्ाधिििा िा धनजले अत्तततर्ारी ठदएको सरकारी िवकल माफय त सम्बत्तन्ित\nअदालतमा मद्दु ा वफताय धलन ु पने कारण सवितको धनिेदन ठदन ु पनेछ।\n(६) उपदफा (५) बमोत्तजम धनिेदन पन य आएमा अदालतले मद्दु ा वफताय धलन े\nआदेश ठदनअु त्तघ सनु िु ाई गराउन ु पनेछ।\n(७) उपदफा (६) बमोत्तजम सनु िु ाई िएपधछ मद्दु ा वफताय धलने आदेश गन य\nमनाधसब िनु े देत्तिएमा कारण िलु ाई सम्बत्तन्ित अदालतले मद्दु ा वफताय धलन सक्ने आदेश\nगन य सक्नेछ।\n(८) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन पनु रािेदन, सािक\nजाँच िा पनु रालोकनको रोिमा िा मद्दु ा दोिो¥र्ाउने अिस्थामा विचारािीन रिेको मद्दु ा\nवफताय धलन सवकने छैन।\n\n११६क. दाबी वफता य धलन सक्नाःे (१) नेपाल सरकार िादी िनु े मद्दु ामा बािेक अन्र् कुनै पधन\nमद्दु ामा मद्दु ाको पिले उजरु ी, पनु रािेदनपत्र िा धनिेदनपत्रमा आफू ले धलएको दाबी त्र्ागी\nसो दाबी वफताय धलनको लाधग िा आफ्नो दाबी साधबत गन य नसक्ने िा दाबीको प्रर्ोजन\nसमाप्त िएको कारण देिाई सो उजरु ी, पनु रािेदनपत्र िा धनिेदनपत्र वफताय धलनको लाधग\nमद्दु ाको फै सला िनु ु अत्तघ जनु सकु ै बित अदालतमा धनिेदन ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम धनिेदन प्राप् त िएमा अदालतले धनिेदन माग\nबमोत्तजम उजरु ी, पनु रािेदनपत्र िा धनिेदनपत्र वफताय धलन अनमु धत ठदने आदेश गन यु पनेछ।\n(३) उपदफा (२) बमोत्तजम उजरु ी, पनु रािेदनपत्र िा धनिेदनपत्र वफताय धलन े\nआदेश िएमा अदालतले सो मद्दु ाको लगत कट्टा गन यु पनेछ।\n(४) र्स दफा बमोत्तजम कसैले उजरु ी, पनु रािेदनपत्र िा धनिेदनपत्र वफता य\nधलएकोमा सोिी व्र्त्तिले त्र्स्तो उजरु ी, पनु रािेदनपत्र िा धनिेदनमा विपि बनाइएका\nव्र्त्ति उपर सोिी विषर्मा उजरु गन य सक्ने छैन।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n90\nwww.lawcommission.gov.np\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११७", "title": "धमलापत्र िनु सक्नाःे (१) अनसु ूची-३ र अनसु ूची-४ अन्तगतय का कसूर सम्बन्िी कुनै मद्दु ामा", "content": "मद्दु ाका पििरुको मञ् जरु ीले जनु सकु ै अिस्थामा धमलापत्र गन य सवकनेछ।\n(२) उपदफा (१) को अधतररि  सिसय ािारणको िगी, अनत्तुचत लेनदेन िा\nसिसय ािारणको सम्पत्तिको िाधन, नोक्सानी , चेक अनादरको जररर्ाबाट उिेको बैवङ्कङ\n,\nकसरु आपराधिक विश्ि ासघात िा आपराधिक लाि िा िैदेत्तशक रोजगारी सम्बन्िी मद्दु ामा\nप्रधतिादी र पीधडत दिु ैले धमलापत्र गराई पाऊँ िनी सम्बत्तन्ित सरकारी िकील समि\nठदएको धनिेदन उपर कारबािी िँदु ा त्र्स्तो व्र्िोरा मनाधसब लागेमा  जनु सकु ै तिमा\nविचारािीन रिेको िा फै सला कार्ायन्िर्न गदायको अिस्थामा रिेको िए तापधन\nमिान्र्ार्ाधिििाले धमलापत्र गराउन आदेश ठदन सक्नेछ।\n\n(३) उपदफा (२) बमोत्तजम धमलापत्र िएमा त्र्स्तो मद्दु ाका सम्बन्िमा फै सला\nबमोत्तजम िएको दण्ड, जररबाना िा शल्ु कको लगत कट्टा िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११८", "title": "धमलापत्र गदाकय ो कार्वयिधिाः (१) दफा ११७ बमोत्तजम मद्दु ामा धमलापत्र गन य चािेमा", "content": "पििरुले िादी दािीधित्र धसमीत रिी धमल्न िोजेको व्र्िोरा िलु ाई दिु ै पिले सिीछाप\nगरी अदालतमा संर्िु धनिेदन पेश गन यु पनेछ।\n(२) उपदफा (१) बमोत्तजम धमलापत्र गने व्र्िोराको धनिेदन अदालतमा पन य\nआएमा अदालतले त्र्स्तो धनिेदन पढेर सनु ाई त्र्स बमोत्तजम रात्तजिशु ीले धमलापत्र गन य\nचािेको िो िा िोइन िनी त्र्स्तो धनिेदन पेश गने पििरुलाई सोध्न ु पनेछ।\n(३) उपदफा (२) बमोत्तजम सोध्दा रात्तजिशु ीले धमलापत्र गन य चािेको िो िन् न े\nजिाफ पििरुले ठदएमा संर्िु धनिेदन पत्रमा उल्लेि िए बमोत्तजमका शतिय रुको\nअिीनमा रिी धमलापत्रको धलित तर्ार गरी पििरुको सिीछाप गराई मद्दु ा िेने\nन्र्ार्ािीशले आफ्नो समेत सिीछाप गन यु पनेछ।\n(४) र्स पररच्छेद बमोत्तजम धमलापत्र गदाय िाररसनामा ठदई धमलापत्र गने\nअधिकार ठदएकोमा सोिी बमोत्तजम र िाररसनामामा िाररसलाई त्र्स्तो अधिकार\nनठदएकोमा िाररस माफय त ् धमलापत्र गदाय त्र्स्तो व्र्िोरा उल्लेि िएको पिको\nमञ् जरु ीनामा पेश गन यु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८० द्वारा संशोधित।\n सशु ासन प्रििनय तथा सािजय धनक सेिा प्रिाि सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८१ द्वारा\nथप।\n91\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "११९", "title": "मद्दु ा वफता य िा धमलापत्र िएमा त्र्सको पररणामाः (१) दफा ११६ बमोत्तजम नेपाल", "content": "सरकारले कुनै मद्दु ा वफता य धलएमा त्र्स्तो मद्दु ाको अधिर्िु उपर सोिी कसूरमा पनु ाः मद्दु ा\nचल्ने छैन।\n(२) दफा ११७ बमोत्तजम धमलापत्र िएकोमा सोिी विषर्मा सोिी पििरुका\nधबचमा पधछ कुनै कारबािी िा मद्दु ा चल्ने छैन।\nतर धमलापत्रमा उल्लेि िएको शत य बमोत्तजम कुनै पिले कुनै काम नगरेमा\nत्र्स्तो कुराको उजरु ी ठदन र्स उपदफाले िािा प¥ुर्ाउने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२०", "title": "मेलधमलाप िनु सक्नाःे (१) अनसु ूची-४ अन्तगतय को कसूर सम्बन्िी कुनै मद्दु ामा पििरुको", "content": "मञ् जरु ी िएमा िा अदालतले त्र्स्तो मद्दु ा मेलधमलापको लाधग पिाउन उपर्िु िानेमा\nपिलाई मेलधमलापकताय रोज्न लगाई र नरोजेमा अदालतले मेलधमलापकता य तोकी ठदई\nत्र्स्तो मद्दु ा मेलधमलापको लाधग जनु सकु ै बित र अिस्थामा पिाउने आदेश ठदन\nसक्नेछ।\n(२) उपदफा (१) बमोत्तजम आदेश िएकोमा मद्दु ाका पििरु त्र्स्तो\nमेलधमलापकताय समि उपत्तस्थत िनु ु पनेछ।\n(३) उपदफा (२) बमोत्तजम पििरु उपत्तस्थत िएपधछ मेलधमलापकतायले\nमेलधमलापको कारबािी सञ् चालन गरी पििरु धमलापत्र गन य मञ्जुर िए धमलापत्रको\nकागज तर्ार गरी अदालत समि पेश गन यु पनेछ।\n(४) उपदफा (३) बमोत्तजमको कागज प्राप् त िएपधछ अदालतले त्र्स्तो\nधमलापत्रको कागज प्रमात्तणत गररठदन ु पनेछ।\n\n(५) र्स दफा बमोत्तजम धमलापत्र िएमा त्र्स्तो मद्दु ाका सम्बन्िमा फै सला\nबमोत्तजम िएको दण्ड, जररबाना िा शल्ु कको लगत कट्टा िनु ेछ।\nपररच्छेद-१३\nमद्दु ाको कारबािी, सनु िु ाई र फै सला सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२१", "title": "अधिर्िु लाई अधिर्ोग सनु ाउन ु पनेाः (१) अधिर्िु अदालतमा उपत्तस्थत िएपधछ", "content": "अदालतले अधिर्िु उपर लगाइएको अधिर्ोग, तत्सम्बन्िी तथ्र् सवितको वििरण र\nअधिर्ोग प्रमात्तणत गन य उजरु िालाले पेश गरेको प्रमाण तथा अधिर्ोग प्रमात्तणत िएमा िनु\n सशु ासन प्रििनय तथा सािजय धनक सेिा प्रिाि सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८१ द्वारा\nसंशोधित।\n92\nwww.lawcommission.gov.np\nसक्ने सजार् स्पष्ट रुपमा सम्झाई बझु ाई अधिर्ोगपत्रमा धलएको माग दािी पढेर सनु ाउन ु\nपनेछ।\n(२) उपदफा (१) बमोत्तजम अधिर्ोग तथा सो अधिर्ोगमा िनु सक्न े सजार्का\nसम्बन्िमा सम्झाउँदा र बझु ाउँदा कुन आरोप कुन कुन सिदु , प्रमाण िा धलितमा\n\nआिाररत छ त्र्स्तो अधिर्ोगमा िनु सक्ने सजार् समेत िलु ाई अधिर्िु ले त्र्स्ता सिदु ,\nप्रमाण िा धलित िेन य िा त्र्सको प्रधतधलपी धलन चािेमा धनजलाई त्र्सको मौका ठदन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२२", "title": "अधिर्िु को बर्ान गराउन ु पनेाः (१) अधिर्िु लाई दफा १२१ बमोत्तजम अधिर्ोग तथा", "content": "त्र्स्तो अधिर्ोगमा िनु सक्ने सजार् सनु ाई सके पधछ अदालतले त्र्स्तो अधिर्ोग उपर\nधनजको के िनाई छ सोिी धनजको बर्ान अधिलेि गन यु पनेछ।\n(२) अदालतमा उपत्तस्थत िई सके को अधिर्िु सँग बर्ान धलन ु अगाधड नै धनजले\nकुनै कानून व्र्िसार्ीसँग सल्लाि धलन चािेमा धनजलाई त्र्सको मौका ठदन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम बर्ान अधिलेि गन यु िन्दा अगाधड नै अदालतले\nअधिर्िु लाई धनजले आफ्नो विरुद्ध बर्ान ठदन कर नलाग्न े कुरा जानकारी गराई धनजले\nठदएको बर्ान धनजको विरुद्ध प्रमाण लाग्न सक्छ िनी जानकारी गराउन ु पनेछ।\n(४) उपदफा (३) बमोत्तजमको व्र्िोरा जानकारी गराउँदा सरकारी िवकलबाट\nधनज विरुद्धको सजार्मा छुट िनु प्रस्ताि गररएको रिेछ िने त्र्स्तो कुरा र त्र्स\nसम्बन्िी प्रचधलत कानूनको व्र्िस्था समेत जानकारी गराउन ु पनेछ।\n(५) र्स दफा बमोत्तजम अधिर्िु को बर्ान अधिलेि गदाय प्रत्र्ेक प्रश्न र त्र्सको\nजिाफ दिु ै लेििद्ध गन यु पनेछ र श्रव्र्-दृश्र् सम्िाद (धिधडर्ो कन्फरेन्स) माफय त बर्ान\nधलएको िए त्र्सको अधिलेि समेत रात न ु पनेछ।\n(६) उपदफा (५) बमोत्तजमको बर्ान अधिलेि िै सके पधछ त्र्स्तो अधिलेिमा\nअधिर्िु को सिीछाप गराई न्र्ार्ािीशले पधन आफ्नो सिीछाप गन यु पनेछ।\nतर श्रव्र्-दृश्र् सम्िाद (धिधडर्ो कन्फरेन्स) माफय त बर्ान धलएकोमा न्र्ार्ािीशले\nत्र्स्तो कुरा प्रमात्तणत गरी रात न ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n93\nwww.lawcommission.gov.np\n(७) र्स दफा बमोत्तजम बर्ान गराउंेँदा अधिर्िु सँग बझु न ु पने कुनै कुरा छुट\nिनु गएमा अदालतले त्र्स्तो अधिर्िु लाई उपत्तस्थत गराउन लगाई धनजसँग छुट कुराको\nतधतम्बा बर्ान धलन सक्नछे ।\n(८) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन अनसु ूची-४\nअन्तगतय को कसूर सम्बन्िी मद्दु ामा प्रधतिादी रिेको व्र्त्तिले अदालतबाट जारी िएको\nम्र्ाद धित्र अनसु ूची-४२ बमोत्तजमको ढाँचामा प्रधतउिर पत्र दात्तिला गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२३", "title": "अधिर्िु ले कसूर स्िीकार गरे मद्दु ाको फै सला तत्काल गन यु पनेाः (१) कुनै अधिर्िु ले", "content": "धनज उपर लागेको कसूरको आरोप स्िीकार गरी अदालतमा साविती बर्ान गरेमा\nअदालतले त्र्स्तो बर्ानको सत्र्ता र विश्वसनीर्तालाई समेत विचार गरी तत्काल उि\nमद्दु ाको फै सला गन य सक्नेछ।\nतर, -\n(क) अधिर्िु ले त्र्स्तो साविती बर्ान गरे तापधन धमधसल संलग्न\nप्रमाण, कसूर गदायको पररत्तस्थधत िा अन्र् कुनै कुराले धनजको\nसाविती साँचो िोइन िन् ने विश्वास िनु े कुनै कारण िएमा\nअदालतले र्स दफा बमोत्तजम मद्दु ा फै सला नगरी कारण सवितको\nआदेश पचाय िडा गरी मद्दु ामा थप प्रमाण बझु न आदेश ठदन ु पनेछ,\n(ि) आरोवपत कसूरमा साविती िएको अधिर्िु ले सजार्मा छुट िा\nकमी िनु ु पने त्तजकीर धलएमा त्र्स सम्बन्िी सबै कुरा िलु ाई\nधनजको बर्ान धलई तत ् सम्बन्िी प्रमाण बझ्ु न पछय।\n(२) कुनै अधिर्िु ले अदालतमा बर्ान गदाय अनसु न्िान अधिकारी समि\nगरेकोिन्दा फरक त्तजवकर धलएमा धनजले पेश गरेको प्रमाण िा त्तजवकरको विषर्मा िादी\nपिले पनु ाः अनसु न्िान गरी िा गराई अदालतमा थप सिदु प्रमाण पेश गन य माग गरेमा\nअदालतले त्र्स्तो थप सिदु प्रमाण पेश गने अनमु धत ठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजम आदेश िएकोमा त्र्स्तो थप प्रमाण पेश निई\nअदालतले उि मद्दु ा फै सला गन य िदु ैन।\nतर त्र्स्तो थप सिदु पेश गन यु पदाय प्रमाण मकु रर आदेश िनु अत्तघ नै पेश गन यु\nपनेछ।\n94\nwww.lawcommission.gov.np\n(४) कुनै अधिर्िु आरोवपत कसूरमा पूण य रुपमा सावित निई आंत्तशक रुपमा\nसावित िएमा अदालतले धनज सावित निएको िदसम्मको विषर्मा थप प्रमाण बझ्ु न े\nआदेश गन यु पनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२४", "title": "िादी प्रधतिादीधबच छलफल गराउन सक्नाःे (१) अधिर्िु ले दफा १२३ बमोत्तजम कसूर", "content": "इन्कार रिेको िा इन्कार प्रधतउिर ठदएको अिस्थामा अदालतले मद्दु ामा ििर गन यु पने\nकुरा र्वकन गनकय ो लाधग िादी तथा प्रधतिादीधबच छलफल गराउने आदेश ठदन\nसक्नेछ।\n(२) उपदफा (१) बमोत्तजम छलफल गराउन आदेश िएकोमा त्र्सरी छलफल\nगने िनी धनिायरण गररएको ठदन िादी, प्रधतिादी र नेपाल सरकार िादी िनु े मद्दु ाको िकमा\nअधिर्िु समेत अदालतमा उपत्तस्थत िनु ु पनेछ र त्र्स्तो अधिर्िु ले चािेमा धनजको\nकानून व्र्िसार्ी समेत उपत्तस्थत िनु सक्नेछ।\n(३) उपदफा (१) बमोत्तजमको छलफलमा िादीले दािी र प्रधतिादीले प्रधतिाद र\nतत्सम्बन्िी प्रमाण प्रस्ततु गन य सक्नेछन।्\n(४) उपदफा (३) बमोत्तजम िादी प्रधतिादीले पेश गरेको दािी, प्रधतबाद तथा\nप्रमाणबाट अदालतले मद्दु ामा ििर गन यु पने कुरा र्वकन गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२५", "title": "प्रमाण बझ्ु न ताररि तोक्नाःे (१) देिार्को अिस्थामा अदालतले दफा १२४ बमोत्तजम", "content": "र्वकन िएको ििर गन यु पने कुरािरु समेत िलु ाई आदेश पचाय िडा गरी प्रमाण बझ्ु न े\nताररि तोक्न ु पनेछाः-\n(क) अधिर्िु ले दफा १२२ बमोत्तजम बर्ान गन य इन्कार गरेमा,\n(ि) प्रधतिादीले प्रधतउिरपत्र दात्तिल नगरेमा,\n(ग) अधिर्िु िा प्रधतिादीले आफू उपरको अधिर्ोग िा दाबी पूरै िा\nआंत्तशक रुपमा इन्कार गरी बर्ान गरेमा िा प्रधतउिर ठदएमा,\n(घ) अदालतले दफा १२३ को उपदफा (१) को प्रधतबन्िात्मक\nिाक्र्ांशको िण्ड (क) िा (ि) बमोत्तजम प्रमाण बझ्ु ने आदेश\nपचाय िडा गरेमा,\n(ङ) अदालतले उपर्िु ििर् र्ाएको अन्र् अिस्थामा।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n95\nwww.lawcommission.gov.np\n(२) उपदफा (१) बमोत्तजम प्रमाण बझु ने ताररि तोक्दा अदालतले सािीिरु\nउपत्तस्थत िनु र प्रमाणका धलित तथा िस्तिु रु पेश िनु सक्न े समर्को अनमु ान गरी\nसम्िि िएसम्म चाँडो प्रमाण सङ्कलन िनु सक्ने गरी तोक्न ु पनेछ।\n(३) कुनै मद्दु ाको िादी पिले दफा १२३ को उपदफा (२) बमोत्तजम थप सबूद\nप्रमाण पेश गनकय ो लाधग समर् माग गरेमा अदालतले उपदफा (१) बमोत्तजम ताररि\nतोक्दा सामान्र्तर्ा मद्दु ा दार्र िएको दईु मविनाधित्र प्रमाण बझ्ु ने ताररि तोक्न ु\nपनेछ।\n(४) उपदफा (२) िा (३) बमोत्तजम प्रमाण बझ्ु नको लाधग ताररि तोक्ने आदेश\nगदाय मद्दु ामा बझ्ु न ु पने सबै प्रमाणिरु सम्िि िएसम्म एकै पटक बझ्ु न े आदेश गरी\nताररि तोक्न ु पनेछ।\n(५) उपदफा (१) िा (२) बमोत्तजम ताररि तोक्ने आदेश गरेपधछ मद्दु ाका\nसम्बत्तन्ित पिले आफू ले पेश गन यु पने प्रमाण िा उपत्तस्थत गराउन ु पने सािी अदालतमा\nतोवकएको ताररिका ठदन पेश िा उपत्तस्थत गराउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२६", "title": "कै द िा थनु ामा परेको पि िा सािीलाई उपत्तस्थत गराउन ु पनेाः (१) मद्दु ाको कुनै पि िा", "content": "सािी कै द िा थनु ामा रिेको िए धनजको बर्ान िा िकपत्र गराउनको लाधग िा धनजसँग\nसम्बद्ध िएको अन्र् मद्दु ामा धनजलाई उपत्तस्थत गराउन ु पने िए त्र्सको लाधग तोवकएको\nताररिको ठदन धनजलाई उपत्तस्थत गराउन कारण िोली अदालतले सम्बत्तन्ित\nकार्ायलर्लाई आदेश ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको आदेश प्राप् त िएपधछ सम्बत्तन्ित कार्ायलर्ले\nसरु िाकमीको साथ लगाई त्र्स्तो पि िा सािीलाई अदालतमा उपत्तस्थत गराउन ु\nपनेछ।\n(३) उपदफा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्तो पि िा\nसािीलाई सरु िाको कारणले िा शारीररक अशिताको कारणले अदालत समि उपत्तस्थत\nगराउन नसवकने मनाधसब कारण िए त्र्स्तो कार्ालय र्ले अदालतको अनमु धत धलई श्रव्र्\nदृष्र् सम्िाद (धिधडर्ो कन्फरेन्स) माफय त धनजलाई बझ्ु ने व्र्िस्था गन य सक्नेछ।\n(४) मद्दु ाको कुनै पि िा सािीलाई उपदफा (३) बमोत्तजम श्रव्र् दृष्र् सम्िाद\n(धिधडर्ो कन्फरेन्स) माफय त बत्तुझएकोमा धनजले िनके ो कुरा अधिलेि रात न ु पनेछ।\n96\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२७", "title": "प्रमाण बझु न े क्रमाः (१) प्रमाण बझु न तोवकएको ताररिको ठदन अदालतले अन्र्था आदेश", "content": "ठदएकोमा बािेक प्रमाण सम्बन्िी कानूनको अिीनमा रिी पविले िादीको र त्र्सपधछ\nप्रधतिादीको सािी प्रमाण बझु न ु पनेछ।\n(२) कुनै पिद्वारा प्रस्ततु गररएको कुनै प्रमाण िा कुनै सािीले बके को कुनै कुरा\nप्रमाणमा नलाग्न े िा प्रमाणको रुपमा धलन निनु े िा असान्दधिकय विषर् िनी अको पिले\nतत्काल कुनै आपत्ति जनाएमा त्र्स्तो आपत्ति मनाधसब िो िा िोइन िनी न्र्ार्ािीशले\nतत्काल धनणर्य ठदन ु पनेछ।\n(३) अदालतले मद्दु ासँग असम्िद्ध प्रमाण पेश गन य कुनै पिलाई अनमु धत ठदन े\nछैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२८", "title": "िोस िेगानमा नरिेका व्र्त्तिको कारबािी सम्बन्िी व्र्िस्थााः (१) कुनै अधिर्िु िोस", "content": "िेगानामा नरिेको कारणले आफ्नो प्रधतरिा गन य असमथ य छ िन् ने विश्वास गनपयु ने कुन ै\nमनाधसब कारण िएमा अदालतले इजाजतप्राप् त त्तचवकत्सकद्वारा धनजको जाँच गराई उपचार\nगराउन समेत आदेश गन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम जाँच गराउँदा अधिर्िु मानधसक अस्िस्थताको\nकारणले आफ्नो प्रधतरिा गन य असमथ य देत्तिएमा त्र्सको आदेश पचाय िडा गरी धनजको\nिकमा मद्दु ा मलु तिी रात न ु पनेछ।\n(३) र्स ऐनमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्तो अधिर्िु\nथनु ामा रिेको िए उपदफा (१) बमोत्तजम कारबािी िँदु ाका बित िा त्र्स्तो कारबािी िै\nउपदफा (२) बमोत्तजमको आदेश पचा य िडा िएपधछ अदालतले मनाधसब सम्झेमा\nधनजलाई थनु ाबाट छोड्न आदेश ठदन सक्नेछ।\n(४) उपदफा (३) बमोत्तजम अधिर्िु लाई छोड्दा अदालतले धनजको संरिकबाट\nत्र्स्तो अधिर्िु ले कसैलाई कुनै प्रकारको िाधन, नोक्सानी प¥ुर्ाउन नपाउने गरी धनजको\nिेरचाि गने र धनज स्िस्थ िएपधछ अदालतले आदेश ठदएका बित धनजलाई अदालतमा\nउपत्तस्थत गराउने शत य गराउन ु पनेछ।\n\n(५) उपदफा (३) बमोत्तजम थनु ाबाट छोड्दा अदालतले चािेमा संरिकसँग\nपररच्छेद-७ बमोत्तजम िरौट िा जमानत धलन सक्नछे ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n97\nwww.lawcommission.gov.np\n(६) पपु िय का लाधग थनु ामा रिेको िोस िेगानामा नरिेको अधिर्िु लाई उपदफा\n(३) बमोत्तजम थनु ाबाट छोधडएको अिस्थामा बािेक अन्र् अिस्थामा विशेष िेरविचार गन य\nसम्बत्तन्ित कारागारलाई अदालतले आदेश ठदन ु पनेछ।\n(७) िोस िेगानामा नरिेको अधिर्िु को मद्दु ा उपदफा (२) बमोत्तजम मलु तिी\nरिेकोमा त्र्स्तो अधिर्िु स्िस्थ िएपधछ अदालतले मलु तिी जगाई धनजलाई अदालतमा\nउपत्तस्थत गराई मद्दु ाको पपु िय शरुु गन यु पनेछ।\nतर त्र्सरी मलु तिी जगाउनिु न्दा पविले अदालतले त्र्स्तो अधिर्िु लाई पनु ाः\nइजाजत प्राप् त त्तचवकत्सकद्वारा जाँच्न लगाई त्र्स्तो त्तचवकत्सकले अधिर्िु स्िस्थ िै\nसके को छ िन् ने व्र्िोरा प्रमात्तणत गरेको िनु ु पनेछ।\n(८) उपदफा (१) िा (७) बमोत्तजम स्िस्थता प्रमात्तणत गने त्तचवकत्सकलाई\nअदालतले चािेमा सािीको रुपमा उपत्तस्थत िनु आदेश ठदन सक्नेछ।\n(९) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन िोस िेगानामा\nनरिेको व्र्त्तिसँग अरु व्र्त्तििरु पधन प्रधतिादी रिेछन िने त्र्स्ता प्रधतिादीको िकमा\nमद्दु ाको सनु िु ाइ गन य बािा पगु ेको माधनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१२९", "title": "मद्दु ाको पपु िय िलु ा इजलासमा गन यु पनेाः अदालतले मद्दु ाको पपु िय गदाय िलु ा इजलासमा", "content": "गन यु पनेछ।\nतर जाससु ी, मानि बेचधबिन तथा ओसार पसार, र्ौनजन्र् कसूर, बालबाधलका\nअधिर्िु िा पीधडत िएको मद्दु ा, मविला धबरुद्धको विंसा, जिजस्य ती करणी, िाडनाता करणी\nिा पती पत्न ीधबच चलेको मद्दु ा िा अदालतले बन्द इजलासमा सनु िु ाई गन य उत्तचत देिी\nआदेश गरेको अन्र् मद्दु ाको पपु िय बन्द इजलासमा िनु सक्नेछ र त्र्स्तो इजलासमा\nअदालतले त्र्स्तो मद्दु ासगँ सम्बत्तन्ित पि, सम्बत्तन्ित कानून व्र्िसार्ी, अदालतका\nकमचय ारी र अदालतले आिश्र्क देिेका अन्र् व्र्त्ति बािेक अरुलाई प्रिेश धनषिे गन य\nसक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३०", "title": "अधिर्िु ले आफ्नो प्रधतरिाको लाधग कानून व्र्िसार्ी धनर्िु गन य सक्नाःे (१) कुन ै", "content": "कसूरको अधिर्ोग लागेको अधिर्िु ले आफू उपर लागेको आरोप िण्डन गन य िा आफ्नो\nप्रधतरिाको लाधग आफू ले रोजेको कानून व्र्िसार्ी धनर्िु गरी बिस पैरिी गराउन\nसक्नेछ।\n98\nwww.lawcommission.gov.np\n(२) जन्म कै दको सजार् िा दश िष य िा दश िषिय न्दा बढी कै दको सजार् िनु\nसक्ने कसूरको आरोप लागेको अधिर्िु ले आफ्नो कानून व्र्िसार्ी धनर्िु नगरेमा\nअदालतले त्र्स्तो अधिर्िु को िकमा अदालतको तफय बाट धनर्िु कानून व्र्िसार्ीबाट\nधनजको प्रधतरिा गन य आदेश ठदन सक्नेछ।\n(३) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै अधिर्िु ले\nउपदफा (१) बमोत्तजम कानून व्र्िसार्ी रात न नचािेमा िा उपदफा (२) बमोत्तजम\nअदालतले धनर्िु गरेको कानून व्र्िसार्ीबाट प्रधतरिा गराउन इन्कार गरेमा पधन\nमद्दु ाको कारबािी अगाधड बढाउन बािा पगु ेको माधनने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३१", "title": "फै सला गन यु पनेाः (१) मद्दु ामा प्रमाण बझु ने कार् य समाप्त िएको सामान्र्तर्ा एक", "content": "मविनाधित्र न्र्ार्ािीशले मद्दु ाको फै सला गन यु पनेछ।\n(२) उपदफा (१) बमोत्तजमको अिधिधित्र फै सला गन य नसवकएमा त्र्सको कारण\nिलु ाई पनु रािेदन सन्ु ने अदालतमा त्र्सको जानकारी गराउन ु पनेछ।\n(३) र्स दफा बमोत्तजम फै सला गदाय देिार्का कुरा समेत उल्लेि गरी अनसु ूची-\n४३ बमोत्तजमको ढाँचामा गन यु पनेछाः-\n(क) मद्दु ाको संत्तिप् त वििरण तथा सोसँग सम्बत्तन्ित आिश्र्क कुरा,\n(ि) मद्दु ामा कुनै कानून व्र्िसार्ीले बिस गरेको िए त्र्स्तो बिसको\nमतु र् मतु र् बदँु ा,\n(ग) मद्दु ाका पििरुले पेश गरेको प्रमाण, ती प्रमाणको विश्वसधनर्ता िा\nिण्डनीर्, त्र्सको आिार, प्रमाणको पर्ायप्तता िा अपर्ायप्तता,\n(घ) मद्दु ामा कुनै पिले कुनै कानूनी प्रश्न उिाएको िए त्र्स सम्बन्िी\nकुरा,\n(ङ) कसूर ििर िनु े िा निनु े आिार तथा त्र्सको कारण,\n(च) पनु रािेदन लाग्ने िा नलाग्ने र पनु रािेदन गन यु पने अदालत,\n(छ) अन्र् आिश्र्क कुरािरु।\n(४) र्स दफा बमोत्तजम फै सला गदाय न्र्ार्ािीशले आफ्नो फै सलाको पूण य लेि\nतर्ार िएकोमा त्र्स्तो पूण य लेि र तर्ार निएकोमा आफ्नो धनणर्य सम्म मात्र सनु ाउन\nसक्नेछ।\n99\nwww.lawcommission.gov.np\n(५) उपदफा (४) बमोत्तजम धनणर्य मात्र सनु ाइएकोमा न्र्ार्ािीशले त्र्स्तो\nधनणर्य को छोटकरी वििरण रार् वकताबमा लेिी सिीछाप गरी मद्दु ाका उपत्तस्थत पिलाई\nसमेत सिीछाप गराई रात न ु पनेछ।\nतर नेपाल सरकार िादी िनु े मद्दु ामा सरकारी िवकललाई सिीछाप गराउन ु पने\nछैन।\n\n(६) उपदफा (५) बमोत्तजम धनणर्य सनु ाएकोमा न्र्ार्ािीशले एक्काइस कार् य\nठदनधित्र फै सला लेिी धमधसल संलग्न रात न ु पनेछ।\nस्पष्टीकरणाः र्स उपदफाको प्रर्ोजनको लाधग “धनणर्य सनु ाएको” िन् नाले सजार् धनिायरण\nगरी सनु ाएको धनणर्य सम्झन ु पछय।\n\n(६क) उपदफा (६) बमोत्तजम तर्ार गररएको फै सलामा फै सला िएको र\nफै सला तर्ार िएको धमधत उल्लेि गरी न्र्ार्ािीशले िस्तािर गरी प्रमाणीकरण गन यु\nपनेछ।\n(७) उपदफा (६) बमोत्तजमको अिधिधित्र फै सला नलेत्तिएमा त्र्स्तो म्र्ाद समाप्त\nिएको तीन ठदनधित्र सम्बत्तन्ित पिले उच्च अदालत र मातित अदालतको फै सलाको\nिकमा सम्बत्तन्ित उच्च अदालतका मतु र् न्र्ार्ािीश समि र सिोच् च अदालतको\nफै सलाको िकमा प्रिान न्र्ार्ािीश समि उजरु गन य सक्नेछ।\n(८) उपदफा (७) बमोत्तजम उजरु पन य आएकोमा सम्बत्तन्ित मतु र् न्र्ार्ािीश िा\nप्रिान न्र्ार्ािीशले एक िप्ताधित्र फै सला तर्ार गरी सक्न सम्बत्तन्ित न्र्ार्ािीशलाई\nधनदेशन ठदन ु पनेछ।\n(९) उपदफा (५) बमोत्तजमको धनणर्य अदालतले सम्िि िएसम्म आफ्नो\nिेिसाइटमा तत्काल रात न ु पनेछ।\n(१०) अदालतले प्रत्र्ेक िप्ता तर्ार िई प्रमाणीकरण िएका फै सलाको वििरण\nअदालतको सूचना पाटीमा टाँस गरी आफ्नो िेबसाईटमा समेत रात न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३२", "title": "फै सलाको सूचना तथा नक्क ल ठदनाःे (१) मद्दु ाको कारबािीमा शरुु देत्ति नै संलग्न नरिेको", "content": "अधिर्िु िा प्रधतिादी, थनु ा िा कै दमा रिेको अधिर्िु िा एउटा मात्र पि िई एकतफी\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n100\nwww.lawcommission.gov.np\nकारबािी िएको मद्दु ाको अधिर्िु लाई अदालतले अनसु ूची-४४ बमोत्तजमको ढाँचामा\nफै सलाको सूचना ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको सूचना समाह्वान सरि तामेल गररनेछ र त्र्स्तो\nसूचना तामेल िनु नसके मा नेपाल सरकारको स्िाधमत्िमा रिेको रावष्ट्रर् स्तरको कुन ै\nदैधनक समाचारपत्रमा सूचना प्रकाशन गररनेछ।\n(३) अनसु ूची-४ बमोत्तजमको मद्दु ाका सन्दिमय ा उपदफा (२) बमोत्तजमको सूचना\nप्रकाशन गदाय लाग्ने िच य सम्बत्तन्ित पिले व्र्िोन यु पनेछ।\n(४) अनसु ूची-१, अनसु ूची-२ र अनसु ूची-३ बमोत्तजमको मद्दु ामा िएको फै सलाको\nजानकारी सम्बत्तन्ित सरकारी िवकलको कार्ायलर्लाई समेत ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३३", "title": "मत्ृ र् ु िएमा मद्दु ा िारेज िनु ाःे (१) र्स ऐनमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन", "content": "कुनै मद्दु ाको अधिर्िु िा प्रधतिादीको मत्ृ र् ु िएमा अदालतले त्र्स्तो मद्दु ा िारेज गररठदन ु\nपनेछ।\nतर एकिन्दा बढी अधिर्िु िा प्रधतिादी िएकोमा कुनै एक अधिर्िु को मत्ृ र् ु\nिदु ैमा मद्दु ा िारेज गन य सवकने छैन।\n\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन धबगो िा िधतपूधत य\nसमािेश िएको मद्दु ामा अधिर्िु िा प्रधतिादीको मत्ृ र् ु िएपधन अदालतले धमधसल संलग्न\n\nप्रमाण र बझ्ु न आिश्र्क देत्तिएको अन्र् प्रमाणिरु समेत बझु ी धबगो िा िधतपूधत य\nकार्म गने धनणर्य गन य सक्नेछ।\n(३) कुनै उजरु िालाको मत्ृ र् ु िए तापधन उपदफा (२) बमोत्तजमको मद्दु ामा\nधनजको िकिालाले त्र्स्तो उजरु िालाको मत्ृ र् ु िएको तीस ठदनधित्र मद्दु ा सकार गन य\nआएमा अदालतले सकार गराई धमधसल सामेल रिेको प्रमाण र बझ्ु न आिश्र्क देत्तिएको\nअन्र् प्रमाणिरु समेत बझु ी धबगो िा िधतपूधत य िराइठदन ु पने िा नपने कुराको धनणर्य गन यु\nपनेछ।\n(४) पनु रािेदन, पनु रािलोकन िा मद्दु ा दोिोर् र्ाउन धनिेदन ठदन े पिको िा त्र्स्तो\nमद्दु ामा पविले कसूरदार ििररएको व्र्त्तिको मत्ृ र् ु िएमा त्र्स्तो पनु रािेदन, पनु रािलोकन\nिा दोिर् र्ाई िेररएको मद्दु ा तामेलीमा रात्तिठदन ु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n101\nwww.lawcommission.gov.np\nतर -\n(क) एकै पिको कुनै एउटा व्र्त्तिको मत्ृ र् ु िएकोमा अन्र् व्र्त्तिको\nिकमा मद्दु ाको कारबािी नगरी तामेलीमा रात न सवकने छैन,\n(ि) धबगो समािेश िएको मद्दु ामा िकिालाले चािेमा जानकारी प्राप् त\nिएको धमधतले पैँतीस ठदनधित्र सकार गन य पाउनेछ।\nपररच्छेद-१४\nपनु रािदे न र सािक सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३४", "title": "पनु रािदे न लाग्नाःे (१) अदालतले गरेको फै सला िा अत्तन्तम आदेश उपर त्तचि नबझ्ु न े", "content": "\nपिले फै सला िएको थािा पाएको धमधतले नेपाल सरकार बादी िनु े फौजदारी मद्दु ाको\nिकमा सिरी ठदन र अन्र् मद्दु ामा तीस ठदनधित्र पनु रािेदन गन य सक्नेछ।\nतर त्र्स्तो अिधिधित्र पनु रािेदन गन य नसके को कारण देिाई पनु रािेदन गन य\nचािने पिले धनिेदन ठदएमा र धनिेदनको व्र्िोरा मनाधसब ििराएमा पनु रािेदन सन्ु ने\nअदालतले बढीमा तीस ठदनसम्मको म्र्ाद थाधमठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम पनु रािेदन गन य चािने व्र्त्तिले फै सला गने\nअदालतको पनु रािेदन सन्ु ने अदालतमा पनु रािेदन दताय गराउन ु पनेछ।\n(३) र्स ऐनमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन अदालतबाट सनु िु ाई\nिँदु ाका बित मद्दु ाको पि िा धनजको िाररस उपत्तस्थत िएको िा धनजको कानून\nव्र्िसार्ी उपत्तस्थत िई बिस पैरिी गरेको रिेछ र सोिी ठदन फै सला िएको रिेछ िने\nमद्दु ाको पिले त्र्स्तो फै सला िएको थािा पाएको माधननेछ।\n\nतर सरकार िादी िएको मद्दु ाको िकमा दफा १३२ को उपदफा (४)\nबमोत्तजम फै सलाको जानकारी प्राप् त िएको धमधतबाट पनु रािेदन गने म्र्ाद शरुु िनु ेछ।\n(४) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन फै सला िएको\nधमधतले एक िषकय ो अिधि नाघेपधछ पिले फै सला िएको स्िताः थािा पाएको माधननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३५", "title": "फै सला गन े अदालत िा कै दमा रिेको कारागार माफय त पनु रािदे न दता य गन य सवकनाःे (१)", "content": "दफा १३४ को उपदफा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन सो दफाको\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n102\nwww.lawcommission.gov.np\nउपदफा (१) बमोत्तजम पनु रािेदन गन य चािने व्र्त्तिले फै सला गने अदालत माफय त िा\nत्र्स्तो फै सलाबाट कसूरदार ििररएको व्र्त्ति कै दमा रिेको िए कै दमा रिेको कारागार\nमाफय त पधन पनु रािेदन गन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम पनु रािेदन दताय िएकोमा त्र्स्तो अदालत िा\nकारागारले पनु रािेदकले धनजलाई िएको सजार् िोगेको िा बझु ाएको िा त्र्स बापत\nिरौट िा जमानत ठदएको िए त्र्स्तो व्र्िोरा िोली पनु रािेदन सन्ु ने अदालतमा\nर्थासम्िि चाँडो पनु रािेदन पिाई पनु रािेदकलाई त्र्स कुराको जानकारी ठदन ु पनेछ।\n(३) फै सला गने अदालतले उपदफा (२) बमोत्तजम पनु रािेदन पिाउँदा सम्बत्तन्ित\nधमधसल समेत साथै रािी पिाउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३६", "title": "पनु रािदे न ठदँदा रीत पर्ु र् ाउन ु पनेाः (१) पनु रािेदन ठदँदा अनसु ूची-४५ बमोत्तजमको ढाँचामा", "content": "ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम ठदने पनु रािेदनमा अन्र् कुराको अधतररि पनु रािेदक\nर प्रत्र्थीको परु ा नाम र िेगाना, मद्दु ाको संत्तिप् त वििरण, तल्लो अदालतको धनणर्य मा त्तचि\nनबझु ेको कुरा र त्र्सको आिार, पनु रािेदन सन्ु ने अदालतबाट धनणर्य िनु ु पने कुरािरु र\nसम्बत्तन्ित कानून स्पष्ट रुपमा उल्लेि गरी पनु रािेदकले सिीछाप गन यु पनेछ।\n(३) उपदफा (१) बमोत्तजम पनु रािेदन ठदँदा देिार्का धलितिरु पनु रािेदन साथ\nसंलग्न गन यु पनेछाः-\n(क) जनु फै सला उपर पनु रािेदन ठदन िोजेको िो त्र्स्तो फै सलाको\nप्रधतधलवप,\n(ि) फै सलाबाट पनु रािेदकलाई कुनै सजार् िएको रिेछ िने धनजले\nत्र्स्तो सजार् िोगेको िा बझु ाएको िा त्र्स बापत कै दमा रिेको\nिा जमानत ठदएको िा िरौट रािेको धनस्सा।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३७", "title": "पनु रािदे न ठदंदा कै दमा बस्न ु पनेाः (१) देिार्को कुनै व्र्त्तिले पनु रािेदन ठदँदा कै दमा", "content": "बसेर ठदन ु पनेछाः-\n(क) जन्मकै दको सजार् िएको व्र्त्ति,\n(ि) दश िषिय न्दा बढी कै द सजार् िएको व्र्त्ति,\n103\nwww.lawcommission.gov.np\n(ग) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय को कसूरमा कसूरदार ििरी\nतीन िषिय न्दा बढी कै दको सजार् पाएको व्र्त्ति,\n(घ) पपु िय को लाधग थनु ामा िसेकोमा कसूरदार ििरी कै द सजार्\nपाएको व्र्त्ति,\n(ङ) कै दको सजार् पाएको र नेपालधित्र स्थार्ी बसोबास निएको\nव्र्त्ति।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन पचििर िष य माधथको\nव्र्त्ति िा धनको निनु े िा अत्र्न्त कडा रोग लागी थनु ामा बस्न नसक्ने िनी नेपाल\nसरकारले गिन गरेको मेधडकल बोडबय ाट धसफाररस िएको व्र्त्ति िा अदालतबाट\nपपु िय को लाधग थनु ामा रात न नपने आदेश िई थनु ामा नबसेको अिस्थामा दश िषसय म्म\nकै द सजार् िएको कसूरदारले थनु ामा नबसी पनु रािेदन ठदने अनमु धतको लाधग कारण\nिलु ाई धनिेदन गरेमा र त्र्स्तो कारण मनाधसब देत्तिएमा पनु रािेदन सन्ु ने अदालतले\nधनजसँग िरौट िा जमानत धलई पनु रािेदन गने अनमु धत ठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजम अनमु धत ठदएकोमा त्र्स्तो अदालतले थनु ामा नबसी\nपनु रािेदन गन य सक्ने कारण िलु ाई आदेश पचाय िडा गरी धमधसल संलग्न रात न ु पनेछ।\n\n(४) उपदफा (१) र (२) मा लेत्तिएको व्र्त्ति बािेक अन्र् व्र्त्तिले सरुु\nअदालतमा िरौट िा जमानत जम्मा गरेको रिेछ िने त्र्स्तो िरौट िा जमानत रकमको\nपन्र प्रधतशत थप िरौट िा जमानत जम्मा गरी पनु रािेदन गन य सक्नेछ।\nतर सरुु अदालतले िरौट िा जमानत नरािेको िा सफाइ ठदई पनु रािेदन सन्ु ने\nअदालतले कै द गरेकोमा कै द बापतको रकम जम्मा गरी पनु रािेदन गन य सक्नेछ।\n(५) उपदफा (४) बमोत्तजम िरौट िा जमानत नठदने व्र्त्तिलाई कै द सजार्\nिएको रिेछ िने धनजले त्र्स्तो सजार् बापत कै दमा बसेर मात्र पनु रािेदन गन य\nसक्नेछ।\n(६) उपदफा (२) िा (४) बमोत्तजमको िरौट िा जमानत ठदन नसकी कै दमा\nबसी पनु रािेदन ठदने व्र्त्तिको पनु रािेदन उपर त्र्स्तो पनु रािेदन दताय िएको धमधतले\n सशु ासन प्रििनय तथा सािजय धनक सेिा प्रिाि सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८१ द्वारा\nसंशोधित।\n104\nwww.lawcommission.gov.np\n\nएक िषधयित्र फै सला िनु नसके मा सम्बत्तन्ित पनु रािेदन सन्ु ने अदालतले धनजलाई त्र्स्तो\nअिधिपधछ कै दबाट छाडी ताररिमा रािी पपु िय\n\nगन य सक्नेछ ।\n(७) उपदफा (६) बमोत्तजमको अिधिधित्र फै सला गन य नसवकएमा त्र्स्तो\nअदालतले कारण िलु ाई पनु रािेदन सन्ु ने अदालतलाई त्र्सको जानकारी गराउन ु पनेछ।\n(८) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन, -\n(क) मद्दु ाको कारबािीको धसलधसलामा थनु ामा िा कै दमा परी फै सला\nबमोत्तजमको सजार् ििु ान गरी सके को व्र्त्ति िए पनु रािेदन\nगनकय ो लाधग कै दमा बस्न िा िरौट िा जमानत ठदन पने छैन,\n(ि) पनु रािेदन गरेको कारणले मात्र कुनै व्र्त्तिलाई फै सला बमोत्तजम\nिएको सजार्िन्दा बढी िनु े गरी कै दमा रात्तिने छैन।\n\n(९) पररच्छेद-७ बमोत्तजम िरौट िा जमानत ठदने व्र्त्तिको िकमा धनिेदन\nठदँदा िा पनु रािेदन गदाय त्र्स्तो िरौट िा जमानतबाट पगु ेसम्म सोिी िरौट िा\nजमानतलाई र्स दफाको प्रर्ोजनका लाधग िरौट िा जमानत कार्म गन य सवकने छ।\n\n(१०) .............\n(११) मद्दु ाको कारबािीको धसलधसलामा पनु रािेदन गने व्र्त्ति बािेक अरु\nकसैको सम्पत्ति िरौट िा जमानत रिेकोमा त्र्स्तो व्र्त्तिको मञ् जरु ीविना त्र्स्तो\nसम्पत्तिलाई र्स दफाको प्रर्ोजनको लाधग िरौट िा जमानत कार्म गन य सवकने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३८", "title": "धमधसल त्तझकाउनाःे (१) दफा १३५ को उपदफा (३) बमोत्तजम धमधसल प्राप् त िएकोमा", "content": "बािेक पनु रािेदन दताय िएपधछ पनु रािेदन सन्ु ने अदालतले र्थासम्िि चाँडो सम्बत्तन्ित\nअदालतलाई त्र्स्तो मद्दु ाको धमधसल पिाउन आदेश ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम आदेश प्राप्त िएको धमधतले तीन ठदनधित्र सम्बत्तन्ित\nअदालतले धमधसल पनु रािदे न सन्ु ने अदालतमा पिाइठदन ु पनेछ।\n सशु ासन प्रििनय तथा सािजय धनक सेिा प्रिाि सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८१ द्वारा\nसंशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n105\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१३९", "title": "पनु रािदे नको सनु िु ाईको ताररि तोक्नाःे दफा १३५ को उपदफा (३) िा दफा १३८", "content": "बमोत्तजम धमधसल प्राप् त िएपधछ पनु रािेदन सन्ु न े अदालतले पनु रािेदनको सनु िु ाई िनु े\nताररि तोक्न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४०", "title": "पनु रािदे नको सनु िु ाईाः (१) तल्लो अदालतबाट धमधसल प्राप्त िएको धमधतले छ मविनाधित्र", "content": "पनु रािेदन सन्ु ने अदालतले पनु रािेदनको सनु िु ाई गररसक्न ु पनेछ।\n(२) उपदफा (१) बमोत्तजम पनु रािेदन सनु िु ाई गदाय तल्लो अदालतले गरेको\nधनणर्य मनाधसब िई तात्तत्िक फरक पने नदेत्तिएमा पनु रािेदन सन्ु ने अदालतले सोको\nकारण िलु ाई पनु रािेदन त्तजवकर अस्िीकृ त गन य सक्नेछ।\n\n(३) उपदफा (१) बमोत्तजम सनु िु ाइ गदाय तल्लो अदालतबाट िएको धनणर्य\nफरक पन य सक्ने देत्तिएमा त्र्सको कारण िलु ाई पनु रािेदन सन्ु ने अदालतले सनु िु ाइको\nलाधग प्रत्र्थी त्तझकाउने आदेश गनेछ।\n\n(४) उपदफा (३) बमोत्तजम प्रत्र्थी त्तझकाउने आदेश िएमा पनु रािेदन सन्ु ने\nअदालतले पनु रािेदन पत्रको प्रधतधलवप साथै रािी प्रत्र्थीको नाउँमा बाटोको म्र्ादबािेक\nपन्र ठदनधित्र उपत्तस्थत िनु म्र्ाद जारी गन यु पनेछ।\n\n(४क) उपदफा (४) मा जनु सकु ै कुरा लेत्तिएको िए तापधन पनु रािेदन सन्ु ने\nअदालतले चािेमा उपदफा (१) बमोत्तजमको म्र्ाद आफैँ ले िा शरुु मद्दु ा फै सला गने\nअदालत माफय त ् र्स संविता बमोत्तजमको रीत पर्यु ाई तामेल गन य सक्नेछ।\n\n(५) उपदफा (४) बमोत्तजमको म्र्ाद पाएको व्र्त्तिले अदालतले तोके को\nअिधिधित्र पनु रािेदनको त्तजवकर िण्डन गरी प्रधतरिा गन य धलत्तित प्रधतिाद पेश गन य\nसक्नेछ।\n\n(६) उपदफा (५) बमोत्तजम अदालतमा पेश गने धलत्तित प्रधतिाद अनसु ूची-४६\nमा उत्तल्लत्तित ढाँचा बमोत्तजम िनु ेछ।\n(७) उपदफा (३) बमोत्तजम सनु िु ाई गरेपधछ पनु रािेदन उपर अदालतले धनणर्य\nगन यु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n106\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४१", "title": "प्रत्र्थी अनपु त्तस्थत िएमा पनु रािदे नको एकतफी सनु िु ाई िनु ाःे (१) दफा १४० को", "content": "उपदफा (३) बमोत्तजम ठदइएको सूचनाको म्र्ादधित्र प्रत्र्थी उपत्तस्थत निएमा पनु रािेदन\nसन्ु ने अदालतले पनु रािेदनको धनणर्य को लाधग कम्तीमा पन्र ठदन पधछको ताररि तोकी\nत्र्स्तो ताररिको ठदन पनु रािेदनको सनु िाई गरी धनणर्य गन य सक्नेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन प्रत्र्थीले दफा १४०\nको उपदफा (३) बमोत्तजम ठदइएको सूचनाको म्र्ादधित्र उपत्तस्थत िनु नसके को कुन ै\nमनाधसब कारण देिाई उपदफा (१) बमोत्तजम तोवकएको ताररि अगािै धनिेदनपत्र ठदएमा\nर त्र्स्तो कारण मनाधसब देत्तिएमा अदालतले धनजको म्र्ाद थामी उपदफा (१) बमोत्तजम\nतोवकएको ताररिको ठदन धनजलाई उपत्तस्थत िनु े आदेश ठदई पनु रािेदन उपरको सनु िु ाई\nगरी मद्दु ाको धनणर्य गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४२", "title": "ताररिमा बस्न नपनेाः (१) पनु रािेदनको कारबािीको धसलधसलामा ताररिमा बस्न नचािेमा", "content": "पनु रािेदक िा प्रत्र्थीले सोिी व्र्िोराको धनिेदन अदालतमा ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम धनिेदन परेकोमा पनु रािेदक िा प्रत्र्थी िोजेको\nबेलामा उपत्तस्थत िनु े कागज गराई अदालतले धनजको ताररि टुटाई ठदन सक्नेछ।\nतर ताररिमा नरिेको पनु रािेदक िा प्रत्र्थीले चािेमा पनु रािेदनको सनु िु ाईको\nलाधग तोवकएको ताररिका ठदन उपत्तस्थत िनु सक्नछे ।\n(३) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन पनु रािेदन सनु िु ाई\nिँदु ाका बित पनु रािेदन उपर के िी कुरा बझ्ु न ु पने िा कुनै प्रमाण दािेल गराउन ु पने\nिन् न े अदालतलाई लागेमा त्र्स्तो अिस्थामा पनु रािेदक िा प्रत्र्थीलाई त्तझकाई ताररिमा\nरात न सवकनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४३", "title": "पनु रािदे क िा प्रत्र्थीलाई ठदइन े सूचना िा आदेश समाह्वान सरि तामेल गररनाःे दफा", "content": "१४० िा १४२ बमोत्तजम पनु रािेदक िा प्रत्र्थीलाई अदालतले ठदने सूचना िा आदेश\nपररच्छेद-६ बमोत्तजम समाह्वान सरि तामेल गररनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४४", "title": "पनु रािदे न सन्ु न े अदालतको अधिकाराः (१) र्स पररच्छेद बमोत्तजम पनु रािेदन उपर", "content": "सनु िु ाई गदाय पनु रािेदन सन्ु ने अदालतलाई देिार् बमोत्तजमको अधिकार िनु ेछाः-\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n107\nwww.lawcommission.gov.np\n(क) तल्लो अदालतको फै सला सदर िा बदर गने िा उल्टी िा के िी\nउल्टी गने,\n(ि) तल्लो अदालतले कसूरदारलाई तोके को सजार्को मात्रा घटाउन े\nिा बढाउने िा सजार्मा पररितनय गने,\n(ग) बझ्ु न ु पने प्रमाण नबझु ी फै सला िएको रिेछ िन े त्र्स्तो प्रमाण\nआपैmले बझ्ु ने िा बझ्ु न तल्लो अदालतलाई आदेश ठदने,\n(घ) मद्दु ामा ििर गन यु पने विषर्मा ििर निएको िए त्र्स्तो विषर्मा\n\nआफै ले ििर गने िा ििर गन य तल्लो अदालतमा पिाउने,\n\n(ङ) तल्लो अदालतको फै सलामा आनषु वङ्गक िा प्रासवङ्गक पररितनय\nगने।\n(२) तल्लो अदालतले गरेको फै सला उपर कुनै िास कसूरदारको िा प्रधतिादीको\nमात्र पनु रािेदन परेको रिेछ र त्र्स्तो पनु रािेदनको धनणर्य गदाय पनु रािेदन नगने\nकसूरदार िा प्रधतिादीको िकमा तल्लो अदालतको फै सला फरक पने देत्तिएमा पनु रािेदन\nसन्ु ने अदालतले सोको कारण िलु ाई त्र्स्तो कसूरदार िा प्रधतिादीको िकमा पधन\nउपदफा (१) मा उत्तल्लत्तित अधिकारको प्रर्ोग गरी कानून बमोत्तजम फै सला गन य\nसक्नेछ।\n(३) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन पनु रािेदन सन्ु न े\nअदालतले तल्लो अदालतलाई िएको अधिकार आिश्र्कता अनसु ार प्रर्ोग गन य\nसक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४५", "title": "सािकाः (१) कुनै अदालतबाट कुनै अधिर्िु लाई बीस िष य िा बीस िषिय न्दा बढी िा", "content": "जन्मकै दको सजार् िनु े गरी फै सला िएकोमा त्र्सरी फै सला िएको धमधतले पैँतीस\nठदनधित्र त्र्स्तो अदालतले धमधसल सवित पनु रािेदन सन्ु ने अदालतमा सािक पेश गन यु\nपनेछ।\n\n(१क) प्रचधलत कानून बमोत्तजम जन्मकै द गन यु पने मद्दु ाको अधिर्िु ले कसूर\nगरेको कुरामा अदालतमा साधबत िएकोमा त्र्स्तो कसूर गदायको पररत्तस्थधतलाई विचार\nगदाय जन्मकै दको सजार् गन यु न्र्ार्को रोिमा बढी पने िई न्र्ार्ािीशले कारण सवित\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n108\nwww.lawcommission.gov.np\nघटी सजार्को प्रस्ताि गरी रार् सवित फै सला गरेकोमा त्र्सरी फै सला िएको धमधतले\nपैंतीस ठदनधित्र धमधसल सवित पनु रािेदन सन्ु ने अदालतमा रार् पेश गन यु पनेछ।\n(२) उपदफा (१) बमोत्तजम सािक पेश िएकोमा पनु रािेदन सन्ु ने अदालतले पधन\nत्र्स्तो अधिर्िु लाई बीस िष य िा बीस िषिय न्दा बढी िा जन्मकै दको सजार् गने ििराई\nफै सला गरेमा सिोच् च अदालतमा सािक पेश गन यु पनेछ।\n\n(३) उपदफा (१क) बमोत्तजम रार् पेश िएकोमा पनु रािेदन सन्ु ने अदालतले\nत्र्सरी गररएको घटी सजार्लाई सदर गरेकोमा सिोच् च अदालतमा रार् पेश गन यु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४६", "title": "सािक फै सला उपर पनु रािदे न लाग्नाःे दफा १४५ बमोत्तजम सािक पेश िनु े गरी िएको", "content": "फै सलामा त्तचि नबझ्ु ने पिले त्र्स्तो फै सला उपर पनु रािेदन गन य सक्नेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४७", "title": "पनु रािदे न लाग्न े म्र्ादसम्म सािक फै सला गन य निनु ाःे (१) दफा १४५ बमोत्तजम", "content": "सािक पेश िएको मद्दु ामा पनु रािेदन लाग्ने म्र्ादसम्म सािकको फै सला गन य िँदु ैन।\n(२) उपदफा (१) बमोत्तजमको म्र्ादधित्र पनु रािेदन परेमा सािकको लगत कट्टा\nगरी पनु रािेदनको रोिबाट मद्दु ाको सनु िु ाई गन यु पनेछ।\nतर सजार् पाउने व्र्त्तििरुमध्र्े कुनै व्र्त्तिको मात्र पनु रािेदन परेकोमा\nपनु रािेदन नगने व्र्त्तिका िकमा पधन सोिी पनु रािेदन कै रोिबाट धनणर्य गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४८", "title": "सािक पशे गदाकय ो कार्वयिधिाः (१) दफा १४५ बमोत्तजम कुनै अदालतले कुनै मद्दु ामा", "content": "सािक पेश गदाय त्र्स्तो मद्दु ाको धमधसल समेत साथै पिाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम सािक पेश गरेको मद्दु ामा अधिर्िु थनु ामा रिेको\nिए धनज थनु ामा रिेको धमधत, धनज रिेको कारागारको नाम तथा अधिर्िु फरार रिेको\nिा थनु ाबाट िागेको िए सो समेत िलु ाई पेश गन यु पनेछ।\n(३) सािक सनु िु ाई सम्बन्िी अन्र् कार्वयिधि पनु रािेदनको सनु िु ाई सरि\nिनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१४९", "title": "सािक िेने अदालतको अधिकाराः (१) सािक िेने अदालतले पनु रािेदन सन्ु न े अदालतलाई", "content": "िए सरिको अधिकार प्रर्ोग गन य सक्नेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n109\nwww.lawcommission.gov.np\n(२) सािक जाँच गदाय तल्लो अदालतको फै सलाको इन्साफ नधमली कुनै\nपररितनय िनु सक्ने देत्तिएमा पन्र ठदनको म्र्ाद ठदई सम्बत्तन्ित पििरुलाई त्तझकाउन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५०", "title": "पनु रािदे न र सािक फै सलााः पनु रािेदन फै सला गदाय अनसु ूची-४७ बमोत्तजमको ढाँचामा र", "content": "सािक फै सला गदाय अनसु ूची-४८ बमोत्तजमको ढाँचामा गन यु पनेछ।\nतर पनु रािेदन र सािकको एउटै फै सला गन यु पने अिस्थामा अनसु ूची-४७\nबमोत्तजमको ढाँचामा गन यु पनेछ।\nपररच्छेद-१५\nफै सला कार्ान्य िर्न सम्बन्िी व्र्िस्था", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५१", "title": "सजार्को लगत िडा गन यु पनेाः (१) अदालतबाट कुनै मद्दु ाको फै सला िए पधछ सम्बत्तन्ित", "content": "अदालतले त्र्स्तो फै सला बमोत्तजम लागेको दण्ड, जररबाना िा ििरेको विगो िा\nिधतपूधतकय ो लगत तर्ार गन यु पनेछ।\n(२) पनु रािदेन सन्ु ने अदालतबाट कुनै व्र्त्ति कसूरदार ििरी िा तल्लो\nअदालतको फै सला उल्टी िई िा बदर िई कसूरदार ििरेकोमा त्र्सको लगत िडा गरी\nकार्ायन्िर्न गन य सम्बत्तन्ित त्तजल्ला अदालतमा फै सलाको प्रधतधलवप पिाउन ु पनेछ।\n(३) उपदफा (१) िा (२) बमोत्तजम लगत िडा गरेपधछ सम्बत्तन्ित अदालतले\nफै सला कार्ायन्िर्न गनेछ र फै सला कार्ायन्िर्नको लाधग कुनै काम कुनै धनकार्ले गन यु\nपने रिेछ िने सम्बत्तन्ित धनकार्लाई त्र्स्तो काम गन य आदेश गनेछ।\n(४) उपदफा (३) बमोत्तजम आदेश गदाय कै द सजार् पाउने व्र्त्ति अदालतमा\nउपत्तस्थत रिेको िए धनजलाई अदालतले कारागारमा चलान गरी पिाउन ु पनेछ र\nउपत्तस्थत िएको रिेनछ िा थनु ा िा कै दमा पधन बसेको रिेनछ िने धनजलाई पक्राउ गरी\nकारागारमा बझु ाउने गरी सम्बत्तन्ित प्रिरी कार्ायलर्लाई अनसु ूची-४९ बमोत्तजमको\nढाँचामा आदेश पिाउन ु पनेछ।\n\n(५) फै सला कार्ायन्िर्न सम्बन्िमा कुनै ठद्ववििा िएमा कारागार कार्ायलर्ले\nसम्बत्तन्ित त्तजल्ला अदालतमा लेिी पिाउन ु पनेछ र त्तजल्ला अदालतबाट धनकासा िए\nबमोत्तजम गन यु पनेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n110\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५२", "title": "फै सला कार्ान्य िर्न गने धनकार्ाः (१) मद्दु ाको फै सला जनु सकु ै तिको अदालतबाट िएको", "content": "िए पधन त्र्स्तो मद्दु ामा िएको फै सलाको कार्ायन्िर्न अधिर्ोगपत्र िा उजरु ी दार्र िएको\nत्तजल्ला अदालतले गनेछ।\n(२) पनु रािेदन सन्ु ने अदालतले शरुु कारबािी र वकनारा गरेको मद्दु ाको फै सला\nकार्ायन्िर्न समेत सम्बत्तन्ित त्तजल्ला अदालतले गनेछ।\n(३) र्स दफामा अन्र्न्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन प्रधतिादीको सङ्खतर्ा\nधनजिरुको बसोबास िा धनजको सम्पत्तिको अित्तस्थधतको कारण फै सला कार्ायन्िर्न गने\nत्तजल्ला अदालत र्वकन िनु नसके मा पनु रािेदन सन्ु ने अदालतले तोके को त्तजल्ला\nअदालतले मद्दु ाको फै सला कार्ायन्िर्न गनेछ।\n(४) धनर्धमत अदालत बािेक अन्र् न्र्ावर्क धनकार्बाट िएको फै सलाको\nकार्ायन्िर्न सम्बत्तन्ित धनकार्ले गनेछ।\n(५) उपदफा (४) मा जनु सकु ै कुरा लेत्तिएको िए तापधन फै सला कार्ान्य िर्न\nगने सम्बन्िमा कानूनमा अन्र्था व्र्िस्था निएकोमा सम्बत्तन्ित त्तजल्ला अदालतले र्सै\nऐन बमोत्तजम फै सला कार्ायन्िर्न गनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५३", "title": "फै सला कार्ान्य िर्न स्थधगत िनु ाःे (१) देिार्को अिस्थामा अदालतले फै सला कार्ायन्िर्न", "content": "स्थगन गन यु पनेछाः-\n(क) कानून बमोत्तजम पनु रािेदन लाग्न सक्ने मद्दु ामा पनु रािेदन परेको\nिए पनु रािेदनको रोिबाट मद्दु ाको अत्तन्तम वकनारा निएसम्म िा\nपनु रािेदन नपरेकोमा पनु रािेदन लाग्न सक्न े म्र्ाद ििु ान\nनिएसम्म,\n(ि) कानून बमोत्तजम सािक पेश िनु े मद्दु ा िए पेश िएको सािकको\nधनकासा निएसम्म।\n(२) उपदफा (१) को िण्ड (क) बमोत्तजम पनु रािेदन परेकोमा पनु रािेदन गने\nपिले पनु रािेदन गरेको व्र्िोराको धनिेदन सम्बत्तन्ित अदालतमा ठदन ु पनेछ।\n(३) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन र्स ऐनमा अन्र्था\nव्र्िस्था िएकोमा बािेक कुनै कसूरदारलाई कै दको सजार् िनु े ििरी फै सला िएकोमा\nत्र्स्तो कसूरदारलाई तत्काल कै दमा पिाउन ु पनेछ।\n111\nwww.lawcommission.gov.np\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५४", "title": "कै दमा रातन ु पनेाः (१) दफा १५१ को उपदफा (४) बमोत्तजम अदालतमा उपत्तस्थत", "content": "कसूरदारको िकमा कै दी पूजी जारी िई आएपधछ र फरारको िकमा समेत कसूरदार\nप्रिरी कार्ायलर्बाट पक्राउ िई अदालतमा पेश गरी धनजको नाममा कै दी पूजी जारी िई\nआएपधछ कारागार कार्ायलर्ले त्र्स्तो कसूरदारलाई कानून बमोत्तजम कै दमा रातन ु\nपनेछ।\nतर अिार िष य उमेर नपगु ेको बालबाधलका कसूरदार ििररएकोमा धनजलाई नपे ाल\nसरकारले व्र्िस्था गरेको छुट्टै बाल सिु ार गिृ िा र्स्तै अन्र् गिृ मा रात न ु पनेछ।\n(२) उपदफा (१) बमोत्तजम कै दमा रातदा कसूरदार कविलेदेत्ति थनु ामा रिेको िा\nपक्राउ परेको िो धनजको कै द अिधि कविले ििु ान िनु े िो िन् ने कुरा समेतको अधिलेि\nकारागार कार्ायलर्ले तर्ार गरी अद्यािधिक रुपमा रात न ु पनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५५", "title": "कै द बापत रकम धतन य सवकनाःे (१) पविलो पटक कसरु दार ििरी एक िष य िा एक", "content": "िषिय न्दा कम कै दको सजार् िएको कसरु दारले कै दको सट्टा त्र्स्तो कै द बापत रकम\nधलई कै दबाट छाधडठदन धनिेदन ठदएमा अदालतले त्र्स्तो रकम धलई कै दमा बस्न ु नपने\nगरी आदेश ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको आदेश ठदनअु त्तघ त्र्स्तो व्र्त्तिलाई कुनै प्रकारको\nकसूर नगरी राम्रो आचरण पालन गनेछु िन् ने व्र्िोराको कागज गराउन ु पनेछ।\n(३) उपदफा (१) बमोत्तजम रकम धतरी कै द बस्न ु नपने गरी आदेश िएको\nकसूरदारले कै द बापत रकम बझु ाउँदा एक ठदन कै दको तीन सर् रुपैर्ाँका दरले रकम\nबझु ाउन ु पनेछ।\n(४) उपदफा (१) बमोत्तजम कै द बस्न छुट िएको व्र्त्तिले त्र्सरी छुटेको\nधमधतले तीन िषधयित्र कै दको सजार् िनु े कुनै कसूर गरेमा धनजलाई पविले िएको फै सला\nबमोत्तजमको कै द समेत थपी सजार् कार्ायन्िर्न गन यु पनेछ।\n(५) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन एक िष य िा एक\nिषिय न्दा कम कै दको सजार् पाई थनु ा िा कै दमा रिे बसेको विदेशी नागररकले कै दको\nसट्टा रकम धतरी कै दबाट छुटकारा पाउन धनिेदन ठदएमा अदालतले दफा १५९ को\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n सशु ासन प्रििनय तथा सािजय धनक सेिा प्रिाि सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८१ द्वारा\nसंशोधित।\n112\nwww.lawcommission.gov.np\nउपदफा (४) मा उल्लेि िएका कसूर बािेक अन्र् कसूरका कसूरदारलाई कै द सजार्\nबापत प्रधत ठदन पाँचसर् रुपैर्ाँका दरले िनु आउन े रकम एकमष्टु तोकी त्र्स्तो रकम\nबझु ाएमा बाकी अिधि कै दमा बस्न ु नपने गरी आदेश ठदन सक्नेछ।\n(६) उपदफा (५) बमोत्तजम आदेश ठदँदा अदालतले त्र्स्तो व्र्त्तिलाई सात\nठदनधित्र नेपाल बाविर पिाउने आदेश ठदन ु पनेछ र अध्र्ागमन कार्ायलर्ले अदालतको\nआदेश बमोत्तजम त्र्स्तो व्र्त्तिलाई नेपाल बाविर पिाउन ु पनेछ।\n(७) उपदफा (३) र (५) बमोत्तजम प्राप् त िएको रकमको पचास प्रधतशत रकम\nकानून बमोत्तजम िडा िएको पीधडत राित कोषमा जम्मा गन यु पनेछ।\n(८) र्स दफा बमोत्तजम रकम धतरेमा कसूरदारले कै द ििु ान गरेको माधननेछ।\n(९) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन र्स दफा बमोत्तजम\nकै दबाट छुटेको व्र्त्तिको कै दको लगत कै द ििु ान िनु े अिधिसम्मका लाधग कार्म\nरिनेछ र धनजले उपदफा (२) र (४) प्रधतकू लको आचरण िा कसूर गरेमा अदालतले\nजनु सकु ै बित र्स दफा बमोत्तजमको आदेश रद्द गन य सक्नेछ।\n(१०) उपदफा (९) बमोत्तजम आदेश रद्द िएकोमा त्र्स्तो कसूरदारले धनजलाई\nिएको पूरै सजार् कै दमा बसी ििु ान गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५६", "title": "सम्पत्ति रोक्क ा रातन ु पनेाः (१) दफा १५१ को उपदफा (४) बमोत्तजम पक्राउ पूजी जारी", "content": "गररएको व्र्त्तिको सम्पत्ति पविले नै रोक् का नरिेको िएमा िा धनज पक्राउ िनु नसके मा\nसम्बत्तन्ित प्रिरी कार्ायलर्ले धनजको अंशिकको सम्पत्ति रोक् का रात नको लाधग त्र्स्तो\nसम्पत्तिको वििरण िलु ाई अदालत समि प्रधतिेदन पेश गन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम प्रधतिेदन पेश िएमा सम्बत्तन्ित अदालतले त्र्स्तो\nव्र्त्तिको िकको सम्पत्ति रोक् का गन य सम्बत्तन्ित मालपोत कार्ायलर् िा अन्र् धनकार् िा\nसंस्थालाई आदेश ठदनेछ।\n(३) उपदफा (२) बमोत्तजम सम्पत्ति रोक् का रातदा रोक् का रात न ु पनेिन्दा बढी\nसम्पत्ति रोक् का िएमा त्र्स्तो व्र्त्तिले बढी रोक् का िएको सम्पत्ति फुकुिा गन य सम्बत्तन्ित\nअदालतमा धनिेदन ठदन सक्नेछ।\n(४) उपदफा (३) बमोत्तजम धनिेदन परेमा र त्र्स्तो धनिेदन जाँचबझु गदाय\nत्र्सरी बढी सम्पत्ति रोक् का रिेको देत्तिन आएमा त्र्सरी बढी रोक् का रिेको िदसम्मको\n113\nwww.lawcommission.gov.np\nसम्पत्ति अदालतले फुकुिा गन य सम्बत्तन्ित मालपोत कार्ायलर् िा धनकार् िा संस्थालाई\nआदेश ठदन सक्नेछ र त्र्सरी आदेश ठदएकोमा त्र्स्तो कार्ायलर् िा संस्थाले त्र्स्तो\nसम्पत्ति फुकुिा गन यु पनेछ।\n(५) कसूरदारले अदालतको फै सला बमोत्तजम धबगो, िधतपूधत य िा अन्र् कुनै रकम\nधतनपयु ने रिेछ िने उपदफा (१) बमोत्तजम रोक् का रिेको सम्पत्तिबाट र्स पररच्छेद\nबमोत्तजम त्र्स्तो रकम िराई ठदई बाँकी रिेको सम्पत्ति मात्र रोक् का गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५७", "title": "सम्पत्ति धललाम गन य सवकनाःे (१) दफा १५१ को उपदफा (४) बमोत्तजम पक्राउ गने", "content": "आदेश िएको धमधतले छ मविनासम्ममा पधन कसूरदार पक्राउ िनु नसके मा फै सला\nबमोत्तजम बझु ाउन ु पने जररबाना िा िधतपूधतकय ो रकम दफा १५६ बमोत्तजम रोक् का रिेको\nसम्पत्ति नगद िए सम्बत्तन्ित धनकार् िा संस्थाबाट प्राप् त गरी र अन्र् चल िा अचल िए\nधललाम धबक्री गरी जररबाना िा सरकारी धबगो बापतको रकम संत्तचत कोषमा दात्तिला\nगन यु पनेछ र त्र्सरी दात्तिला गरी बाँकी रिेमा िधतपूधत य िराउन ु पने िए िधतपूधत य िराई\nबाँकी रकम धनजको िकिालालाई वफताय गन यु पनेछ।\n(२) र्स ऐन बमोत्तजम लगत कट्टा िनु िु न्दा पविले कसूरदार पक्राउ िएमा र\nधनजले आफू लाई लागेको जररबाना विगो िा िधतपूधत य बापतको रकम नगदै बझु ाउन\nचािेमा दफा १५६ बमोत्तजम रोक् का रिेको सम्पत्ति धललाम धबक्री िई नसके को िए\nत्र्स्तो सम्पत्ति रोक् का रातदा िएको िच य असूल गरी र धललाम धबक्री िै सके कोमा\nरोक् का रातदा र धललाम धबक्री गदाय िएको िचिय रु कटाई धललाम धबक्रीबाट प्राप् त\nिएको रुपैर्ाँ धनजलाई वफताय ठदई कै द सजार् कार्ान्य िर्न गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५८", "title": "सजार् पाएको व्र्त्तिको मत्ृ र् ु िएमा सजार् धमनािा िनु ाःे (१) अदालतबाट कसूरदार ििरी", "content": "सजार् पाएको व्र्त्तिको मत्ृ र् ु िएमा मत्ृ र् ु िँदु ाका बितसम्म कार्ायन्िर्न िनु बाँकी\nरिेको सम्पूण य कै द सजार् िा जररबाना स्िताः धमनािा िनु ेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन सरकारी िा धनजी\nधबगो, िधतपूधत य िा अन्र् कुनै रकम िन यु पने व्र्त्तिको त्र्स्तो धबगो, िधतपूधत य िा रकम\nिराउन ु अगािै मत्ृ र् ु िएमा धनजको िकको सम्पत्तिबाट असलु उपर िनु ेसम्म र्स ऐन\nबमोत्तजम असलु उपर गरी िराई ठदन ु पनेछ।\n114\nwww.lawcommission.gov.np\n(३) उपदफा (२) बमोत्तजम धबगो, िधतपूधत य िा रकम िराउँदा त्र्स्तो व्र्त्तिको\nसम्पत्तिले िामेसम्म क्रमशाः सरकारी धबगो, िधतपूधत,य धनजी िधतपूधत य र धबगोलाई\nप्राथधमकता ठदई क्रमशाः िराउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१५९", "title": "सजार् माफी ठदन सवकनाःे (१) अदालतको फै सला बमोत्तजम िेवकएको सजार् पाएको", "content": "व्र्त्तिले सो सजार् माफी पाउन, त्र्सलाई मलु तिी रात न, पररितनय गन य िा कम गन य गिृ\nमन्त्रालर् माफय त राष्ट्रपधत समि धनिेदन ठदन सक्नछे ।\n(२) उपदफा (१) बमोत्तजम धनिेदन ठदँदा जनु अदालतको फै सलाबाट धनिेदकले\nसजार् पाएको िो सो अदालतको फै सलाको प्रधतधलवप संलग्न गन यु पनेछ।\n(३) उपदफा (१) बमोत्तजमको धनिेदन आिश्र्क कारबािीको लाधग राष्ट्रपधतले\nगिृ मन्त्रालर्मा पिाएमा सो मन्त्रालर्ले देिार्का कुरािरु विचार गरी धनजलाई िएको\nसजार् माफी गने, मल्ु तिी रात ने, पररितनय गने िा कम गने सम्बन्िमा धनणर्य को लाधग\nनेपाल सरकार समि पेश गन य सक्नेछाः-\n(क) कसूरको प्रकृ धत र कसूर गदायको अिस्था,\n(ि) कसूरदारको उमेर तथा शारीररक अिस्था,\n(ग) कसूरदारलाई तोवकएको सजार्को िद,\n(घ) कसूरदारले सो सजार् पाउनअु त्तघ कुनै कसूर गरी कै दको सजार्\nपाएको िा नपाएको िा पाएको िए त्र्स्तो कसूरको प्रकृ धत र\nधनजले िोगेको सजार्,\n(ङ) कसूरदार थनु ामा रिेको िा नरिेको।\n(४) उपदफा (३) मा जनु सकु ै कुरा लेत्तिएको िए तापधन देिार्का कसूरका\nकसूरदारलाई िएको सजार् माफी गने, मल्ु तिी रात ने, पररितनय गने िा कम गने कारबािी\nगन य सवकने छैनाः-\n(क) भ्रष्टाचार,\n(ि) र्ातना,\n(ग) जबरजस्ती करणी,\n(घ) क्रु र तथा अमानिीर् तररकाले िा धनर्न्त्रणमा धलई ज्र्ान मारेको,\n115\nwww.lawcommission.gov.np\n\n(घ१) तेजाब िा अन्र् ज्िलनशील पदाथ य प्रर्ोग गरी ज्र्ान मारेको िा\nअङ्गिङ्ग गरेको िा शारीररक िधत पर्ु र् ाएको,\n(ङ) जाधत ित्र्ा,\n(च) विष्फोटक पदाथ,य\n(छ) अपिरण, शरीर बन्िक िा व्र्त्ति बेपिा,\n(ज) मानि बेचवििन तथा ओसारपसार,\n(झ) सम्पत्ति शद्धु ीकरण, र\n(ञ) तीन िषिय न्दा बढी कै द सजार् िनु े लागूऔषिको ओसारपसार िा\nकारोबार।\n(५) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै अदालतमा\nपनु रािेदन, सािक जाँच िा पनु रािलोकन िा मद्दु ा दोिो¥र्ाउने अिस्थाको रोिमा\nविचारािीन रिेको िा जनु अदालतको फै सलाबाट सजार् तोवकएको िो त्र्स्तो सजार्\nअत्तन्तम िई नसके को अिस्थामा गिृ मन्त्रालर्ले उपदफा (३) बमोत्तजमको कारबािी गन य\nसक्ने छैन।\n(६) उपदफा (३) बमोत्तजम धनणर्य गनअयु त्तघ नपे ाल सरकारले कानून बमोत्तजम\nस्थावपत प्र्ारोल तथा प्रोिशे न बोडकय ो परामश य धलन सक्नेछ।\n(७) उपदफा (३) बमोत्तजम धनणर्य गदाय धनिेदकलाई िएको सजार् पूरै िा\nआंत्तशक रुपमा माफी िनु ु पने, त्र्सलाई मलु तिी रात न ु पने, पररितनय गन यु पने िा कम\nगन यु पने मनाधसब कारण देिेमा नेपाल सरकारले त्र्सको आिार िलु ाई आफ्नो रार्\nसवित राष्ट्रपधत समि धसफाररस गनेछ।\n(८) उपदफा (७) बमोत्तजम नेपाल सरकारबाट िएको धसफाररस बमोत्तजम कुन ै\nकसूरदारलाई िेवकएको सजार् राष्ट्रपधतबाट माफी िएमा, त्र्सलाई मलु तिी रात्तिएमा,\nपररितनय िएमा िा कम गररएमा नेपाल सरकारले त्र्सको सूचना सम्बत्तन्ित अदालतलाई\nठदन ु पनेछ।\n(९) उपदफा (८) बमोत्तजमको सूचना प्राप् त गरेपधछ सम्बत्तन्ित अदालतले सोिी\nबमोत्तजम सजार्को लगत कट्टा िा अद्याबधिक गन यु पनेछ।\n फौजदारी कसूर तथा फौजदारी कार्वयिधि सम्बन्िी केिी ऐन संशोिन गने ऐन, २०७९ द्वारा थप।\n116\nwww.lawcommission.gov.np\n(१०) र्स दफा बमोत्तजम राष्ट्रपधतबाट कुनै व्र्त्तिलाई िेवकएको सजार् माफी\nिएको, सजार् पररितनय िा कम िएको कारणले सम्बत्तन्ित अदालतको फै सला बदर िनु े\nछैन र त्र्स्तो व्र्त्तिले िोगी सके को सजार् िा ििु ानी गररसके को जररबाना िा\nधबगोलाई कुनै असर पने छैन।\n(११) उपदफा (३) र (७) बमोत्तजम प्रस्ताि िा धसफाररस गने प्रर्ोजनको लाधग\nनेपाल सरकारले आिश्र्क मापदण्ड बनाउन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६०", "title": "लगत कट्टा गन यु पनेाः (१) अदालतले दफा १५१ को उपदफा (१) िा (२) बमोत्तजम", "content": "िडा िएको लगत देिार्को अिस्थामा कारण िलु ाई कट्टा गन यु पनेछाः-\n(क) कसूरदारले र्स पररच्छेद बमोत्तजम कै द ििु ान गरेमा,\n(ि) कसूरदारले प्रचधलत कानून बमोत्तजम श्रम गरी कै द ििु ान गरेमा,\n(ग) कसूरदारको मत्ृ र् ु िई दफा १५८ बमोत्तजम कै द िा सजार्\nधमनािा िएमा,\n(घ) कसूरदारले प्रचधलत कानून बमोत्तजम सिु ार गिृ िा सामदु ावर्क\nके न्द्रमा कै द ििु ान गरेमा िा सामदु ावर्क सेिा गरी कै द ििु ान\nगरेमा,\n\n(ङ) कसूरदारले दफा १५९ बमोत्तजम ........ सजार् माफी पाएमा,\n(च) कसूरदारले र्स पररच्छेद बमोत्तजम जररबाना िा विगो िा िधतपूधत य\nबापतको पूरै रकम बझु ाएमा, िा\n(छ) कसूरदारलाई लागेको कै द िा सजार् िा विगो िा िधतपूधत य\nबापतको रकम र्स पररच्छेद बमोत्तजम असलु गररएमा।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन कै दको सजार्\nतोवकएको िा प्रचधलत कानून बमोत्तजम जररबाना िा सरकारी धबगो िा अन्र् कुनै रकम\nबापत कै द बस्न ु पने व्र्त्ति देिार्को अिधिसम्म अदालतमा उपत्तस्थत निएमा,\nकारागारमा कै द बस्न नआएमा िा पक्राउ िनु नसके मा अदालतले धनजको िकमा िडा\nिएको कै दको लगत कट्टा गररठदन ु पनेछाः-\n(क) जन्मकै दको सजार् िएकोमा पचास िष,य\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n117\nwww.lawcommission.gov.np\n(ि) दश िषिय न्दा बढी कै द सजार् िएकोमा चालीस िष,य\n(ग) पाँच िषिय न्दा बढी दश िषसय म्म कै द सजार् िएकोमा तीस िष,य\n(घ) एक िषिय न्दा बढी पाँच िषसय म्म कै द सजार् िएकोमा बीस िष,य\n(ङ) एक िषसय म्मको कै द सजार् िएकोमा बाह्र िष।य\n(३) उपदफा (२) बमोत्तजम लगत कट्टा िएको व्र्त्ति त्र्स्तो अिधि ििु ान\nिएपधछ फे ला परेमा अदालतले धनजको िकमा लगत कट्टा निए सरि र्स पररच्छेद\nबमोत्तजम फै सला कार्ायन्िर्न गन यु पनेछ।\n(४) उपदफा (२) बमोत्तजम लगत कट्टा गदाय र्स ऐन बमोत्तजम धनजको सम्पत्ति\nरोक् का गररएको रिेछ िने त्र्स्तो सम्पत्ति जफत गरी धललाम धबक्री गरी प्राप् त रकम\nसंत्तचत कोषमा दात्तिला गन यु पनेछ।\n(५) र्स दफा बमोत्तजम सजार् ििु ान निएको कारणले लगत कट्टा िएको\nव्र्त्तिले त्र्स्तो लगत िेवकने गरी िएको फै सला बमोत्तजमको सजार् ििु ान नगरेसम्म\nप्रचधलत कानूनमा जनु सकु ै कुरा लेत्तिएको िए तापधन धनज कुनै पधन सािजय धनक\nजिाफदेिीको पदमा धनर्त्तुि िा मनोनर्न िनु , तोवकन िा धनिायत्तचत िनु अर्ोग्र् िएको\nमाधननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६१", "title": "थनु ामा बसेको अिधि कै दमा कट्टा िनु ाःे (१) अदालतबाट फै सला िँदु ा कसूरदार ििरी", "content": "कै दको सजार् पाएको व्र्त्ति अनसु न्िानको धसलधसलामा विरासत िा थनु ामा बसेको िए\nधनजलाई त्र्सरी थनु ामा बसेको अिधि फै सला बमोत्तजमको कै दमा कटाई बाँकी अिधिको\nलाधग मात्र कै द गन यु पनेछ।\n(२) कुनै कसूरदार अनसु न्िानको धसलधसलामा थनु ामा बसेकोमा धनजलाई कै दको\nसजार् निई जररबाना मात्र िनु े ििरेको िए धनज थनु ामा बसेको अिधिको एक ठदनको\nतीन सर् रुपैर्ाँको दरले विसाि गरी िनु आउने जम्मा रकम त्र्स्तो कसूरदारले बझु ाउन ु\nपने जररबानाको रकममा कट्टा गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६२", "title": "जररबानाको सजार्को कार्ान्य िर्नाः (१) दफा १५१ बमोत्तजम िडा िएको लगत अनसु ार", "content": "जररबाना धतन यु पने व्र्त्तिले जररबानाको रकम तत्काल बझु ाउन ु पनेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्तो व्र्त्तिले\nजररबाना तत्काल बझु ाउन नसकी त्र्स बापत कुनै सम्पत्ति जमानत ठदएमा अदालतले\n118\nwww.lawcommission.gov.np\nएक िषधयित्र त्र्स्तो रकम चिु ा िनु े गरी बढीमा तीन वकस्तामा जररबाना बझु ाउने आदेश\nठदन सक्नेछ।\n(३) उपदफा (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्सरी जररबाना िएको\nव्र्त्तिले पररच्छेद-७ िा दफा १३७ बमोत्तजम कुनै िरौट िा जमानत रािेको िए\nजररबानाको रकम त्र्स्तो िरौट िा जमानतबाट असूल गरी नपगु िए जधतको सम्बन्िमा\nमात्र वकस्तािन्दी रुपमा बझु ाउने आदेश ठदन ु पनेछ।\n(४) उपदफा (२) बमोत्तजम वकस्तािन्दीमा जररबाना रकम बझु ाउने व्र्िस्था\nिएकोमा िा मद्दु ाको कारबािीको धसलधसलामा कै द िा थनु ामा परी सजार् ििु ान\nगररसके कोमा िा पररच्छेद-७ िा दफा १३७ बमोत्तजम रात्तिएको िरौट िा जमानतबाट\n\nजररबानाको रकम असलु िनु े िएमा बािेक कसूरदारले जररबानाको रकम अत्तन्तम\nफै सला िएपधछ तत्काल निझु ाएमा अदालतले जररबाना बापत कै द गन य सम्बत्तन्ित\nकारागारको नाउँमा आदेश पिाउन ु पनेछ।\n(५) उपदफा (४) बमोत्तजम आदेश िएकोमा जररबाना नबझु ाउने कसूरदारले\nजररबानाको रकम के िी बझु ाई के िी बाँकी रािेकोमा िा मद्दु ाको धसलधसलामा कै द िा\nथनु ामा परी त्र्सरी कै द िा थनु ामा परेको अिधि जधत सजार् धमन्िा िनु े अिस्था िएमा\nसोसमेत कट्टा गरी जररबाना नबझु ाए बापत िनु े कै दको अिधि र जररबानाको कू ल\nरकमको अनपु ातमा मात्र बाँकी जररबाना बापत कै द गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६३", "title": "सरकारी धबगो िा अन्र् रकम सम्बन्िी व्र्िस्थााः (१) धबगो िराउने गरी फै सला िएकोमा", "content": "सरकारी धबगोलाई धनजी धबगोिन्दा प्राथधमकता ठदई िराई ठदन ु पनेछ।\nतर सरकारी धबगो िराइठदने गरी फै सला िनु िु न्दा पविले नै धनजी धबगो िराई\nठदने गरी कुनै फै सला िएको रिेछ िने सरकारी धबगोलाई प्राथधमकता ठदइने छैन।\n(२) फै सला बमोत्तजम िराउन ु पने सरकारी धबगो िा अन्र् कुनै रकम असूल\nनिएमा िा असलु िनु े अिस्था निएमा त्र्स्तो धबगो िा रकम िन यु पने कसूरदारको\nसम्पत्ति पविले नै रोक् का िएको रिेनछ िने फै सला िएपधछ र्थासम्िि चाडो रोक् का गन यु\nपनेछ।\n(३) उपदफा (१) बमोत्तजमको धबगो िा अन्र् रकम फै सला अत्तन्तम िएको\nधमधतले तीस ठदनधित्र कसूरदारले नबझु ाएमा धनजको उपदफा (२) बमोत्तजम रोक् का\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n119\nwww.lawcommission.gov.np\nिएको चल सम्पत्तिको िकमा त्र्स्तो सम्पत्ति रिेको धनकार् िा संस्थाबाट प्राप् त गरी र\nअचलको िकमा धललाम धबक्री गरी िराई ठदन ु पनेछ।\n(४) उपदफा (३) बमोत्तजम सम्पत्ति धललाम धबक्री गदाय पधन असूल निएको\nसरकारी धबगो बापत त्र्स्तो व्र्त्तिलाई कै द गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६४", "title": "सरकारी धबगो बापत कै द गन य सवकनाःे (१) अदालतबाट फै सला िँदु ा असूल उपर िनु ु पने", "content": "गरी ििर िएको सरकारी धबगो िा अन्र् कुनै रकम सम्बत्तन्ित व्र्त्तिले बझु ाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको सरकारी धबगो िा त्र्स्तो रकम त्र्स्तो व्र्त्तिले\nनबझु ाएमा धनजको सम्पत्ति जार्जात गरी असूल उपर गन यु पनेछ।\n(३) उपदफा (२) बमोत्तजमको जार्जात गदाय पधन सरकारी धबगो िा त्र्स्तो\nरकम असूल उपर िनु नसके मा त्र्स्तो व्र्त्तिलाई देिार्को सरकारी धबगो िा त्र्स्तो\nरकम बापत देिार्को अिधिसम्म कै द सजार् धनिायरण गन यु पनेछाः-\n(क) पाँच िजार रुपैर्ाँदेत्ति दश िजार रुपैर्ाँसम्मको विगो बापत एक\nमविना,\n(ि) दश िजार रुपैर्ाँिन्दा बढी पच्चीस िजार रुपैर्ाँसम्मको विगो\nबापत तीन मविना,\n(ग) पच्चीस िजार रुपैर्ाँिन्दा बढी पचास िजार रुपैर्ाँसम्मको विगो\nबापत छ मविना,\n(घ) पचास िजार रुपैर्ाँिन्दा बढी एक लाि रुपैर्ाँसम्मको विगो\nबापत एक िष,य\n(ङ) एक लाि रुपैर्ाँिन्दा बढी प्रत्र्ेक पचास िजार रुपैर्ाँसम्मको\n\nविगो बापत छ मविनाको दरले।\n(४) उपदफा (३) को िण्ड (क) मा उत्तल्लत्तित रकमिन्दा कम रकम बापत\nकै द गन यु पदाय प्रधत ठदनको तीन सर् रुपैर्ाँ कट्टी िनु े गरी गन यु पनेछ।\n(५) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन सरकारी धबगो बापत\nकै द गन यु पदाय सात िषिय न्दा बढी िनु े गरी कै द िेक्न सवकने छैन।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n120\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६५", "title": "धनजी धबगो िा िधतपूधत य िराउन े कार्वयिधिाः (१) अदालतको फै सला बमोत्तजम कुनै", "content": "व्र्त्तिले धतन यु पने ििरेको धनजी धबगो, पीधडत िा धनजको िकिालाले पाउने िधतपूधत य िा\nअन्र् कुनै रकम त्र्सरी फै सला बमोत्तजम धतन यु पने व्र्त्तिलाई फै सला िएको छ\nमविनाधित्र बझु ाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको अिधिधित्र त्र्स्तो व्र्त्तिले त्र्स्तो धबगो, िधतपूधत य\nिा रकम नबझु ाएमा धनजलाई दश िजार रुपैर्ाँसम्म जररबाना िनु ेछ।\n(३) उपदफा (१) बमोत्तजमको अिधिधित्र धबगो, िधतपूधत य िा त्र्स्तो रकम\nबझु ाउन ु पने व्र्त्तिले नबझु ाएमा त्र्स्तो धबगो िधतपूधत य िा रकम िरी पाउने व्र्त्तिले\nअत्तन्तम फै सला िएको धमधतले तीन िषधयित्र त्र्स्तो धबगो, िधतपूधत य िा रकम िन यु पने\nव्र्त्तिको िकको सम्पत्ति देिाई धनिेदन ठदन सक्नेछ।\n(४) उपदफा (३) बमोत्तजम धनिेदन परेमा अदालतले त्र्स्तो सम्पत्ति रोक्क ा र\nधललाम धबक्री गरी क्रमशाः धबगो, िधतपूधत य िा त्र्स्तो रकम िराई ठदन ु पनेछ।\n(५) उपदफा (१) बमोत्तजम धबगो, िधतपूधत य िा रकम धतन यु पने व्र्त्तिले\nअदालतमा त्र्स्तो रकम बझु ाएमा िा दफा ६८ को उपदफा (१) बमोत्तजम कुनै रकम\nिरौट िा जमानत रािेको िए त्र्सबाट िधतपधुत,य धबगो िा त्र्स्तो रकम असूल िनु े िएमा\nसोिी बमोत्तजम िराई ठदन ु पनेछ।\n(६) उपदफा (३) बमोत्तजमको अिधिधित्र धबगो, िधतपूधत य िा अन्र् रकम िराई\nपाउने व्र्त्तिले सम्पत्ति पिा लगाउन नसके मा त्र्स्तो सम्पत्ति फे ला परेको बित धनजले\nजनाउ ठदएमा िराई ठदने गरी अदालतले त्र्स्तो धनिेदन तामेलीमा रात न ु पनेछ।\n(७) उपदफा (४) बमोत्तजम धबगो, िधतपूधत य िा अन्र् कुनै रकम असलु उपर िनु\nनसके मा असूल उपर निएको बाँकी धबगो, िधतपूधत य िा अन्र् रकम िराई पाउने व्र्त्तिले\nकसूरदारको सम्पत्ति धललाम धबक्री िएको धमधतले िा उपदफा (६) बमोत्तजम धनिेदन\nतामेलीमा रिेको तीस ठदनधित्र धनजलाई कै द गराउन धनिेदनपत्र ठदन सक्नेछ।\n(८) उपदफा (७) बमोत्तजमको धनिेदन परेमा अदालतले एक ठदनको तीन सर्\nरुपैर्ाँको दरले त्र्सरी बाँकी िनु आएको धबगो िा रकमलाई कै दमा पररणत गरी त्र्स्तो\nधबगो िा रकम िन यु पने व्र्त्तिलाई कै द गन यु पनेछ।\n(९) उपदफा (८) बमोत्तजम कुनै व्र्त्तिलाई कै द गदाय व्र्त्ति विशेषको धबगोको\nिकमा दईु िष य र नेपाल सरकार, प्रदेश सरकार िा स्थानीर् तिको पूण य िा अधिकांश\n121\nwww.lawcommission.gov.np\nस्िाधमत्ि िा धनर्न्त्रण िएको सािजय धनक संस्थाको धबगोको िकमा चार िषिय न्दा बढी\nकै द गन य सवकने छैन।\nतर िधतपूधत य असूल उपर निए बापत कै द गराउन पदाय चार िषसय म्म कै द गन य\nसवकनेछ।\n(१०) उपदफा (८) बमोत्तजम धनजी धबगो, िधतपूधत य िा अन्र् रकम बापत कै द\nगन यु पदाय तीन सर् रुपैर्ाँिन्दा कम रकम िएमा िा बाँकी रिन गएमा सो बापत एक\nठदन कै द गन ु पनेछ।\n(११) उपदफा (८) बमोत्तजम कै द गदाय कानून बमोत्तजम लाग्ने धसिा िच य नपे ाल\nसरकारले व्र्िोन यु पनेछ।\n(१२) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन धनजी धबगो,\nिधतपूधत य िा अन्र् रकम धतन यु पने व्र्त्तिले उपदफा (१) िा (३) बमोत्तजमको अिधिधित्र\nआफ्नो कुनै सम्पत्ति लकु ाएको िा कुनै प्रकारले रुपान्तरण गरेको ििरेमा प्रचधलत\nकानूनमा जनु सकु ै कुरा लेत्तिएको िए तापधन त्र्स्तो सम्पत्ति पिा लगाएमा त्र्स्तो सम्पत्ति\nजफत िनु ेछ र र्सरी जफत िएको सम्पत्तिको पच्चीस प्रधतशत रकम पिा लगाउनेलाई\nठदई बाँकी रिेको रकमबाट धतन यु पने धबगो, िधतपूधत य िा अन्र् रकम ििु ानी गरी बाँकी\n\nरिेमा त्र्सरी बाँकी रिेको रकम सम्बत्तन्ित व्र्त्तिलाई वफताय गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६६", "title": "फै सला बमोत्तजमको रकम िरौटबाट असूल गनेाः (१) र्स पररच्छेदमा अन्र्त्र जनु सकु ै", "content": "कुरा लेत्तिएको िए तापधन कुनै कसूरदारले र्स ऐन बमोत्तजम कुनै रकम िरौट रािेको\nिए त्र्स्तो िरौटबाट पगु ेसम्म फै सला बमोत्तजम धनजले बझु ाउन ु पने जररबाना, धबगो,\nिधतपूधत य िा अन्र् रकम असूल गन य र िराई ठदन ु पनेछ।\n(२) उपदफा (१) बमोत्तजम िराउँदा देिार् बमोत्तजमको प्राथधमकताक्रमको\nआिारमा िराई ठदन ु पनेछाः-\n(क) जररबाना,\n\n(ि) सरकारी धबगो,\n(ग) िधतपूधत,य\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n122\nwww.lawcommission.gov.np\n\n(ग१) धबगो,\n(घ) अन्र् कुनै रकम िए त्र्स्तो रकम।\n(३) उपदफा (१) बमोत्तजमको रकमबाट जररबाना, धबगो िधतपूधत य िा अन्र् रकम\nअसलु निएमा िा िराई ठदन नसवकएमा त्र्सरी नपगु िए जधतको लाधग मात्र र्स\nपररच्छेद बमोत्तजम कारबािी गरी असलु उपर गन यु िा िराई ठदन ु पनेछ।\n(४) र्स पररच्छेदमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै कसूरदारले\nफै सला बमोत्तजम बझु ाउन ु पने जररबाना, धबगो, िधतपूधत य िा अन्र् कुनै रकम धनजले\nतत्काल बझु ाएकोमा िा उपदफा (१) मा उल्लेि िए बमोत्तजम असलु िनु े िएमा बािेक\nर्ो ऐन बमोत्तजम धनजले िा धनजको तफय बाट अरु कसैले कुनै सम्पत्ति जमानत ठदएको\nरिेछ िने सोिी सम्पत्ति धललाम धबक्री गरी िराई ठदन ु पनेछ।\n(५) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन कुनै कसूरदारको\nिकमा कुनै व्र्त्तिले आफ्नो सम्पत्ति िरौट िा जमानत ठदएको रिेछ िने अदालतले\nत्र्स्तो व्र्त्तिको सम्पत्ति धललाम धबक्री गनअयु त्तघ धनजलाई फै सला बमोत्तजम कसूरदारले\nबझु ाउन ु पने जररबाना, धबगो, िधतपूधत य िा अन्र् रकम बझु ाउन पैँतालीस ठदनको सूचना\nठदन ु पनेछ र त्र्स्तो समर्धित्र धनजले त्र्स्तो रकम बझु ाएमा धनजले िरौट िा जमानत\nठदएको िदसम्मको सम्पत्ति फुकुिा गररठदन ु पनेछ।\n(६) उपदफा (३) बमोत्तजमकोेे सम्पत्तिबाट िराउन नपगु िएको बाँकी रकमको\nिकमा कसूरदारको अरु सम्पत्ति धललाम धबक्री गरी िराई ठदन ु पनेछ र त्र्सरी िराउँदा\nउपदफा (२) बमोत्तजमको प्राथधमकता ठदई िराई ठदन ु पनेछ।\n(७) उपदफा (६) बमोत्तजम धललाम गने प्रर्ोजनका लाधग कसूरदारको अंश\nछुवट्टएको रिेनछ िने धनजको िकमा कानून बमोत्तजम अंश िाग छुट्याई धललाम गन यु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६७", "title": "सम्पत्ति रोक्क ा, कब्जा िा धनर्न्त्रण रातन े कार्वयिधिाः (१) र्स ऐन बमोत्तजम कुन ै", "content": "\nअधिर्िु , प्रधतिादी िा कसूरदारको सम्पत्ति रोक् का रातदा, कब्जा िा धनर्न्त्रणमा धलँदा\nसम्बत्तन्ित अदालतले देिार् बमोत्तजम गन यु पनेछाः-\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n123\nwww.lawcommission.gov.np\n(क) दताय िा छुट्टै अनमु धत प्राप् त िएको सम्पत्ति िए दता य नामसारी गने\nिा लाइसेन्स ठदने िा निीकरण गने कार्ायलर्लाई रोक् काको\nजनाउँ ठदने,\n(ि) नगद सम्पत्ति िए त्र्स्तो नगद रात ने संस्थालाई रोक् काको जनाउ\nठदने,\n(ग) बाली िा बिाल आउने सम्पत्ति िए सम्बत्तन्ित स्थानीर् तिलाई\nत्र्स्तो बाली िा बिाल असूल गरी िरौटी िातामा जम्मा गन य\nआदेश ठदन,े\n ,\n(घ) चाँडै नाधसने िा धबग्रने सम्पत्ति चौपार्ा िा सिारी सािन िए\n,\nत्र्स्तो सम्पत्ति चौपार्ा िा सिारी सािन धललाम धबक्री गरी\n,\nत्र्सबाट प्राप् त रकम िरौटी िातामा जम्मा गन य लगाउने\nतर सिारी सािनको िकमा सिारी िनीले त्र्स्तो सिारी\nसािनको परल मूल्र्मा ह्रासकट्टी गरी िनु आएको रकम िरौटी\nिातामा जम्मा गरेमा त्र्स्तो सिारी सािन सम्बत्तन्ित िनीलाई\nवफताय ठदन ु पनेछ।\n(२) र्स ऐन बमोत्तजम कुनै व्र्त्तिको सम्पत्ति रोक्क ा रातदा धनजले अरु कसैलाई\nकुनै ऋण ठदएको िा लगानी गरेको िए त्र्स्तो ऋण िा लगानीको साँिा, व्र्ाज िा अन्र्\nकुनै प्रधतफल समेत धनजले असूल उपर गन य नपाउने गरी ऋणीलाई अदालतले आदेश\nठदन ु पनेछ।\n(३) उपदफा (२) बमोत्तजमको ऋण िा लगानीको सािाँ, व्र्ाज, प्रधतफल र अन्र्\nर्स्तै रकम ऋणीलाई नै अदालतमा दात्तिल गन य लगाउनेछ।\n(४) र्स दफा बमोत्तजम रोक् का िएको सम्पत्ति उपर अरु कसैको िक िए\nत्र्स्तो व्र्त्तिले आफ्नो िक देिाई त्र्सरी रोक् का िएको थािा पाएको पैँतीस ठदनधित्र\n\nरोक् का गने अदालतमा धनिेदन गन य सक्नेछ।\n सशु ासन प्रििनय तथा सािजय धनक सेिा प्रिाि सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८१ द्वारा\nसंशोधित।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n124\nwww.lawcommission.gov.np\n(५) उपदफा (४) बमोत्तजम उजरु परेमा त्र्स्तो अदालतलाई कानून बमोत्तजम\nसम्पत्तिको िक बेिकको धनणर्य गने अधिकार िए सोिी अदालतले तत्सम्बन्िी धनणर्य गन य\nर त्र्स्तो अधिकार निए अधिकार प्राप् त अदालतमा त्र्स्तो उजरु ी पिाई ठदन ु पनेछ।\n(६) उपदफा (५) बमोत्तजम अदालतले कुनै धनणर्य गरेकोमा त्र्स्तो धनणर्य मा त्तचि\nनबझु ने व्र्त्तिले कानून बमोत्तजम पनु रािेदन गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६८", "title": "विगो, िधतपूधत य िा अन्र् रकम िराई ठदन ताररि तोक्न ु पनेाः (१) फै सला बमोत्तजम धबगो,", "content": "िधतपूधत य िा अन्र् कुनै रकम िराई ठदन ु पने सम्बन्िमा ताररि तोक्दा कुन प्रर्ोजनको\nलाधग कविलेको ताररि तोवकएको िो त्र्सको कारण िलु ाई तोक्न ु पनेछ।\nतर सरकारी धबगो िा िधतपूधतकय ो िकमा सरकारी पि ताररिमा बस्न ु पने\nछैन।\n(२) उपदफा (१) बमोत्तजम तोवकएको ताररिमा िराई पाउने व्र्त्ति अनपु त्तस्थत\nिएमा िराई ठदने सम्बन्िी कारबािी त्र्स ठदन स्थधगत िनु ेछ।\n(३) उपदफा (१) बमोत्तजम तोवकएको ताररिमा आफू उपत्तस्थत िनु नसके को\nकुनै मनाधसब कारण देिाई धबगो, िधतपूधत य िा अन्र् कुनै रकम िराई पाउने व्र्त्तिले\nएक पटकको लाधग पन्र ठदनधित्र अदालतमा धनिेदन ठदएमा त्र्स्तो व्र्त्तिलाई फै सला\nबमोत्तजम िराई ठदन ु पने धबगो, िधतपूधत य िा अन्र् रकम िराई ठदन ु पनेछ।\n(४) उपदफा (१) बमोत्तजम तोवकएको ताररिमा उपत्तस्थत निएको धबगो, िधतपूधत य\n\nिा अन्र् कुनै रकम िराई पाउने व्र्त्तिले उपदफा (३) बमोत्तजमको अिधिधित्र धनिेदन\nनठदएमा त्र्स्तो धबगो, िधतपूधत य िा अन्र् कुनै रकम िराई ठदने सम्बन्िी कार् य एक\nिषसय म्मको लाधग तामेलीमा रात्तिनेछ।\n(५) उपदफा (४) बमोत्तजमको अिधिधित्र सम्बत्तन्ित व्र्त्ति उपत्तस्थत िएमा\nफै सला बमोत्तजम िराई ठदन ु पने धबगो, िधतपूधत य िा अन्र् रकम िराई ठदन ु पनेछ।\n(६) उपदफा (४) बमोत्तजमको अिधिधित्र सम्बत्तन्ित व्र्त्ति उपत्तस्थत निएमा\nत्र्सपधछ त्र्स्तो धबगो, िधतपूधत य िा अन्र् कुनै रकम िराई ठदने सम्बन्िमा कुनै कारबािी\nगररने छैन।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n125\nwww.lawcommission.gov.np\nपररच्छेद-१६\nविविि\n\n१६८क. उजरु गन य सक्नाःे (१) अदालतका कमचय ारीले मद्दु ामा गरेको काम कारबािी उपर त्तचि\nनबझ्ु ने सरोकारिाला व्र्त्तिले पन्र ठदनधित्र सोिी अदालतका न्र्ार्ािीश समि उजरु\nगन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम परेको उजरु ीमा िएको धनणर्य मा त्तचि नबझ्ु न े\nव्र्त्तिले त्र्स्तो धनणर्य िएको पन्र ठदनधित्र पनु रािेदन सन्ु ने अदालतमा धनिेदन ठदन\nसक्नेछ।\n(३) उपदफा (१) बमोत्तजम परेको उजरु ी एक मविनाधित्र र उपदफा (२)\nबमोत्तजम परेको धनिेदन दईु मविनाधित्र टुङ्गो लगाउन ु पनेछ।\n(४) फै सला कार्ायन्िर्नको उपत्तस्थधतको लाधग ठदइएको सूचना प्राप् त गरी\nताररिमा अनपु त्तस्थत रिने पिले र्स दफा बमोत्तजमको उजरु ी िा धनिेदन ठदन पाउन े\nछैन।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१६९", "title": "सम्बत्तन्ित त्तजल्ला अदालतलाई अधिकार ित्रे िनु ाःे (१) अपराि संवितामा उत्तल्लत्तित", "content": "मद्दु ामा त्तजल्ला अदालतले शरुु कारबािी, सनु िु ाइ र वकनारा गनेछ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन अपराि संवितामा मद्दु ा\nिेने अधिकारी सम्बन्िमा छुट्टै व्र्िस्था िएको िा सो संवितामा उत्तल्लत्तित मद्दु ामध्र् े\nनेपाल सरकारले नेपाल राजपत्रमा सूचना प्रकाशन गरी छुट्टै मद्दु ा िेने अधिकारी\nतोवकठदएकोमा त्र्स्ता अधिकारीबाट त्र्स्ता मद्दु ाको शरुु कारबािी, कारबािी, सनु िु ाइ र\nवकनारा गन य बािा पने छैन।\n(३) कानून बमोत्तजम कुनै अदालत, धनकार् िा अधिकारीलाई मद्दु ामा कारबािी,\nसनु िु ाइ र वकनारा गने अधिकार िएको तर त्र्स्तो अदालत िा धनकार् गिन निएको िा\nअधिकारी नतोवकएको अिस्थामा त्र्स्तो अदालत िा धनकार् गिन निएसम्म िा\nअधिकारी नतोवकएसम्म त्र्स्तो मद्दु ाको कारबािी, सनु िु ाइ र वकनारा गने अधिकार समेत\nसम्बत्तन्ित त्तजल्ला अदालतलाई िनु ेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n126\nwww.lawcommission.gov.np\n\n१६९क. िदम्र्ादाः प्रचधलत कानून बमोत्तजम िदम्र्ाद तोवकएकोमा सोिी बमोत्तजम र िदम्र्ाद\nनतोवकएकोमा जविलेसकु ै मद्दु ा गन य सवकनेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७०", "title": "...............", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७१", "title": "धलितिरुको पत्तञ्ज का: प्रत्र्ेक मद्दु ामा अनसु ूची-५० बमोत्तजमको ढाँचामा पत्तञ् जका िडा", "content": "गरी दताय धमधतको क्रमले धलितिरुको क्रमसङ्खत र्ा र वििरण जनाई पत्तञ् जका िडा गरी\nरात न ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७२", "title": "धलित िल्ु र्ाउन ु पनेाः अदालतले मद्दु ाको अत्तन्तम धनणर्य िएको पाँच िषपय धछ सो मद्दु ाको", "content": "धमधसलमा रिेका देिार्का धलितिरु बािेक अरु धलितिरु िल्ु र्ाउन ु पनेछाः-\n(क) उजरु ी, अधिर्ोगपत्र िा वफरादपत्र,\n (क१) पिको नाममा जारी िएको पक्राउ पूजी िा समाह्वान,\n(ि) अधिर्िु को बर्ान िा प्रधतउिरपत्र,\n(ग) प्रधतउिरपत्र सरिको बर्ान,\n(घ) प्रमाणका सक् कल धलितिरु,\n(ङ) पनु रािेदन परेको िए पनु रािेदनपत्र,\n(च) मद्दु ा दोिो¥र्ाउने िा पनु रािलोकनको लाधग ठदइएको धनिेदनपत्र,\n(छ) अदालतबाट िएको फै सला िा अत्तन्तम धनणर्य ,\n(ज) नक्सा, तार्दाती फाराम, सम्पत्ति वििरण,\n(झ) कानून बमोत्तजम संरिण गन य आिश्र्क देत्तिएका अन्र् कुनै धलित।\nस्पष्टीकरणाः र्स दफाको प्रर्ोजनको लाधग “अत्तन्तम धनणर्य िएको” िन् नाले पनु रािेदन\nपरेको फै सलाको सम्बन्िमा पनु रािेदन सन्ु ने अदालतबाट िएको धनणर्य र सािक पेश\nिएको फै सलाको सम्बन्िमा सािकको धनकासा गन य अधिकार प्राप् त अदालतबाट िएको\nधनणर्य सम्झन ु पछय।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७३", "title": "धलित अनिु ाद गन यु पनेाः (१) नेपाली िाषा बािेक अन्र् कुनै िाषामा लेत्तिएको कुन ै", "content": "धलित अदालतमा प्रमाणको रुपमा पेश िएमा र त्र्स्तो धलित नेपाली िाषामा अनिु ाद\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा त्तझवकएको।\n127\nwww.lawcommission.gov.np\nगन यु पने देत्तिएमा अदालतले त्र्स्तो धलित पेश गने पिलाई त्र्स्तो धलितको नेपाली\nिाषामा आधिकाररक अनिु ाद गरी पेश गने आदेश ठदन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम अदालतबाट आदेश िएका सम्बत्तन्ित पिले सो\nधलित नपे ाली िाषामा अनिु ाद गराई त्र्सको प्रमात्तणत प्रधत अदालतमा पेश गन यु पनेछ।\n(३) उपदफा (२) बमोत्तजमको अनिु ादका सम्बन्िमा कुनै वििाद उत्पन्न िएमा\nअदालतले त्र्स्तो विषर्को विशेषज्ञलाई त्तझकाई बझ्ु न सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७४", "title": "अनिु ादकको सिर्ोग धलन सक्नाःे (१) नेपाली िाषा नबझ्ु ने िा बोल्न नसक्ने कुन ै", "content": "अधिर्िु िा सािीको बर्ान िा बकपत्र धलन ु परेमा िा अन्र् कुनै प्रर्ोजनको लाधग\nआिश्र्क िएमा अनसु न्िान अधिकारी, अधिर्ोजनकताय िा अदालतले सम्बत्तन्ित िाषा िा\nसाङ्केधतक िाषाको अनिु ादकको सिर्ोग धलन सक्नछे ।\n(२) उपदफा (१) बमोत्तजम अनिु ादकको सिर्ोग धलदा लाग्ने िच य नपे ाल\nसरकारले व्र्िोनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७५", "title": "नक्क ल ठदन ु पनेाः (१) मद्दु ाको सरोकारिाला पि िा धनजको कानून व्र्िसार्ीले कुन ै", "content": "मद्दु ाको धमधसलमा रिेको कुनै धलितको नक् कल कानूनमा व्र्िस्था िए बमोत्तजमको\nदस्तरु धतरी धलन सक्नेछ।\nतर फै सलाको नक् कल जनु सकु ै कानून व्र्िसार्ीले धलन पाउने छ।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन कानून बमोत्तजम गोप्र्\nरात न ु पने धलितको नक् कल ठदइने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७६", "title": "स्िाथ य बात्तझन े मद्दु ा िेन य निनु ाःे (१) न्र्ार्ािीशले देिार्का मद्दु ाको कारबािी, सनु िु ाई र", "content": "वकनारा गन य िँदु ैनाः-\n(क) आफ्नो िा आफ्नो नत्तजकको नातेदारको िक वित िा सरोकार\nिएको मद्दु ा,\nस्पष्टीकरणाः र्स दफाको प्रर्ोजनको लाधग “नत्तजकको नातेदार”\nिन् नाले अपतु ाली परे िान पाउने नाताको व्र्त्ति िा मामा,\nमाइज्र्ू, सानी आमा, िुली आमा, सान ु बाब,ु िुला बाब,ु सासू, ससरु ा,\nफुपू, फुपाज,ु जेिान, साला, जेिी सासू, साली, ठददी, बविनी, धिनाज,ु\nबविनी ज्िाइ, छोरी ज्िाइ, िाञ्जा, िाञ्जी, िाञ्जी ज्िाइ, िाञ्जी बिु ारी,\n128\nwww.lawcommission.gov.np\nआमाका बाब,ु आमाकी आमा िा त्र्स्तो नाता पने व्र्त्तिको\nपररिारको सदस्र् सम्झन ु पछय।\n(ि) कुनै बित आफू िाररस, कानून व्र्िसार्ी िा सािी िएको मद्दु ा,\n(ग) आफू ले न्र्ार्ािीशको िैधसर्तमा कुनै अदालतमा धनणर्य गरेको िा\nअत्तन्तम आदेश गरेको मद्दु ा,\n(घ) कुनै बित आफू ले मद्दु ा चल्ने िा नचल्ने विषर्मा रार् ठदएको\nमद्दु ा,\n(ङ) अन्र् कुनै कारणले आिारितू रुपमा आफ्नो र आफ्नो एका\nसगोलका पररिारका सदस्र्को स्िाथ य गाँधसएको मद्दु ा।\n(२) उपदफा (१) बमोत्तजमको कुनै अिस्था देत्तिएकोमा न्र्ार्ािीशले मद्दु ा िेन य\nनिनु े कारण िलु ाई आदेश गन यु पनेछ।\n(३) उपदफा (१) को प्रधतकू ल िनु े गरी कुनै न्र्ार्ािीशले कुनै मद्दु ाको\nकारबािी, सनु िु ाई िा वकनारा गन य लागेमा मद्दु ाको कुनै पिले आिश्र्क प्रमाण सवित\nकारबािी, सनु िु ाई िा वकनारा नगन य धनिेदन ठदन सक्नेछ।\n(४) उपदफा (३) बमोत्तजम धनिेदन पन य आएमा न्र्ार्ािीशले मद्दु ाको कारबािी,\nसनु िु ाई िा वकनारा गनअयु त्तघ त्र्स्तो धनिेदन दािी मनाधसब िएको िा निएको सम्बन्िमा\nधनणर्य गन यु पनेछ।\n(५) उपदफा (४) बमोत्तजम धनणर्य गदाय धनिेदन दािी मनाधसब देत्तिएकोमा िा\nउपदफा (२) बमोत्तजम न्र्ार्ािीश आपैmले मद्दु ाको कारबािी, सनु िु ाई िा वकनारा गन य निनु े\nआदेश गरेकोमा त्र्स्तो मद्दु ा सोिी अदालतमा अको न्र्ार्ािीश िए धनज समि र त्र्स्तो\nन्र्ार्ािीश निएमा दफा ९६ को उपदफा (३) बमोत्तजम मद्दु ा स्थानान्तरणको लाधग\nसम्बत्तन्ित पनु रािेदन सन्ु ने अदालत समि लेिी पिाउन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७७", "title": "न्र्ार्ािीश आफैं ले गन यु पने कामिरुाः (१) र्स ऐन बमोत्तजम अदालतले गने कामिरुमध्र् े", "content": "देिार्का कामिरु न्र्ार्ािीश आफैँ ले गन यु पनेछाः-\n(क) अधिर्िु िा सािीको बर्ान धलने िा िकपत्र गराउने,\n(ि) सािीलाई शपथ गराउने,\n129\nwww.lawcommission.gov.np\n(ग) पपु िय का लाधग थनु ामा रात ने िा िरौट िा जमानतमा रात न आदेश\nठदने,\n(घ) मद्दु ामा धनणर्य ठदन ु पने कुरािरुको आदेश पचाय िडा गने,\n(ङ) प्रमाण बझ्ु ने सम्बन्िी आदेश ठदने,\n(च) अन्तररम िा अन्तरकालीन आदेश ठदन,े\n(छ) मद्दु ाको सनु िु ाई गने,\n(ज) मद्दु ाको प्रारत्तम्िक र पूि य सनु िु ाई छलफल गराउने,\n(झ) आिश्र्क अन्र् कुनै वकधसमको आदेश गने, र\n(ञ) फै सला गने, िा अत्तन्तम आदेश ठदने।\n(२) उपदफा (१) मा जनु सकु ै कुरा लेत्तिएको िए तापधन देिार्का कुरािरु\nदेिार् बमोत्तजम गन य सवकनेछाः-\n(क) सािीको िकपत्र न्र्ार्ािीशको धनदेशनमा अदालतको कम्तीमा\nराजपत्र अनवङ्कत प्रथम श्रेणीसम्मको कमचय ारीले अधिलेि गने,\n(ि) न्र्ार्ािीशको अनपु त्तस्थधतमा अदालतमा उपत्तस्थत िएका मध्र् े\nसबैिन्दा िररष्टतम कमचय ारीले अधिर्िु को बर्ान गराउने िा\nधनजलाई थनु ामा रात ने िा धनजसँग िरौट िा जमानत धलन े\n\nसम्बन्िमा पररच्छेद-७ बमोत्तजम आदेश ठदने।\nतर र्स िण्ड बमोत्तजम िएको आदेश न्र्ार्ािीश अदालतमा िात्तजर िनु ासाथ धनज\nसमि पेश गन यु पनेछ र धनजले त्र्स्तो आदेश जाँची सदर, बदर िा संशोिन गन य\nसक्नेछ।\n(३) उपदफा (१) िा (२) मा लेत्तिएदेत्ति बािेक अरु कामिरु न्र्ार्ािीशको\nधनदेशन िा आदेश बमोत्तजम धनज मातितको कमचय ारीले गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७८", "title": "थनु िु ा िा कै दीलाई ररिाई गदा य अपनाउन ु पने कार्वयिधिाः (१) अदालतको फै सला िा", "content": "आदेश बमोत्तजम कुनै थनु िु ा िा कै दीलाई ररिाई गनपयु ने िएमा धनजलाई ररिाई गन यु पने\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n130\nwww.lawcommission.gov.np\nकारण, कै दी िा थनु िु ाको परु ा नाम र िेगाना तथा मद्दु ाको वििरण िोली सम्बत्तन्ित\nकारागारलाई त्र्सको आदेश पिाउन ु पनेछ।\n(२) उपदफा (१) बमोत्तजमको आदेश प्राप् त िएपधछ सम्बत्तन्ित कारागारले\nत्र्स्तो आदेश बमोत्तजम थनु िु ा िा कै दीलाई तरुु न्त ररिाई गन यु पनेछ।\n(३) उपदफा (१) र (२) मा जनु सकु ै कुरा लेत्तिएको िए तापधन फै सला िा\nआदेश बमोत्तजम ररिा गन यु पने थनु िु ा िा कै दी अदालतमा उपत्तस्थत रिेकोमा फै सला\nिएपधछ तत्काल धनजलाई ररिाई गरी त्र्सको सूचना सम्बत्तन्ित कारागारलाई ठदन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१७९", "title": "रोक्क ा रिेको सम्पत्ति फुकुिा गदा य सूचना ठदनाःे र्स ऐन बमोत्तजम रोक् का रिेको सम्पत्ति", "content": "अदालतको फै सला िा आदेश बमोत्तजम फुकुिा गन यु पदाय अदालतले रोक् का रात न े\nसम्बत्तन्ित कार्ायलर् र व्र्त्तिलाई त्र्सको सूचना ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८०", "title": "सरकारी िवकलले बिस पैरबी तथा पनु रािदे न गन यु पनेाः (१) अनसु ूची-१ र अनसु ूची-२", "content": "अन्तगतय का कसूर सम्बन्िी मद्दु ामा नेपाल सरकारको तफय बाट सरकारी िवकलले बिस\nपैरबी तथा प्रधतरिा गनेछ।\n(२) अनसु ूची-३ मा उत्तल्लत्तित कसूर सम्बन्िी मद्दु ामा सम्बत्तन्ित अधिकारीबाट\nमद्दु ाको दार्री िा पनु रािेदन िनु ेछ र प्रधतरिाको लाधग सम्बत्तन्ित सरकारी िवकललाई\nलेिी पिाएमा सरकारी िवकलले प्रधतरिा गररठदन ु पनेछ।\n(३) सरकारी िवकलले मद्दु ािरुमा बिस पैरबी गदाय व्र्ािसावर्क आचरण\nसम्बन्िी प्रचधलत मान्र्ता अनसु ार बिस पैरबी गन यु पनेछ।\n(४) उपदफा (१) बमोत्तजमको मद्दु ामा अदालतबाट ििर िएको फै सला िा\nआदेश उपर त्तचि नबझु ेमा पनु रािेदन गने, पनु रािलोकन गराउने, मद्दु ा दोिो¥र्ाउने धनिेदन\nगने अधिकार प्रचधलत कानूनमा अन्र्था व्र्िस्था िएकोमा बािेक सरकारी िवकललाई\nिनु ेछ।\n(५) र्स दफामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन नेपाल सरकार िादी\nिनु े कुनै िास मद्दु ामा सरकारी िवकलका अधतररि अन्र् कुनै कानून व्र्ािसार्ीबाट\nसमेत बिस पैरबी गराउन ु पने िएमा त्र्सको कारण िलु ाई सम्बत्तन्ित धनकार्ले\nमिान्र्ार्ाधिििा िा धनजले अत्तततर्ारी ठदएको सरकारी िवकलको अनमु धत धलन ु पनेछ।\n131\nwww.lawcommission.gov.np\n(६) उपदफा (५) बमोत्तजम अनमु धत प्राप् त िएपधछ त्र्स्तो धनकार्ले अन्र् कानून\nव्र्िसार्ी मकु रर गन य सक्नेछ।\n(७) उपदफा (६) बमोत्तजम मकु रर िएको कानून व्र्िसार्ीले मिान्र्ार्ाधिििा\nिा धनजले अत्तततर्ारी ठदएको सरकारी िवकलको सामान्र् धनदेशनमा रिी बिस पैरबी गन यु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८१", "title": "सरकारी िवकलले उजरु गन य सक्नाःे कुनै न्र्ावर्क िा अि य न्र्ावर्क धनकार्बाट िएको", "content": "धनणर्य िा आदेशिाट नेपाल सरकारको िक, वित िा सरोकारमा असर पने रिेछ र\nत्र्स्तो आदेश िा धनणर्य विरुद्ध मद्दु ा दार्र गन,य पनु रािेदन गन,य पनु रािलोकन गन य िा\nअन्र् कुनै वकधसमले उजरु ी िा धनिेदन गन य कानूनले कुनै अधिकारी तोके को रिेनछ िने\nत्र्स्तो विषर्मा मिान्र्ार्ाधिििा आपैmले िा धनजले तोके को सरकारी िवकलले त्र्स्तो\nधनणर्य िा आदेश विरुद्ध कानूनको अिीनमा रिी सम्बत्तन्ित धनकार्मा उजरु गन,य\nपनु रािेदन गन,य पनु रािलोकन गन य िा अन्र् कुनै धनिेदन ठदन सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८२", "title": "अदालतमा दता य गराउन ल्र्ाएको धलित दता य गन यु पनेाः (१) अदालतमा दताय गराउन", "content": "ल्र्ाएको धलित कानून बमोत्तजम रीत पगु ेको रिेछ िने तरुु न्त दताय गरी िरपाई ठदन ु\nपनेछ।\n(२) उपदफा (१) बमोत्तजम दताय गराउन ल्र्ाएको धलित कानून बमोत्तजम रीत\nनपगु ेको िए रीत नपगु ेको कुरा िोली दरपीि गरी वफताय गरी ठदन ु पनेछ।\n\n(३) उपदफा (२) बमोत्तजम धलित दरपीि िएकोमा तीन ठदनिन्दा बढी\nिदम्र्ाद िा म्र्ाद बाँकी रिेछ िने बाँकी रिेको िदम्र्ाद िा म्र्ादधित्र र तीन ठदनिन्दा\nकम िदम्र्ाद िा म्र्ाद बाँकी रिेछ िने दरपीि िएको धमधतले सात ठदनधित्र रीत पर्यु ाई\nिा सच्र्ाई दताय गन य ल्र्ाएमा सम्बत्तन्ित अधिकृ तले त्र्स्तो धलित दताय गने आदेश ठदन ु\nपनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८३", "title": "पीधडत िा सािीको पररचर् गोप्र् रातन सवकनाःे (१) र्स ऐनमा अन्र्त्र जनु सकु ै कुरा", "content": "लेत्तिएको िए तापधन कुनै िास कसूरबाट पीधडत व्र्त्ति िा सािीको पररचर् सािजय धनक\nगदाय त्र्स्तो व्र्त्ति िा सािीको सामात्तजक प्रधतष्ठा िा इज्जत उपर प्रधतकू ल प्रिाि पन य\nसक्ने िा धनज उपर अधिर्िु िा अन्र् कुनै पिबाट अनत्तुचत डर, त्रास िा िर् िनु सक्न े\nिा धनजको जीउ, ज्र्ानको सरु िामा प्रधतकू ल असर पन य सक्ने देत्तिएमा त्र्स्तो व्र्त्ति िा\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n132\nwww.lawcommission.gov.np\nसािीको नाम, थर, ितन िा धनजको बाबकु ो नाम िा धनजको पररचर् िनु सक्न े अन्र् कुन ै\nिधुलर्ा गोप्र् रात न अनसु न्िान अधिकारीले सरकारी िवकल माफय त अदालतलाई अनरु ोि\nगन य सक्नेछ।\n(२) उपदफा (१) बमोत्तजम अनरु ोि िएकोमा अदालतले त्र्स्तो पीधडत व्र्त्ति िा\nसािीको नाम, थर, ितन, धनजको बाबकु ो नाम िा धनजको पररचर् गोप्र् रात ने गरी आदेश\nठदन सक्नेछ।\n(३) उपदफा (२) बमोत्तजम गोप्र् रात्तिएको व्र्त्तिको नाम, थर, ितन िा बाबकु ो\nनाम सम्बत्तन्ित मद्दु ाको सनु िु ाईका बित िा सो सम्बन्िी वििरण प्रकाशन गदायका बित\nअदालतको आदेश बमोत्तजम काल्पधनक नाम, थर, ितन िा बाबकु ो काल्पधनक नाम रािी\nप्रकाशन गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८४", "title": "अनसु न्िान अधिकारी समि िएको बर्ान, कागज िा धलितलाई श्रव्र् दृश्र्का सािनमा", "content": "अधिलेि गन य सवकनाःे (१) र्स ऐनमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन\nदेिार्को अिस्थामा अनसु न्िान अधिकारीले कसूरबाट पीधडत व्र्त्ति, जािेरिाला िा\nसािीको बर्ान, कागज िा कुनै धलित सरकारी िवकलको रोििरमा श्रव्र् दृष्र्का सािन\nमाफय त अधिलेि गन य िा गराउन सक्नेछाः\n(क) कसूरबाट पीधडत व्र्त्ति, जािेरिाला िा कुनै सािीलाई अधिर्िु ले\nअनत्तुचत प्रिािमा पारी िा धनज उपर डर, त्रास, िम्की देिाई\nधनजलाई अदालतमा उपत्तस्थत िनु नठदने िा अदालतमा उपत्तस्थत\nिएपधन अनसु न्िान अधिकारी समि गरेको बर्ान िा कागजिन्दा\nप्रधतकू ल िनु े गरी बर्ान िा बकपत्र गराउन बाध्र् गराउनेछ िन् न े\nविश्वास गन यु पने मनाधसब कारण िएमा,\n(ि) शारीररक अशिता िा नाबालक िएको कारणले त्र्स्तो व्र्त्ति,\nजािेरिाला िा सािी प्रिरी कार्ायलर् िा सरकारी िवकलको\nकार्ायलर्मा उपत्तस्थत िनु नसक्ने िएमा,\n(ग) प्रमाणको रुपमा अदालतमा पेश गररने िस्त ु सो िस्त ु रिेको\nिाउँबाट उिाएर अदालतमा ल्र्ाउन नसवकने िएमा।\n(२) उपदफा (१) बमोत्तजम अधिलेि गररएको श्रव्र् दृश्र्का सािनलाई\nअदालतले प्रमाणको रुपमा स्िीकार गन य सक्नेछ।\n133\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८५", "title": "माधथल्लो तिको कमचय ारीले काम कारबािी गन य सक्नाःे (१) र्स ऐन बमोत्तजम कुन ै", "content": "सरकारी िवकल, प्रिरी कमचय ारी िा अन्र् कुनै अधिकारीले गन यु पने िा गन य सक्ने कुन ै\nकाम िा कतव्य र् मिान्र्ार्ाधिििाले तोके बमोत्तजमको माधथल्लो िा समान तिको\nसरकारी िवकलले िा प्रिरी मिाधनरीिकले तोके बमोत्तजमको माधथल्लो िा समान तिको\nप्रिरी कमचय ारीले िा सम्बत्तन्ित कार्ायलर्को माधथल्लो िा समान तिको अन्र् कुन ै\nअधिकृ तले पधन गन य सक्नछे ।\n(२) उपदफा (१) बमोत्तजम गररएको काम कारबािी अधिकार प्राप् त\nअधिकारीबाट िए गरेको माधननेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८६", "title": "िरपाई धलन ु िा ठदन ु पनेाः (१) अदालतमा दताय िएको कुनै धलित कुनै व्र्त्तिलाई वफता य", "content": "ठदँदा िा अदालतबाट कुनै धलित कुनै व्र्त्तिलाई बझु ाउँदा त्र्स्तो धलित वफताय धलएको\nिा बझु ाएको व्र्िोराको िरपाई िा धनस्सा धलई धमधसल सामेल रात न ु पनेछ।\n(२) अदालतमा कुनै व्र्त्तिले पेश गरेको कुनै धलित अदालतले बझु ी धलँदा सो\nव्र्त्तिलाई त्र्सको िरपाई ठदन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८७", "title": "रोििरमा बस्न तथा सिीछाप गन य सिर्ोग गन यु पनेाः (१) र्स ऐन बमोत्तजम कुनै काम", "content": "कारबािीको धसलधसलामा रोििरमा बस्न ु पने व्र्त्तिले रोििरमा बसी तथा अदालतबाट\nतर्ार गररएको धलितमा सिीछाप गन यु पने व्र्त्तिले सिीछाप गरी अदालतलाई सिर्ोग\nगन यु पनेछ।\n(२) उपदफा (१) बमोत्तजम रोििरमा बस्न िा कुनै धलितमा सिीछाप गन य कुन ै\nव्र्त्तिले इन्कार गरेमा त्र्स्तो काम िा धलित गराउने कमचय ारीले त्र्स्तो व्र्िोरा\nउल्लेि गरी सम्बत्तन्ित धलितमा रोििरमा निसेको िा सिीछाप नगरेको कारण िलु ाई\nकै वफर्त जनाई उपत्तस्थत िएका अन्र् दईु व्र्त्तिको सिीछाप गराई आफू ले पधन त्र्समा\nसिीछाप गरी धलित तर्ार गन यु पनेछ।\n(३) उपदफा (२) बमोत्तजम तर्ार गररएको धलितलाई कानून बमोत्तजम रीत\nपगु ेको माधननेछ।\n(४) अदालतमा िएको कुनै धलितमा सिीछाप गन यु पने कुनै व्र्त्तिले सिीछाप\nगन य इन्कार गरेमा न्र्ार्ािीशले सोिी व्र्िोरा उल्लेि गरी सम्बत्तन्ित धलितमा कै वफर्त\nजनाई आफ्नो सिीछाप गरी रात न ु पनेछ।\n134\nwww.lawcommission.gov.np\n(५) र्स दफा बमोत्तजम रोििरमा नबसी िा सिीछाप नगरी अदालतको काममा\nअसिर्ोग गने व्र्त्तिलाई अदालतले पाँच िजार रुपैर्ाँसम्म जररबाना गन य सक्नेछ।\n(६) र्स ऐन बमोत्तजम कुनै व्र्त्तिले कुनै धलितमा सिीछाप गदाय त्र्स्तो\nधलितमा उल्लेि िएको कुनै व्र्िोरामा आफ्नो सिमधत निएमा आफ्नो व्र्िोरा छुट्टै\nलेत्ति सिीछाप गन य सक्नेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८८", "title": "कारबािी नगररनाःे (१) र्स ऐन बमोत्तजम सरकारी िवकलले कुनै मद्दु ाको सन्दिमय ा असल", "content": "धनर्तले गरेको धनणर्य , अधिर्ोजन, बिस पैरबी एिं प्रधतरिा सम्बन्िमा प्रश्न उिाइने र\nकुनै अदालतमा मद्दु ा चलाइने छैन।\n(२) अनसु ूची-१ र अनसु ूची-२ अन्तगतय का कसूर सम्बन्िी मद्दु ाको अनसु न्िानको\nसम्बन्िमा अनसु न्िान अधिकारीले असल धनर्तले गरेको काम कारबािी उपर कुनै\nकारबािी िनु सक्ने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१८९", "title": "अनसु न्िान सधमधतको व्र्िस्थााः र्स ऐनमा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन", "content": "अपराि संविताको दफा ९९ बमोत्तजमको बदधनर्तपूिकय अनसु न्िान िा अधिर्ोजन गरेको\nकसूरको सम्बन्िमा परेको उजरु ीको अनसु न्िान देिार् बमोत्तजमको सधमधतले गनेछाः-\n(क) मिान्र्ार्ाधिििाले तोके को कम्तीमा राजपत्रावङ्कत\nप्रथम श्रेणीको सिन्र्ार्ाधिििा - अध्र्ि\n(ि) नेपाल सरकारले तोके को नेपाल सरकारको\nकम्तीमा राजपत्रावङ्कत प्रथम श्रेणीको अधिकृ त - सदस्र्\n(ग) नेपाल सरकारले तोके को नेपाल प्रिरीको कम्तीमा\nराजपत्रावङ्कत प्रथम श्रेणीको अधिकृ त - सदस्र्\n(२) उपदफा (१) बमोत्तजमको सधमधतले अनसु न्िान गदाय त्र्सरी बदधनर्तपूिकय\nअनसु न्िान िा अधिर्ोजन गरेको देत्तिएमा त्र्स सम्बन्िमा मद्दु ा चलाउन सम्बत्तन्ित\nसरकारी िवकलको कार्ायलर्लाई लेिी पिाउनेछ।\n135\nwww.lawcommission.gov.np\n\n(३) र्स संवितामा अन्र्त्र जनु सकु ै कुरा लेत्तिएको िए तापधन अपराि\nसंविताको दफा २३१, २३२, २३३ र २३८ बमोत्तजमको कसूरको अनसु न्िान देिार्\nबमोत्तजमको सधमधतले गनेछाः\n(क) नेपाल मेधडकल काउत्तन्सलले तोके को सम्बत्तन्ित\nविज्ञ त्तचवकत्सक - संर्ोजक\n(ि) स्िास्थ्र् सम्बन्िी विषर् िेने नेपाल सरकारको मन्त्रालर्ले\nतोके को नेपाल स्िास्थ्र् सेिाको सम्बत्तन्ित िेत्रमा विज्ञता\nिाधसल गरेको कम्तीमा एघारौँ तिको अधिकृ त - सदस्र्\n(ग) मिान्र्ार्ाधिििाले तोके को सिन्र्ार्ाधिििा - सदस्र्\n(घ) गिृ मन्त्रालर्ले तोके को नेपाल प्रिरीको\nकम्तीमा राजपत्रावङ्कत प्रथम श्रेणीको अधिकृ त - सदस्र्\n(ङ) उपिोिा िकवितको िेत्रमा वक्रर्ाशील व्र्त्तिमध्र्ेबाट\nस्िास्थ्र् सम्बन्िी विषर् िेने नेपाल सरकारको\nमन्त्रालर्ले तोके को एकजना - सदस्र्\n\n(४) उपदफा (३) बमोत्तजमको सधमधतले अनसु न्िान गदाय सम्बत्तन्ित व्र्त्तिले\nकसूर गरेको प्रमाण िेवटएमा धनज विरुद्ध मद्दु ा चलाउन सम्बत्तन्ित सरकारी िकीलको\nकार्ायलर्लाई लेिी पिाउनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९०", "title": "मद्दु ा सकार गन य अनमु धत ठदन सक्नाःे कै द िा जररबानाको सजार् िनु े बािेक धबगो िराउन ु", "content": "पने िा कुनै वकधसमको चल अचल िराउन ु पने अनसु ूची-४ अन्तगतय को कसूर सम्बन्िी\nमद्दु ामा उजरु िाला मरेमा, धनजको िोस िेगानमा नरिेमा िा धनज िेपिा िई अदालतबाट\nतोवकएको म्र्ाद ताररि गज्रु मे ा उजरु िाला मरेको, धनजको िोस िेगानमा नरिेको िा धनज\nिेपिा िएको धमधतले बाटोको म्र्ाद बािेक पैँतीस ठदनधित्र मद्दु ा सकार गरी म्र्ाद ताररि\nथमाउन प्रमाण कागज सवित धनजको िकदारले धनिेदन ठदएमा अदालतले व्र्िोरा\nमनाधसब िएको देिेमा मद्दु ा सकार गरी गत्तुज्रएको म्र्ाद ताररि थाधमठदन अनमु धत ठदन\nसक्नेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n136\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९१", "title": "पारस्पररक कानूनी सिार्ता आदान प्रदान गन य सवकनाःे र्स ऐन बमोत्तजम कारबािी, सनु िु ाइ", "content": "र वकनारा िनु े कसूर सम्बन्िी मद्दु ाको कुनै अधिर्िु विदेशमा रिेकोमा धनजका नाउँमा\nसमाह्वान िा पक्राउ पूजी जारी गन यु पने िा कुनै प्रमाण बझ्ु न ु पने िएमा िा विदेशी\nअदालतमा विचारिीन मद्दु ाको कुनै अधिर्िु नेपालमा रिेकोमा धनजको नाउँमा समाह्वान\nिा पक्राउ पूजी तामेल गने िा प्रमाण बझ्ु न सिर्ोग गन यु पने िएमा पारस्पररक कानूनी\nसिार्ता सम्बन्िी कानून बमोत्तजम गन यु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९२", "title": "विद्यतु ीर् माध्र्मबाट धलित आदान प्रदान गन य सवकनाःे र्स ऐन बमोत्तजमका धलित", "content": "विद्यतु ीर् कारोबार सम्बन्िी प्रचधलत कानून बमोत्तजम विद्यतु ीर् माध्र्मबाट आदान प्रदान\nगन य सवकनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९३", "title": "मद्रु ण िा गत्तणतीर् त्रटु ीले असर नगनेाः र्स ऐन अन्तगतय मद्दु ाको तिवककात, अधिर्ोजन", "content": "तथा अन्र् काम कारबािी गदाय र्स ऐन बमोत्तजमको कार्वयिधिका सम्बन्िमा लेिाइ,\nछपाइ िा मद्रु णमा िएको गत्तणतीर् िा अन्र् कुनै सानाधतना त्रटु ी िा छुट िएकोमा सोिी\nकारणले मात्र त्र्ससँग सम्बत्तन्ित सम्पूण य काम, कारबािी गैर कानूनी िएको माधनन े\nछैन।\n\n१९३क. दस्तरु लाग्नाःे (१) र्स संवितामा अन्र्था उल्लेि िएकोमा बािेक अदालतमा देिार्का\nविषर्मा देिार् बमोत्तजम दस्तरु लाग्नेछाः-\n(क) उजरु ीपत्र, वफरादपत्र िा प्रधतउिरपत्र ठदंदा रु २००।-\n(ि) पनु रािेदनपत्र ठदंदा रु ३००।-\n(ग) िण्ड (क) र (ि) बमोत्तजम बािेक अन्र् धनिेदन ठदंदा रु १०।-\n(२) उपदफा (१) मा जनु सकै कुरा लेत्तिएको िए तापधन नेपाल सरकार िादी\nिएको मद्दु ामा उपदफा (१) बमोत्तजमको दस्तरु लाग्ने छैन।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९४", "title": "समन्िर् सधमधताः (१) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय का कसूर सम्बन्िी मद्दु ाको", "content": "अनसु न्िान तथा अधिर्ोजनसँग संलग्न धनकार्का धबचमा आिश्र्कता अनसु ार समन्िर्\nकार्म गरी अनसु न्िान तथा अधिर्ोजन सम्बन्िी कार्मय ा प्रिािकाररता ल्र्ाउन देिार्\nबमोत्तजमको समन्िर् सधमधत रिनेछाः-\n(क) मिान्र्ार्ाधिििा - अध्र्ि\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा थप।\n137\nwww.lawcommission.gov.np\n(ि) सत्तचि, कानून, न्र्ार् तथा संसदीर्\nमाधमला मन्त्रालर् - सदस्र्\n(ग) सत्तचि, गिृ मन्त्रालर् - सदस्र्\n(घ) प्रिरी मिाधनरीिक, नेपाल प्रिरी - सदस्र्\n(ङ) मिान्र्ार्ाधिििाले तोके को\nमिान्र्ार्ाधिििाको कार्ायलर्को\nराजपत्रावङ्कत प्रथम श्रेणी िा\nसोिन्दा माधथल्लो दजायको\nसरकारी िवकल - सदस्र् सत्तचि\n(२) समन्िर् सधमधतको कार्वयिधि सधमधत आफैँ ले धनिायरण गरे बमोत्तजम िनु ेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९५", "title": "वििागीर् कारबािी िनु ाःे र्स ऐन बमोत्तजम गन यु पने कुनै काम कारबािी गन य र्स ऐनमा", "content": "अिधि तोवकएकोमा त्र्स्तो अिधिधित्र त्र्स्तो काम कारबािी नगने राष्ट्रसेिकलाई कानून\nबमोत्तजम वििागीर् कारबािी िनु ेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९६", "title": "धनर्म बनाउन े अधिकाराः (१) र्स ऐनको कार्ायन्िर्नको लाधग अनसु न्िान, अधिर्ोजन", "content": "तथा सरकारी िकीलको काम, कतव्य र् र अधिकारको विषर्मा मिान्र्ार्ाधिििाको\nपरामश य धलई नेपाल सरकारले र अदालती कामकारबािीको विषर्मा सिोच्च अदालतले\nधनर्म बनाउन सक्नेछ।\n(२) उपदफा (१) बमोत्तजम धनर्म बनाउँदा न्र्ार् प्रशासन सम्बन्िी विषर्मा\nन्र्ार् पररषद्को परामश य धलन ु पनेछ।", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९७", "title": "धनदेत्तशका बनाउन सवकनाःे (१) र्स ऐन बमोत्तजम सम्पादन िनु े कामकारबािीलाई सरल,", "content": "स्पष्ट र सव्ु र्ित्तस्थत गन य देिार्को विषर्मा देिार्को अधिकारीले आिश्र्कता अनसु ार\nधनदेत्तशका बनाई लागू गन य सक्नेछाः-\n(क) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय का कसूर सम्बन्िी मद्दु ाको\nअनसु न्िान एिं अधिर्ोजन सम्बन्िमा मिान्र्ार्ाधिििाको रार्\nधलई नेपाल सरकारले,\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n138\nwww.lawcommission.gov.np\n(ि) अनसु ूची-१ िा अनसु ूची-२ अन्तगतय का कसूर सम्बन्िी मद्दु ाको\nबिस पैरबी प्रधतरिा, कानूनी रार् सम्बन्िमा मिान्र्ार्ाधिििाले,\n(ग) पररच्छेद ६ अन्तगतय समाह्वान तामेलीका सम्बन्िमा सिोच् च\nअदालतले,\n(घ) अदालत िा इजलासको व्र्िस्थापनका सम्बन्िमा सिोच् च\nअदालतले,\n(ङ) पररच्छेद १५ अन्तगतय का फै सला कार्ायन्िर्नका सम्बन्िमा\nसिोच् च अदालतले,\n(च) दफा ११६ बमोत्तजम मद्दु ा वफताय धलने सम्बन्िमा\nमिान्र्ार्ाधिििाको परामश य धलई नेपाल सरकारले,\n(छ) दफा १५९ बमोत्तजम माफीका सम्बन्िमा मिान्र्ार्ाधिििासँग\nपरामश य धलई नेपाल सरकारले,\n(ज) अन्र् अदालती कामकारबािीका सम्बन्िमा सिोच् च अदालतले।\n(२) उपदफा (१) बमोत्तजमको धनदेत्तशका र्सै ऐन अन्तगतय जारी िएको\nमाधननेछ।\n", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१९८", "title": "अनसु ूचीमा िेरफे र िा थपघट गन य सक्नाःे (१) नपे ाल सरकारले मिान्र्ार्ाधिििाको", "content": "परामशमय ा नेपाल राजपत्रमा सूचना प्रकाशन गरी अनसु ूची-१, अनसु ूची-२, अनसु ूची-३ र\nअनसु ूची-४ मा आिश्र्क िेरफे र िा थपघट गन य सक्नेछ।\n(२) उपदफा (१) मा उल्लेि िए बािेक अन्र् अनसु ूचीमा अनसु न्िान तथा\nअधिर्ोजन सम्बन्िी विषर्मा मिान्र्ार्ाधिििाको र अदालती कारबािीको विषर्मा\nसिोच् च अदालतको परामशमय ा कानून, न्र्ार् तथा संसदीर् माधमला मन्त्रालर्ले नेपाल\nराजपत्रमा सूचना प्रकाशन गरी आिश्र्कता अनसु ार थपघट िा िेरफे र गन य सक्नेछ।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०७५ द्वारा संशोधित।\n139\nwww.lawcommission.gov.np\nअनसु ूची-१\n(दफा २ को िण्ड (घ) र (ि) सँग सम्बत्तन्ित)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "१", "title": "अपराि संविताको देिार्का पररच्छेद िा देिार्का पररच्छेदका देिार् दफा अन्तगतय का", "content": "कसूराः -\n(क) िाग २ कोाः\n(१) पररच्छेद-१\n(२) पररच्छेद-२\n(३) पररच्छेद-४ को दफा ९२, ९३, ९४ र १०२\n(४) पररच्छेद-५ को दफा १०४, १०५, १०६, ११०, ११४, ११८, ११९,\n\n१२०, १२१, १२२, १२३, १२४,  १२५, १२५क. र १२६ तथा\n१२६क.\n(५) पररच्छेद-६\n(६) पररच्छेद-७\n(६क) पररच्छेद ७क.\n(७) पररच्छेद-८ को दफा १५१, १५२\n(८) पररच्छेद-९\n(९) पररच्छेद-१०\n(१०) पररच्छेद-११\n(११) पररच्छेद-१२\n(१२) पररच्छेद-१३\n धमधत २०७८।१०।२९ को नेपाल राजपत्रमा प्रकात्तशत सूचनाद्वारा अनसु ूची िेरफे र।\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) धनिारण तथा व्र्ािसावर्किातािरण प्रिद्धयन सम्बन्िी केिी ऐनलाई\nसंशोिन गने ऐन, २०८० द्धारा संशोधित।\n फौजदारी कसूर तथा फौजदारी कार्वयिधि सम्बन्िी केिी ऐन संशोिन गने ऐन, २०७९ द्वारा संशोधित।\n सम्पत्ति शद्धु ीकरण (मनी लाउण्डररङ्ग) धनिारण तथा व्र्ािसावर्किातािरण प्रिद्धयन सम्बन्िी केिी ऐनलाई\nसंशोिन गने ऐन, २०८० द्धारा थप।\n140\nwww.lawcommission.gov.np\n\n(१३) पररच्छेद-१४ को दफा १९२, १९२क.\n(१४) पररच्छेद-१५\n(१५) पररच्छेद-१६\n(१६) पररच्छेद-१७,\n(१७) पररच्छेद-१८ को २१९, २२१, २२२, २२३, २२५, २२६ को उपदफा\n\n(३) र सो दफा तथा उपदफािरुसँग सम्बत्तन्ित दफा २२७क.\nअन्तगतय को कसूर\n(१८) पररच्छेद-१९\n(१९) पररच्छेद-२०\n(२०) पररच्छेद-२१ को दफा २४९ को उपठदफा (३) को िण्ड (क) र (ि),\nर दफा २४९,  दफा २४९क., २५०, २५१, २५२ र २५३\n(२१) पररच्छेद-२२ र २३\n(२२) पररच्छेद-२५ को दफा २७६ को उपदफा (३) को िण्ड\n(क), (ि), (ग) र दफा २७८\n(२३) पररच्छेद-२६ को दफा २८३ (धनजी सम्पत्ति बािेक) २८७\n(२४) पररच्छेद-२७", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "२", "title": "प्रकरण १ अन्तगतय को कसूरको उद्योग, दरुु त्सािन, षडर्न्त्रको कसूर,", "content": "३ मानि बेचधबिन तथा ओसार पसार सम्बन्िी कसूर,\n४ िलु ाक ऐन, २०१९ अन्तगतय को कसूर,\n५ नागररकता सम्बन्िी कसूर,", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "६", "title": "प्राचीन स्मारक सम्बन्िी कसूर,", "content": " फौजदारी कसूर तथा फौजदारी कार्वयिधि सम्बन्िी केिी ऐन संशोिन गने ऐन, २०७९ द्वारा थप।\n र्ौन विंसा विरुद्धका केिी ऐनलाई संशोिन गने ऐन, २०७९ द्वारा थप।\n मलु कु ी संविता सम्बन्िी केिी नेपाल ऐनलाई संशोिन गने ऐन, २०८० द्वारा थप।\n141\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "७", "title": "लागू औषि सम्बन्िी कसूर,", "content": "८ आिश्र्क सेिा सञ् चालन ऐन, २०१४ अन्तगतय को कसूर,"